window.STUDY_DATA = {"scores": [{"subject": "历史", "full": 100.0, "score": 60.0}, {"subject": "地理", "full": 100.0, "score": 51.0}, {"subject": "政治", "full": 100.0, "score": 59.0}, {"subject": "生物", "full": 100.0, "score": 55.0}, {"subject": "化学", "full": 100.0, "score": 31.0}, {"subject": "语文", "full": 150.0, "score": 100.0}, {"subject": "英语", "full": 150.0, "score": 96.5}, {"subject": "物理", "full": 100.0, "score": 61.0}, {"subject": "数学", "full": 150.0, "score": 59.0}], "wrong": [{"subject": "物理", "question_no": "5", "full_score": 6.0, "got_score": 3.0, "student_answer": "BC", "std_answer": "CD", "error_type": "概念混淆", "knowledge_point": "速度与加速度关系：a是速度变化快慢，与v大小无关；a增大v可能减小（反向时）", "note": "卡面3分；按规则含错误选项应0分，待确认", "key": "物理|5|1", "card_type": "concept", "teach": "加速度 a 描述的是速度变化的快慢，和速度 v 本身的大小没有直接关系：刹车瞬间 v 很大但 a 可以很小，起步时 v 很小但 a 可以很大，高速匀速时 v 最大而 a=0。判断 v 增减只看方向：a 与 v 同向，v 增大；a 与 v 反向，v 减小，此时 a 越大 v 减得越快。易混点：a 减小不等于 v 减小——同向时 a 减小只是加得慢了，v 还在增大。抓手：先比方向定增减，再看大小定快慢，两步分开想。", "why": "把加速度大小和速度大小直接挂钩，没先判断 a 与 v 的方向关系就下了结论。", "check_q": "一物体做直线运动，加速度方向与速度方向相反，且加速度大小逐渐增大，它的速度怎样变化？", "check_a": "速度越来越小，而且减小得越来越快（反向减速、减幅增大）。", "steps": "1. 先分清选项问的是速度还是加速度，两者分开判断，别把 v 和 a 混成一个量。\n2. 判断速度增减只比方向：a 与 v 同向则 v 增大，反向则 v 减小，与 a 的大小无关。\n3. 判断变化快慢只看 |a|：|a| 越大变得越快；a 减小只是变得慢了，不代表 v 减小。\n4. 逐项代入情景核对：刹车（反向，v 减小）、起步（同向，v 增大）、匀速（a=0，v 不变），对完再定选项。", "need": ["加速度的定义式与物理意义（速度变化快慢）", "速度与加速度方向关系：同向加速、反向减速", "匀速直线运动加速度为零"], "stem": "关于速度和加速度的关系，下列说法中正确的是（ ）\nA. 物体的加速度等于零，速度一定等于零\nB. 物体的加速度越大，速度一定越大\nC. 物体的加速度越大，速度一定改变越快\nD. 物体的加速度增大，速度可能减小"}, {"subject": "物理", "question_no": "8", "full_score": 6.0, "got_score": 3.0, "student_answer": "AB", "std_answer": "BD", "error_type": "知识盲区", "knowledge_point": "等分位移比例推论：v_B:v_C:v_D:v_E=1:√2:√3:2；中间时刻速度", "note": "卡面3分；按规则含错误选项应0分，待确认", "stem": "如图所示，光滑斜面 AE 被分成长度相等的四段（B、C、D 为分点），一个物体由 A 点静止释放后做匀加速直线运动，下面结论中正确的是（ ）", "paper_cause": "概念不清——把\"相等位移\"误当成\"相等时间\"，以为每段速度增量相同；等位移与等时间两套比例规律混淆。", "key": "物理|8|1", "card_type": "redo", "options": {"A": "经过每一部分时，其速度增量均相同", "B": "物体到达 B、C、D、E 各点的速度大小之比为 1 : √2 : √3 : 2", "C": "物体通过 AB、BC、CD、DE 段所需的时间之比为 1 : √2 : √2 : √3 : 2", "D": "若该物体从 A 点运动到 E 点共用时 4s，则物体在第 2s 末的速度等于 B 点速度"}, "teach": "初速度为零的匀加速有两套比例，别混用：等时间段的位移比是 1:3:5:7；等位移段要用 v²=2ax，速度比 1:√2:√3:2，所以 B 对；每段时间比是 1:(√2−1):(√3−√2):(2−√3)，越走越快、每段用时越来越短。A 错就错在这里：速度增量 Δv=aΔt，每段 Δt 不同，增量依次是 1、√2−1、√3−√2、2−√3，越来越小，不相等。D 的抓手：B 是位移中点，全程位移比 1:4 对应时间比 1:2，总时间 4s 到达 B 恰好是 2s。", "why": "把“相等位移”当成“相等时间”，以为每段速度增量相同，多选了 A，双选含错项归零。", "check_q": "初速度为零的匀加速直线运动，物体通过第 1 段位移末的速度为 v，则通过第 2 段位移末（累计 2 段）的速度是多大？", "check_a": "√2 v。因为 v² 与位移成正比，位移变成 2 倍，速度变成 √2 倍。", "steps": "1. 先认题型：初速度为零、位移被等分，用的是“等位移”规律，别套等时间段的 1:3:5:7。\n2. 求各点速度比：由 v²=2ax，位移成 1:2:3:4，速度比就是 1:√2:√3:2，B 成立。\n3. 验 A：速度增量 Δv=aΔt，而等位移下每段时间比为 1:(√2−1):(√3−√2):(2−√3) 越来越短，所以增量越来越小、不相等，A 错。\n4. 验 D：B 是位移中点，位移比 1:4 对应时间比 1:2，总时间 4s 到 B 恰好是 2s，第 2s 末速度等于 B 点速度，D 成立。", "need": ["初速度为零的匀加速运动等位移比例规律（速度比、时间比）", "速度位移公式 v²−v₀²=2ax", "速度变化量 Δv=aΔt 与时间的关系"]}, {"subject": "物理", "question_no": "9空1", "full_score": 2.0, "got_score": 0.0, "student_answer": "7.5", "std_answer": "7.2", "error_type": "概念混淆", "knowledge_point": "前\"一半路程\"的平均速度≠算术平均，v=2v₁v₂/(v₁+v₂)=7.2", "note": "", "stem": "一物体做直线运动，它经过前一半路程的平均速度为 6 m/s，经过后一半路程的平均速度为 9 m/s，求物体全过程的平均速度。（原卷第 9 题，只做前一半路程这一问）", "paper_cause": "概念不清——等路程平均速度不能用算术平均代替，本质上是不理解平均速度等于总位移比总时间。", "key": "物理|9空1|1", "card_type": "redo", "teach": "平均速度只有一个定义：总位移÷总时间，不存在“把两个平均速度再平均”的道理。等路程时两段路程相同，但慢的那段耗时更长、在总时间里权重更大，所以结果偏向慢速，必须用调和平均：v̄=2v₁v₂/(v₁+v₂)=2×6×9÷(6+9)=7.2 m/s。只有等时间时，两段时间相同，才可以直接算术平均 (v₁+v₂)/2。抓手：看到“一半路程”先分别写 t=s/v 求两段时间，别凭感觉取中点。", "why": "把等路程平均速度按算术平均 (6+9)÷2=7.5 算了，忘了慢段耗时更长。", "check_q": "前一半路程速度为 4 m/s、后一半路程速度为 12 m/s，全程平均速度是多少？", "check_a": "2×4×12÷(4+12)=6 m/s（不是算术平均的 8 m/s）。", "steps": "1. 先定性：题面是“前一半路程”，属于等路程分段，不是等时间，平均速度不能直接取算术平均。\n2. 设每半段路程为 s，分别算时间：t₁=s/6，t₂=s/9。\n3. 回到定义：全程平均速度=总路程÷总时间=2s/(s/6+s/9)。\n4. 约掉 s 得 2×6×9/(6+9)=7.2 m/s；自查：慢段耗时更长，结果应小于算术平均 7.5 且偏向 6，对得上再落笔。", "need": ["平均速度的定义（总位移÷总时间）", "等路程分段的调和平均 2v₁v₂/(v₁+v₂)", "等时间分段与等路程分段的区别"], "points": ["先把半程设为 s，写出全程时间 t=s/6+s/9（约1分，过程点）", "套平均速度定义 v=2s/t=2×6×9/(6+9)=7.2（约1分）", "填 7.2 m/s 得满分 2 分；写算术平均 7.5 得 0 分——等路程必须用调和平均"], "frame": "填空题落笔三步：题旁草稿先写'设半程为 s'→列总时间 t=s/6+s/9→套 v=总路程/总时间算出 7.2→再把数值填进空里。不要心算直接填，公式先行能挡住顺手写算术平均。"}, {"subject": "物理", "question_no": "10空2", "full_score": 2.0, "got_score": 0.0, "student_answer": "3", "std_answer": "−3", "error_type": "概念混淆", "knowledge_point": "坐标变化量Δx=x末−x初=0−3=−3（含符号）", "note": "", "stem": "某物体沿 x 轴做直线运动，其位置坐标随时间的变化规律为：0~1s 坐标由 2m 升到 3m，1~3s 保持 3m 不变，3~4s 降到 0m。求第 4s 内物体坐标的变化量 Δx。（原卷第 10 题的其中一空）", "paper_cause": "概念不清——平均速度是矢量，第 4s 内物体反向运动，平均速度应带方向（负号）；她算出的 0.6 与任何正确量都不对应，", "key": "物理|10空2|1", "card_type": "redo", "teach": "坐标变化量 Δx=x末−x初，必须带符号算：第 4s 内坐标从 3m 变到 0m，Δx=0−3=−3 m，负号表示沿 x 轴负方向运动。易混点：“变化量”问的是位移（矢量），不是路程——这 1 秒内路程是 3m，位移是 −3m，问法不同答案不同。抓手：凡是 Δ 开头的量（Δx、Δv）都先定正方向、用“末减初”，符号会自己出来；千万不要先算大小再回头猜符号，那一步最容易丢分。", "why": "只写了大小 3，没按“末坐标减初坐标”带符号计算，丢了负号。", "check_q": "物体坐标从 −2m 变到 5m，坐标变化量 Δx 是多少？", "check_a": "Δx=5−(−2)=7 m。", "steps": "1. 先在图上读坐标：第 4s 初（即 3s 末）坐标 3m，第 4s 末坐标 0m。\n2. 坐标变化量用“末减初”：Δx=x末−x初=0−3。\n3. 带符号算完得 −3m，负号表示这 1s 沿 x 轴负方向运动，只写 3 就丢了方向。\n4. 自查问法：问“变化量/位移”带符号，问“路程”才写正数 3m，两种别混。", "need": ["位移与坐标变化量 Δx=x末−x初", "矢量正负号与运动方向的对应", "位移与路程的区别"], "points": ["从图乙读出第 4s 初（即 3s 末）坐标 x=3 m、第 4s 末坐标 x=0 m（约1分）", "写 Δx=x末−x初=0−3=−3 m（约1分）", "填 −3 得满分 2 分；只写 3（丢负号）得 0 分"], "frame": "先在图上把第 4s 的起点、终点两个点描出来→在空旁写一行 Δx=x末−x初→带符号相减得 −3→原样填入。位移类填空先写减法式再填数，负号是答案的一部分不能后补。", "img": "phy-10.jpg"}, {"subject": "物理", "question_no": "10空4", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.5", "std_answer": "−3", "error_type": "知识盲区", "knowledge_point": "x-t图像斜率=速度：第4s内3→0，v=−3m/s", "note": "", "stem": "某物体沿 x 轴做直线运动，其位置坐标随时间的变化规律为：0~1s 坐标由 2m 升到 3m，1~3s 保持 3m 不变，3~4s 降到 0m。求第 4s 内物体的平均速度。（原卷第 10 题的其中一空）", "paper_cause": "概念不清——平均速度是矢量，第 4s 内物体反向运动，平均速度应带方向（负号）；她算出的 0.6 与任何正确量都不对应，", "key": "物理|10空4|1", "card_type": "redo", "teach": "平均速度 v̄=Δx/Δt，是矢量：第 4s 内 Δx=0−3=−3 m，Δt=1 s，所以 v̄=−3 m/s。在 x-t 图像上，某段时间内的平均速度就是这段图线的斜率，图线下降，斜率为负、大小是 3。易混点：平均速度不等于平均速率——这 1s 内路程是 3m，平均速率是 3 m/s（正值），但平均速度必须带方向符号。抓手：先算带符号的 Δx，再除以时间，方向自动跟着符号走。", "why": "填了约 0.5，把路程和时间乱配相除，既没用 Δx 也没带方向。", "check_q": "x-t 图中物体 2s 时坐标为 6m，4s 时坐标为 2m，2~4s 内平均速度是多少？", "check_a": "(2−6)÷2=−2 m/s，负号表示沿负方向运动。", "steps": "1. 先求这一段的位移：第 4s 内坐标由 3m 到 0m，Δx=0−3=−3m（带符号）。\n2. 套平均速度定义：v̄=Δx/Δt=−3÷1=−3 m/s。\n3. 换角度验算：x-t 图线这段在下降，斜率为负、大小 3，与 −3 m/s 一致。\n4. 注意别拿路程 3m 乱配时间：平均速度只认带符号的位移，平均速率才用路程。", "need": ["平均速度定义式 v̄=Δx/Δt", "x-t 图像斜率表示速度（含正负）", "平均速度与平均速率的区别"], "points": ["引用上一空的结果 Δx=−3 m、Δt=1 s（约1分）", "写 v̄=Δx/Δt=−3/1=−3 m/s（约1分）", "填 −3 得满分 2 分；她填 0.5（把路程和时间乱配相除）得 0 分"], "frame": "紧接上一空往下写，不另起炉灶：抄下 Δx 的结果→一行公式 v̄=Δx/Δt→代入得 −3→带负号填入。平均速度是矢量，大小和方向（负号）要在同一个数里交代完。", "img": "phy-10.jpg"}, {"subject": "物理", "question_no": "11空3", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.21", "std_answer": "0.14", "error_type": "计算失误", "knowledge_point": "a=Δv/Δt，时间Δt代入错误", "note": "", "stem": "用气垫导轨和光电门测物体的加速度：遮光板宽度为 2.0cm，通过第一个光电门的时间为 0.25s，通过第二个光电门的时间为 0.04s，遮光条从开始遮住第一个光电门到开始遮住第二个光电门的时间为 3s。求滑块的加速度 a。（结果保留两位小数；原卷第 11 题，只做加速度这一空）", "paper_cause": "计算失误——方法本身对（速度两空全对），最后一步除法算错。", "key": "物理|11空3|1", "card_type": "redo", "teach": "光电门测速的原理是“用很短时间内的平均速度代替瞬时速度”：v=遮光板宽÷遮光时间，所以 v₁=0.02÷0.25=0.08 m/s，v₂=0.02÷0.04=0.50 m/s。加速度回到定义式 a=Δv/Δt=(v₂−v₁)/t，这里的 t 是滑块在两门之间运动的过程时间 3s，不是任何一个遮光时间：a=(0.50−0.08)÷3=0.14 m/s²。抓手：定义式题目不玩变形，认准“速度的变化量÷对应的时间间隔”，先把每个时间到底指哪一段标清楚再代入。", "why": "两个速度都算对了，最后把速度差除错了时间（约除以 2），得到 0.21。", "check_q": "滑块通过两个光电门的速度分别为 0.20 m/s 和 0.80 m/s，中间历时 2s，加速度是多少？", "check_a": "a=(0.80−0.20)÷2=0.30 m/s²。", "steps": "1. 先用光电门原理算两个瞬时速度：v=d/Δt，宽度先换成 m，v₁=0.02÷0.25=0.08 m/s，v₂=0.02÷0.04=0.50 m/s。\n2. 认清每个时间的身份：0.25s、0.04s 是遮光时间（只用来算速度），3s 才是两门之间的运动时间。\n3. 回加速度定义式：a=(v₂−v₁)/t=(0.50−0.08)÷3。\n4. 得 0.14 m/s²；自查数量级：速度只变了 0.42 又跨 3s，加速度必在 0.1 左右，得 0.21 就是除错了时间。", "need": ["光电门测速原理（极短时间平均速度代替瞬时速度）", "加速度定义式 a=Δv/Δt", "单位换算（cm→m）与数量级检查"], "points": ["先用前两空已算出的 v₁=0.08 m/s、v₂=0.50 m/s（本地基，错了连带错）", "时间认题干给的'开始遮光到开始遮光'3 s（约1分；她纠结 3 s 还是 2.75 s，代错时间结果就错）", "写 a=(v₂−v₁)/t=(0.50−0.08)/3=0.14（约1分）", "结果保留两位小数、带单位 m/s²，填 0.14 得满分 2 分"], "frame": "实验题连环空落笔：把前两空的答案抄到本空算式上方→写公式 a=(v₂−v₁)/t→t 只认题干明说的 3 s，不自己拼时间→代入算完先核对小数位数（保留两位小数）再填空。"}, {"subject": "物理", "question_no": "12(2)a", "full_score": 2.0, "got_score": 0.0, "student_answer": "4.05", "std_answer": "0.81", "error_type": "审题偏差", "knowledge_point": "漏看\"相邻计数点间还有四个计时点未标出\"，T=0.1s误作0.02s（0.81×5=4.05）", "note": "", "stem": "用打点计时器研究小车运动，打点计时器所接电源频率为 50Hz。纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，测得 AB 段 7.10cm、BC 段 9.10cm。求打 B 点时小车的速度 v_B。（结果保留 2 位有效数字；原卷第 12 题第 (2) 问的第一空）", "paper_cause": "概念不清——\"相邻计数点间还有四个计时点未标出\"意味着时间间隔是 0.1s 而非 0.02s，这个关键点没掌握，导致后面", "key": "物理|12(2)a|1", "card_type": "redo", "teach": "纸带题第一件事是定计数周期：打点周期是 1/50=0.02s，“相邻计数点间还有四个计时点未标出”意味着两个计数点之间隔了 5 个打点周期，T=5×0.02=0.1s。她当时把 T 当成 0.02s，结果恰好放大 5 倍（4.05=0.81×5）。第二件事：匀变速运动中，中间时刻的瞬时速度等于这段的平均速度，v_B=(AB+BC)÷2T=(0.0710+0.0910)÷0.2=0.81 m/s。抓手：看到“还有 n 个点未标出”，先写 T=(n+1)×0.02s 再动笔算。", "why": "漏看“还有四个计时点未标出”，把计数周期 0.1s 当成 0.02s，速度放大了 5 倍。", "check_q": "50Hz 打点计时器，相邻计数点间还有 2 个计时点未标出，计数周期是多少？", "check_a": "T=(2+1)×0.02=0.06 s。", "steps": "1. 动笔第一件事定计数周期：打点周期 0.02s，“还有四个计时点未标出”说明相邻计数点间有 5 个周期，T=5×0.02=0.1s。\n2. 认准方法：匀变速运动中间时刻的瞬时速度等于这段的平均速度，v_B 用 AC 段平均速度求。\n3. 代入：v_B=(AB+BC)/(2T)=(0.0710+0.0910)÷0.2，位移先把 cm 换成 m，得 0.81 m/s。\n4. 自查：若算出 4.05，正好是 5 倍，多半是 T 错用了 0.02s。", "need": ["打点计时器计数点与计数周期 T=(n+1)×0.02s", "匀变速运动中间时刻速度等于这段平均速度", "纸带位移数据的单位换算"], "points": ["先定计数周期：相邻计数点间还有 4 个未标出，T=5×0.02=0.1 s（约1分，本题命门）", "用中间时刻速度公式 v_B=(AB+BC)/(2T)，长度换成米：(0.071+0.091)/0.2（约0.5分）", "算出 v_B=0.81 m/s、保留 2 位有效数字（约0.5分）", "她把时间取成 0.02 s 量级得 4.05，整空 0 分"], "frame": "纸带题固定开局：第一行先写 T=0.1 s 并圈起来，后面所有公式都用它→再写 v_B 的公式→代入前先把 cm 换成 m→算完按'保留 2 位有效数字'收尾再填空。", "img": "phy-12.jpg"}, {"subject": "物理", "question_no": "12(2)b", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.50", "std_answer": "2.0", "error_type": "知识盲区", "knowledge_point": "逐差法求加速度未掌握", "note": "", "stem": "用打点计时器研究小车运动，打点计时器所接电源频率为 50Hz。纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，测得 AB 段 7.10cm、BC 段 9.10cm。求小车运动的加速度 a。（结果保留 2 位有效数字；原卷第 12 题第 (2) 问的第二空）", "paper_cause": "概念不清——\"相邻计数点间还有四个计时点未标出\"意味着时间间隔是 0.1s 而非 0.02s，这个关键点没掌握，导致后面", "key": "物理|12(2)b|1", "card_type": "redo", "teach": "匀变速纸带求加速度用位移差公式 Δx=aT²：相邻相等时间内的位移之差恒定。先定 T：还有四个点未标出，T=5×0.02=0.1s（这一步错，后面全错）。再算 a=(x_BC−x_AB)÷T²=(0.0910−0.0710)÷0.1²=2.0 m/s²。两个注意点：位移要先把 cm 换成 m 再代入；T 要平方。抓手顺序固定：先数点定 T，再写“后段减前段除以 T 的平方”，最后检查单位和数量级（小车加速度一般在零点几到几 m/s²）。", "why": "计数周期取错，逐差法也没用对，a 在 3.56 与 4.56 之间涂改，两个都不对。", "check_q": "纸带上相邻两段位移分别为 5.00cm 和 7.00cm，计数周期 T=0.1s，加速度是多少？", "check_a": "a=(0.0700−0.0500)÷0.01=2.0 m/s²。", "steps": "1. 先定 T：还有四个计时点未标出，T=5×0.02=0.1s，这步错全题错，先写在纸带边上。\n2. 想原理：匀变速运动相邻相等时间内的位移之差恒定，Δx=aT²。\n3. 代入后段减前段：a=(x_BC−x_AB)/T²=(0.0910−0.0710)÷0.1²，位移先换成 m，T 别忘了平方。\n4. 得 2.0 m/s²；自查数量级：小车加速度一般是零点几到几 m/s²，相差太远就回头查 T 和单位。", "need": ["逐差法与位移差公式 Δx=aT²", "打点计时器计数周期的确定", "单位换算与有效数字"], "points": ["沿用上一空的 T=0.1 s（约0.5分）", "写逐差/定义式 a=(BC−AB)/T²=(0.091−0.071)/0.01（约1分）", "算出 a=2.0 m/s²、2 位有效数字（约0.5分）", "她在 3.56 与 4.56 之间涂改，两个都不对，0 分——错根仍在 T"], "frame": "接着上一空同段写：公式先行→分子是后段减前段（BC−AB，别写反）→代入 T²=0.01→算完做量级检查（小车加速度 2 m/s² 合理、4 点几明显可疑）再落笔。", "img": "phy-12.jpg"}, {"subject": "物理", "question_no": "13(1)", "full_score": 4.0, "got_score": 0.0, "student_answer": "2m/s", "std_answer": "18m/s", "error_type": "概念混淆", "knowledge_point": "速度变化量的矢量性：反向踢回，Δv=8−(−10)=18m/s", "note": "", "stem": "一质量为 0.4kg 的足球，以 10 m/s 的速度迎面飞来，足球守门员将球以 8 m/s 的速度反向踢出，守门员与球接触的时间为 0.1s。求足球在与守门员接触的这段时间内的速度变化量大小。（原卷第 13 题第 (1) 问）", "paper_cause": "概念不清——速度变化量要按矢量处理、反向必须带负号，这一点没建立起来，整题无从下笔（方法不会为次因）。", "key": "物理|13(1)|1", "card_type": "redo", "teach": "速度是矢量，速度变化量 Δv 必须先定正方向、带符号再相减。取来球方向为正方向：初速度 v₀=+10 m/s，被反向踢出后 v=−8 m/s，Δv=v−v₀=−8−10=−18 m/s，大小为 18 m/s。记忆抓手：“反向相减变相加”——末速度与初速度方向相反时，变化量的大小等于两者大小之和 10+8=18，而不是 10−8=2。凡遇到掉头、反弹、反向踢出，先给反方向的速度挂上负号，再套 Δv=v−v₀，这一步立住整题就立住了。", "why": "把速度变化量当标量算成 10−8=2，没给反向踢出的速度带负号。", "check_q": "小车以 6 m/s 向东行驶，碰墙后以 4 m/s 向西返回，速度变化量的大小是多少？", "check_a": "取向东为正，Δv=−4−6=−10 m/s，大小为 10 m/s。", "steps": "1. 先定正方向：取来球方向为正，把速度写成带符号的数：v₀=+10 m/s，反向踢出后 v=−8 m/s。\n2. 速度变化量用“末减初”：Δv=v−v₀。\n3. 代入 Δv=−8−10=−18 m/s，题目问大小，报 18 m/s。\n4. 记住这个模型：反向、掉头、反弹时，变化量大小等于两速度大小之和（10+8），不是相减得 2。", "need": ["速度的矢量性与正方向的选取", "速度变化量 Δv=v−v₀", "反弹类问题中变化量大小的算法"], "points": ["第一行声明正方向：取来球方向为正，v₀=+10 m/s、v=−8 m/s（约1分）", "写出 Δv=v−v₀=−8−10=−18 m/s（约2分）", "单独答'速度变化量大小为 18 m/s'（约1分）", "她按 8−10 算（把反向速度当同向），是本题的陷阱点，整问 0 分"], "frame": "矢量计算题四件套：先写'取…为正方向'→列 Δv=v−v₀ 并把带符号的初末速度代入→得到带符号的结果→最后一句分开答大小。符号在代入时定，大小在答语里说，两步不能混。"}, {"subject": "物理", "question_no": "13(2)", "full_score": 4.0, "got_score": 4.0, "student_answer": "20m/s²", "std_answer": "180m/s²", "error_type": "连带错误", "knowledge_point": "加速度定义式a=Δv/Δt列对，但Δv代入错误", "note": "卡面13题计4分，约2分为教师裁量", "stem": "一质量为 0.4kg 的足球，以 10 m/s 的速度迎面飞来，足球守门员将球以 8 m/s 的速度反向踢出，守门员与球接触的时间为 0.1s。已知这段时间内速度变化量 Δv=−18 m/s（取来球方向为正），求足球的平均加速度大小。（原卷第 13 题第 (2) 问）", "paper_cause": "概念不清——速度变化量要按矢量处理、反向必须带负号，这一点没建立起来，整题无从下笔（方法不会为次因）。", "key": "物理|13(2)|1", "card_type": "redo", "teach": "平均加速度 a=Δv/Δt，代入的是带符号的速度变化量：a=−18÷0.1=−180 m/s²，大小 180 m/s²，方向与 Δv 相同，即守门员对球的施力方向。注意两点：题目问“大小”时最后报正数，但列式必须先带符号算；另外 Δv 是这一问的命根子，上一问 Δv 错一位，这一问 a 跟着错一位（她当时 Δv 取 2，a 就成了 20）。抓手：连环小题要分步落纸，第一问的 Δv 单独写一行算清、检查方向，再代入第二问。", "why": "定义式列对了，但代入了上一问错误的 Δv=2，加速度跟着算成 20 m/s²，连带丢分。", "check_q": "某物体速度在 0.2s 内由 +5 m/s 变为 −15 m/s，平均加速度大小是多少？", "check_a": "Δv=−15−5=−20 m/s，a=−20÷0.2=−100 m/s²，大小 100 m/s²。", "steps": "1. 先把上一问的 Δv 单独写一行确认：带符号 Δv=−18 m/s，方向、大小都核对过再用。\n2. 套平均加速度定义式：a=Δv/Δt。\n3. 代入 a=−18÷0.1=−180 m/s²，问大小报 180 m/s²，方向与 Δv 相同。\n4. 连环题自查：第二问完全依赖第一问的 Δv，第一问错一位第二问全错，落笔前回头验 Δv。", "need": ["平均加速度定义式 a=Δv/Δt", "速度变化量的矢量运算", "连环小题中间结果的校验"], "points": ["写出平均加速度定义式 a=Δv/t（约1分，公式分）", "代入 Δv=−18 m/s、t=0.1 s 得 a=−180 m/s²（约2分）", "答'平均加速度大小为 180 m/s²'（约1分）", "注：卡面本问计 4 分含约 2 分教师裁量；第 (1) 问 Δv 错会连带本问，正方向必须与上一问共用"], "frame": "不另起一段方向声明：开头写'由 (1)，Δv=−18 m/s'→一行公式 a=Δv/t→代入算出→答大小收尾。与上一问共用同一正方向、同一组符号，这是连环问的省分写法。"}, {"subject": "物理", "question_no": "14(2)", "full_score": 6.0, "got_score": 4.0, "student_answer": "2m/s", "std_answer": "20m/s", "error_type": "计算失误", "knowledge_point": "v-t面积=位移=1500m正确，但1500/75=20算成2", "note": "", "key": "物理|14(2)|1", "card_type": "concept", "teach": "v-t 图像题的两把钥匙：图线斜率是加速度，图线与时间轴围成的面积是位移。她这道题面积算对了，总位移 1500m，最后平均速度=总位移÷总时间=1500÷75=20 m/s，却把商写成了 2，纯粹是除法错位。防这类错靠量级检查：75 秒走了 1500m，速度必然在十几到二十几 m/s，若写出 2 m/s（比步行还慢）应当场警觉重算。记住平均速度只认定义，与图线是直是弯无关，先求总位移再除总时间。", "why": "位移 1500m 算对了，最后一步 1500÷75 算错一位得 2，交卷前没做量级检查。", "check_q": "某物体在 0~50s 内的总位移为 1000m，它的平均速度是多大？", "check_a": "1000÷50=20 m/s。", "steps": "1. 先读图求总位移：v-t 图线与时间轴围成的面积就是位移，这题面积为 1500m。\n2. 平均速度只走定义：v̄=总位移÷总时间，与图线是直是弯无关。\n3. 代入 1500÷75，心算拆开：1500÷75=150÷7.5=20 m/s。\n4. 落笔前做量级检查：75s 走 1500m，速度应在 20 m/s 上下；若算出 2 m/s（比走路还慢）立刻重算除法。", "need": ["v-t 图像面积表示位移", "平均速度的定义（总位移÷总时间）", "计算结果的数量级自查"], "points": ["先由 v-t 图面积得总位移 x=1500 m（约3分，与前一问衔接，她这步是对的）", "写平均速度定义式 v̄=x/t=1500/75（约1分）", "算出 20 m/s（约2分；她除成 2，是除法错位丢的分）"], "frame": "图像题落笔两段：第一段写面积求位移的列式→第二段套 v̄=x/t→除法先估量级（1500÷75≈20，不可能是 2）再写结果。图题每问都要留下列式痕迹，只写一个数既丢过程分又查不出错。", "stem": "（10分）一摩托车由静止开始在平直的公路上行驶，其运动过程的 v-t 图像如图所示，求：\n（1）摩托车在 0~20s 这段时间内的加速度大小；\n（2）摩托车在 0~75s 这段时间内的平均速度大小。\n【图像数据：0~20s 内速度由 0 均匀增大到 30 m/s；20~45s 以 30 m/s 匀速行驶；45~75s 速度由 30 m/s 均匀减小到 0】", "img": "phy-14.jpg"}, {"subject": "物理", "question_no": "15(1)", "full_score": 4.0, "got_score": 1.0, "student_answer": "12m/s（无公式）", "std_answer": "12m/s", "error_type": "表述不规范", "knowledge_point": "v=v₀+at公式分（2分）丢了，只拿结果分", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 1s 末的速度。（原卷第 15 题第 (1) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(1)|1", "card_type": "redo", "teach": "刹车题有固定开局：先算停止时间 t₀=v₀/a=18÷6=3s，之后每个问题都拿所问时间跟 3s 比较。1s 小于 3s，车还在运动，直接用速度公式 v=v₀−at=18−6×1=12 m/s。再提醒一个规范问题：她这问结果算对了，却只写结果没写公式，公式分丢了——解答题评分是“公式+代入+结果+单位”四件齐全才给满分，哪怕口算得出也要把 v=v₀−at 写出来。抓手：刹车题第一行永远先写 t₀。", "why": "结果 12 m/s 算对了，但没写公式，只拿到结果分，公式分被丢掉。", "check_q": "汽车以 20 m/s 刹车，加速度大小为 5 m/s²，它的停止时间是多少？", "check_a": "t₀=v₀/a=20÷5=4 s。", "steps": "1. 刹车题固定开局：先算停止时间 t₀=v₀/a=18÷6=3s，写在第一行。\n2. 拿所问时间与 t₀ 比：1s<3s，车还在运动，可以套公式。\n3. 写全公式再代入：v=v₀−at=18−6×1=12 m/s。\n4. 按“公式+代入+结果+单位”四件套落笔，只写结果会丢公式分。", "need": ["匀变速直线运动速度公式 v=v₀+at", "刹车问题停止时间 t₀=v₀/a", "解答题公式分的评分规范"], "points": ["写出速度公式 v=v₀−at（约2分——公式分，她只写结果就丢在这里，只得 1 分）", "代入 v=18−6×1（约1分）", "结果 12 m/s、带单位（约1分）"], "frame": "解答题定式'公式→代入→结果→单位'四件套，每问一段、标上 (1)：哪怕口算就能得出，也先把公式抄下来再算——评分按点给，公式本身就是一个得分点。"}, {"subject": "物理", "question_no": "15(2)", "full_score": 5.0, "got_score": 0.0, "student_answer": "18m", "std_answer": "24m", "error_type": "知识盲区", "knowledge_point": "匀减速位移公式 x=v₀t−½at² 不会用，拼凑答案", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 2s 内的位移。（原卷第 15 题第 (2) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(2)|1", "card_type": "redo", "teach": "先比时间：停止时间 t₀=18÷6=3s，2s 小于 3s，车在这 2s 内一直在动，可以放心套位移公式 x=v₀t−½at²=18×2−½×6×2²=36−12=24 m。记公式的抓手：“初速乘时间，减去半 a t 方”——匀减速的位移就是匀速位移减掉被加速度吃掉的那部分。再教一个验算招：2s 末速度是 6 m/s，平均速度 (18+6)÷2=12 m/s，位移 12×2=24 m，两种算法对上才落笔。她当时拼凑出 18m，就是公式没记牢靠蒙。", "why": "匀减速位移公式不会用，靠拼凑得了 18m。", "check_q": "初速度 10 m/s、加速度大小 2 m/s² 的匀减速运动，3s 内的位移是多少？（停止时间 5s，未停）", "check_a": "x=10×3−½×2×3²=30−9=21 m。", "steps": "1. 先算停止时间 t₀=18÷6=3s，再比：2s<3s，车全程在动，位移公式可以放心用。\n2. 选公式并写全：x=v₀t−½at²（减速取减号）。\n3. 代入：x=18×2−½×6×2²=36−12=24 m。\n4. 换平均速度法验算：2s 末速度 6 m/s，平均速度 (18+6)/2=12 m/s，位移 12×2=24 m，两法一致再落笔。", "need": ["匀变速直线运动位移公式 x=v₀t+½at²", "停止时间与所问时间的比较判断", "用平均速度法验算位移"], "points": ["先作时间判断：2 s<停止时间 3 s，车还没停（约1分）", "写出位移公式 x=v₀t−½at²（约2分）", "分项代入：18×2−½×6×2²=36−12（约1分）", "结果 24 m、带单位（约1分）", "她拼凑出 18 m，公式没成形，整问 0 分"], "frame": "承接 (1) 往下写：先一行判断'2 s<3 s，未停'→列位移公式→两项分开算再相减（不连等、不拼凑）→结果带单位。与上一问共用 v₀、a 的数值，不用重抄题干。"}, {"subject": "物理", "question_no": "15(3)", "full_score": 7.0, "got_score": 0.0, "student_answer": "24m", "std_answer": "27m", "error_type": "审题偏差/知识盲区", "knowledge_point": "**刹车陷阱**：未先算停止时间t₀=v₀/a=3s，直接代t=4s", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 4s 内的位移。（原卷第 15 题第 (3) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(3)|1", "card_type": "redo", "teach": "这是刹车题的标准陷阱，必须先算停止时间再套公式：t₀=v₀/a=18÷6=3s。所问的 4s 大于 3s，车在第 3s 末已经停下，第 4 秒整段是静止的，位移只能按 3s 算：x=v₀²/(2a)=18²÷(2×6)=27 m。她直接把 t=4 代入公式得 24m——位移公式默认车全程在运动，车停了以后公式继续算会让车“倒退”，结果甚至不比 2s 内的位移大，一眼就该看出荒谬。铁律：所问时间超过 t₀，一律用 t₀ 代入，或直接用 v₀²/2a。", "why": "没先算停止时间，直接把 t=4s 套进位移公式得 24m，正中刹车陷阱。", "check_q": "汽车以 15 m/s 刹车，加速度大小 5 m/s²，求刹车 5s 内的位移。", "check_a": "停止时间 t₀=15÷5=3s，小于 5s，x=15²÷(2×5)=22.5 m。", "steps": "1. 先算停止时间 t₀=v₀/a=18÷6=3s，这是刹车题的第一动作。\n2. 拿所问时间比：4s>3s，车在第 3s 末已经停下，第 4 秒位移为零，不能把 t=4 直接代公式。\n3. 改用实际运动时间 3s 算：x=v₀²/(2a)=18²÷(2×6)=27 m（或把 t=3 代入位移公式）。\n4. 反常识自查：若代 t=4 得 24m，和 2s 内的位移一样多，车停后位移不可能停滞甚至变小，出现这种结果就是中了刹车陷阱。", "need": ["刹车陷阱与停止时间 t₀=v₀/a", "速度位移公式 v²−v₀²=2ax", "位移随时间单调不减的常识校验"], "points": ["先算停止时间 t₀=v₀/a=18÷6=3 s（约2分，本题的题眼）", "判断 4 s>3 s，车在 3 s 时已停下（约1分）", "改用总位移公式 x=v₀²/(2a)=18²/(2×6)=27 m（或按 t=3 s 代位移公式）（约3分）", "结果 27 m、带单位（约1分）", "直接把 4 s 代入位移公式得 24 m 是陷阱答案——她就是这样丢的整问 7 分"], "frame": "刹车题收尾问的固定动作：动笔前单起一行算 t₀ 并写出与所问时间的比较→判断已停就换总位移公式→再按公式、代入、结果、单位落笔。凡刹车/减速到停的问题，第一行永远先写 t₀，后面几问都回头看它。"}, {"subject": "生物", "question_no": "1", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "细胞学说被列入19世纪自然科学的三大发现之一。下列相关叙述正确的是（ ）①认为动、植物都是由细胞发育而来的 ②认为新细胞是由老细胞分裂产生的 ③把动植物分为真核细胞和原核细胞 ④主要阐明了动物和植物的统一性 ⑤揭示了生物界和非生物界的统一性 ⑥使生物学研究进入分子水平", "paper_cause": "概念不清", "key": "生物|1|1", "card_type": "redo", "options": {"A": "①③⑤⑥", "B": "①②④", "C": "①②③④⑥", "D": "①②③⑤"}, "teach": "细胞学说只讲三件事：一切动植物都由细胞发育而来、细胞是一个相对独立的单位、新细胞由老细胞分裂产生；它的意义是揭示动植物的统一性（④对），使生物学研究进入细胞水平。三个高频陷阱要划清：细胞学说不涉及真核/原核分类（③错，那是后来按细胞结构分的）；揭示的是生物界内部的统一性，不是生物界与非生物界之间（⑤错）；进入的是细胞水平不是分子水平（⑥错，分子水平始于DNA双螺旋发现）。只含①②④的B才对。", "why": "没把细胞学说的内容清单记死，③⑤⑥每个都觉得“好像说过”就全放进了选项。", "check_q": "“细胞学说使生物学研究进入分子水平”这句话错在哪里？", "check_a": "应为进入细胞水平；分子水平始于20世纪DNA双螺旋结构的发现。", "steps": "1. 先圈设问的范围：本题只问细胞学说本身说了什么、意义是什么，凡超出这个范围的表述一律先打问号\n2. 把细胞学说的三点内容逐条默出来：一切动植物由细胞发育而来、细胞是相对独立的单位、新细胞由老细胞分裂产生——选项里的说法先对这三条\n3. 再验意义类表述：细胞学说揭示的是动植物（生物界内部）的统一性、使研究进入细胞水平\n4. 最后专杀三个偷换：真核/原核分类（学说没提过）、生物界与非生物界的统一性（偷换范围）、分子水平（那是DNA双螺旋时代的事），含这三类词的选项直接排除", "need": ["细胞学说的主要内容（三点）与提出者", "细胞学说的意义：揭示动植物统一性、研究进入细胞水平", "真核细胞与原核细胞分类的提出背景", "DNA双螺旋结构与分子生物学的兴起"]}, {"subject": "生物", "question_no": "3", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "生物学实验常呈现“五颜六色”的变化。下列实验中溶液颜色变化叙述正确的是（ ）", "paper_cause": "概念不清", "key": "生物|3|1", "card_type": "redo", "options": {"A": "在氨基酸溶液中加入双缩脲试剂，混匀后变成紫色", "B": "在淀粉溶液中加入碘液，混匀后变成蓝色", "C": "在花生匀浆中加入苏丹III染液，混匀后由橘黄色变成红色", "D": "在新鲜的梨汁中加入斐林试剂，混匀后在加热条件下由无色变成砖红色"}, "teach": "显色反应按“试剂本身颜色＋反应后颜色”成对记：双缩脲试剂检测的是蛋白质（含肽键）呈紫色，氨基酸没有肽键，加进去不变紫，A错；淀粉遇碘变蓝，B对；苏丹III染液本身就是橘黄色，它把脂肪染成橘黄色，C说“变成红色”错了（染成红色的是苏丹IV），错在方向；斐林试剂本身是浅蓝色而不是无色，D错在起点颜色，且斐林试剂必须水浴加热才出现砖红色沉淀。四个选项里只有B的起点、终点颜色全对。", "why": "选了C，把苏丹III染脂肪的颜色记反了——苏丹III是橘黄色，红色是苏丹IV。", "check_q": "检测花生种子中的脂肪用苏丹III染液，脂肪颗粒被染成什么颜色？", "check_a": "橘黄色（若用苏丹IV染液则为红色）。", "steps": "1. 先把每种试剂的“本色”和“反应后颜色”在脑子里列表：双缩脲—紫色、碘液—蓝色、苏丹III—橘黄色、斐林试剂—砖红色沉淀\n2. 逐个选项验两头：起点颜色对不对（试剂本身什么色）、终点颜色对不对（反应后变成什么色），错一头就排除\n3. 再验对象对不对：双缩脲只认肽键（蛋白质），氨基酸没有肽键不变色\n4. 特别留意“由X色变成Y色”的方向陷阱：苏丹III本身就是橘黄色、把脂肪染成橘黄色，写“变成红色”的是苏丹IV", "need": ["双缩脲试剂鉴定蛋白质的原理（肽键呈紫色）", "斐林试剂鉴定还原糖的条件与现象（水浴加热、砖红色沉淀）", "苏丹III与苏丹IV染脂肪的颜色区别", "淀粉遇碘变蓝的显色反应"]}, {"subject": "生物", "question_no": "6", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "细胞是生命活动的基本单位，下列事实或证据不符合这一观点的是（ ）", "paper_cause": "概念不清", "key": "生物|6|1", "card_type": "redo", "options": {"A": "变形虫是单细胞生物，能进行摄食与运动", "B": "荷花的生长和发育离不开细胞的分裂和分化", "C": "当敌害来临时，丹顶鹤惊飞需要一系列细胞协同配合", "D": "离体的叶绿体在一定条件下能释放氧气"}, "teach": "这道题问“不符合”，要找的是反例。A、B、C都是正面证据：变形虫靠一个细胞完成摄食和运动，荷花的生长发育靠细胞分裂和分化，丹顶鹤惊飞靠一系列细胞协同配合，全都在说生命活动离不开细胞。D是陷阱：离体的叶绿体已经脱离了完整细胞，却还能进行光合作用放出氧气，说明某些生命活动可以在没有完整细胞的情况下进行，恰恰与观点唱反调。破题抓手：看到“不符合、例外”，先锁定那个“脱离细胞还能活动”的选项。", "why": "选了C，没看出C仍是细胞协同配合的正面例证，漏掉了D这个真正的反例。", "check_q": "“离体线粒体在适宜条件下能消耗氧气”，这支持还是违背“细胞是生命活动的基本单位”？", "check_a": "构成例外（违背）：它脱离完整细胞仍能进行呼吸作用。", "steps": "1. 先看题眼：问的是“不符合”，即找反例，和平时找正确项的方向相反，先把心态调过来\n2. 逐个选项判断立场：它是在证明“生命活动离不开细胞”，还是在举“脱离细胞也能进行”的例子\n3. 变形虫摄食、荷花发育、丹顶鹤惊飞都是细胞在干活，属于正面证据，排除\n4. 锁定那个“离体的”结构：叶绿体离开完整细胞还能放氧，正好与观点唱反调，就是要选的反例", "need": ["细胞是生命活动基本单位的含义", "单细胞生物独立完成生命活动的特点", "细胞器离体实验（如离体叶绿体光合作用）的结论边界"]}, {"subject": "生物", "question_no": "12", "full_score": 2.0, "got_score": 0.0, "student_answer": "D", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "生物|12|1", "card_type": "concept", "teach": "病毒是本章最爱考的分类陷阱：病毒没有细胞结构，只由蛋白质外壳和内部的一种核酸（DNA或RNA）构成，它既不属于原核生物，也不属于真核生物，是单独一类。病毒没有独立代谢的能力，必须寄生在活细胞内才能增殖，离开细胞就只是没有生命的化学物质。判断抓手：凡是说“病毒有细胞膜、核糖体、能独立代谢”的全错；诺如病毒、噬菌体、HIV都一样无细胞结构。原核生物指的是细菌、蓝藻这类有细胞但无核膜的生物，病毒不在其中。", "why": "把诺如病毒当成了原核生物，没抓住“病毒无细胞结构”这条分界线。", "check_q": "噬菌体属于原核生物吗？它由什么构成？", "check_a": "不属于。病毒无细胞结构，由蛋白质外壳和一种核酸（噬菌体为DNA）构成。", "steps": "1. 先给选项里的生物挨个归类：细菌、蓝藻归原核；动植物、真菌归真核\n2. 遇到病毒单独拎出来：先问一句“它有细胞结构吗”——没有，直接排除出原核、真核两边\n3. 再核对病毒的构成：蛋白质外壳＋一种核酸（DNA或RNA），没有细胞膜、核糖体，不能独立代谢\n4. 凡选项把病毒说成原核生物、或说它有核糖体能独立增殖的，一律判错", "need": ["病毒的结构组成（蛋白质外壳与一种核酸）", "病毒的增殖方式：必须寄生在活细胞内", "原核生物的范围（细菌、蓝藻、支原体等）", "原核细胞与真核细胞的划分依据（有无核膜包被的细胞核）"], "stem": "每年10月到次年3月是诺如病毒感染高发时期，诺如病毒是引起急性胃肠炎常见的病原体之一，感染者的临床症状主要为恶心、呕吐、发热、腹痛和腹泻。下列有关叙述错误的是（ ）\nA. 诺如病毒必须寄生在活细胞内，其离开细胞不能进行增殖\nB. 诺如病毒和支原体都属于单细胞原核生物，具有核糖体和拟核等结构\nC. 诺如病毒不属于生命系统的结构层次，但参与某些层次生命系统的构成\nD. 适量饮酒不能预防诺如病毒的感染，要科学预防传染病"}, {"subject": "生物", "question_no": "17", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "某小组将样液脱色处理后打成匀浆，用斐林试剂鉴定其含糖情况。下列叙述错误的是（ ）", "paper_cause": "概念不清", "key": "生物|17|1", "card_type": "redo", "options": {"A": "脱色处理的目的是为了排除色素等无关变量对实验结果的干扰", "B": "使用斐林试剂时需将甲液和乙液等量混匀后再注入待测样液", "C": "为检测还原糖浓度，可增设多组不同浓度的蔗糖溶液作为颜色对照", "D": "斐林试剂通过简单处理后，也能用于鉴定待测样液中的蛋白质"}, "teach": "本题选“错误”项，逐个验：A脱色是为排除材料自身颜色的干扰，对；B斐林试剂必须甲液、乙液等量混合后立即使用，对；D斐林试剂经简单处理可转化为双缩脲试剂鉴定蛋白质，也是教材结论。C错：蔗糖是非还原糖，与斐林试剂不会产生砖红色反应，做还原糖定量的颜色对照必须用已知浓度的葡萄糖溶液。抓手是还原糖名单，只记三个：葡萄糖、果糖、麦芽糖；蔗糖、淀粉、纤维素都不是还原糖。", "why": "放过了“C用蔗糖作还原糖对照”这个真错误，反而怀疑起B项的正确用法。", "check_q": "下列糖中属于还原糖的是哪一个：蔗糖、淀粉、麦芽糖、纤维素？", "check_a": "麦芽糖。蔗糖、淀粉、纤维素均为非还原糖。", "steps": "1. 先确认本题选的是“错误”项，逐项验时心里默认其余三项要站得住\n2. 抓住斐林试剂的鉴定对象：它只认还原糖，先把还原糖名单过一遍——葡萄糖、果糖、麦芽糖\n3. 验C项的对照设计：要给还原糖定量做颜色对照，对照液必须本身是还原糖，蔗糖是非还原糖、不产生砖红色，C项设计从根上错\n4. 其余项按规范核对：脱色是排除材料颜色干扰（对）；斐林试剂甲乙液等量混匀现配现用（对）；斐林试剂调整后可作双缩脲试剂用（对）", "need": ["还原糖与非还原糖的判定（葡萄糖、果糖、麦芽糖为还原糖）", "斐林试剂的使用方法（等量混合、水浴加热）", "检测实验中排除材料自身颜色干扰的处理", "斐林试剂与双缩脲试剂的成分关系"]}, {"subject": "生物", "question_no": "18", "full_score": 4.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "生物|18|1", "card_type": "concept", "teach": "蛋白质变性要和水解分清：变性是高温、强酸、强碱、重金属盐等使蛋白质的空间结构被破坏、功能丧失（如高温灭菌、酒精消毒），但肽键并不斷裂，氨基酸的排列顺序不变；肽键断裂是水解，要靠酶或强酸强碱长时间作用。另一个易混点是盐析：加浓盐溶液使蛋白质溶解度降低而析出，空间结构不变，加水还能复溶，是可逆的。抓手：变性动的是“形状”不动肽键，盐析连形状也不动。", "why": "以为蛋白质变性就是肽链被打断，没分清变性（空间结构）与水解（肽键）。", "check_q": "鸡蛋煮熟是蛋白质变性，煮熟过程中肽键断裂了吗？熟蛋能再变回液态吗？", "check_a": "肽键没有断裂（破坏的是空间结构）；变性不可逆，不能变回液态。", "steps": "1. 先给“蛋白质失去活性”分清两条路：是空间结构被破坏（变性），还是肽键被切断（水解），两者后果完全不同\n2. 看题干给的条件：高温、强酸、强碱、重金属盐、酒精——这些动的是空间结构，走变性\n3. 再判可逆性：变性不可逆（煮熟的鸡蛋回不去）；若只是加盐析出、加水能复溶，那是盐析，什么都没破坏\n4. 落笔前回查一句：变性后氨基酸顺序不变、肽键不断，凡说“肽链断裂、氨基酸被破坏”的选项判错", "need": ["蛋白质变性的概念、条件与不可逆性", "蛋白质水解与变性的区别（肽键是否断裂）", "盐析的原理与可逆性", "蛋白质空间结构与功能的关系"], "stem": "肠粉是广东的传统特色美食之一。以米浆蒸制而成的薄粉皮包裹着猪肉、牛肉、虾仁等馅料，形态晶莹剔透，淋上以豉油为主的酱汁，色泽诱人，味道鲜香，口感爽滑。下列有关叙述错误的是（ ）\nA. 牛肉细胞中含量最多的有机物是蛋白质\nB. 虾仁中的蛋白质在蒸制过程中由于肽键的断裂而变得伸展、松散，容易消化\nC. 粉皮中的淀粉需在消化道内水解成葡萄糖才能被细胞吸收\nD. 猪肉中含有的大量元素钙和磷，可以促进人体骨骼的生长以及牙齿的发育"}, {"subject": "生物", "question_no": "20", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "某种脑啡肽具有镇痛作用，它的基本组成单位是氨基酸。结合该脑啡肽的结构（由5个氨基酸组成，其中一种氨基酸重复出现），下列叙述正确的是（ ）", "paper_cause": "概念不清", "key": "生物|20|1", "card_type": "redo", "options": {"A": "该分子在合成时，脱去的水分子中的氧来自羧基", "B": "该分子是由5种氨基酸脱水缩合而成，称为五肽", "C": "该分子在合成时，相对分子质量减少90", "D": "该分子经高温加热后不会丧失其功能"}, "teach": "这类题按固定顺序拆：先数个数，再数种类，最后算脱水。脑啡肽含5个氨基酸、1条肽链，是五肽；但数“种类”要看R基——5个氨基酸中甘氨酸重复出现，R基只有4种不同，所以是4种氨基酸，“个数≠种类”是第一陷阱，B错。脱水数＝氨基酸数－肽链数＝5－1＝4，相对分子质量减少4×18＝72，不是90，C错。脱去的水中氧来自羧基，A对。高温会破坏蛋白质空间结构使其失活，D错。", "why": "把“5个氨基酸”直接等同于“5种氨基酸”，没数R基去重，掉进个数与种类的陷阱。", "check_q": "某六肽由6个氨基酸组成，其中亮氨酸出现2次、其余各1次，该肽含几种氨基酸？脱去几个水分子？", "check_a": "5种氨基酸；脱去5个水分子（脱水数＝6－1＝5）。", "steps": "1. 先数个数：结构里氨基酸残基有几个，就是几肽、由几个氨基酸缩合而成\n2. 再数种类：逐个看R基，R基相同的算同一种——个数减去重复的，才是种类数，这一步最容易被跳过\n3. 再算脱水：脱水数＝氨基酸数－肽链数，相对分子质量减少量＝脱水数×18\n4. 最后验功能类表述：肽链经高温空间结构被破坏会失活，凡说“加热不影响功能”的判错", "need": ["氨基酸种类由R基决定（21种氨基酸的区别在R基）", "脱水缩合的计算：脱水数＝氨基酸数－肽链数", "多肽相对分子质量变化的计算", "高温使蛋白质变性失活"], "img": "bio-20.jpg"}, {"subject": "生物", "question_no": "21-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "\"有无细胞结构\"（字迹潦草，疑为\"无细胞结构\"）", "std_answer": "有细胞结构", "error_type": "概念混淆", "knowledge_point": "病毒无细胞结构 vs 蓝藻等细胞生物有细胞结构（据答案反推）", "note": "", "stem": "显微镜下观察到的酵母菌、蓝细菌、植物细胞、草履虫、细菌等都是细胞生物，它们与病毒的最大区别是它们具有____。", "paper_cause": "记忆缺失", "key": "生物|21-(1)|1", "card_type": "redo", "teach": "细胞生物与病毒的分界线只有一条：有没有细胞结构。酵母菌、蓝藻、细菌、草履虫无论原核还是真核，都有细胞膜、细胞质和核糖体，是细胞生物；病毒只有蛋白质外壳加核酸，没有细胞结构，必须寄生在活细胞里才能增殖。这类填空先看清主语：问“它们（细胞生物）与病毒的区别”填“具有细胞结构”，问“病毒的特点”才填“无细胞结构”，主语看反、答案就反。", "why": "没看清主语是“它们（细胞生物）”，按病毒的角度作答，方向正好反了。", "check_q": "病毒与细菌最根本的区别是什么？", "check_a": "病毒没有细胞结构；细菌有细胞结构（属于原核细胞）。", "steps": "1. 先看清主语是谁：这道空问的是“它们（酵母菌、蓝细菌等细胞生物）与病毒的区别”，答案要站在细胞生物一侧写\n2. 找两类生物最根本的那条分界线：有没有细胞结构，其余差别（大小、寄生与否）都是次要的\n3. 按主语方向落笔：细胞生物“具有细胞结构”；若主语换成病毒，才写“无细胞结构”\n4. 写完回读一遍题干，确认答案和主语没有反向", "need": ["病毒无细胞结构的基本特征", "细胞生物的共同结构（细胞膜、细胞质、核糖体）", "原核生物与真核生物同属细胞生物"], "points": ["填\"有细胞结构\"（主语是酵母菌、蓝藻等细胞生物，它们与病毒的最大区别就是有细胞结构）", "写成\"无细胞结构\"或\"有无细胞结构\"都不得分——那是病毒那一侧的特点，方向反了"], "frame": "先看清主语问的是哪一侧：设问\"它们与病毒的最大区别是它们___\"，主语是细胞生物，就填细胞生物的特征；再落笔写全\"有细胞结构\"五字，不写含糊的\"有无\"。"}, {"subject": "生物", "question_no": "21-(2)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "BDE", "std_answer": "B、E", "error_type": "粗心多选", "knowledge_point": "原核生物举例，多选了D（据答案反推）", "note": "", "stem": "如图是显微镜下观察到的几种细胞或组织图像（A 光学显微镜视野、D 小肠上皮细胞[部分文字不清]，图中 A-E 为酵母菌、蓝细菌、植物细胞、草履虫、细菌等）。(1)材料中各种生物形态差异很大，从结构上来看，它们与病毒的最大区别是它们＿＿。(2)科学家依据＿＿将细胞分为原核细胞和真核细胞，其中属于原核生物的是＿＿，与真核细胞结构上的统一性表现在都具有＿＿（至少 2 点）。(4)过量繁殖会引起\"水华\"的是＿＿（填标号），该细胞中含有＿＿，因此能利用光能合成有机物，故其是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(2)-②|1", "card_type": "concept", "teach": "判断原核生物抓两点。一看名单：细菌（乳酸菌、杆菌、球菌等）、蓝藻（蓝细菌、颤藻、念珠藻）、支原体、衣原体、放线菌。二看反例：酵母菌、草履虫、衣藻以及一切动植物细胞都是真核。原题图中D是小肠上皮细胞，属动物细胞、有成形的细胞核，她多选了D。记忆口诀：“细菌蓝藻支衣放，原核名单就这几家”。特别提醒：带“菌”字的不全是原核（酵母菌、霉菌是真菌，属真核），带“藻”字的也不全（衣藻是真核，只有蓝藻是原核）。", "why": "多选了D，把小肠上皮细胞（真核）也划进了原核生物。", "check_q": "下列哪些是原核生物：乳酸菌、酵母菌、颤藻、草履虫？", "check_a": "乳酸菌和颤藻是原核生物；酵母菌、草履虫是真核生物。", "steps": "1. 先把原核生物的标准名单默出来：细菌、蓝藻（蓝细菌）、支原体、衣原体、放线菌\n2. 逐个材料对名单：名单里有的留下，不在名单上的一律剔除，不凭“长得像细菌”猜\n3. 专防两类伪装者：带“菌”字的真菌（酵母菌、霉菌是真核）、动物植物的细胞（小肠上皮细胞等是真核）\n4. 多选题最后逐个复核一遍每个选项的归类再定稿，多选一个全题丢分", "need": ["原核生物的常见类群（细菌、蓝藻、支原体、衣原体、放线菌）", "真菌属于真核生物（酵母菌、霉菌）", "动植物细胞均为真核细胞", "蓝藻即蓝细菌的归类"], "points": ["选出 B（细菌类）——原核生物，约1分", "选出 E（蓝细菌）——原核生物，约1分", "不选 D（小肠上皮细胞，动物细胞、真核）——多选 D 本小问不得分", "不选酵母菌、草履虫等真核生物——选错同样倒扣到0分"], "frame": "先默念原核名单（细菌、蓝藻、支原体、衣原体、放线菌）→逐个图对号：带细胞核/动物植物细胞一律划掉→只圈名单内的→最后回查有没有把\"带菌字、藻字的真核\"（酵母菌、衣藻）误圈。", "img": "bio-21.jpg"}, {"subject": "生物", "question_no": "21-(2)-③", "full_score": 2.0, "got_score": 2.0, "student_answer": "DNA和细胞膜", "std_answer": "细胞膜、细胞质（或核糖体）、都以DNA作为遗传物质", "error_type": "—（教师给满分；但缺\"细胞质/核糖体\"项，存疑）", "knowledge_point": "细胞的统一性（据答案反推）", "note": "", "stem": "如图是显微镜下观察到的几种细胞或组织图像（A 光学显微镜视野、D 小肠上皮细胞[部分文字不清]，图中 A-E 为酵母菌、蓝细菌、植物细胞、草履虫、细菌等）。(1)材料中各种生物形态差异很大，从结构上来看，它们与病毒的最大区别是它们＿＿。(2)科学家依据＿＿将细胞分为原核细胞和真核细胞，其中属于原核生物的是＿＿，与真核细胞结构上的统一性表现在都具有＿＿（至少 2 点）。(4)过量繁殖会引起\"水华\"的是＿＿（填标号），该细胞中含有＿＿，因此能利用光能合成有机物，故其是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(2)-③|1", "card_type": "concept", "teach": "原核细胞与真核细胞的“统一性”要背标准件：都有细胞膜、都有细胞质、都有核糖体、都以DNA为遗传物质。答“至少两点”的空，优先写细胞膜和细胞质或核糖体——只写DNA容易被阅卷按“结构不完整”扣分，她写的“DNA和细胞膜”就漏了细胞质、核糖体。与统一性成对记的是“差异性”：有无以核膜为界限的细胞核，原核细胞只有拟核。统一性写共有结构，差异性只写核，这对概念要成对背。", "why": "只写了DNA和细胞膜，漏掉细胞质、核糖体，统一性的标准表述没背全。", "check_q": "原核细胞与真核细胞的统一性表现在哪几方面（至少写两点）？", "check_a": "都有细胞膜、细胞质和核糖体；都以DNA作为遗传物质（任写两点）。", "steps": "1. 先分清问的是“统一性”还是“差异性”：统一性写两者共有的东西，差异性才写细胞核有无\n2. 把共有结构按“膜—质—器—遗传物质”的顺序数全：细胞膜、细胞质、核糖体、都以DNA为遗传物质\n3. 题目要求至少两点时，优先写结构类（细胞膜、细胞质或核糖体），只写DNA一项容易被判不全\n4. 落笔前和差异性对照检查：别把“有无核膜”这类差异写进统一性的空里", "need": ["原核细胞与真核细胞的统一性表现", "原核细胞与真核细胞的差异性（有无核膜包被的细胞核、拟核）", "核糖体是原核与真核共有的细胞器", "DNA是两类细胞共同的遗传物质"], "points": ["写出\"细胞膜\"——统一性的共有结构之一", "写出\"细胞质（或核糖体）\"——她漏了这一项，少一点约扣1分", "写出\"都以 DNA 作为遗传物质\"——可作第三点补充"], "frame": "先调\"统一性标准件\"清单（细胞膜、细胞质、核糖体、DNA 为遗传物质）→题目要两点就优先写结构类两点（细胞膜+细胞质/核糖体）→落笔后数一遍点数够不够。", "img": "bio-21.jpg"}, {"subject": "生物", "question_no": "21-(3)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "叶绿体", "std_answer": "藻蓝素和叶绿素", "error_type": "知识盲区", "knowledge_point": "蓝藻含藻蓝素和叶绿素，无叶绿体（典型易错点）", "note": "", "stem": "过量繁殖会引起“水华”的蓝细菌（蓝藻）细胞中含有____（色素），因此能利用光能合成有机物，是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(3)-②|1", "card_type": "redo", "teach": "蓝藻能光合作用靠的是色素而不是叶绿体：蓝藻是原核生物，细胞里没有任何叶绿体，它的光合色素是藻蓝素和叶绿素，分布在光合片层上直接吸收光能。这是全章最经典的陷阱——“能光合作用”不等于“有叶绿体”。对比记牢：真核的植物细胞靠叶绿体进行光合作用，原核的蓝藻靠藻蓝素加叶绿素。抓手：原核细胞唯一的细胞器是核糖体，其余一切功能都由细胞膜或细胞质中的成分完成。", "why": "填了“叶绿体”，忘了蓝藻是原核生物、根本没有叶绿体。", "check_q": "蓝藻与水绵都能进行光合作用，它们的光合场所分别是什么？", "check_a": "蓝藻无叶绿体，靠细胞质中的藻蓝素和叶绿素；水绵在叶绿体中进行。", "steps": "1. 先定身份：蓝细菌是原核生物，原核细胞唯一的细胞器是核糖体——填空里出现“叶绿体”先警惕\n2. 再想它凭什么能光合作用：靠的不是细胞器，而是细胞里的光合色素\n3. 把色素名写全：藻蓝素和叶绿素，分布在光合片层上吸收光能\n4. 和真核藻类对照收尾：水绵靠叶绿体，蓝藻靠色素，“能光合≠有叶绿体”是这类空的固定考法", "need": ["蓝藻的光合色素（藻蓝素和叶绿素）", "原核细胞的细胞器只有核糖体", "原核生物无叶绿体等膜性细胞器", "自养生物的判断依据"], "points": ["写\"藻蓝素\"——蓝藻特有色素，缺一不可", "写\"叶绿素\"——与藻蓝素并列，两点齐全才得满分", "写\"叶绿体\"得0分：蓝藻是原核生物，根本没有叶绿体"], "frame": "先定性：蓝藻=原核生物→原核细胞唯一的细胞器只有核糖体，一切\"叶绿体、线粒体\"先排除→再想它靠什么光合：色素（藻蓝素+叶绿素）→两个色素都写上。"}, {"subject": "生物", "question_no": "22-(1)-①", "full_score": 2.0, "got_score": 0.0, "student_answer": "淀粉", "std_answer": "水", "error_type": "审题偏差/知识盲区", "knowledge_point": "种子晒干失去的主要是水（据答案反推）", "note": "", "stem": "青萝卜细胞多汁、营养丰富。青萝卜细胞中含量最多的化合物是____。", "paper_cause": "记忆缺失", "key": "生物|22-(1)-①|1", "card_type": "redo", "teach": "“含量最多”要先分清问法：活细胞（鲜重）中含量最多的化合物永远是水，约占85%；含量最多的有机物才是蛋白质；干重中含量最多的化合物也是蛋白质。青萝卜是多汁的活细胞，问的又是“化合物”，答案锁定水。她答“淀粉”是把“重要的储能物质”错当成“含量最多的化合物”。抓手三连：鲜重问化合物答水，问有机物答蛋白质，问元素答O（氧）。", "why": "把储能物质淀粉当成了含量最多的化合物，没抓住“活细胞水最多”这条基准线。", "check_q": "种子干重中含量最多的化合物是什么？鲜活细胞中含量最多的元素是什么？", "check_a": "蛋白质；氧（O）。", "steps": "1. 先分清题干问的是鲜重还是干重、问的是化合物还是有机物——四个问法四个答案，先定位\n2. 本题是活细胞（鲜重）问化合物：基准线直接锁定——含量最多的化合物永远是水\n3. 排除干扰项：淀粉是储能物质、蛋白质是有机物之最，都不是本题问的“化合物之最”\n4. 顺手把配套结论过一遍防串：鲜重元素最多是O，干重化合物最多是蛋白质", "need": ["活细胞中含量最多的化合物是水", "鲜重与干重下含量最多化合物的区别", "细胞中含量最多的有机物是蛋白质", "鲜重时含量最多的元素是氧"], "points": ["填\"水\"——活细胞（鲜重）中含量最多的化合物，约占85%", "答\"淀粉/蛋白质\"不得分：问的是化合物总量第一，不是储能物质；含量最多的有机物才是蛋白质"], "frame": "先分问法：鲜重问\"化合物\"→水；问\"有机物\"→蛋白质；问\"元素\"→O→本题是活的多汁细胞问化合物，直接锁定\"水\"。"}, {"subject": "生物", "question_no": "22-(2)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "无机物", "std_answer": "无机盐", "error_type": "概念混淆", "knowledge_point": "无机物包括水和无机盐，此处应为无机盐", "note": "", "stem": "把晒干的小麦种子放在试管中点燃，直至燃成灰烬，此灰烬主要是____。", "paper_cause": "记忆缺失", "key": "生物|22-(2)-②|1", "card_type": "redo", "teach": "种子点燃，烧掉的是有机物——糖类、脂质、蛋白质受热分解成气体散失；剩下的灰烬是烧不掉的部分。而种子里的水在晒干时已经散失，灰烬里不可能有水，所以灰烬只能是无机盐。概念链要分清：无机物包括水和无机盐两类，题目问“灰烬”时水已被排除，答案必须落到无机盐。她答“无机物”范围偏大，阅卷按标准答案给分，这类空要答到最具体的层级。", "why": "答了大概念“无机物”，没缩小到灰烬的实际成分“无机盐”。", "check_q": "晒干种子点燃后的灰烬中还能找到水吗？为什么？", "check_a": "不能。水在晒干时已散失；灰烬只剩无机盐。", "steps": "1. 先顺着实验过程走一遍：晒干先去掉什么（水），点燃又烧掉什么（有机物）\n2. 剩下没走的才是灰烬：水早已散失、有机物烧成气体，能留下的只有烧不掉的无机盐\n3. 警惕概念层级：无机物包括水和无机盐两类，题目问具体成分时要答到最细一级，不能用大概念糊弄\n4. 落笔写“无机盐”，并回头确认水已被前面的步骤排除", "need": ["细胞中无机物的组成（水和无机盐）", "种子晒干失去的主要是自由水", "有机物燃烧分解、无机盐不能燃烧的性质"], "points": ["填\"无机盐\"——种子燃烧后的灰烬成分", "答\"无机物\"不得分：范围太大，水也是无机物但晒干/燃烧后不在灰烬里，必须答到最具体层级"], "frame": "先走排除链：灰烬=烧不掉的→有机物烧成气体排除→水在晒干时已散失排除→只剩\"无机盐\"→落笔写最具体的词，不写大概念。"}, {"subject": "生物", "question_no": "22-(3)", "full_score": 2.0, "got_score": 2.0, "student_answer": "自由水含量", "std_answer": "自由水与结合水的比例", "error_type": "—（教师给满分；与标准表述有出入，存疑）", "knowledge_point": "细胞代谢强弱的影响因素（据答案反推）", "note": "", "stem": "概念辨析：细胞的代谢强弱与细胞内哪项指标有密切关系？", "paper_cause": "记忆缺失", "key": "生物|22-(3)|1", "card_type": "concept", "teach": "细胞代谢强弱看的不是自由水的绝对含量，而是自由水与结合水的比值：比值越大，自由水相对越多，代谢越旺盛，但抗逆性越差；比值越小，如休眠的种子，代谢弱而抗逆性强。种子晒得不够干就入仓会发热霉烂，就是因为自由水比例高、呼吸作用旺盛放热。她写“自由水含量”意思接近，标准表述应是“自由水与结合水的比值”。配套记：种子萌发时比值上升，晒干储藏时比值下降。", "why": "只答了自由水含量，没写出决定代谢强弱的是自由水与结合水的比值。", "check_q": "休眠的种子和萌发的种子，哪一个自由水/结合水的比值更大？", "check_a": "萌发的种子比值更大（代谢旺盛）；休眠种子比值小、抗逆性强。", "steps": "1. 先抓住关键词“代谢强弱”：代谢看的不是水的总量，而是两种水的相对比例\n2. 把规律默出来：自由水与结合水的比值越大，代谢越旺盛、抗逆性越差；比值越小正相反\n3. 用生活实例自检：萌发种子比值大、休眠种子比值小，能对上就说明方向没反\n4. 落笔写全称“自由水与结合水的比值”，只写“自由水含量”属于答偏", "need": ["自由水与结合水的概念及相互转化", "自由水/结合水比值与代谢旺盛程度的关系", "比值与抗逆性的关系（种子萌发与休眠的实例）"], "points": ["写出\"自由水与结合水的比例（比值）\"——决定代谢强弱的是比值，不是自由水的绝对含量（本空老师已给满分，但阅卷标准口径以\"比值\"为准）", "只写\"自由水含量\"按严口径约扣一半：漏了\"与结合水的比例\"这个核心"], "frame": "先想原理：代谢旺盛程度看自由水相对占比→落笔必须出现\"比值/比例\"字样→再顺手自查方向（比值大代谢旺、抗逆性差）。"}, {"subject": "生物", "question_no": "22-(4)", "full_score": 2.0, "got_score": 0.0, "student_answer": "在细胞中的含量（字迹潦草）", "std_answer": "作为良好溶剂", "error_type": "知识盲区", "knowledge_point": "自由水的功能：良好溶剂、参与反应、运输", "note": "", "stem": "青萝卜细胞多汁，糖等多种物质溶解于水中，这说明细胞中水的功能是____。", "paper_cause": "记忆缺失", "key": "生物|22-(4)|1", "card_type": "redo", "teach": "自由水的功能背三条：①良好的溶剂，许多物质溶解在水中进行运输和反应；②参与化学反应，如光合作用、呼吸作用；③为细胞提供液体环境、运送营养物质和废物。做这类题的方法是先把功能清单背熟，再用题干关键词对号入座：本题题干说的是“溶解于水中”，直接对应第①条“水是细胞内良好的溶剂”。她这空写成了“在细胞中的含量”，把功能题答成了含量题，是审题时没抓“说明水的功能”这个问法。", "why": "没从“溶解”这个关键词对到“良好溶剂”，把功能空答成了含量描述。", "check_q": "血液运送氧气和养料，体现了自由水的哪项功能？", "check_a": "运输功能（运送营养物质和代谢废物）。", "steps": "1. 先看题干的问法：问的是“水的功能”，就把自由水功能清单先默出来——良好溶剂、参与反应、运输物质、提供液体环境\n2. 再抓题干给的场景词：“溶解于水中”直接指向清单里的第一条\n3. 把关键词和功能对号入座：溶解→溶剂，流动运送→运输，化学反应消耗水→参与反应\n4. 落笔写“作为细胞内良好的溶剂”，别把功能空写成含量、存在形式等别的维度", "need": ["自由水的生理功能（良好溶剂、参与反应、运输等）", "结合水的功能（细胞结构的重要组成成分）", "自由水与结合水的存在形式区别"], "points": ["写\"作为良好溶剂\"（或\"水是细胞内良好的溶剂，许多物质溶解在其中\"）——与题干\"溶解于水中\"对应", "答含量、状态类描述不得分：本题问的是水的功能，不是含量"], "frame": "先认题型：这是功能题→调自由水功能清单（良好溶剂/参与反应/运输与液体环境）→拿题干关键词\"溶解\"对号入座第①条→原话落笔。"}, {"subject": "生物", "question_no": "23-(1)", "full_score": 3.0, "got_score": 0.0, "student_answer": "文字描述\"一个碳原子上至少连接一个氨基和一个羧基\"（未画结构式）", "std_answer": "画出氨基酸结构通式 H2N—C(R)(H)—COOH", "error_type": "审题偏差/表述不规范", "knowledge_point": "氨基酸的结构通式（要求画图，给文字描述得0分）", "note": "", "stem": "画出组成蛋白质的氨基酸的结构通式，并标出R基。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(1)|1", "card_type": "redo", "teach": "氨基酸结构通式必须能默画：一个中心碳原子上连着四样东西——氨基（-NH2）、羧基（-COOH）、氢（-H）和R基。判断一种物质是不是氨基酸就看两条：至少含一个氨基和一个羧基，并且它们连在同一个碳原子上；R基决定氨基酸的种类，21种氨基酸的差别全在R基。这类题题干写“画出”就必须动笔画图并标出R基，只用文字描述结构特点不得分。审题时看到“画出、写出结构式”，要立刻切换到作图模式。", "why": "题目要求画结构通式，她只用文字描述了特点，没作图、没标R基，直接0分。", "check_q": "某分子有一个氨基和一个羧基，但连在不同的碳原子上，它是组成蛋白质的氨基酸吗？", "check_a": "不是。氨基和羧基必须连在同一个碳原子上（中心碳）。", "steps": "1. 先看题干的动作词：写的是“画出”，就必须动笔画图，文字描述结构特点不得分\n2. 画图从中心碳开始：中间一个C，向四个方向分别连氨基（-NH2)、羧基（-COOH)、氢（-H）和R基\n3. 画完逐项打勾：氨基、羧基是否连在同一个碳上，R基有没有单独标出\n4. 最后用判断标准自检：至少一个氨基和一个羧基、且连在同一碳原子上，才是组成蛋白质的氨基酸", "need": ["氨基酸的结构通式及各基团的写法", "R基决定氨基酸种类", "组成蛋白质氨基酸的判断标准（氨基与羧基连在同一碳原子上）"], "points": ["画出中心碳原子，四个键齐全（图对约1分）", "标全四样：氨基 -NH2、羧基 -COOH、氢 -H 各就其位（约0.5分）", "第四个基团标为 R 基——漏标 R 基约扣0.5分，只用文字描述不得分"], "frame": "看到\"画出/写出结构式\"立刻切作图模式：先画中心 C→四条键分别挂 -NH2、-COOH、-H、R基→画完对照\"至少一个氨基和一个羧基连在同一碳上\"自查一遍。"}, {"subject": "生物", "question_no": "23-(3)-②", "full_score": 1.0, "got_score": 0.0, "student_answer": "51", "std_answer": "49", "error_type": "计算失误/概念不清", "knowledge_point": "脱水数=氨基酸数-肽链数（51-2=49，她直接写了氨基酸总数）", "note": "", "stem": "一个牛胰岛素分子由51个氨基酸脱水缩合而成，含2条肽链。求该分子中的肽键数。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(3)-②|1", "card_type": "redo", "teach": "肽键数有一条万能公式：肽键数＝脱去的水分子数＝氨基酸总数－肽链条数。原理是每形成一个肽键就脱去一分子水，而每条肽链内部的连接数比氨基酸数少1，所以有几条链就少几个肽键。牛胰岛素：51－2＝49个肽键。配套公式一起记：每条肽链至少含1个游离氨基和1个游离羧基。她直接把氨基酸总数51填进去，是没理解“肽链条数要减掉”这一步——公式不是死背的，是数连接点数出来的。", "why": "把氨基酸总数51当成了肽键数，没减去肽链条数2。", "check_q": "某蛋白质由100个氨基酸、3条肽链组成，肽键数和脱水数各是多少？", "check_a": "都是97（100－3）。", "steps": "1. 先从题干抓两个数：氨基酸总数51、肽链条数2，缺一个都算不了\n2. 想清原理再套公式：每条肽链内部的肽键比氨基酸少1，有几条链就少几个——肽键数＝氨基酸数－肽链数\n3. 代入计算：51－2＝49，并记住肽键数永远等于脱去的水分子数\n4. 自检：答案若等于氨基酸总数，说明忘了减肽链数，立刻改", "need": ["肽键数＝脱去水分子数＝氨基酸数－肽链数的公式", "脱水缩合形成肽键的过程", "多条肽链时肽键数的计算"], "points": ["列出公式：脱水数＝肽键数＝氨基酸数－肽链数（写公式约0.5分）", "代入 51－2＝49（结果对得满分1分）", "直接写 51 得0分：没减肽链条数"], "frame": "先从图上数清两个量：氨基酸总数51、肽链条数2→写公式 脱水数=氨基酸数−肽链数→代入计算→答案49。"}, {"subject": "生物", "question_no": "23-(3)-③", "full_score": 2.0, "got_score": 0.0, "student_answer": "882", "std_answer": "888", "error_type": "计算失误", "knowledge_point": "蛋白质相对分子质量计算，有漏项（据答案反推）", "note": "", "stem": "牛胰岛素由51个氨基酸、2条肽链组成，含3个二硫键。求氨基酸形成胰岛素后，相对分子质量比原来减少多少。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(3)-③|1", "card_type": "redo", "teach": "相对分子质量的减少量有两笔账，必须都算：第一笔是脱水缩合，脱去49个水，减少49×18＝882；第二笔是二硫键，每个二硫键由两个-SH脱去2个H形成，减少2，胰岛素有3个二硫键，再减少3×2＝6。合计882＋6＝888。她只算了第一笔得882，漏的正是二硫键这笔小账。抓手：题目只要出现二硫键（-S-S-），相对分子质量计算就要多减“二硫键数×2”；只问肽键数、脱水数时不用管二硫键。", "why": "只算了脱水减少的882，漏掉了3个二硫键形成时脱去的6个H。", "check_q": "某肽链含20个氨基酸、形成1个二硫键，形成后相对分子质量比原来减少多少？", "check_a": "脱水19个减19×18＝342，二硫键减2，合计减少344。", "steps": "1. 先列账本：形成蛋白质时相对分子质量的减少来自两笔——脱水缩合脱的水、二硫键形成脱的氢，题目出现二硫键就必须记第二笔\n2. 算第一笔：脱水数＝51－2＝49，减少49×18＝882\n3. 算第二笔：每个二硫键由两个-SH脱去2个H，减少2；3个二硫键共减少6\n4. 两笔相加：882＋6＝888；交卷前检查题干有没有“二硫键”字样，有就别漏账", "need": ["蛋白质相对分子质量的计算（减去脱去水的质量）", "二硫键的形成过程（两个-SH脱氢）及对相对分子质量的影响", "肽键数与脱水数的计算"], "points": ["第一笔账：脱水减少 49×18＝882（约1分）", "第二笔账：3 个二硫键形成脱 6 个 H，再减少 3×2＝6（约0.5分，她漏的就是这笔）", "合计相对分子质量减少 882＋6＝888（结果约0.5分）"], "frame": "先分两笔账列式：①脱水账=脱水数×18；②二硫键账=二硫键数×2（题目出现 -S-S- 就必须算）→两笔相加→最后检查\"二硫键算了没有\"再落笔。"}, {"subject": "生物", "question_no": "23-(4)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "圈选①④⑥", "std_answer": "②④⑥⑧", "error_type": "知识盲区", "knowledge_point": "氨基酸分类（据答案反推）", "note": "", "stem": "从 1958 年开始，中国科学院上海生物化学研究所、上海有机化学研究所和北京大学三家单位联合攻关，终于在 1965 年人工合成了具有全部生物活性的结晶牛胰岛素。图 a 为牛胰岛素肽链结构示意图，其中的数字为氨基酸序号，二硫键（-S-S-）是由两个巯基（-SH）连接脱去两个 H 而形成的；图 b 是胰岛素部分肽链放大图。(1)氨基酸是组成蛋白质的基本单位，组成人体蛋白质的 21 种氨基酸[以脱水缩合方式连接，不清]。(2)生物体中不同的蛋白质具有不同的生物活性和功能。胰岛素是[胰岛 B 细胞分泌的降低血糖的]一种蛋白质类激素。与结晶牛胰岛素的生物活性有直接关系的选项是（ ）A.胰岛素分子中氨基酸的种类 B.胰岛素分子中二硫键的数目和位置 C.胰岛素分子中肽键的数目 D.胰岛素分子中氨基酸脱水缩合的方式。(3)一个牛胰岛素分子由 51 个氨基酸脱水缩合而成。根据图 a 判断，一个胰岛素分子中含有＿＿条肽链，＿＿个肽键。氨基酸形成胰岛素后，相对分子质量比原来的总相对分子质量减少了＿＿。(4)图 b 中游离的氨基有＿＿个，表示 R 基的序号是＿＿，含有肽键的序号是＿＿。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(4)-②|1", "card_type": "concept", "teach": "在肽链结构图上认三样东西：肽键是氨基酸之间的-CO-NH-连接处，先在图中找到羰基碳与氮相连的位置；R基是每个中心碳上“多出来的”支链——中心碳连的四样东西里氨基、羧基、氢都是固定的，剩下的那个就是R基；游离氨基在肽链一端，若R基里带氨基也要算入。她的圈选漏了两处R基，是把个别中心碳的支链误认成了肽键结构的一部分。认图顺序：先标全部肽键，再逐个中心碳找支链，最后数两端和R基上的游离基团。", "why": "在图中漏认了两个R基，把中心碳的支链和肽键结构混淆了。", "check_q": "一条肽链中游离的氨基至少有几个？它们分布在哪里？", "check_a": "至少1个（在肽链的一端）；若R基中还含有氨基，还要加上R基上的氨基数。", "steps": "1. 先在图上找肽键：-CO-NH-的连接处就是肽键，先把所有肽键标出来，剩下的结构再分类\n2. 再逐个中心碳拆解：每个中心碳连四样东西——氨基、羧基、氢是固定的，第四样支链就是R基，逐个圈出别漏\n3. 最后数游离基团：肽链两端各有游离的氨基（或羧基），R基上若带氨基、羧基也要一并计入\n4. 按“先肽键、后R基、再两端”的固定顺序复核一遍，避免把支链误认成肽键的一部分", "need": ["肽键的结构（-CO-NH-）与识别", "R基在氨基酸结构中的位置与识别", "肽链中游离氨基、游离羧基数目的计算（含R基上的）"], "points": ["圈对 ②④⑥⑧ 中她已圈对的 ④⑥（部分分约1分）", "补圈漏掉的 ②⑧——漏一处约扣0.5分", "不误圈 ①（她多圈了①，含错选本小问按规约扣至0~1分）"], "frame": "认图三步：先在全图标出所有肽键（-CO-NH-）→再逐个中心碳找\"多出来的支链\"即 R 基→最后对照编号逐个打勾，宁慢勿漏，数完再圈。", "img": "bio-23.jpg"}, {"subject": "生物", "question_no": "24-(1)-③", "full_score": 1.0, "got_score": 0.0, "student_answer": "因为没有对试管进行加热", "std_answer": "因为没有水浴加热", "error_type": "表述不规范", "knowledge_point": "\"水浴\"是关键限定词，直接加热不行", "note": "", "stem": "水熊虫对不良环境有极强的抵抗力。当环境恶化时，水熊虫会处于一种假死状态，代谢率几乎降到零，甚至能耐受 -273℃ 冰冻数小时，直到环境改善为止。据研究，水熊虫进入假死状态时，体内会产生大量海藻糖。(1)若要探究海藻糖是否为还原糖，可加入＿＿试剂鉴定，在海藻糖溶液中加入该试剂没有发生相应的颜色反应，能否说明海藻糖为非还原糖？＿＿为什么？＿＿。(2)有人认为\"水熊虫体液中的海藻糖可以保护组织细胞，使组织细胞免受低温造成的损伤\"，为探究上述假设的真实性，设计了一个实验方案：①为了确保实验的科学性和准确性，从化学组成及生理功能看，实验材料应选择＿＿的动物细胞（多选）A.含有海藻糖 B.不含海藻糖 C.能够合成海藻糖 D.不能合成海藻糖。②操作过程：a.取适量步骤①中选择的动物细胞，等分成甲、乙两组；b.甲组添加含海藻糖的细胞培养液，乙组添加＿＿；c.两组均控制在＿＿条件下数小时；d.观察环境改变后，甲、乙两组细胞的存活率。③预期结果及结论：若＿＿，则假设成立，海藻糖可以保护组织细胞，使其免受低温造成的损伤；若＿＿，则假设不成立。", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(1)-③|1", "card_type": "concept", "teach": "斐林试剂鉴定还原糖的完整条件是“50～65℃水浴加热”，缺了加热这一步，即使溶液里全是葡萄糖也不会出现砖红色沉淀——所以“没有变色”不能推出“不是还原糖”，结论必须建立在操作规范的前提上。她答“因为没有加热”被扣分，是因为少了“水浴”二字：水浴受热均匀、能防止液体暴沸和Cu(OH)2受热分解，直接对试管加热在实验规范里是错误操作。答实验题的原则：条件类答案要写全方式和程度，少一个限定词就少一分。", "why": "答对了“要加热”，却漏了关键限定词“水浴”，表述不规范被扣分。", "check_q": "用斐林试剂鉴定还原糖时，为什么必须水浴加热，不能直接用酒精灯加热试管？", "check_a": "水浴受热均匀、温度可控；直接加热易使液体暴沸溅出，且Cu(OH)2受热分解变黑，干扰颜色观察。", "steps": "1. 先回忆斐林鉴定的完整条件：不是“加热”两个字，而是50～65℃水浴加热，条件的每个限定词都是得分点\n2. 看题目要解释的现象：没加热就不会出现砖红色，没变色推不出“不是还原糖”——结论必须建立在操作规范的前提上\n3. 答原因类空时把方式和程度写全：加热方式（水浴）、温度范围，缺一处扣一处\n4. 顺带想清为什么不能直火加热：受热不均易暴沸，Cu(OH)2受热分解变黑干扰观察", "need": ["斐林试剂鉴定还原糖的实验条件（50～65℃水浴加热）", "水浴加热的作用（受热均匀、温度可控）", "实验结论必须以操作规范为前提"], "points": ["写出\"水浴\"二字——斐林试剂鉴定还原糖须 50~65℃ 水浴加热（本空1分全在限定词上）", "只写\"没有加热\"不得分：直接加热是错误操作，条件必须写全方式"], "frame": "答\"实验没变色的原因\"先查操作清单：试剂对不对→条件全不全（水浴加热）→时间够不够→本题卡在条件，落笔把\"水浴加热\"写全，不留省略。"}, {"subject": "生物", "question_no": "24-(2)-①", "full_score": 2.0, "got_score": 0.0, "student_answer": "BC", "std_answer": "BD", "error_type": "知识盲区/审题偏差", "knowledge_point": "实验变量分析（据答案反推：海藻糖低温保护细胞实验）", "note": "", "stem": "为探究海藻糖能否保护细胞免受低温损伤，实验材料应选择怎样的动物细胞（多选）：", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-①|1", "card_type": "redo", "options": {"A": "含有海藻糖", "B": "不含海藻糖", "C": "能够合成海藻糖", "D": "不能合成海藻糖"}, "teach": "实验材料的选择原则是“排除内源干扰”：要研究外加海藻糖有没有用，实验对象本身必须是一张白纸——体内不含海藻糖（B），也不能自己合成海藻糖（D），这样甲组（外加海藻糖）与乙组（不加）之间唯一的差别就是人为添加的海藻糖，自变量干净。如果选C（能够合成），细胞受低温刺激时会自己产生海藻糖，乙组也被污染，实验直接作废。多选题的每个选项都要按“会不会干扰自变量”逐个过一遍，不能只想一层。", "why": "选了“能够合成海藻糖”的C，细胞自己产糖会污染对照组，自变量就不纯了。", "check_q": "研究外源胰岛素对血糖的影响，实验动物应选健康鼠还是糖尿病模型鼠？为什么？", "check_a": "糖尿病模型鼠（自身胰岛素分泌不足），这样外加胰岛素的效果才能单独显现，排除内源胰岛素的干扰。", "steps": "1. 先认本实验的自变量：人为添加的海藻糖，因变量是低温下的细胞存活率\n2. 材料选择只守一条原则：实验对象本身不能自带、也不能自产海藻糖，否则对照组被污染，自变量就不纯\n3. 逐个选项按“会不会干扰自变量”过一遍：不含海藻糖（留）、能合成海藻糖（删）、不能合成（留）\n4. 多选题定稿前再把每个入选项和自变量对照一次，确认组间唯一差别只剩“加不加海藻糖”", "need": ["对照实验中自变量、无关变量的控制原则", "实验材料选择要排除内源性干扰", "海藻糖与低温保护的实验背景"], "points": ["选 B（体内不含海藻糖）——材料须是\"白纸\"，约1分", "选 D（自身不能合成海藻糖）——防内源污染，约1分", "不选 C（能合成）——选 C 本小问不得分：细胞自己产糖，对照组被污染，自变量不纯"], "frame": "逐项过筛：每个选项都问一句\"它会不会让细胞自己带糖/产糖\"→会的一律排除→剩下\"不含也不能合成\"的才选→最后确认自变量（外加海藻糖）是唯一差别。"}, {"subject": "生物", "question_no": "24-(2)-③", "full_score": 2.0, "got_score": 0.0, "student_answer": "相同", "std_answer": "相同的低温", "error_type": "表述不规范", "knowledge_point": "对照条件缺关键限定词\"低温\"", "note": "", "stem": "在海藻糖保护细胞的实验中：甲组添加含海藻糖的培养液，乙组添加等量不含海藻糖的培养液，两组均控制在____条件下数小时，再观察存活率。（填实验条件）", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-③|1", "card_type": "redo", "teach": "对照实验的条件表述要写“全”：本题假设检验的是海藻糖能否抵抗低温损伤，所以处理条件必须是“相同的低温条件”——“相同”保证无关变量一致，“低温”点明假设指向的环境因素，两者缺一不可。她只写“相同”，阅卷认为没答出处理因素。这一坑在实验题里反复出现：凡是“控制在__条件下”的空，都要先把题干假设里的关键环境词（低温、黑暗、适宜光照等）找出来写进去，再补上“相同”等限定词。", "why": "只写了“相同”，漏掉了假设指向的核心条件“低温”。", "check_q": "探究光照对光合作用的影响时，两组装置应分别放在什么条件下？", "check_a": "一组光照、一组黑暗作对照，其余条件（温度、水分等）相同且适宜。", "steps": "1. 先回读实验假设：检验的是“海藻糖能否抵抗低温损伤”，处理条件必须把假设里的环境因素点出来——低温\n2. 再把对照原则套上：两组除自变量外一切条件相同，所以要写“相同的”\n3. 两个词缺一不可：“相同”管无关变量一致，“低温”管处理因素明确，只写一个必扣分\n4. 养成习惯：凡“控制在__条件下”的空，先从题干里把关键环境词（低温、黑暗、适宜光照等）抄下来，再补限定词", "need": ["对照实验的单一变量原则与无关变量相同且适宜", "实验假设与处理条件的对应关系", "实验条件表述的规范（限定词完整）"], "points": ["写\"相同的\"——无关变量一致，约1分", "写\"低温\"——假设指向的核心环境条件，约1分，她漏的就是这个词", "只写\"相同\"约得一半分"], "frame": "填条件空两步：先回题干假设里抠核心环境词（低温）→再补限定词\"相同的\"→合起来写\"相同的低温条件\"，两个词缺一不可。"}, {"subject": "生物", "question_no": "24-(2)-⑤", "full_score": 2.0, "got_score": 2.0, "student_answer": "甲乙两组细胞存活率相…（字迹潦草，疑为\"相同/相近\"）", "std_answer": "甲、乙两组细胞的存活率都很低（或基本相等）", "error_type": "—（字迹不清，按最可能的辨认给分）", "knowledge_point": "", "note": "", "stem": "概念辨析：在对照实验中，预期“假设不成立”时的结果应如何规范表述？", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-⑤|1", "card_type": "concept", "teach": "实验题的“预期结果及结论”必须会写双向：如果假设成立，甲组（有海藻糖）存活率明显高于乙组；如果假设不成立，甲、乙两组存活率无显著差异。表述要用“明显高于”“无显著差异”这类可比较的语言，不要写“存活率都很低”这种没有对照意义的话。她这空写成存活率相近的意思，老师酌情给了分，但规范写法应是“甲、乙两组细胞的存活率基本相等（无显著差异）”。抓手：预期结果与结论成对出现，假设有几种可能就写几种。", "why": "表述含糊，只写存活率相近，没用“无显著差异”这类规范的对照语言（本题老师酌情给分）。", "check_q": "若实验结果是甲组存活率远高于乙组，应得出什么结论？", "check_a": "海藻糖可以保护组织细胞、使其免受低温造成的损伤，假设成立。", "steps": "1. 先分清这问要的是“预期结果”，不是实际测得的结果：要按假设成立、不成立两种情况各写一版\n2. 假设成立时写差异：甲组（有海藻糖）存活率明显高于乙组\n3. 假设不成立时写无差异：甲、乙两组存活率基本相等（无显著差异）——用可比较的相对语言，不写“都很低”这类没有对照意义的绝对描述\n4. 结果与结论成对落笔：写完预期结果，紧跟对应的结论句", "need": ["对照实验预期结果与结论的规范表述", "“无显著差异”等相对比较用语的使用", "验证性实验与探究性实验在结果预测上的区别"], "points": ["写出\"若假设不成立：甲、乙两组存活率基本相等（无显著差异）\"——规范的对照表述（本空老师酌情给了分）", "用可比较的语言（明显高于/无显著差异）——写\"存活率都很低\"这类无对照含义的话约扣1分"], "frame": "预期结果按双向写：先写假设成立时（甲>乙）→再写假设不成立时（甲、乙无显著差异）→每句都带比较词→回扣到结论（支持/不支持假设）。"}, {"subject": "化学", "question_no": "1", "full_score": 4.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "化学|1|1", "card_type": "concept", "teach": "实验室安全题抓三条线。一是钠的取用：钠保存在煤油中，剩余的钠必须放回原试剂瓶（钠太活泼，随便丢弃遇水会起火）。二是灭火与存放：钠着火只能用干燥沙土盖灭，泡沫灭火器喷出的水会助长反应；浓硫酸与氢氧化钠一酸一碱不能同橱存放。三是见光易分解的试剂：氯水中的HClO见光分解，必须用棕色细口瓶避光保存，液体用细口瓶而不是广口瓶。逐项过：对象是谁、怕什么、用什么容器。", "why": "把“剩余钠放回原瓶”这个特殊规定当成了错误项，又放过了广口瓶存氯水等细节错误。", "check_q": "实验室里氯水应保存在什么瓶中？金属钠着火用什么灭火？", "check_a": "棕色细口瓶（避光保存）；用干燥的沙土盖灭，不能用水或泡沫灭火器。", "steps": "1. 先把每个选项拆成“对象＋规定”两半，逐项问：这东西怕什么、该怎么存怎么处理\n2. 走安全线：钠保存在煤油里、剩余钠必须放回原瓶、着火只能用干燥沙土——涉及钠的选项先按这三条验\n3. 走存放线：酸碱不能同橱（浓硫酸与NaOH分开）、见光易分解的试剂（氯水、硝酸）用棕色瓶、液体试剂用细口瓶\n4. 最后专查“特殊规定”类陷阱：一般药品剩余不回原瓶，唯独钠是例外，这类反常识点最爱设错", "need": ["金属钠的保存（煤油中）与取用、剩余钠放回原瓶的规定", "钠着火的扑灭方法（干燥沙土，忌水和泡沫灭火器）", "氯水的保存（棕色细口瓶避光）与HClO见光分解", "浓硫酸与氢氧化钠等试剂的分类存放"], "stem": "下列做法符合实验室要求的是（ ）\nA. 剩余的钠块放回原试剂瓶\nB. 金属钠着火时使用泡沫灭火器灭火\nC. 浓硫酸与氢氧化钠固体放在同一实验橱内\nD. 新制氯水保存在棕色□口瓶中，置于避光阴凉处"}, {"subject": "化学", "question_no": "4", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "化学|4|1", "card_type": "concept", "teach": "钠投入盐溶液，永远先和水反应，这是铁律：2Na＋2H2O＝2NaOH＋H2↑，生成的NaOH再与盐发生复分解。钠投入MgCl2溶液：先得NaOH和H2，NaOH再与MgCl2生成Mg(OH)2白色沉淀，所以现象是浮、熔、游、响加白色沉淀，绝不会置换出金属镁——钠虽活泼，但在水溶液中抢先与水反应。判断抓手：只要环境里有水，钠的第一反应对象就是水，第二步再看生成的碱与盐是否反应。", "why": "按“钠置换镁”的金属活动性思路选错，没走“先水后盐”两步。", "check_q": "把一小块钠投入CuSO4溶液，能看到红色铜析出吗？实际现象是什么？", "check_a": "不能。钠先与水反应放出H2，生成的NaOH与CuSO4生成蓝色Cu(OH)2沉淀；现象为浮、熔、游、响并有蓝色沉淀。", "steps": "1. 先看清反应环境：钠是投进盐的水溶液，先别想置换反应，第一反应对象永远是水\n2. 按“先水后盐”两步走：第一步写钠与水的反应——生成NaOH并放出H2\n3. 第二步看生成的NaOH和盐认不认识：能生成沉淀、气体或水就接着反应（如与MgCl2生成Mg(OH)2白色沉淀）\n4. 现象按顺序拼：钠与水的浮、熔、游、响，加上第二步的沉淀或变色；凡选项说“置换出金属单质”的直接判错", "need": ["钠与水反应的化学方程式及现象（浮、熔、游、响、红）", "钠投入盐溶液的反应规律（先与水反应）", "复分解反应发生的条件（生成沉淀、气体或水）", "氢氧化钠与镁、铜、铁盐溶液的反应"], "stem": "下列关于钠及其化合物的说法正确的是（ ）\nA. Na₂O 久置于空气中，最终转化为 NaHCO₃\nB. Na₂O 与 Na₂O₂ 都能和水反应生成碱，它们都是碱性氧化物\nC. Na₂CO₃ 溶液能与酸溶液反应，但不能与碱溶液反应\nD. Na 投入 MgCl₂ 溶液中生成白色沉淀和无色气体"}, {"subject": "化学", "question_no": "7", "full_score": 4.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "氯气与氯水的性质（卷面订正口径）", "note": "", "stem": "下列关于氯气和氯水的说法中正确的是（ ）", "paper_cause": "概念不清", "key": "化学|7|1", "card_type": "redo", "options": {"A": "红热的铁丝在Cl2中剧烈燃烧生成FeCl3", "B": "氯气是一种无色、密度比空气大的有毒气体", "C": "新制氯水能杀菌消毒是因为Cl2有毒，能杀灭细菌", "D": "氯气溶于水后生成的次氯酸见光易分解（据卷面辨认，含错误表述）"}, "teach": "四个选项逐个验：A红热铁丝在Cl2中剧烈燃烧生成FeCl3，正确——Cl2氧化性强，变价金属与Cl2反应一律生成最高价氯化物。B错在颜色：Cl2是黄绿色气体（密度比空气大、有毒这两点对）。C错在主角：新制氯水杀菌消毒靠的是HClO的强氧化性，不是Cl2有毒。抓手：氯气本身黄绿色、有毒；溶于水后真正起漂白消毒作用的是HClO。做这类题先把每个选项的“事实点”单独验真假，别被一句大体眼熟的话带走。", "why": "放过了A项“铁与氯气生成FeCl3”这个确定正确的事实，被表述含糊的D项带偏。", "check_q": "新制氯水能使有色布条褪色，起漂白作用的是哪种物质？氯气是什么颜色？", "check_a": "次氯酸（HClO）；黄绿色。", "steps": "1. 别看选项的整句表述，先把每个选项拆成一两个“事实点”：颜色、产物、谁起作用，逐点验真假\n2. 验产物类：变价金属与Cl2反应一律生成最高价氯化物——铁与氯气生成FeCl3，这是确定事实\n3. 验性质类：Cl2是黄绿色气体；氯水杀菌消毒靠的是HClO的强氧化性，不是Cl2本身有毒\n4. 四个点全验完再对答案，警惕“大半句眼熟、一个词偷换”的选项（如把黄绿色说成无色）", "need": ["氯气的物理性质（黄绿色、密度比空气大、有毒）", "铁与氯气反应生成FeCl3（最高价氯化物）", "新制氯水的成分与HClO的漂白杀菌作用", "氯气溶于水的反应及次氯酸的性质"]}, {"subject": "化学", "question_no": "8", "full_score": 4.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "物质的量：微粒数与分子内原子数换算（卷面订正口径）", "note": "", "stem": "下列各物质所含原子数由多到少排列的是（ ）①0.5 mol NH3 ②4 g H2 ③标准状况下0.3 mol CO2 ④0.2 mol H3PO4", "paper_cause": "计算失误", "key": "化学|8|1", "card_type": "redo", "options": {"A": "①④③②", "B": "④③②①", "C": "②③④①", "D": "②①④③"}, "teach": "比较原子数只用一条公式：原子的物质的量＝分子的物质的量×每个分子的原子数。逐个算：①0.5×4＝2 mol；②4 g H2先换成2 mol，再×2＝4 mol；③0.3×3＝0.9 mol；④0.2×8＝1.6 mol（H3PO4一个分子有3个H＋1个P＋4个O共8个原子，别漏数）。由多到少是②①④③。两个易错点：题目给质量的，先除以摩尔质量换成物质的量；数分子内原子数时把每个元素都数全。", "why": "把分子的多少当成了原子的多少，没乘每个分子的原子个数，H2的质量也没先换算成物质的量。", "check_q": "0.4 mol H2SO4和8 g CH4，哪一个含的原子更多？", "check_a": "H2SO4含原子0.4×7＝2.8 mol；8 g CH4是0.5 mol，含原子0.5×5＝2.5 mol，H2SO4更多。", "steps": "1. 先定公式：比的是原子数，就统一算“原子的物质的量＝分子的物质的量×每个分子的原子数”，不比分子数\n2. 逐个换算物质的量：题目给质量的先除以摩尔质量（如4 g H2是2 mol），给物质的量的直接用\n3. 逐个乘原子数：NH3乘4、H2乘2、CO2乘3、H3PO4乘8——数分子内原子时每个元素都要数全，H3PO4的3个H最易漏\n4. 四个数排完序再对选项：2、4、0.9、1.6由多到少对应②①④③，检查选项顺序别抄反", "need": ["物质的量与质量的换算（n＝m/M）", "微粒数目的计算：原子的物质的量＝分子的物质的量×分子内原子数", "常见分子（NH3、H3PO4等）的原子构成"]}, {"subject": "化学", "question_no": "9", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "下列说法正确的是（ ）", "paper_cause": "概念不清", "key": "化学|9|1", "card_type": "redo", "options": {"A": "同温、同压下，相同质量的气体都占有相同的体积", "B": "在标准状况下，1 mol任何物质的体积均为22.4 L", "C": "1 mol某气体的体积为22.4 L，该气体所处的状态一定是标准状况", "D": "同温、同压下，相同体积的气体都含有相同数目的分子数"}, "teach": "22.4 L/mol的适用条件要背全三个限定：标准状况（0℃、101 kPa）、1 mol、气体，缺一个都不能用。B错在“任何物质”：固体、液体1 mol的体积远不是22.4 L。A错在“相同质量”：质量相同而摩尔质量不同，物质的量就不同，体积也不同；同温同压下体积只由物质的量决定。C错在反推：改变温度压强，非标况下1 mol气体体积也可以恰好是22.4 L。D是阿伏加德罗定律本身，正确。", "why": "选了B，把22.4 L无条件套到“1 mol任何物质”，丢了“标况＋气体”两个限定词。", "check_q": "标准状况下，1 mol H2O的体积是22.4 L吗？为什么？", "check_a": "不是。标况下水是液体，22.4 L/mol只适用于气体；1 mol水体积约18 mL。", "steps": "1. 先把22.4 L/mol的三个限定词默出来：标准状况、1 mol、气体——选项里少任何一个都要警惕\n2. 逐项找偷换：把“任何物质”当气体的错、把“相同质量”当“相同物质的量”的错、由体积反推一定是标况的错\n3. 验阿伏加德罗定律本体：同温同压下，气体的体积之比等于物质的量之比、分子数之比，与气体种类无关\n4. 剩下表述与定律原文完全一致的才是答案，别选“听起来差不多”的", "need": ["气体摩尔体积的适用条件（标况、气体、22.4 L/mol）", "阿伏加德罗定律及其推论", "同温同压下气体体积与物质的量的关系", "标准状况的界定（0℃、101 kPa）"]}, {"subject": "化学", "question_no": "10", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "用下列实验装置进行相应实验，装置正确且能达到相应实验目的的是（ ）", "paper_cause": "概念不清", "key": "化学|10|1", "card_type": "redo", "options": {"A": "用图甲（饱和NaCl溶液、浓硫酸两洗气瓶）除去Cl2中的HCl并干燥", "B": "用图乙装置进行钠的燃烧实验", "C": "用图丙装置稀释浓硫酸", "D": "用图丁制备二氧化碳"}, "teach": "装置题逐图排查三句话：仪器对不对、试剂对不对、顺序对不对。甲对：除Cl2中的HCl用饱和食盐水（抑制Cl2溶解又能吸收HCl），再用浓硫酸干燥，顺序先除杂后干燥。乙错：钠的燃烧必须在坩埚中进行，不能在普通装置里直接加热钠。丙错：稀释浓硫酸要在烧杯中、酸入水并不断搅拌，绝不能在量筒类容器里操作。丁的装置与药品组合达不到制CO2目的。逐图排除，只剩甲。", "why": "选了D项制CO2装置，放过了甲图“先饱和食盐水除HCl、再浓硫酸干燥”这个标准组合。", "check_q": "除去Cl2中混有的HCl并干燥，两个洗气瓶应依次装什么试剂？", "check_a": "先饱和食盐水（除HCl），后浓硫酸（干燥）。", "steps": "1. 装置题逐图排查，每幅图固定问三句：仪器用对了吗、试剂用对了吗、先后顺序对了吗\n2. 图甲验洗气顺序：除Cl2中的HCl用饱和食盐水（抑Cl2溶解又吸HCl），干燥用浓硫酸，且必须先除杂后干燥——标准组合，对\n3. 图乙验仪器：钠的燃烧要在坩埚中加热，普通装置里直接加热钠不合规范，错\n4. 图丙验操作：稀释浓硫酸必须在烧杯里酸入水、不断搅拌，在量筒类容器里稀释是大忌，错；图丁的装置药品达不到制CO2目的，错——逐图排除后只剩甲", "need": ["氯气除杂干燥的试剂与顺序（饱和食盐水除HCl、浓硫酸干燥）", "钠燃烧实验的仪器（坩埚）", "浓硫酸稀释的规范操作（烧杯、酸入水、搅拌）", "实验室制取二氧化碳的装置与药品"], "img": "chem-10.jpg"}, {"subject": "化学", "question_no": "11-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "4Na+O2=Na2O（自加不明条件\"R△\"）", "std_answer": "重建：2Na+O2=点燃=Na2O2", "error_type": "产物错误", "knowledge_point": "钠与氧气反应：条件决定产物（常温Na2O/加热Na2O2），据答案反推", "note": "", "key": "化学|11-(1)|1", "card_type": "redo", "stem": "写出钠块在氧气中加热、生成淡黄色固体的化学方程式。", "teach": "钠与氧气反应，条件决定产物：常温缓慢氧化生成白色Na2O：4Na＋O2＝2Na2O；加热或点燃生成淡黄色Na2O2：2Na＋O2＝Na2O2（条件写点燃或△）。题目给了“加热、淡黄色”两个信号，产物锁定Na2O2。用四步检查法自查：①化学式——产物是Na2O2不能写成Na2O；②配平——2个Na、2个O两边相等；③条件——等号上方写点燃或△，不能自创符号；④符号——没有气体沉淀生成，不标。她第①步产物就判错，后面全丢。", "why": "写成4Na＋O2＝Na2O，把加热产物当成了常温产物，还自创了不明条件符号。", "check_q": "钠在常温下与氧气反应的化学方程式是什么？产物什么颜色？", "check_a": "4Na＋O2＝2Na2O，产物是白色固体。", "steps": "1. 先由题干的信号定产物：“加热、淡黄色”锁定过氧化钠Na2O2；常温无特殊说明才是白色的Na2O\n2. 写骨架：Na＋O2→Na2O2，先把化学式写对，产物判错后面全白搭\n3. 配平：两边各2个Na、2个O，写成2Na＋O2＝Na2O2\n4. 标条件符号：等号上方写△或点燃（用规范写法，不自创符号）；无气体沉淀生成，不标↑↓；最后数一遍两边原子数收尾", "need": ["钠与氧气反应的产物随条件不同（常温Na2O、加热Na2O2）及颜色", "化学方程式的配平方法", "反应条件（点燃、加热）的规范标注"], "points": ["产物写对 Na2O2（加热/点燃产物；写 Na2O 整个方程式不得分）——约1分", "配平 2Na+O2=Na2O2 系数正确——约0.5分", "条件标注\"点燃\"或\"△\"，且不自创符号——约0.5分"], "frame": "先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "11-(2)", "full_score": 2.0, "got_score": 0.0, "student_answer": "3H2+Cl2=…→2H3Cl（涂改混乱）", "std_answer": "重建：H2+Cl2=点燃=2HCl", "error_type": "知识盲区", "knowledge_point": "氢气在氯气中燃烧", "note": "", "key": "化学|11-(2)|1", "card_type": "redo", "stem": "写出氢气在氯气中燃烧的化学方程式。", "teach": "H2在Cl2中安静燃烧、发出苍白色火焰：H2＋Cl2＝2HCl，条件点燃。四步检查法：①化学式——产物是HCl，一个H配一个Cl；②配平——系数比1∶1∶2，H、Cl两边都是2；③条件——点燃；④符号——HCl虽是气体，但反应物中也有气体，不标↑。最要紧的一条铁律：配平只能改系数，化学式的下标永远不能动。她写出的“2H3Cl”是把系数挪进了化学式，凭空造出不存在的物质，这是方程式书写的大忌。", "why": "把配平系数写进了化学式，造出不存在的H3Cl，化学式书写规则没过关。", "check_q": "H2在Cl2中燃烧的火焰是什么颜色？产物遇水蒸气有什么现象？", "check_a": "苍白色火焰；产物HCl遇水蒸气形成白雾（盐酸小液滴）。", "steps": "1. 先定产物：H2在Cl2中燃烧只生成HCl，一个H配一个Cl，化学式先写对\n2. 写骨架：H2＋Cl2→HCl\n3. 配平只动系数：HCl前配2，得H2＋Cl2＝2HCl——铁律是下标永远不能改，把系数写进化学式就造出了不存在的物质\n4. 标条件符号：条件写点燃；HCl虽是气体，但反应物中也有气体，不标↑；最后数两边H、Cl各2个收尾", "need": ["氢气在氯气中燃烧的反应与现象（苍白色火焰）", "化学方程式配平只能改系数、不能改下标的规则", "气体符号↑的标注条件（反应物无气体时才标）"], "points": ["产物写对 HCl（化学式下标绝不能改；写 H3Cl 不得分）——约1分", "配平系数 1-1-2（H2+Cl2=2HCl）——约0.5分", "条件\"点燃\"——约0.5分；HCl 不标↑（反应物里已有气体）"], "frame": "先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "11-(3)", "full_score": 2.0, "got_score": 0.0, "student_answer": "2Fe+HCl=Fe3Cl2", "std_answer": "重建：2Fe+3Cl2=点燃=2FeCl3", "error_type": "概念混淆", "knowledge_point": "Fe与Cl2生成FeCl3 vs Fe与盐酸生成FeCl2+H2↑，两者混淆且化学式错误", "note": "", "key": "化学|11-(3)|1", "card_type": "redo", "stem": "写出细铁丝在氯气中燃烧的化学方程式。", "teach": "铁与氯气、铁与盐酸是两个完全不同的反应，必须分开记：Cl2氧化性强，红热铁丝在Cl2中剧烈燃烧、产生棕褐色烟，产物是FeCl3：2Fe＋3Cl2＝2FeCl3（点燃），铁被氧化到＋3价；盐酸是非氧化性酸，铁与盐酸反应生成的是FeCl2和H2。规律：变价金属与Cl2反应生成最高价氯化物，与盐酸反应生成低价盐。四步检查：化学式FeCl3、配平2-3-2、条件点燃、无符号。", "why": "把“铁与氯气”错换成“铁与盐酸”，反应物写成HCl，产物价态和化学式一起错。", "check_q": "铁与盐酸反应的化学方程式是什么？铁是几价？", "check_a": "Fe＋2HCl＝FeCl2＋H2↑，铁为＋2价（与氯气反应则生成＋3价的FeCl3）。", "steps": "1. 先确认反应物到底是谁：题干是铁与氯气，不是铁与盐酸——两个反应的产物价态完全不同，别串台\n2. 定产物价态：Cl2氧化性强，把铁氧化到＋3价，产物是FeCl3\n3. 写骨架配平：2Fe＋3Cl2＝2FeCl3，按Fe、Cl两边相等定系数2-3-2\n4. 标条件：点燃；无气体沉淀符号；最后和“铁与盐酸生成FeCl2＋H2”对照一遍，确认没把两个反应混起来", "need": ["铁与氯气反应生成FeCl3（变价金属与Cl2生成最高价氯化物）", "铁与盐酸反应生成FeCl2和氢气", "氯气的强氧化性", "化学方程式的配平方法"], "points": ["反应物是 Cl2 不是盐酸（与 Cl2 反应生成最高价 FeCl3；写 HCl 整题错）——约1分", "产物 FeCl3 化学式与价态对——约0.5分", "配平 2-3-2 且条件\"点燃\"——约0.5分"], "frame": "先分清反应对象：Cl2 氧化性强→铁升到+3价→产物 FeCl3→先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "11-(4)", "full_score": 2.0, "got_score": 0.0, "student_answer": "HClO=H2O+Cl2↑", "std_answer": "重建：2HClO=光照=2HCl+O2↑", "error_type": "知识盲区", "knowledge_point": "次氯酸见光分解", "note": "", "key": "化学|11-(4)|1", "card_type": "redo", "stem": "次氯酸不稳定、需避光保存在冷暗处。写出次氯酸见光分解的化学方程式。", "teach": "次氯酸见光分解：2HClO＝2HCl＋O2↑，条件是光照。这也是氯水必须避光保存、久置氯水最终变成稀盐酸的原因。四步检查法：①化学式——产物是HCl和O2；②配平——2个HClO分解出2个HCl和1个O2，H、Cl、O三边守恒；③条件——光照，写在等号上方；④符号——O2是唯一生成的气体，加↑。写完方程式一定回头数两边原子个数：她写的HClO＝H2O＋Cl2↑，左右原子数根本对不上，数一遍就能发现。", "why": "凭感觉拼产物写成H2O和Cl2，没用原子守恒检验，产物和配平双错。", "check_q": "久置的氯水最终主要变成什么？什么现象能说明HClO见光分解？", "check_a": "主要变成稀盐酸；光照新制氯水有气泡（O2）冒出、黄绿色变浅。", "steps": "1. 先由“见光分解”定产物：HClO分解生成HCl和O2——氯水久置变稀盐酸就是这个道理\n2. 写骨架：HClO→HCl＋O2\n3. 配平：HClO前配2，得2HClO＝2HCl＋O2↑，逐个元素数：H、Cl各2，O两边各2\n4. 标条件符号：等号上方写“光照”；O2是唯一生成的气体且反应物无气体，标↑；写完务必数一遍两边原子数，数目对不上立刻重配", "need": ["次氯酸见光分解的化学方程式", "氯水久置变质的原因（成分变化）", "用原子守恒检验方程式配平", "气体符号↑的标注条件"], "points": ["产物写对 HCl 和 O2（写 H2O+Cl2 不得分）——约1分", "配平 2HClO=2HCl+O2，三种原子守恒——约0.5分", "条件\"光照\"+O2 后标↑——约0.5分"], "frame": "先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。本题特别提醒：HClO 分解产物是 O2 不是 Cl2，写完数原子验证。"}, {"subject": "化学", "question_no": "11-(5)", "full_score": 2.0, "got_score": 0.0, "student_answer": "2Ca(OH)2+2H2O+4Cl2=CaCl2+Ca(ClO)2+HClO（另有一版涂改作废）", "std_answer": "重建：2Ca(OH)2+2Cl2=CaCl2+Ca(ClO)2+2H2O", "error_type": "配平错误+产物记忆错误", "knowledge_point": "漂白粉的制取", "note": "", "key": "化学|11-(5)|1", "card_type": "redo", "stem": "写出工业上制取漂白粉的化学方程式（氯气通入石灰乳）。", "teach": "漂白粉是把Cl2通入冷的石灰乳制成的：2Cl2＋2Ca(OH)2＝CaCl2＋Ca(ClO)2＋2H2O，产物是两种盐加水，漂白粉就是CaCl2与Ca(ClO)2的混合物，有效成分是Ca(ClO)2。四步检查法：①化学式——反应物只有Cl2和Ca(OH)2，水是产物不是反应物；②配平——按Ca守恒先定Ca(OH)2为2，再数Cl两边各4；③条件——常温，不用写；④符号——无气体沉淀。她把H2O错放到反应物一侧、产物还多出HClO，第①步就没过关。", "why": "把产物水写进了反应物，又凭空多写了HClO，方程式左右两边完全不对等。", "check_q": "漂白粉的有效成分是什么？它靠什么起漂白作用？", "check_a": "有效成分是Ca(ClO)2；它与空气中的CO2和水反应生成HClO，靠HClO的强氧化性漂白杀菌。", "steps": "1. 先定反应物：工业制漂白粉是Cl2通入石灰乳，反应物只有Cl2和Ca(OH)2——水是产物，绝不能写到左边去\n2. 定产物：氯气与碱的反应生成氯化物和次氯酸盐，即CaCl2和Ca(ClO)2，再加水\n3. 配平抓钙守恒：先定Ca(OH)2为2，推出CaCl2、Ca(ClO)2各1，再数Cl两边各4，Cl2配2、H2O配2\n4. 标条件符号：常温反应不写条件，无气体沉淀不标符号；顺带记住产物中的有效成分是Ca(ClO)2", "need": ["漂白粉的制取原理与化学方程式", "漂白粉的成分与有效成分Ca(ClO)2", "氯气与碱反应的规律（生成氯化物与次氯酸盐）", "化学方程式按元素守恒配平"], "points": ["反应物只有 Cl2 和 Ca(OH)2（把 H2O 写进反应物不得分）——约1分", "产物 CaCl2+Ca(ClO)2+2H2O 齐全、无多余 HClO——约0.5分", "配平 2-2-1-1-2（先按 Ca 守恒定 Ca(OH)2 为2，再数 Cl 各4）——约0.5分"], "frame": "先想制法场景：Cl2 通入石灰乳→产物是两种盐+水→先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "11-(6)", "full_score": 2.0, "got_score": 0.0, "student_answer": "CuSO4+NaOH=Na2SO4（产物不全）", "std_answer": "重建：CuSO4+2NaOH=Cu(OH)2↓+Na2SO4", "error_type": "方程式不完整", "knowledge_point": "复分解反应：产物有蓝色Cu(OH)2沉淀", "note": "", "key": "化学|11-(6)|1", "card_type": "redo", "stem": "写出往CuSO4溶液中滴加NaOH溶液的化学方程式。", "teach": "这是复分解反应：两种化合物交换成分，Cu2＋与OH－结合成难溶的蓝色沉淀Cu(OH)2：CuSO4＋2NaOH＝Na2SO4＋Cu(OH)2↓。用四步检查法对应她的三处错：①化学式——OH是原子团，个数为2时必须加括号写(OH)2，她写成CuOH2，这种物质不存在；②配平——右边有2个Na和2个OH，NaOH前面必须配2，她没配；③条件——常温无条件；④符号——Cu(OH)2是沉淀必须加↓，她漏了。四步错三步，一分都剩不下。", "why": "没给NaOH配平、Cu(OH)2没加括号、沉淀符号也漏了，方程式只剩骨架。", "check_q": "CuSO4溶液中滴加NaOH会看到什么现象？沉淀是什么、什么颜色？", "check_a": "产生蓝色絮状沉淀、溶液蓝色变浅；沉淀是Cu(OH)2。", "steps": "1. 先定反应类型：两种化合物交换成分，是复分解反应，Cu2＋与OH－结合成难溶的Cu(OH)2\n2. 写骨架先过化学式关：氢氧根是原子团，个数为2必须写(Cu(OH))2的形式——写成CuOH2就是不存在的物质\n3. 配平看右边倒推：产物有2个Na、2个OH，NaOH前必须配2，得CuSO4＋2NaOH＝Na2SO4＋Cu(OH)2↓\n4. 标符号：Cu(OH)2是沉淀必须加↓；常温无条件；最后数Na、O、H两边是否相等", "need": ["复分解反应的概念与发生条件", "氢氧化铜是蓝色沉淀及其化学式的写法（原子团加括号）", "沉淀符号↓的标注规则", "化学方程式的配平方法"], "points": ["产物 Cu(OH)2 写对且带括号（写 CuOH2 不得分）——约1分", "NaOH 前配 2（CuSO4+2NaOH=…）——约0.5分", "沉淀符号 ↓ 标在 Cu(OH)2 后——约0.5分；她三处全漏，只剩骨架不得分"], "frame": "先判复分解：交换成分，Cu2+ 与 OH- 结合成难溶物→先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。原子团 OH 出现两个以上必加括号，最后专查↓。"}, {"subject": "化学", "question_no": "13-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "Na+H2O=NaOH（未配平，漏写H2）", "std_answer": "重建：2Na+2H2O=2NaOH+H2↑", "error_type": "漏写气体产物+未配平", "knowledge_point": "钠与水的反应", "note": "", "stem": "写出钠与水反应的化学方程式。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(1)|1", "card_type": "redo", "teach": "钠与水反应是必背方程式：2Na＋2H2O＝2NaOH＋H2↑。用四步检查法自查：①化学式——产物NaOH和H2两个都要写全；②配平——Na两边各2、H两边各4、O两边各2；③条件——常温剧烈反应，不需要条件；④符号——H2是气体且反应物中没有气体，必须加↑。她写的Na＋H2O＝NaOH漏了H2、没配平、漏↑，四步错三步。习惯要养成：每写完一个方程式，化学式、配平、条件、符号逐项打勾再往下做。", "why": "漏写了产物H2，也没配平，气体符号也没标——没走四步检查。", "check_q": "钠与水反应的现象可用哪五个字概括？", "check_a": "浮、熔、游、响、红（浮在水面、熔成小球、四处游动、发出嘶嘶响声、滴酚酞后变红）。", "steps": "1. 先定产物别漏项：钠与水反应生成NaOH和H2，两种产物都要写上——漏写H2是最常见的丢分\n2. 写骨架：Na＋H2O→NaOH＋H2\n3. 配平逐个元素数：Na两边配2、H2O配2，得2Na＋2H2O＝2NaOH＋H2，数O两边各2收尾\n4. 标条件符号：常温剧烈反应不写条件；反应物中没有气体而生成H2，必须标↑；养成每写完一个方程式按“化学式、配平、条件、符号”逐项打勾的习惯", "need": ["钠与水反应的化学方程式", "钠与水反应的现象（浮、熔、游、响、红）", "气体符号↑的标注条件", "化学方程式的配平方法"], "points": ["产物两个都写全：NaOH 和 H2（漏写 H2 整式不得分）——约1分", "配平 2-2-2-1（2Na+2H2O=2NaOH+H2）——约0.5分", "H2 后标↑（反应物无气体，必须标）——约0.5分；常温反应不写条件"], "frame": "先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "13-(2)-方程1", "full_score": 2.0, "got_score": 1.0, "student_answer": "Na2O2+CO2=2Na2CO3+O2（未配平）", "std_answer": "重建：2Na2O2+2CO2=2Na2CO3+O2", "error_type": "配平错误（按规则扣1分）", "knowledge_point": "过氧化钠与二氧化碳反应", "note": "", "stem": "写出过氧化钠与二氧化碳反应的化学方程式。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(2)-方程1|1", "card_type": "redo", "teach": "Na2O2与CO2的反应：2Na2O2＋2CO2＝2Na2CO3＋O2，这是Na2O2用作呼吸面具、潜水艇供氧剂的原理。四步检查法：①化学式——产物是Na2CO3和O2，她这步对了；②配平——抓Na守恒：右边2个Na2CO3含4个Na，左边Na2O2必须配2，CO2随之配2，最后数O自动守恒；③条件——常温无条件；④符号——反应物CO2本身是气体，生成的O2不标↑（只有反应物无气体时才标）。她就栽在第②步：两个系数2都没写。", "why": "产物全对，就是Na2O2和CO2前的系数2没写，未配平被扣分。", "check_q": "Na2O2与水反应的化学方程式是什么？Na2O2在呼吸面具中起什么作用？", "check_a": "2Na2O2＋2H2O＝4NaOH＋O2↑；吸收人呼出的CO2并释放O2（供氧剂）。", "steps": "1. 先定产物：Na2O2与CO2反应生成Na2CO3和O2，产物写对了才谈得上配平\n2. 配平先抓Na守恒：右边2个Na2CO3共含4个Na，左边Na2O2必须配2\n3. 顺藤摸瓜：Na2O2配2后，CO2随之配2；再数O验算——左边4＋4＝8，右边6＋2＝8，守恒，配平完成：2Na2O2＋2CO2＝2Na2CO3＋O2\n4. 标条件符号：常温无条件；反应物CO2本身是气体，生成的O2不标↑，只有反应物无气体时才标", "need": ["过氧化钠与二氧化碳反应的化学方程式", "过氧化钠作供氧剂的原理", "化学方程式按元素守恒配平", "气体符号↑的标注条件（反应物含气体时不标）"], "points": ["产物 Na2CO3 和 O2 写对——约1分（她这步对了，拿到基础分）", "配平：Na2O2 前 2、CO2 前 2（抓 Na 守恒倒推；未配平约扣1分，她就丢在这里）", "O2 不标↑（反应物 CO2 本身是气体）"], "frame": "先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。配平抓手固定：先数产物侧 Na 总数→倒推 Na2O2 系数→CO2 跟随→O 自动守恒，最后通数一遍。"}, {"subject": "化学", "question_no": "13-(5)", "full_score": 2.0, "got_score": 0.0, "student_answer": "圈选①③②④⑤", "std_answer": "未知（标准缺失）", "error_type": "未知（据总分反推0分，不确定）", "knowledge_point": "疑为排序题，标准未知", "note": "", "stem": "[钠及其化合物转化关系图：Na、Na2O、NaOH、Na2CO3、NaHCO3、NaCl 按化合价与类别排布，部分文字不清](1)Na 与水反应的化学方程式为＿＿。(2)Na2O2 与二氧化碳反应的化学方程式为＿＿。(3)Na2CO3 粉末与过量盐酸反应的化学方程式为＿＿。(4)NaH 中氢元素的化合价为＿＿价，NaH 与水反应生成一种强碱和一种可燃性气体，反应的化学方程式为＿＿。(5)将一小块钠投入 CuSO4 溶液中，观察到的现象是＿＿（填序号：①钠浮于液面上 ②熔化成小球 ③发出嘶嘶的响声，放出气体 ④有蓝色沉淀产生 ⑤析出红色的铜）。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(5)|1", "card_type": "concept", "teach": "钠投入CuSO4溶液的现象，正确序号是①②③④，没有⑤。原理还是“先水后盐”：钠先与水反应，所以浮（密度比水小）、熔（反应放热且钠熔点低）、游、响四项都有；生成的NaOH再与CuSO4生成蓝色Cu(OH)2沉淀，即④。⑤“析出红色的铜”是陷阱：钠在水溶液中绝不置换出金属。记忆抓手：钠入盐溶液的现象＝钠与水反应的现象＋生成的碱与盐反应的现象，两段拼起来，唯独没有金属单质析出。", "why": "把⑤也圈了进去，以为钠能像置换反应那样从溶液里置换出铜。", "check_q": "钠投入FeCl3溶液中，除了浮、熔、游、响，还会看到什么现象？", "check_a": "产生红褐色沉淀Fe(OH)3（生成的NaOH与FeCl3反应），不会析出铁。", "steps": "1. 现象排序题先拆实验过程：钠投入盐溶液，把全过程切成两段——钠与水反应、生成的碱与盐反应\n2. 第一段的现象按“浮熔游响”排：密度小浮在水面、放热熔成小球、气体推动四处游动、发嘶嘶响声\n3. 第二段的现象接在后面：NaOH与CuSO4生成蓝色Cu(OH)2沉淀，排在钠与水现象之后\n4. 最后专删陷阱项：“置换出红色的铜”在水溶液中绝不可能发生，凡含金属单质析出的选项一律排除", "need": ["钠与水反应的现象（浮、熔、游、响）", "钠投入盐溶液的反应规律（先水后盐）", "氢氧化钠与硫酸铜反应生成蓝色沉淀", "钠在水溶液中不能置换出金属单质"]}, {"subject": "化学", "question_no": "14-(1)-方程", "full_score": 4.0, "got_score": 2.0, "student_answer": "MnO2+HCl=MnCl2+Cl2↑+H2O（未配平，缺\"浓\"和\"△\"）", "std_answer": "重建：MnO2+4HCl(浓)=△=MnCl2+Cl2↑+2H2O", "error_type": "配平错误+条件缺失（按规则各扣1分）", "knowledge_point": "氯气的实验室制法", "note": "", "stem": "写出实验室用MnO2和浓盐酸制取氯气的化学方程式。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(1)-方程|1", "card_type": "redo", "teach": "实验室制Cl2是本章第一个必背方程式：MnO2＋4HCl(浓)＝MnCl2＋Cl2↑＋2H2O，条件△。四步检查法对她的错：①化学式——盐酸必须标注“浓”，稀盐酸与MnO2不反应，这是最关键的限定；②配平——先数产物一侧的Cl：MnCl2有2个、Cl2有2个，共4个，所以HCl配4，再配H2O为2，她只写了1个HCl；③条件——必须加热，△不能漏，她漏了；④符号——Cl2加↑她写对了。配平抓手：从产物Cl总数倒推HCl系数。", "why": "没配平HCl的系数4，条件△和“浓”字也都缺了，一个方程式丢了两处分。", "check_q": "实验室制氯气为什么必须用浓盐酸？稀盐酸行不行？", "check_a": "不行。MnO2氧化能力有限，需要浓盐酸才能被氧化放出Cl2；稀盐酸与MnO2不反应。", "steps": "1. 先定全反应物和产物：MnO2＋浓盐酸→MnCl2＋Cl2＋H2O，盐酸必须带“浓”字，稀盐酸与MnO2不反应\n2. 配平从产物侧的Cl总数倒推：MnCl2含2个Cl、Cl2含2个Cl，共4个，所以HCl配4，H2O随之配2\n3. 写全：MnO2＋4HCl（浓）＝MnCl2＋Cl2↑＋2H2O\n4. 标条件符号：条件是加热△不能漏；Cl2是生成气体且液体中逸出，标↑；最后数Cl、H、O两边是否守恒", "need": ["实验室制取氯气的原理与化学方程式（MnO2与浓盐酸）", "浓盐酸才能与MnO2反应的原因（稀盐酸不反应）", "化学方程式的配平方法（由产物Cl总数倒推）", "反应条件（加热）的标注"], "points": ["盐酸标注\"浓\"（稀盐酸与 MnO2 不反应，漏\"浓\"约扣1分）", "配平：HCl 系数 4（从产物 Cl 总数 2+2 倒推）、H2O 系数 2——约1.5分，她只写1个 HCl 是主要丢分处", "产物 MnCl2+Cl2 写全、Cl2 标↑——约1分", "条件 △ 写在等号上方（漏△约扣0.5分）"], "frame": "先默背这是本章第一个必背方程式→写骨架→配平专用抓手：数产物一侧 Cl 总数（MnCl2 的2+Cl2 的2=4）倒推 HCl 配4→补 H2O 配2→先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "14-(1)-BDC", "full_score": 2.0, "got_score": 0.0, "student_answer": "BDC", "std_answer": "未知（题意不明）", "error_type": "未知（据总分反推0分，不确定）", "knowledge_point": "疑为装置/选项选择", "note": "", "stem": "I. 氯气是制备含氯化合物的重要原料，工业和生活中常用含氯消毒剂，实验室还用下图所示装置制取干燥纯净的氯气。(1)装置 A 中发生反应的化学方程式为＿＿。(2)B、C 中分别装的试剂是＿＿、＿＿。(3)写出该实验中[尾气处理]的化学方程式＿＿。(4)新制氯水显黄绿色说明其中含有＿＿，[说明其中含有 HClO 的现象，不清]。(5)实验发现，一瓶密封不严的漂白粉已变质[部分文字不清]。假设①：该漂白粉未变质；假设②：该漂白粉全部变质，含有 CaCl2、CaCO3[推断]；假设③：该漂白粉部分变质，既含有 CaCl2、Ca(ClO)2，又含有 CaCO3。II. 设计实验方案：实验 1，取少量上述漂白粉样品于试管中，加入适量稀盐酸，观察是否有气泡产生；实验 2，向实验 1 反应后的试管中滴加 1-2 滴品红溶液，振荡。预期现象和结论：a.若有气泡产生，则假设＿＿不成立；b.若品红溶液褪色，结合实验 1 的判断，则假设＿＿成立；c.若品红溶液不褪色，则假设＿＿成立。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(1)-BDC|1", "card_type": "concept", "teach": "制取干燥纯净Cl2的净化顺序是固定的：发生装置制出的Cl2先过B瓶饱和食盐水——除去混有的HCl（HCl极易溶于水，Cl2在饱和食盐水中溶解很少）；再过C瓶浓硫酸——干燥除水蒸气；最后收集，尾气用NaOH溶液吸收。顺序绝不能反：如果先干燥后除HCl，气体从食盐水里出来又会带上水蒸气，干燥白做。记忆抓手八个字：“先除杂、后干燥”，B的任务是除HCl，C的任务是吸水。", "why": "对B、C两瓶各装什么、谁先谁后没有把握，净化流程的顺序和分工没记牢。", "check_q": "制Cl2时把饱和食盐水和浓硫酸的顺序颠倒，会有什么问题？", "check_a": "气体最后经过食盐水会重新带上水蒸气，干燥失败，收集到的Cl2不纯净不干燥。", "steps": "1. 先给净化流程排总顺序：发生装置出来的气体先除杂、再干燥、后收集、最后尾气处理——“先除杂后干燥”是总纲\n2. 给每个瓶子分工：饱和食盐水瓶负责除HCl（HCl极易溶、Cl2在饱和食盐水中溶解少），浓硫酸瓶负责吸水蒸气\n3. 按分工套字母：先过除HCl的B瓶，再过干燥的C瓶，顺序写定\n4. 自检反序后果：若先干燥后除杂，气体从食盐水中出来会重新带水，干燥白做——能讲出这一步说明顺序真懂了", "need": ["制取氯气的净化顺序（先除杂后干燥）", "饱和食盐水除去Cl2中HCl的原理", "浓硫酸的干燥作用", "氯气尾气用NaOH溶液吸收"], "img": "chem-14.jpg"}, {"subject": "化学", "question_no": "14-(3)", "full_score": 4.0, "got_score": 0.0, "student_answer": "Cl2+NaOH=NaCl+HClO", "std_answer": "重建：Cl2+2NaOH=NaCl+NaClO+H2O", "error_type": "产物错误", "knowledge_point": "氯气与NaOH反应（尾气吸收）；注意产物是NaClO不是HClO", "note": "", "stem": "写出用NaOH溶液吸收氯气（尾气处理）的化学方程式。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(3)|1", "card_type": "redo", "teach": "Cl2与NaOH溶液反应：Cl2＋2NaOH＝NaCl＋NaClO＋H2O，产物是次氯酸钠NaClO，不是次氯酸HClO。两个反应要分清：Cl2与水反应生成HCl和HClO（可逆）；Cl2与碱反应时，生成的HClO会立刻被碱中和，最终产物是次氯酸盐。工业制漂白液、实验室吸收Cl2尾气用的都是这个反应。四步检查：化学式NaClO里的Na不能丢；NaOH配2；常温无条件；没有气体和沉淀，不加符号。她把氯水反应和氯碱反应混成了一个。", "why": "产物写成HClO，没想通碱性环境里HClO会被NaOH中和成NaClO。", "check_q": "漂白液的有效成分是什么？它和漂白粉的有效成分有什么共同点？", "check_a": "NaClO；两者有效成分都是次氯酸盐，遇酸或CO2都能生成HClO起漂白作用。", "steps": "1. 先分清两个近亲反应：Cl2与水生成HCl＋HClO；Cl2与碱反应，产物要再走一步——生成的HClO立刻被碱中和成盐\n2. 定产物：NaCl、NaClO（次氯酸钠）和H2O，写化学式时NaClO里的Na绝不能丢\n3. 写骨架配平：Cl2＋2NaOH＝NaCl＋NaClO＋H2O，Na、Cl、O逐个数平\n4. 标条件符号：常温无条件，无气体沉淀不标符号；收尾对照“氯水反应”确认没把两个反应写串", "need": ["氯气与NaOH溶液反应的化学方程式", "次氯酸钠NaClO是漂白液的有效成分", "氯气与水反应和与碱反应的区别", "酸与碱中和对产物的影响（HClO被中和为NaClO）"], "points": ["产物写 NaClO（次氯酸钠）不是 HClO——约1.5分，她错在核心产物", "产物三件全：NaCl+NaClO+H2O——约1分", "配平：NaOH 前配 2（Cl2+2NaOH=…）——约1分", "无条件、无符号（常温溶液反应，无气体沉淀生成）——约0.5分"], "frame": "先想环境：碱性溶液里生成的 HClO 会立刻被 NaOH 中和→产物落到次氯酸盐 NaClO→先定产物（反应类型/条件定产物）→写骨架式→四步检查逐项打勾：①化学式写对（下标不动）→②配平（抓守恒或从产物原子总数倒推系数）→③条件写全→④气体↑/沉淀↓该标才标→最后数一遍两边原子数再落笔。"}, {"subject": "化学", "question_no": "14-(5)", "full_score": 6.0, "got_score": 0.0, "student_answer": "CaCl2·Ca(ClO)2 / CaCO3 / 圈②；下行圈①、③", "std_answer": "部分重建：有效成分应为Ca(ClO)2", "error_type": "概念混淆+未知（标准缺失，据总分反推合计0分，不确定）", "knowledge_point": "漂白粉：有效成分Ca(ClO)2 vs 混合物CaCl2·Ca(ClO)2", "note": "", "stem": "I. 氯气是制备含氯化合物的重要原料，工业和生活中常用含氯消毒剂，实验室还用下图所示装置制取干燥纯净的氯气。(1)装置 A 中发生反应的化学方程式为＿＿。(2)B、C 中分别装的试剂是＿＿、＿＿。(3)写出该实验中[尾气处理]的化学方程式＿＿。(4)新制氯水显黄绿色说明其中含有＿＿，[说明其中含有 HClO 的现象，不清]。(5)实验发现，一瓶密封不严的漂白粉已变质[部分文字不清]。假设①：该漂白粉未变质；假设②：该漂白粉全部变质，含有 CaCl2、CaCO3[推断]；假设③：该漂白粉部分变质，既含有 CaCl2、Ca(ClO)2，又含有 CaCO3。II. 设计实验方案：实验 1，取少量上述漂白粉样品于试管中，加入适量稀盐酸，观察是否有气泡产生；实验 2，向实验 1 反应后的试管中滴加 1-2 滴品红溶液，振荡。预期现象和结论：a.若有气泡产生，则假设＿＿不成立；b.若品红溶液褪色，结合实验 1 的判断，则假设＿＿成立；c.若品红溶液不褪色，则假设＿＿成立。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(5)|1", "card_type": "concept", "teach": "漂白粉要分三层记：成分是CaCl2和Ca(ClO)2的混合物；有效成分只有Ca(ClO)2；变质产物是CaCO3。变质过程：Ca(ClO)2吸收空气中的CO2和水，生成CaCO3和HClO，HClO见光分解失效，所以全部变质的漂白粉只剩CaCl2和CaCO3。检验变质的两个探针：加稀盐酸有气泡，说明含CaCO3、已经变质；再滴品红，褪色说明还有Ca(ClO)2，是部分变质，不褪色则是全部变质。她把成分、有效成分、变质产物搅在一起，三个假设自然无从判断。", "why": "把漂白粉的成分、有效成分和变质产物混为一谈，假设判断全乱了。", "check_q": "一瓶漂白粉加稀盐酸产生气泡，再加品红不褪色，说明它处于什么状态？", "check_a": "全部变质：含CaCO3（加酸有气泡），且已无Ca(ClO)2（品红不褪色）。", "steps": "1. 先把漂白粉的三个身份分开列：成分是CaCl2与Ca(ClO)2的混合物，有效成分只有Ca(ClO)2，变质产物是CaCO3——判断题逐项只对一个身份\n2. 把变质链写出来：Ca(ClO)2吸空气中CO2和水→生成CaCO3和HClO→HClO见光分解失效\n3. 用两个探针判变质程度：加稀盐酸有气泡说明含CaCO3（已变质）；品红褪色说明还有Ca(ClO)2（部分变质），不褪色是全部变质\n4. 逐个假设代入探针结果验证，别把成分、有效成分、变质产物三个概念搅在一起套用", "need": ["漂白粉的成分与有效成分Ca(ClO)2的区别", "漂白粉变质的原理（与CO2、水反应及HClO分解）", "碳酸钙与稀盐酸反应产生气泡的检验", "品红溶液检验次氯酸盐漂白性"], "points": ["成分答对：漂白粉是 CaCl2 与 Ca(ClO)2 的混合物（约2分）", "有效成分答对：Ca(ClO)2（她答成混合物写法 CaCl2·Ca(ClO)2，不得分，约2分）", "变质产物答对：CaCO3（约1分）", "检验/判断变质的方法点：加稀盐酸有气泡证明含 CaCO3、已变质；滴品红褪色说明还有 Ca(ClO)2、部分变质（约1分）"], "frame": "漂白粉题固定三层落笔：先写\"成分\"（两种盐的混合物）→再写\"有效成分\"（只 Ca(ClO)2 一个）→最后写\"变质\"（吸 CO2+H2O 生成 CaCO3、HClO 见光分解）→判断题逐个假设按这三层对号，不要把三层搅在一起。", "img": "chem-14.jpg"}, {"subject": "语文", "question_no": "1", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "审题偏差", "knowledge_point": "论述类：张冠李戴——把本文作者的观点（\"写诗的人\"机械写诗缺诗意）安到江湜头上；江湜诗只是论据", "note": "", "key": "语文|1|1", "card_type": "concept", "teach": "论述类文本选择题第一大坑叫张冠李戴：材料里有好几个人在说话，选项故意把甲的观点安到乙头上。这道题里，江湜是材料二请来的诗人，他的诗和话只是被讨论的例子；批评有人写诗像机器一样拼凑、缺乏诗意，是文章作者的观点，不是江湜说的。你选错，就是把作者的观点认成了江湜的。防坑方法固定三步：第一步，圈出选项里的主语（谁说、谁认为）；第二步，回原文找到这个人名所在的段落；第三步，把选项的说法和原文那句话逐字比对，主语对不上、原文找不到出处的，直接排除。宁可慢十秒，也不要凭印象选。", "why": "没圈选项的主语就凭印象选，把作者的观点安到了江湜头上。", "check_q": "材料中作者引用学者王某的事例来说明自己的观点。下列哪一项犯了张冠李戴的错误？A.作者认为写作不能机械拼凑 B.王某认为写作不能机械拼凑（原文中王某只提供了事例，并未表态）C.材料提到了王某的事例", "check_a": "B。事例提供者没有发表这个观点，把作者的观点安到他头上就是张冠李戴；判断时先认主语，再回原文找这个人说过的原话。", "steps": "1. 先看设问落点：问的是某个观点的归属（谁说的、谁认为的），先把要判断的主语锁死。\n2. 圈出每个选项里的人名和主语，把江湜和本文作者先分清谁是谁。\n3. 回原文定位江湜出现的段落，看他的诗和话在文中是被讨论的例子（论据），还是观点本身。\n4. 逐项对位验：'机械写诗、缺乏诗意'是作者批评别人的话，被选项安到了江湜头上——张冠李戴，排除。\n5. 剩下选项再逐项回原文核对细节（对象、程度、范围），与原文全对上的才留下。", "need": ["论述类文本张冠李戴型干扰项的识别", "论述类文本中观点与论据（例子）的区分", "《AI写诗》一文的论述结构与作者观点梳理"], "stem": "（阅读材料：材料一（AI 写诗）、材料二（文艺创作与 AI），见原卷）1. 下列对材料相关内容的理解和分析，不正确的一项是（3 分）A. 诗人江湜认为，诗意来自生活中的灵感，“写诗的人”通过机械式写出来的作品往往缺乏独特的诗意。B. AI 在诗歌创作上具有惊人的综合和组织能力，虽已冲击到“写诗的人”，但无法完全替代真正的“诗人”。C. AI 能够描写景象，也能渲染氛围，但是，它缺失“自我意识”，难以通过深度思考而创作出伟大的作品。D. 当内心被震撼的景象触动时，诗人才会有创作的冲动，然而，诗心是难以把控的，AI 目前更是无法产生。"}, {"subject": "语文", "question_no": "4", "full_score": 6.0, "got_score": 2.0, "student_answer": "笼统作答（约2点）", "std_answer": "①原创能力②诗境营造③诗心触动④解决自己的问题", "error_type": "表述不规范", "knowledge_point": "信息筛选整合：四点只答出约两点，且语言口语化、未扣住\"高段位/诗境/诗心\"术语", "note": "", "key": "语文|4|1", "card_type": "concept", "teach": "这道6分简答题问人类诗歌高于AI的地方，标准答案是四个得分点：①原创能力——AI只是把现成诗句综合组织、拼凑模仿，人能从无到有地创造；②诗境营造——AI能渲染气氛，却营造不出浑然天成的诗境；③诗心触动——诗人会被景象和经历触动内心而产生创作冲动，AI没有自我意识和情感；④解决自己的问题——写诗是诗人表达情感、安顿自我的方式，AI没有自己的问题。你只答出约两点，还用了口头语，所以只得2分。方法记牢：先看分值定点数，6分题至少准备3到4点；再回材料逐段找差异句，一段提炼一点；最后用材料里的术语（诗境、诗心、高段位）写答案，一点一行，不要揉成一团。", "why": "只凭感觉答了约两点，没按分值回材料逐段提炼得分点，还用了口头话。", "check_q": "一道6分的简答题，参考答案有4个得分点。动笔答题之前，你应该先做哪两件事？", "check_a": "先按分值估点数（6分约需3到4点），再回原文逐段划出关键句、一段提炼一点，用原文术语分点作答。", "steps": "1. 先按分值定点数：6分题按一点约1.5分估，先在草稿上列出4个空位再动笔。\n2. 回原文分段扫描，专找作者直接比较'人高于AI'的句子，逐段提炼，不靠印象。\n3. 把提炼出的意思换成原文术语表述（高段位、诗境、诗心），写成观点句，不用口头话。\n4. 按原创能力、诗境营造、诗心触动、解决自己的问题四层排好顺序，分点写全。\n5. 写完自查三件事：点数够不够、每点有没有原文依据、最后的情感层有没有漏掉。", "need": ["简答题按分值定点数的答题方法", "信息类文本的筛选整合与术语化表述", "《AI写诗》四个核心论点（原创/诗境/诗心/解决问题）及其原文依据"], "points": ["得分点1（约 1.5 分）：原创能力——人能从无到有创造，AI 只是综合组织、拼凑模仿现成诗句。她答题时没有明确点出这一层。", "得分点2（约 1.5 分）：诗境营造——人能营造浑然天成的诗境，AI 只能渲染氛围。她用口头话带过，没扣住'诗境'这个材料术语，部分给分。", "得分点3（约 1.5 分）：诗心触动——诗人被景象和经历触动内心产生创作冲动，AI 没有自我意识和情感。她约略答到，是她 2 分的主要来源之一。", "得分点4（约 1.5 分）：解决自己的问题——写诗是诗人表达情感、安顿自我的方式，AI 没有自己的问题。她没有答到。", "她的账：4 点只答出约 2 点，且语言口语化、没用材料里的'高段位/诗境/诗心'等术语，得 2/6。"], "frame": "先看分值定点数：6 分题先在草稿上列 4 个空位再动笔。回材料逐段找'人有而 AI 无'的差异句，一段提炼一点。落笔一点一行、序号标清，每点写成'术语观点句 + 一句材料依据'（如'诗境营造：AI 能渲染氛围，却成不了浑然天成的诗境'）。写完自查：点数够不够、每点有没有用上材料原词、有没有两点揉成一团。", "stem": "（阅读材料：材料一（AI 写诗）、材料二（诗人江湜谈 AI），见原卷）设问：结合两则材料简要分析（与《登高》何以称「七律之冠」相关），从材料中提炼 AI 诗歌与人类诗歌的差异。（6 分）"}, {"subject": "语文", "question_no": "8", "full_score": 6.0, "got_score": 3.0, "student_answer": "部分作答", "std_answer": "①叙事线索②桥梁/奉献象征③守望与归属④人生过渡", "error_type": "表述不规范", "knowledge_point": "\"渡口\"多重象征只答出一半，\"奉献\"\"过渡\"等义项缺失", "note": "", "key": "语文|8|1", "card_type": "concept", "teach": "小说标题内涵题要挖四层，你只答出约一半。这篇《渡口》的标题：①表层义与结构义——渡口是故事发生的地点，也是叙事线索，人物在这里相遇、等待、离别，全文围绕它展开；②象征义之奉献——渡口和摆渡者默默连接两岸、送人过河，象征无私奉献、成全他人；③象征义之守望与归属——渡口是离人出发、归人回来的地方，承载着守望、牵挂与归属感；④主题义之人生过渡——渡口是从此岸到彼岸的过渡，象征人生中的转折、成长与命运变迁。答题公式记住：地点物象义到线索结构义，再到象征义，最后到主题义，逐层往下挖，每层都回原文找一处证据支撑，不要停在第一层。", "why": "只答了表层和一部分象征义，奉献和人生过渡两层没有挖出来。", "check_q": "某小说以桥为题：桥是村里通往外界的唯一通道，老村长守桥三十年，主人公走出大山后又回到家乡。按四层法，桥的主题义应怎样概括？", "check_a": "象征人生的跨越与归途：走出大山是人生的过渡与成长，返乡是归属；桥既是出发点也是归途，寄托成长、闯荡与归属的主题。能答出过渡转折加归属即对。", "steps": "1. 先定框架：标题内涵题按表层义→结构义→象征义→主题义四层挖，先把四层写在草稿边上。\n2. 回小说找'渡口'的关键情节：人物在这里相遇、等待、离别，摆渡人做了什么。\n3. 由情节提炼象征层：摆渡连接两岸、送人过河＝奉献与成全；送往迎来＝守望与归属。\n4. 再升一层主题义：从此岸到彼岸＝人生过渡、命运的转折点。\n5. 分点作答，每层'义项＋文中情节依据'配套写，交卷前数一遍四层齐不齐。", "need": ["小说标题内涵题的四层分析法（表层/结构/象征/主题）", "象征手法在小说中的作用", "《渡口》的情节线索、摆渡人形象与主题"], "points": ["得分点1（约 1.5 分）：表层义与结构义——渡口是故事发生的地点，也是叙事线索，人物在此相遇、等待、离别。她答到了。", "得分点2（约 1.5 分）：象征义·奉献——渡口与摆渡者默默连接两岸、送人过河，象征无私奉献、成全他人。她没有挖出来，整点丢失。", "得分点3（约 1.5 分）：象征义·守望与归属——渡口是离人出发、归人回来的地方，承载守望、牵挂与归属感。她只答出一部分。", "得分点4（约 1.5 分）：主题义·人生过渡——渡口是从此岸到彼岸的过渡，象征人生的转折、成长与命运变迁。她没有答到。", "她的账：四层只落实约两层，得 3/6，丢分集中在奉献和人生过渡两层。"], "frame": "标题内涵题按四层往下挖，顺序不能乱：地点物象义 → 线索结构义 → 象征义（可拆两点）→ 主题义。每层落笔都写成'观点句 + 原文一处证据'（如'奉献：摆渡者日复一日送人过河，自己始终留在岸边'）。自查：有没有停在第一层就收笔；每一层能不能在原文里指出对应的情节或细节。", "stem": "（阅读材料：小说《渡口》（有删改），见原卷）设问：标题「渡口」的内涵。（6 分）"}, {"subject": "语文", "question_no": "9", "full_score": 3.0, "got_score": 0.0, "student_answer": "非BEG", "std_answer": "BEG", "error_type": "知识盲区", "knowledge_point": "文言断句：\"天下将乱\"后断、\"也\"句末断、\"其\"句首表揣测", "note": "", "key": "语文|9|1", "card_type": "concept", "teach": "文言断句有三招，这道题全用得上。第一招，看句末语气词：也、矣、乎、哉多在句末出现，见到它们，先在它后面断一刀。第二招，看句首虚词：其放在句首常表揣测或反问（其……乎），要在其前面断开，让它领起新句；夫、盖、若夫出现的地方也多是句首。第三招，先找主谓宾：先通读一句，认出谁做什么，一个完整的主谓结构就是一句话，比如天下将乱主谓完整，后面就该断。你这次断错，就是逐字硬猜、没先理大意。固定流程：先默读一遍说出大意，再按语气词和主谓结构下刀，最后连起来读一遍，检验通不通顺。", "why": "没先通读理大意，也没用语气词和主谓结构定位，逐字猜断点。", "check_q": "断句时，句首的其表揣测语气，应该在它的前面还是后面断开？另外，句末见到哪个字最常提示要断开？", "check_a": "在其前面断开，让其领起新句（如其李将军之谓乎，是揣测语气）；句末见也、矣、乎、哉等语气词，一般在其后断开。", "steps": "1. 先通读全句理大意，不急着逐字猜断点，先感知整句在说什么。\n2. 标出句末语气词（也、矣、乎、哉），在它们后面先断一刀。\n3. 标出句首虚词（其、夫、盖）：'其'在句首表揣测，要在它前面断开，让它领起新句。\n4. 用主谓结构验断点：'天下将乱'主谓完整，后面该断；每段都要能找出主谓。\n5. 把断好的句子连读一遍，检查语气连贯、每段意思完整，再对照选项定组合。", "need": ["文言断句中句末语气词（也/矣/乎）的定位作用", "句首虚词（其/夫/盖）的断句标志作用", "文言句子主谓宾结构的识别"], "points": ["关键断点1（共 3 分，按断点对错给分）：“天下将乱”之后断——“天下将乱”主谓完整、自成一句。她逐字猜断，这里断错。", "关键断点2：句末语气词“也”之后断——“也”出现在句末就要在它后面落一刀。她没有用语气词定位。", "关键断点3：句首“其”之前断——“其”放句首表揣测（其……乎），要让它领起新句，在其前面断开。她把“其”粘在上一句里了。", "她的账：三个定位点一个都没用上，断句组合选错，得 0/3。"], "frame": "断句固定三步：第一步先默读全句、用白话说出大意，不认识的字先放过；第二步下刀——先在句末语气词（也、矣、乎、哉）后面断，再在句首虚词（其、夫、盖）前面断，最后按主谓宾完整性补齐其余断点；第三步把断好的句子连起来通读一遍，不顺口的地方就是断错的地方，回去改。自查：每句是否都有主谓、语气词是否都落在了句末。", "stem": "9. 材料一中画波浪线的部分有三处需要断句，请用铅笔将答题卡上相应位置的答案标号涂黑。（3 分）原句：天下将 A 乱 B 非命 C 世之才不能 D 济也 E 能 F 安之者 G 其 H 在君乎"}, {"subject": "语文", "question_no": "12(1)", "full_score": 4.0, "got_score": 0.0, "student_answer": "\"现在天下没有…的地方…的人呢？\"", "std_answer": "当今天下莫非还有…在渭水岸边钓鱼的贤人吗？", "error_type": "知识盲区", "knowledge_point": "\"得无…乎\"（莫非…吗）译反，\"被（穿着）\"\"钓于渭滨（状后）\"全丢", "note": "", "key": "语文|12(1)|1", "card_type": "concept", "teach": "这句4分你得0分，三个采分点全丢，逐个拆。原句的标准译意是：当今天下莫非还有像姜太公那样披着蓑衣在渭水岸边钓鱼的贤人吗？采分点一，得无……乎是固定句式，译作莫非……吗，是反问不是疑问，你把语气译反，整句意思就反了。采分点二，被通披，是动词穿着、披着，不能漏译。采分点三，钓于渭滨是状语后置，正常语序是于渭滨钓，译时要倒过来说在渭水岸边钓鱼。翻译铁律是字字落实：每个实词、虚词、句式都要在译文里有对应的词，漏一个扣一分；动笔前先在原文上把后置、省略、通假标出来，再逐字翻。", "why": "得无……乎的反问句式不认识导致译反，又漏译了被（披）和状语后置。", "check_q": "翻译句子：得无异于古之贤人乎？（提示：得无……乎等于莫非……吗）", "check_a": "（这人）莫非和古代的贤人不一样吗？得无……乎要译成莫非……吗，语气是反问，不能译成平常的疑问或否定。", "steps": "1. 先逐字落实再组句：给每个字定身份，特别留意固定句式和通假字，先别急着顺译。\n2. 先认句式定语气：'得无……乎'是固定反问句式，译作'莫非……吗'，全句语气先立住。\n3. 逐个啃得分点词：'被'通'披'，译'穿着、披着'，这个字漏译整句丢分。\n4. 处理特殊语序：'钓于渭滨'是状语后置，调整成'在渭水岸边钓鱼'再译。\n5. 组句通读一遍，按人物、地点、动作排顺，逐项核对得分点是否全部译出。", "need": ["固定句式'得无……乎'的反问用法", "通假字'被'通'披'及常见通假现象", "文言状语后置句的语序调整译法"], "points": ["得分点1（1 分）：“得无……乎”固定句式译作“莫非……吗”，是反问语气。她把语气译反，整句意思跟着反了，这 1 分丢。", "得分点2（1 分）：“被”通“披”，译作“穿着、披着”（披着蓑衣）。她漏译，这 1 分丢。", "得分点3（1 分）：“钓于渭滨”是状语后置，要倒译成“在渭水岸边钓鱼”。她按原语序硬译，这 1 分丢。", "得分点4（1 分）：全句句意通顺、对象准确——译出“像姜太公那样的贤人”。三个采分点全丢，这一点自然也拿不到。", "她的账：4 个点全丢，得 0/4。标准译文：当今天下莫非还有像姜太公那样披着蓑衣在渭水岸边钓鱼的贤人吗？"], "frame": "翻译动笔前先在原文上做三处标记：圈出固定句式（得无……乎之类）、标出状语后置和省略成分、给通假字注上本字。然后逐字落实落笔：每个实词、虚词都要在译文里找到对应的词，句式语气（反问/疑问）必须原样保留。译完回读一遍自查：有没有漏译的词、有没有语序没倒过来的后置成分、语气和原句是否一致。", "stem": "12. 把材料中画横线的句子翻译成现代汉语。（8 分）（1）今天下得无有被褐怀玉而钓于渭滨者乎？"}, {"subject": "语文", "question_no": "12(2)", "full_score": 4.0, "got_score": 2.0, "student_answer": "大意译出", "std_answer": "从这一点说，人有些缺点难道就弃而不用吗？", "error_type": "知识盲区（部分）", "knowledge_point": "\"由（从）/偏短（缺点）/庸（难道）\"只落实部分", "note": "", "key": "语文|12(2)|1", "card_type": "concept", "teach": "这句的标准译文是：从这一点说，人有些缺点，难道就弃而不用吗？三个关键词决定分数：由是从，由是观之就是从这件事看；偏短不能拆开按字面理解，它合成一个词，指缺点、短处；庸是副词难道，放在疑问句里加强反问语气。你只落实了一部分，得2分丢2分。文言翻译最常见的丢分就是这种词认识一半：多义词只记第一个义项，合成词拆开硬译。办法是建一份高频词多义清单，比如庸有难道、平庸、受雇等义，由有从、由于、听任等义，短有短处、说人坏话等义；翻译时先想这个词在本句最合理的义项，再代入检验通不通。", "why": "由、偏短、庸三个关键词只落实了一部分，多义词只记了表面义项。", "check_q": "庸在下列哪句中应译为难道？A.庸医误人 B.庸可弃乎 C.中庸之道", "check_a": "B。庸可弃乎是反问句，庸作副词译难道；A中的庸是平庸，C中是儒家概念，都不能译作难道。", "steps": "1. 先逐字落实，圈出拿不准的词（由、偏短、庸），逐个定性后再组句。\n2. '由'结合固定结构'由是观之'定性：从这件事看，译'从'。\n3. '偏短'不许拆字硬译：它是合成词，整体译'缺点、短处'。\n4. '庸'放在疑问句里是副词'难道'，配合全句定成反问语气。\n5. 组句通读自查：每个关键词都有对应译词、语气与原句一致，才算落实。", "need": ["文言多义词'庸'的义项辨别（难道/平庸/功用）", "合成词'偏短'的整体释义", "'由是观之'类固定结构的译法"], "points": ["得分点1（1 分）：“由”译作“从”（由是观之＝从这一点说）。她只落实了一部分。", "得分点2（1 分）：“偏短”是合成词，译作“缺点、短处”，不能拆成'偏'和'短'按字面硬译。她在此处丢分。", "得分点3（1 分）：“庸”是副词，译作“难道”，加强反问语气。她没有译出。", "得分点4（1 分）：全句通顺——“人有些缺点难道就弃而不用吗”，反问语气完整。她大意译出，拿到部分分。", "她的账：三个关键词只落实约一半，得 2/4，丢分全在多义词只记表面义项上。标准译文：从这一点说，人有些缺点，难道就弃而不用吗？"], "frame": "翻译先啃得分点词再组句：把句中三四个关键词逐个列在草稿上，每个词先想它最常见的 2–3 个义项，再代入本句选最合理的（合成词如'偏短'不许拆开译）。然后按'字字对应'把整句写出来，最后通读检验：译文读起来像不像一句通顺的现代话、反问等语气有没有保留。平时把高频多义词（庸、由、短这类）按义项建清单，考前只看清单。", "stem": "12. 把材料中画横线的句子翻译成现代汉语。（8 分）（2）由此言之，士有偏短，庸可废乎？"}, {"subject": "语文", "question_no": "13", "full_score": 3.0, "got_score": 2.0, "student_answer": "部分作答", "std_answer": "①材料一：不计前嫌用张绣/魏种/毕谌②材料二三：唯才是举、不因小瑕弃用", "error_type": "表述不规范", "knowledge_point": "曹操\"山不厌高，海不厌深\"求贤若渴，材料三要点或表述有缺", "note": "", "key": "语文|13|1", "card_type": "concept", "teach": "这道题要求结合三则材料，说明曹操山不厌高、海不厌深式的求贤若渴是怎样体现的。满分3分，一则材料1分，必须分材料作答。得分构成是：①材料一，曹操不计前嫌，任用曾经背叛过他、与他为敌的张绣、魏种、毕谌等人，体现的是不计较旧怨；②材料二和材料三，唯才是举，不因为一个人有小缺点、小瑕疵就弃而不用，体现的是用人只看才能。你的答案丢了1分，多半是把几则材料混在一起写，或者漏了不计前嫌这一面。方法记牢：凡题目说结合材料一二三，答案就分成三点写，每点用固定句式：材料几中，某人做了什么，体现了哪一点，最后不要再加空泛的总结。", "why": "没有按材料逐则对应作答，要点混在一起，漏了不计前嫌这一面。", "check_q": "题目要求结合材料一、材料二分别说明某人的特点。写答案时最稳妥的格式是什么？", "check_a": "分点写：①材料一……体现……；②材料二……体现……。每则材料单独成点，用谁加做了什么加体现哪一点的句式，不混写、不漏则。", "steps": "1. 先审设问：要求'结合三则材料'说明，先定规矩——一则材料对应一个要点，分开答。\n2. 逐则回材料定位：材料一找曹操用人的具体人事（张绣、魏种、毕谌都曾与他为敌）。\n3. 给材料一提炼关键词：任用背叛过自己的人＝不计前嫌。\n4. 给材料二、三提炼关键词：唯才是举、不因小瑕弃人＝用人只看才能。\n5. 分材料分点落笔，一条材料写一点，写完数一遍三则材料是否都回应到了。", "need": ["曹操《求贤令》与'唯才是举'的用人思想", "材料题逐则对应、分材料作答的方法", "《短歌行》'山不厌高，海不厌深'的用典与求贤情感"], "points": ["得分点1（1 分）：材料一——曹操不计前嫌，任用曾经背叛他、与他为敌的张绣、魏种、毕谌，体现'不计较旧怨'。她把材料混着写，这一点漏掉了。", "得分点2（1 分）：材料二——唯才是举，用人只看才能。她答到了。", "得分点3（1 分）：材料三——不因小缺点、小瑕疵就弃而不用（礼贤、广纳）。她答到了。", "她的账：一则材料 1 分，她丢的是材料一那 1 分，得 2/3。丢分动作很具体：没有分材料作答，要点揉在一起，阅卷找不到对应点。"], "frame": "题目说'结合材料一二三'，答案就必须分三点、与材料一一对应，一点都不能合并。每点用固定句式落笔：'材料几中，某人做了什么事，体现了……'，先写事例动作、再点品质词。写完不要再加空泛总结句。自查：数一遍材料有几则、答案就有几点；每点里有没有具体人名和具体事，没有就是空话，重写。", "stem": "（阅读材料：《三国志·魏书·武帝纪》＋《资治通鉴》，共三则材料，见原卷）设问：三则材料如何体现「山不厌高，海不厌深」？（3 分）"}, {"subject": "语文", "question_no": "17", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "知识盲区", "knowledge_point": "字音：B揳入(xiē)/C忸怩(ní)/D皱褶(zhě)包扎(zā)着恼(zháo)", "note": "", "key": "语文|17|1", "card_type": "concept", "teach": "这道字音题错在几个高频易读错字，一次记牢：揳入的揳读xiē，和楔子的楔同音，不读jiā；忸怩读niǔ ní，是不好意思的样子，不要读成nǐu nì；皱褶的褶读zhě，连起来是zhòu zhě；包扎是动词，扎读zā，扎是多音字，扎根读zhā，包扎读zā，挣扎读zhá；着恼的着读zháo。字音题没有取巧的技巧，全靠平时积累：读课文、做题时把拿不准的字音当场查、当场记进错字本，尤其多音字要连着词记音，记包扎zā，而不是只记一个孤零零的字。你这次选错，说明这几个词的读音从来没有真正落实过。", "why": "揳、忸怩、褶、扎这几个字的读音凭感觉读，从没查证落实。", "check_q": "下列读音全对的一组是：A.楔子xiē子、挣扎zhá B.包扎bāo zhā、忸怩niǔ ní C.皱褶zhòu zhē、着急zháo jí", "check_a": "A。B错在包扎应读zā；C错在褶应读zhě。多音字必须连着词语一起记读音。", "steps": "1. 先认清题型：字音题没有推理捷径，只能逐项把每个字的读音落实，逐项朗读排查。\n2. 把拿不准的字先圈出来（揳、忸怩、褶、扎、着），尤其优先排查多音字。\n3. 多音字按语境定音：'包扎'是动词，扎读zā；'着恼'的着读zháo，先定音再判断。\n4. 用落实好的读音逐项排错：揳xiē、忸怩niǔ ní、皱褶zhě逐个与选项拼音核对。\n5. 剩下读音全对的一项即答案；错题里的字音当场记进积累本，不许凭感觉放过。", "need": ["易读错字专项：揳（xiē）、忸怩（niǔ ní）、皱褶（zhě）", "多音字'扎'（zā/zhā/zhá）与'着'（zháo/zhe/zhuó）的语境辨音", "字音积累方法：当场查证与积累本"], "stem": "17. 下列词语中字形和加点字的注音完全正确的一项是（2 分）A. 峭壁（qiào） 思忖（sīcǔn） 炽（ch□）热 茫茫 霞蔚云蒸 B. 静谧（mì） 揳入（□iē） 峥嵘（zhēng） 石碣 轻歌曼舞 C. 喑哑（yīn） □靠（□） 忸怩（nǐ） 慰藉 嬉皮笑脸 D. 皱褶（zhě） 包扎（zhā） 着恼（zhuó） 阴霾 酩酊淋漓"}, {"subject": "语文", "question_no": "18", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "知识盲区", "knowledge_point": "文言实词：C项\"到中流击水（击水：游泳）\"说法错误", "note": "", "key": "语文|18|1", "card_type": "concept", "teach": "这道题考课文《沁园春·长沙》里的到中流击水。错误项把击水解释错了：击水就是击打水面、游泳前行，写的是青年毛泽东在湘江中流击水而进的矫健身姿，不是敲击水面抒发感慨之类。这类题叫课内迁移题，选项拿的全是学过的课文名句，判断对错只能靠课文注释里的原始解释，不能自己望文生义。复习方法很明确：把必修课文里老师划过的重点词句注释过一遍，尤其是诗词名句中的实词，像击水、峥嵘、挥斥方遒、浪遏飞舟；考场上遇到课内句子，先在心里默念注释，再去判断选项。", "why": "击水没有回课文注释，望文生义，把游泳前行理解错了。", "check_q": "《沁园春·长沙》浪遏飞舟中，遏是什么意思？击水又指什么？", "check_a": "遏是阻止、挡住，指江水阻挡飞快行进的船只；击水指游泳、击打水面奋力前行。两个词都必须按课文注释来记。", "steps": "1. 先定位出处：选项句子出自课内名篇《沁园春·长沙》'到中流击水'，先想课文不凭语感。\n2. 回课文注释找原始解释：'击水'＝击打水面、游泳前行，注释就是判定标准。\n3. 逐项验：把每个选项的释义代回原句，与注释逐字对照。\n4. C项对'击水'的说法与注释不符——说法错误，正是本题要选的项。\n5. 其余三项再用注释复核一遍，确认没有第二处对不上，才定案。", "need": ["《沁园春·长沙》重点实词注释（击水、峥嵘、挥斥方遒、指点江山）", "课内文言实词迁移题的注释优先原则", "文言实词望文生义的防范"], "stem": "18. 下列词语中对加点词的解释全都错误的一项是（2 分）A. □江宴送（宴：酒） 使快婢数曲（快：快速） B. 忽有飞来（飞：阻止） 绿水逶迤清□□（漪：清澈） C. 到中流击水（击水：游泳） 越陌度阡（阡：指东西向的田间小路） D. 轻拢慢捻（拢：拨弦，□□） 低眉信手续续弹（信：随意）"}, {"subject": "语文", "question_no": "19", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "知识盲区", "knowledge_point": "虚词\"之\"：C项两\"之\"均为助词\"的\"，A项介词/连词不同", "note": "", "key": "语文|19|1", "card_type": "concept", "teach": "判断虚词之的用法，靠的是替换检验法，逐项过。之常见的身份有四种：①助词的，前后是修饰关系，如水陆草木之花，换成的读得通就是它；②代词，可以换成他、它、这件事；③动词到、往，后面常跟地点，如送孟浩然之广陵的之是到；④音节助词，没有实义，如久之、顷之。这道题C项的两个之都是助词的，A项两个之一个带介词性、一个带连词性，用法并不相同，所以选错。你要做的不是背定义，而是把每一项的之依次换成的、他、到试读，哪个通顺就是哪一种。平时把课文里每个之的用法标注出来，考前只看这本账。", "why": "凭语感猜之的用法，没用替换法逐项检验，C项两个的没有看出来。", "check_q": "判断予独爱莲之出淤泥而不染中之的用法，并说明你用的检验方法。", "check_a": "之是结构助词，译作的（莲的出淤泥而不染）。检验法：把之换成的读，句子通顺且前后是修饰关系，即为助词的；若能换成他、它，则是代词。", "steps": "1. 先把每项里的两个'之'分别拎出来，单个单个判，不看整句先看单个词的身份。\n2. 用替换检验法逐个试：能换成'的'是助词；能换成'他/它'是代词；后面跟地点是动词'到'。\n3. 逐项判定：C项两个'之'换成'的'都读得通——都是助词，用法相同。\n4. A项两个'之'替换结果不同（一个介词性、一个连词性），用法不相同，排除。\n5. 选出用法相同的一项，再把每个'之'的身份默念复核一遍定案。", "need": ["文言虚词'之'的四种用法辨别（助词/代词/动词/音节助词）", "虚词辨析的替换检验法", "课内名句中'之'的典型例句（水陆草木之花、送孟浩然之广陵）"], "stem": "19. 下列各选项中，加点虚词意义和用法相同的一项是（2 分）A. 何以解忧？唯有杜康 / 忽魂悸以魄动 B. 为君翻作《琵琶行》 / 初为《霓裳》后《六幺》 C. 呦呦鹿鸣，食野之苹 / 云之君兮纷纷而来下 D. 我欲因之梦吴越 / 因为长句，歌以赠之"}, {"subject": "语文", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "知识盲区", "knowledge_point": "古今异义：②④⑨古今义相同（憔悴/一生/门庭冷落），其余不同", "note": "", "key": "语文|20|1", "card_type": "concept", "teach": "判断古今异义只有一条办法：把词放回原句翻译，译不通、别扭，就是古今义不同。先记一批常见陷阱词：妻子在古代指妻子和儿女，今天只指配偶；卑鄙在古代指地位低微、见识浅陋，是诸葛亮的自称，今天指品德坏；涕在古代指眼泪，今天指鼻涕；走在古代指跑，行在古代指走。这道题里，憔悴、一生、门庭冷落这几个词古今意思相同，其余各句都有古今差别，所以要选相同的一组。你答错，是因为拿现代义去套古句，觉得好像也讲得通。做题时对每个词都多问一句：这个意思放回古代语境，合不合人物的身份和情理？合不上就是异义。", "why": "用现代词义去套古句，没把词放回原句翻译检验，相同与不同分反了。", "check_q": "弃甲曳兵而走（《寡人之于国也》）中的走，与现代汉语走路的走意思相同还是不同？为什么？", "check_a": "不同。古义是跑、逃跑（士兵丢下盔甲、拖着兵器逃跑），今义才是步行。判断古今异义必须把词放回原句翻译，身份情理对不上就是异义。", "steps": "1. 先把设问方向圈出来：这题选古今义'相同'的一组，方向先看清，别按找不同的惯性做。\n2. 逐词放回原句翻译：译得通顺自然的，古今义多半相同，先放过。\n3. 译着别扭的词停下来：想它在古代的意思（妻子、卑鄙、涕、走这类陷阱词重点查）。\n4. 逐组核对统计：②④⑨（憔悴、一生、门庭冷落）古今相同，其余各句都有古今差别。\n5. 按'相同'这个方向定组，再把组内每个词回原句译一遍复核。", "need": ["古今异义词的识别与常见陷阱词（妻子/卑鄙/涕/走）", "词义回原句翻译的检验方法", "双音节词古今义的异同（憔悴、一生、门庭冷落）"], "stem": "20. 下列加点词古今意义相同的一项是（2 分）①失向来之烟霞 ②□□□憔□ ③人生几何 ④似诉平生不得志 ⑤铁骑突出刀枪鸣 ⑥去来江口守空船 ⑦曲终收拨当心画 ⑧明明如月 ⑨门前冷落鞍马稀 ⑩整顿衣裳起敛容 A. ①⑤⑧ B. ②⑥⑨ C. ③④⑥ D. ②④⑨"}, {"subject": "语文", "question_no": "23", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "知识盲区", "knowledge_point": "修辞：例句借代；B\"唯有杜康\"借代，A为互文", "note": "", "key": "语文|23|1", "card_type": "concept", "teach": "借代和互文最容易混，用一个检验动作就能分开。借代是用与本体相关的特征、工具、人物来代替本体，能换回去：杜康代酒（杜康是传说中的造酒者），巾帼代女子，烽烟代战争。互文是上下两句字面各说一半，意思必须拼起来才完整，比如秦时明月汉时关，其实是秦汉时的明月和关隘；开我东阁门，坐我西阁床，动作是交叉着说的。这道题B项唯有杜康以造酒者代酒，是借代；A项是互文，你把互文认成了借代。记口诀：借代找替身，互文找拼图。句子单独看意思残缺、必须和邻句拼起来读的，就是互文。", "why": "分不清借代与互文，把上下句互补的互文当成了借代。", "check_q": "判断两句的修辞：①将军百战死，壮士十年归 ②何以解忧，唯有杜康。哪句是互文，哪句是借代？", "check_a": "①是互文：并非将军都战死、壮士都归来，而是将士们征战多年、有的战死有的归来，两句要合起来理解。②是借代：杜康代指酒。", "steps": "1. 先给两个易混手法各定一个检验动作，不凭印象选：借代看'换得回本体吗'，互文看'要拼起来吗'。\n2. 验借代：'杜康'能换回'酒'（造酒者代酒），换得回——借代成立。\n3. 验互文：A项上下两句字面各说一半、意思必须拼起来才完整——是互文。\n4. 对照例句本身的手法（借代），选同为借代的一项，两项不能混选。\n5. 用互文的标志（上下对举、各说一半）再复核一遍被排除项，确认没认错。", "need": ["借代的构成方式（特征、工具、人物代本体）", "互文的识别（上下文互补、交错成义）", "借代与借喻、比喻的区别"], "stem": "23. 下列选项与例句修辞手法相同的一项是（2 分）例句：举酒欲饮无管弦 A. 主人下马客在船 B. 唯有杜康 C. 大珠小珠落玉盘 D. 千呼万唤始出来"}, {"subject": "语文", "question_no": "25", "full_score": 60.0, "got_score": 45.0, "student_answer": "《选择与（坚守）初心》", "std_answer": "—", "error_type": "论证深度不足", "knowledge_point": "见下文作文专项评估", "note": "", "key": "语文|25|1", "card_type": "concept", "teach": "你的题目《选择与坚守初心》立意没有跑偏，45分卡在论证太浅。材料里其实站着三个人：曹操天下归心，是顺应大势、成就大事；李白安能摧眉折腰事权贵，是不肯顺势、低头，守住本心；黄文秀是把个人选择落到奉献里。只写要坚守初心，等于把三个人喊成了一句口号。升格写法是设三个递进的分论点：选择要顺时代之势（曹操、黄文秀回应时代需要），坚守要不违本心之真（李白），初心最后要落到行动与奉献上（黄文秀）。再加一段思辨：当顺势与守心冲突时怎么办，势可以顺，底线不能丢。这一段就是从二类文迈进一类文的关键。每段都要事例加一句分析，不要只堆事例。", "why": "立意停在口号层，没有分论点递进，事例后面缺分析句，也没有思辨段。", "check_q": "请为这篇作文写出三个递进的分论点（各一句话），分别对应曹操、李白、黄文秀。", "check_a": "示例：①顺势而为，在时代需要中确立自己的选择（曹操成就大业、黄文秀扎根乡村）；②守心不移，在权势与诱惑面前不丢本真（李白）；③以行践心，把初心落成实实在在的奉献（黄文秀）。三点按选、守、行递进即合格。", "steps": "1. 先拆材料里的三个人，各定一个关键词：曹操顺应大势、李白守住本心、黄文秀选择落地奉献。\n2. 由三人提炼中心论点，再拆成三个递进的分论点：顺时代之势→不违本心之真→初心落于行动。\n3. 每个分论点配一个事例，事例讲完必须跟一句分析句，点明它证明了什么，不许只叙不议。\n4. 中段加一个思辨段：讨论顺势与守心冲突时如何取舍，把立意从口号拉到思考层。\n5. 结尾回扣三位人物与题目；自查三件事：分论点有没有递进、有没有只喊口号的段落、事例后有没有分析句。", "need": ["议论文分论点递进式结构", "叙议结合：事例后分析句的写法", "多则材料作文的提炼与思辨升格"], "points": ["立意维度：题目《选择与坚守初心》扣住了材料，没跑偏，保住了二类文的底盘；但立意停在'要坚守初心'的口号层，没有把三个人区分开，这是卡在 45 分的第一原因。", "结构维度：有分论点意识，但分论点之间是并列堆放、不是递进（顺势 → 守心 → 落到行动），结构分拿到但不高。", "论据维度：曹操、李白、黄文秀三则材料都用上了，材料不缺；问题是事例后面缺分析句，只有叙述没有论证，论据分打折。", "思辨维度：整段缺失——没有写'当顺势与守心冲突时怎么办'（势可以顺、底线不能丢）。这是从二类文进一类文的关键一段，她整段没写，是最大的失分维度。", "语言维度：表达基本通顺，没有明显加分项也没有大的语病，属于不加不减。", "字数与卷面维度：未见因此扣分的记录，按时写完、篇幅达标，这部分守住了。", "她的账：45/60，卡点排序是——思辨段缺失 > 分论点不递进 > 事例后无分析；立意和材料本身没问题。"], "frame": "落笔前先在草稿上完成四件事：1）把材料里每个人定一个关键词（曹操＝顺势、黄文秀＝奉献、李白＝守心）；2）排三个递进分论点（选择要顺时代之势 → 坚守要不违本心之真 → 初心最后落到行动与奉献）；3）专门留一段思辨，写清两个关键词冲突时怎么取舍；4）每段按'分论点句 + 事例一句 + 分析句一句'落笔，事例不许多写、分析不许不写。自查：分论点能不能用'不仅……而且……'串起来（能串才是递进）；每段最后一句是不是分析句；思辨段在不在。", "stem": "材料作文：材料以曹操「天下归心」、李白「安能摧眉折腰事权贵」、黄文秀等「新时代青年」事迹为引（材料原文见原卷）。要求：作为刚刚开启高中生涯的新时代青年，谈自己的思考与感悟；选准角度，明确立意，自拟标题；不少于 800 字。（60 分）"}, {"subject": "英语", "question_no": "2", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "词汇量不足/听辨弱", "knowledge_point": "短对话：house颜色，漏听关键信息", "note": "", "key": "英语|2|1", "card_type": "concept", "teach": "颜色细节题有固定套路：录音里往往不止一个颜色——先想要的、别人建议的、最后定下的，问题问最终结果。她选 B、正确是 C（dark green），多半把中间提到的颜色当了答案。抓题要诀：听到 but、in the end、let's take... 这类「拍板信号」才锁定，信号后的颜色才是真答案。场景词先认熟：paint 刷漆，decorate 装修，dark/light green 深绿/浅绿，prefer 更喜欢，curtain 窗帘。做题时在每个颜色旁记「谁说的、是不是最后定的」。", "why": "把录音中间提到的颜色当成最终答案，没等转折后的拍板信息。", "check_q": "听力小练：录音说 \"I first chose the blue curtains, but my mother thought the grey ones looked better, so we took the grey ones.\" 他们最后选了什么颜色？", "check_a": "Grey（灰色）。but 之后妈妈的意见被采纳，so 后面是最终结果；blue 是干扰项。", "steps": "1. 听前先把四个选项里的颜色词扫一遍，心里记住每个选项是什么颜色\n2. 录音里每出现一个颜色，就在对应选项旁标上「谁说的」（先想要的、妈妈建议的）\n3. 专门等拍板信号词：but、in the end、let's take、so we took——信号出现之前不下笔选\n4. 信号之后出现的颜色（dark green）才是最终定下的，锁定它\n5. 第二遍播放时只核对一件事：自己选的是不是「最后定的」那个颜色", "need": ["装修场景词：paint（刷漆）、decorate（装修）、curtain（窗帘）、dark/light green（深绿/浅绿）", "转折与拍板信号词：but、in the end、let's take", "prefer 的用法：prefer A to B（更喜欢 A）"], "stem": "（听力第2题，音频原文见试卷）考查点：短对话中 house 颜色的最终选择；注意区分先提到的颜色、他人建议的颜色与最后定下的颜色。"}, {"subject": "英语", "question_no": "3", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "听辨弱", "knowledge_point": "短对话：mother jogging outdoors", "note": "", "key": "英语|3|1", "card_type": "concept", "teach": "短对话问「某人靠什么锻炼」时，答案藏在答句的动词短语里。这题问母亲的锻炼方式，正确 B（by jogging outdoors，户外慢跑）。对话常设干扰：先提别人做什么、或以前做什么，最后才说问的那个人现在做什么，听到第一个动词就选必中坑。步骤：听前把选项动词（jogging、swimming、cycling、doing yoga）的发音在脑子里过一遍；听时只盯问的那个人的动词。场景词背熟：jog 慢跑，go cycling 骑行，do yoga 做瑜伽，take a walk 散步，keep fit 保持健康。", "why": "没盯住答句里的动词短语，被对话中提到的其他活动带偏了。", "check_q": "听力小练：\"—How does your father keep fit? —He goes swimming twice a week.\" 父亲靠什么锻炼？", "check_a": "Swimming（游泳）。答句的动词短语 goes swimming 就是答案，keep fit 是问句里的背景词，别被带偏。", "steps": "1. 听前先确认题目问的是谁（母亲），再把选项里的活动词发音在脑子里过一遍：jogging、swimming、cycling、yoga\n2. 听时只盯母亲这个人的信息，父亲或别人做的活动先在心里划掉\n3. 抓住答句里的动词短语——goes jogging outdoors 这类短语就是答案本体\n4. 警惕对话先提别人或以前的活动做干扰，以最后落到母亲身上的那个动词为准\n5. 第二遍只核对这一个动词短语有没有听错", "need": ["锻炼方式词：jog（慢跑）、go cycling（骑行）、do yoga（做瑜伽）、take a walk（散步）", "keep fit（保持健康）", "by + 动名词表方式：by jogging outdoors"], "stem": "（听力第3题，音频原文见试卷）考查点：母亲靠什么方式锻炼；注意听答句中的动词短语 by jogging outdoors。"}, {"subject": "英语", "question_no": "5", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "粗心/听辨弱", "knowledge_point": "短对话：brush teeth时间", "note": "", "key": "英语|5|1", "card_type": "concept", "teach": "这题问整段对话在谈什么（正确 A：什么时候刷牙），不是某个细节。她选 B，多半抓住一个听到的细节词就下手——话题题里，选项中出现的原文词最危险，往往只是细节不是主题。方法：短对话听完先用一句中文概括「他们在聊什么」，再对选项；若选项里只有一个是概括性的、其余都是具体小事，优先考虑概括的。场景词认熟：brush one's teeth 刷牙，twice a day 一天两次，before breakfast 早餐前，after meals 饭后，dentist 牙医。练习：每段听完先复述主题再看题。", "why": "把对话里出现的细节当成了主题，话题类题没有先概括整段内容。", "check_q": "听力小练：对话「—When should I brush my teeth? —The dentist says twice a day, in the morning and before bed.」这段对话的主题是什么？", "check_a": "刷牙的时间/频率（when to brush teeth）。整段围绕时间展开，牙膏、牙医都只是背景。", "steps": "1. 听前看选项构成：几个是具体小事、一个是概括性话题时，这题多半考主题\n2. 整段先听完，用一句中文在心里概括「他们到底在聊什么」（什么时候刷牙）\n3. 再回头对选项：牙膏、牙医这些词出现过不等于主题，是细节干扰，排除\n4. 话题题不抢答，等对话结束再定\n5. 第二遍验证：整段是不是都绕着这个主题转，是才坐实", "need": ["刷牙场景词：brush one's teeth、twice a day、before breakfast、after meals、dentist", "区分「对话主题」与「对话中顺带提到的细节」"], "stem": "（听力第5题，音频原文见试卷）考查点：整段短对话的话题——什么时候刷牙（when to brush their teeth）。"}, {"subject": "英语", "question_no": "7", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "听辨弱", "knowledge_point": "长对话：cinema，细节（时间/停车）抓不住", "note": "", "key": "英语|7|1", "card_type": "concept", "teach": "长对话信息密集，靠脑记必漏，这题错在电影场景的时间、停车等细节没抓住（她选 C，正确 A）。方法只有一个：边听边记。听前几秒扫选项，心里分成「时间、价格、地点、人物」几类；听到数字立刻写在对应选项旁，听到地点词打钩。数字题防双数字陷阱：7:30 和 8:00 可能一个是开场、一个是出发，问题问哪个就抓哪个动词后面的数。场景词必熟：cinema 电影院，start at 几点开场，ticket 票，seat 座位，car park 停车场，traffic jam 堵车。练习：精听专练「听到数字就落笔」，一周三次。", "why": "长对话细节全靠脑记，数字和地点一多就混了，没做边听边记。", "check_q": "听力小练：\"The film starts at 7:40. Let's meet at the cinema at 7:20.\" 电影几点开始？", "check_a": "7:40。meet 的时间 7:20 是干扰项，问题问 starts，就抓 starts at 后面的数字。", "steps": "1. 听前几秒扫选项，心里先给信息分类：时间、价格、地点、人物各归一类\n2. 录音一开始就动笔：听到任何数字立刻写在对应选项旁边，不靠脑记\n3. 数字题防双数字陷阱：7:20 是见面时间、7:40 是开场时间，问题问 starts 就抓 starts at 后面的那个数\n4. 听到地点词（cinema、car park）就在对应选项上打钩\n5. 第二遍只补第一遍漏记的信息，边听边和选项核对", "need": ["电影场景词：cinema、start at、ticket、seat、car park、traffic jam", "时间数字听辨：7:20 与 7:40 这类近似数字的区分", "meet at（约定见面）与 start at（正式开始）的区分"], "stem": "（听力第7题，音频原文见试卷）考查点：电影场景长对话中的时间、停车等细节信息。"}, {"subject": "英语", "question_no": "8", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "听辨弱", "knowledge_point": "长对话：工作单位/咖啡馆", "note": "", "key": "英语|8|1", "card_type": "concept", "teach": "长对话问某人在哪工作，答案多藏在场所词里。听到 serve customers、menu、order，多半在餐厅；听到 office、manager、meeting，多半是公司职员。她选 C 错、正确 A，没把场所词和职业对上号。方法：听前看选项，全是职业或地点时，专等场所名词（cafe、office、shop、hospital），听到一个标一个。配对背熟：clerk—office，barista—coffee shop，waiter—restaurant，nurse—hospital。考的就是「场所→职业」这步推断。", "why": "没听出工作场所的信号词，职业推断这一步没做出来。", "check_q": "听力小练：\"She takes orders and serves coffee to customers all day.\" 她在哪儿工作？", "check_a": "咖啡馆（coffee shop / cafe）。orders 和 coffee 是场所信号词，由场所推出职业场合。", "steps": "1. 听前看选项：全是职业或地点时，先定性——这题考「场所推职业」\n2. 听时专等场所名词和动作信号词：takes orders、serves coffee 出现就标注「咖啡馆」\n3. 把听到的场所和选项里的职业逐个配对（barista 对 coffee shop、clerk 对 office）\n4. 录音没直接说职业时用场所反推，不凭选项眼熟乱选\n5. 第二遍验证场所词有没有漏听或听错", "need": ["职业与场所配对：barista—coffee shop、waiter—restaurant、clerk—office、nurse—hospital", "场所信号词：take orders、serve customers、menu、meeting"], "stem": "（听力第8题，音频原文见试卷）考查点：长对话中由工作场所和服务内容判断人物的工作单位/职业场景（咖啡馆）。"}, {"subject": "英语", "question_no": "13", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|13|1", "card_type": "concept", "teach": "独白讲人物经历要按时间线切分：at first 起初，then 后来，years later 多年后，now 现在，每个标记对应一个阶段，题目只问其中一段。这题问最初的工作（bank clerk，银行职员），她混了段。方法：听独白时在纸上画一条线，听到时间词就分段记职业和事件，答题按题干问的时段对号。场景词：bank clerk 银行职员，businessman 商人，retire 退休，career 职业生涯。独白没对话提示、语速快，时间词是唯一路标。练习：听完按「过去—后来—现在」复述三句。", "why": "独白里几个阶段的工作混在一起，没用时间词切分，问哪段答错段。", "check_q": "听力小练：\"At first he was a bank clerk. Ten years later, he opened his own shop.\" 他最初的工作是什么？", "check_a": "Bank clerk（银行职员）。at first 标记最初阶段，后面的 shop owner 是后来，问「最初」就选前者。", "steps": "1. 听前先看清题干问哪个时段（at first 最初），把时段词圈出来\n2. 独白一开始就在纸上画一条时间线\n3. 每听到一个时间词（at first、then、years later、now）就在时间线上分一段，段后立刻记下职业和事件\n4. 答题时按题干问的时段回时间线对号：问最初就取第一段（bank clerk），不拿后来的 shop owner 顶替\n5. 第二遍核对每段的职业有没有记串行", "need": ["时间线标记词：at first、then、years later、now、retire", "职业词：bank clerk（银行职员）、businessman、shop owner", "独白按时间顺序组织信息的特点"], "stem": "（听力第13题，音频原文见试卷）考查点：人物独白细节；按时间线区分不同阶段的工作，其中最初的工作是 bank clerk。"}, {"subject": "英语", "question_no": "14", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|14|1", "card_type": "concept", "teach": "问感受、态度的题，答案是形容词，且要分清 -ing 和 -ed：事情「令人有压力」用 stressful，人「感到有压力」用 stressed。她选的正是 stressful 方向的选项，掉进这对词的坑。听时听到 feel 就记下后面的词——feel 后跟的永远是人的感受词（stressed、tired、proud）。几对词成对背熟：stressed/stressful、bored/boring、interested/interesting、tired/tiring。一句话：-ed 形容人，-ing 形容事。", "why": "stressed 和 stressful 没分清，感受类形容词的人/物分工不明确。", "check_q": "听力小练：\"The job was so stressful that he felt stressed every day.\" 哪个词形容工作，哪个词形容人？", "check_a": "stressful 形容工作（令人有压力的），stressed 形容人（感到有压力的）。", "steps": "1. 听前看选项：清一色 -ing/-ed 形容词时，先默念分工——形容人用 -ed，形容事用 -ing\n2. 听时先定题干问的对象：是工作的性质，还是人的感受\n3. 听到 feel 就记下它后面的词：feel 后永远跟人的感受词（stressed、tired、proud）\n4. 选前代入验一遍：「工作令人有压力」用 stressful，「他感到有压力」用 stressed\n5. 第二遍专门核对 -ing 和 -ed 有没有选反", "need": ["-ing/-ed 形容词分工：-ed 形容人、-ing 形容事", "成对词：stressed/stressful、bored/boring、interested/interesting、tired/tiring", "feel + 形容词（人的感受词）结构"], "stem": "（听力第14题，音频原文见试卷）考查点：人物感受类细节；区分 stressed 与 stressful 的使用对象。"}, {"subject": "英语", "question_no": "15", "full_score": 1.5, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|15|1", "card_type": "concept", "teach": "这题是最典型的教训：她先选 A（Chicago），又改成 B（San Francisco），两个都不对。独白里地名成串出现——出生地、去过的地方、现居地、要去的地方，问题只问其中一个身份，听到一个就选必错。方法：听前看清问哪类（was he born / does he live now），听时给每个地名标身份（生、去、住、往）。再立纪律：改答案必须有「听到了确切新信息」，凭感觉改，第一答案往往才对。她这次是地名身份没分清，又凭感觉改错。", "why": "几个地名的身份没区分，又凭感觉改了答案，两头落空。", "check_q": "听力小练：\"He was born in Chicago. He moved to New York at 20 and now lives in San Francisco.\" 他现在住在哪儿？", "check_a": "San Francisco。now lives 标记现居地，Chicago 是出生地、New York 是中途站，都是干扰。", "steps": "1. 听前看清问哪类地名：was born（出生地）还是 lives now（现居地），把题干关键词圈出来\n2. 独白里每出现一个地名，立刻在旁边标身份：生、去过、现住、要去\n3. 地名成串出现时不抢答，等独白放完，再按题干问的身份取对应那个\n4. 立改答案纪律：必须听到确切的新信息才改，凭感觉改往往越改越错\n5. 第二遍专门核对每个地名的身份标注有没有贴错", "need": ["地名身份信号词：was born in、moved to、now lives in、is going to", "听力答题纪律：没有确切新信息不改第一答案"], "stem": "（听力第15题，音频原文见试卷）考查点：人物独白中的多个地名及其身份，区分出生地、去过的地方、现居地和将去的地方。"}, {"subject": "英语", "question_no": "19", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|19|1", "card_type": "concept", "teach": "独白常考最后一问：讲话的目的是什么（正确方向 to introduce different cultures，介绍不同文化）。她错在拿某个细节当了目的。抓法：听开头第一句和结尾句，讲话人通常开门见山交代主题、结尾再呼应；中间反复出现的关键词就是主题词——customs、festivals 反复出现，主题就是 cultures。顺序也要改：细节题可边听边选，主旨题必须听完再选。选项多是 to do 开头，选前先问「这句能不能概括全篇」，只能概括一段的排除。", "why": "用局部细节代替全篇目的，主旨题没有听完、没抓反复出现的主题词。", "check_q": "听力小练：一段独白反复讲各国节日、食物和习俗，结尾说 \"I hope you can learn more about the world.\" 这段讲话的目的是什么？", "check_a": "介绍不同文化（to introduce different cultures）。反复出现的 customs、festivals 就是主题词，结尾句也在呼应。", "steps": "1. 讲话目的题放最后做：先做细节题，这题必须听完整段再选\n2. 重点听第一句和最后一句：讲话人通常开头交代主题、结尾再呼应一次\n3. 边听边留意反复出现的词：customs、festivals 反复出现，主题词就是 cultures\n4. 选项多是 to do 开头，逐个自问「这句能不能概括全篇」，只能概括某一段的先排除\n5. 最后用排除法收尾：细节型选项划掉，剩下能罩住全篇的才是目的", "need": ["主旨题抓手：开头句与结尾呼应句", "主题词识别：全篇反复出现的关键词（customs、festivals、cultures）", "目的类选项动词：to introduce、to explain、to tell"], "stem": "（听力第19题，音频原文见试卷）考查点：独白的讲话目的——介绍不同文化（to introduce different cultures）。"}, {"subject": "英语", "question_no": "28", "full_score": 2.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "审题偏差", "knowledge_point": "阅读：细节/推理题，关键句定位错", "note": "", "key": "英语|28|1", "card_type": "concept", "teach": "这题问段落的写作目的，正确是 C（引出话题）。判断分两步：先看位置——第一段通常引出话题，最后一段多是总结升华，中间段才论证举例；再看内容——这一段若主要在摆现象、讲引子，选项写「给出建议」「得出结论」的就多半不对。她选 D，是把铺垫当成了目的。落笔前先把选项动词译出来：introduce 引出，prove 证明，show 展示，conclude 总结——目的题一半败在这些动词的细微差别上。先用一句话说清「这段在干什么」，再对选项。", "why": "没先判断段落功能，被选项里眼熟的内容带走，把铺垫当成了目的。", "check_q": "小练：文章第一段讲「越来越多学生用手机查单词」这一现象，第二段才开始分析原因。第一段的写作目的是什么？", "check_a": "引出话题（to introduce the topic）。只摆现象、未分析未下结论，就是引出。", "steps": "1. 先看段落位置定大方向：第一段多半引出话题，最后一段多总结升华，中间段才论证举例\n2. 用一句话说清「这段到底在干什么」：只摆现象、讲引子，就是引出话题\n3. 把选项里的动词逐个译成中文：introduce 引出、prove 证明、show 展示、conclude 总结\n4. 拿第二步的判断去对选项：内容对得上、动词也对得上才选\n5. 这段若没有分析和结论，写「给出建议」「得出结论」的选项直接排除", "need": ["段落功能与位置：首段引出话题、尾段总结、中间段论证举例", "目的类动词辨析：introduce、prove、show、conclude、suggest"], "stem": "（C篇阅读，见原卷）设问：这段文字的写作目的是什么？正确选项：C. To introduce the topic of the text。"}, {"subject": "英语", "question_no": "29", "full_score": 2.5, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "审题偏差", "knowledge_point": "阅读：同上", "note": "", "key": "英语|29|1", "card_type": "concept", "teach": "细节题铁律：答案必须在原文有依据句，没依据的选项再「合理」也不能选。这题问为什么说这本书好，正确是 B（写作风格）；她选的 C（插图色彩丰富）是常识型陷阱——听着顺，原文没说。三步：1）拿题干关键词（perfect book）回原文扫读定位；2）圈出定位句里的原因（信号 because、for、its...）；3）选项逐个回原文核对，没提到的当场排除。她七选五全对，衔接感不差，缺的就是这个「定位—核对」硬动作。以后每道细节题强制画出依据句再选。", "why": "用生活常识和眼熟词选了答案，没有回原文找依据句核对。", "check_q": "小练：原文说 \"The book is popular not for its pictures, but for its simple language.\" 这本书受欢迎的原因是什么？", "check_a": "语言简单（its simple language）。not...but... 后面才是真原因，前面的 pictures 是被否定掉的干扰。", "steps": "1. 读题干先划定位词（perfect book、为什么受欢迎），带着词回原文扫读定位\n2. 找到依据句就画线，重点盯原因信号：because、for、not...but...\n3. 特别处理 not...but...：not 后面是被否定掉的干扰（pictures），but 后面才是真原因（simple language）\n4. 四个选项逐个回依据句核对：原文没提到的选项，再合理也当场排除\n5. 选完再读一遍依据句，确认所选项和原文是同义替换关系", "need": ["not...but... 结构：前面是否定干扰，后面才是重点", "原因信号词：because、for、thanks to", "细节题铁律：没有依据句的选项不选"], "stem": "（C篇阅读，见原卷）设问：为什么说这本书是 perfect book？已知选项：B. Its writing style；C. Its colourful pictures。"}, {"subject": "英语", "question_no": "33", "full_score": 2.5, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "词汇量不足", "knowledge_point": "阅读：词义/推理题", "note": "", "key": "英语|33|1", "card_type": "concept", "teach": "这题考「one tourist for each person」：游客数和当地人数 1:1，平均每个居民对应一个游客，总量非常大，所以正确 C（大量游客到访西班牙）。她选 D，是没把比率换算成总量。方法：遇到 one X for each Y、twice as many as 这类数量表达，先换算成一句话——「游客总数≈当地人口总数」，结论立刻清楚：人山人海。顺带记 masses of＝大量的，后接可数名词复数。数字、比率、百分比题都先换算再对选项，别停在字面。", "why": "\"一个居民对应一个游客」的比率没换算成总量，短语的字面含义没读懂。", "check_q": "小练：\"The village has one car for each family.\" 这句话是什么意思？", "check_a": "平均每户有一辆车（汽车总量约等于家庭户数），不是「全村只有一辆车」。", "steps": "1. 原文出现数量表达（one X for each Y、twice as many as）先停下来，不急着看选项\n2. 把比率换算成一句总量话：「一个居民对应一个游客」等于游客总数约等于当地人口总数\n3. 带着换算出的结论回选项，找同义表达（masses of tourists，大量游客）\n4. 警惕字面陷阱：one car for each family 是「每户一辆」，不是「全村只有一辆」\n5. 数字、比率、百分比类题一律先换算再对选项，不停在字面", "need": ["数量表达：one X for each Y、twice as many as、percent", "masses of + 可数名词复数（大量的）", "把比率换算成总量再判断的读法"], "stem": "（D篇阅读，见原卷）设问：文中“one tourist for each person”说明了什么？正确选项：C. There are masses of tourists visiting Spain。"}, {"subject": "英语", "question_no": "34", "full_score": 2.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "审题偏差", "knowledge_point": "阅读", "note": "", "key": "英语|34|1", "card_type": "concept", "teach": "这题要用「否定信息反推」。原文说游客 don't mind pollution（不介意污染）、can allow traffic jams（能容忍堵车），言下之意这些不会让人扫兴；问什么会毁兴致，就选没被「豁免」的那个：A 阴雨天。她选 D，是正着找「文中提到的坏事」，正中出题人的坑。固定方法：遇到 ruin、except、NOT 类题，先分两堆——被 don't mind、not care 豁免的放一堆（全是排除项），没被豁免的才是答案。步骤：圈否定词→标豁免项→反推。but 后面的信息权重最高。", "why": "正着找答案，没注意到原文用 don't mind 把污染、堵车都豁免了，需要反推。", "check_q": "小练：原文说 \"Visitors don't mind the cold, but they hate rainy days.\" 什么会让游客扫兴？", "check_a": "雨天（rainy days）。cold 被 don't mind 豁免，but 后面的 hate 指向的才是真答案。", "steps": "1. 题干带 ruin、except、NOT 字样时先定性：这题要反着找答案\n2. 回原文把否定句全圈出来：don't mind、can allow 后面跟的全是「被豁免项」\n3. 把豁免项归成一堆（pollution、traffic jams），它们全是排除项\n4. 在选项里找没被豁免的那个（rainy days），它才是答案\n5. 特别留意 but：but 后面 hate、ruin 指向的信息权重最高", "need": ["否定豁免表达：don't mind、not care、can allow", "except / NOT / ruin 类题的反推法", "but 后信息权重最高的阅读习惯"], "stem": "（D篇阅读，见原卷）设问：什么会让游客扫兴？文中说游客 don't mind pollution、can allow traffic jams；正确选项：A. Rainy weather。"}, {"subject": "英语", "question_no": "44", "full_score": 1.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "词汇辨析", "knowledge_point": "完形：近义词/语境辨析不清", "note": "", "key": "英语|44|1", "card_type": "redo", "stem": "完形填空：This nervousness finally led to ___. A. actions B. words C. plans D. ambitions", "teach": "先看搭配：led to「导致、通向」，后接名词作结果。再辨析四词：actions 行动，words 话语，plans 计划，ambitions 抱负。紧张（nervousness）是情绪，它导向的应是外在行动——情绪推动人做行动，逻辑最顺；words 是说出口的话，紧张不会「导致话语」成本句结果；plans、ambitions 是长期打算，与 finally「终于转变」的语气不搭。所以选 A。完形名词题三步：看空前动词要什么宾语；四词逐个译中文；代入读整句验逻辑。别凭眼熟选。", "why": "led to 后面四个名词没逐个辨析，凭眼熟选了 words，没验证逻辑是否成立。", "check_q": "小检验：Years of practice finally led to his ___ in the competition. A. success B. word C. plan D. ambition", "check_a": "A（success）。led to 接努力带来的结果，success 和 practice 的因果最顺，其余三项都不是「结果」。", "steps": "1. 先通读这一段抓主线：nervousness（紧张）最后导致了什么变化\n2. 看空前动词 led to：它后面要接「结果」类名词，先把不像结果的选项降权\n3. 四个名词逐个译中文再辨析：actions 行动、words 话语、plans 计划、ambitions 抱负\n4. 逐个代入原句验逻辑：情绪导致行动最顺，「导致话语」「导致计划」都不搭\n5. 再和后文核对：后文写到他做出的改变，就更加坐实 actions", "need": ["动词搭配：lead to + 结果名词", "近义名词辨析：action、word、plan、ambition 的词义与使用场合"]}, {"subject": "英语", "question_no": "48", "full_score": 1.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "词汇辨析", "knowledge_point": "完形：逻辑连词/语境", "note": "", "key": "英语|48|1", "card_type": "redo", "stem": "完形填空：He was late again, but it was just an ___ — in fact, he had overslept. A. reason B. adventure C. excuse D. chance", "teach": "辨析 excuse 和 reason：excuse 是「借口、托词」，为掩盖真相编出的说法，带贬义；reason 是「原因、理由」，中性，是真实原因。本句两个信号：just（不过是）和破折号后的 in fact he had overslept（其实睡过头了）——前面的说法是编的，所以选 excuse（C）。搭配：make an excuse 找借口，an excuse for being late。看到 just、in fact 出现，就警惕「表面说法≠真相」，多半选 excuse。她错在把借口和原因当一回事。", "why": "excuse（借口）和 reason（真实原因）没分清，漏看了 just 和 in fact 的提示。", "check_q": "小检验：Don't make ___ for your mistakes; just say sorry. A. reasons B. excuses C. adventures D. chances", "check_a": "B（excuses）。make excuses 是固定搭配「找借口」，且语境是认错道歉，不是讲真实原因。", "steps": "1. 先读完整句，再读破折号后半句：in fact he had overslept——真相是睡过头了\n2. 回头看空前信号词 just（不过是）：它提示前面的说法是编出来的\n3. 辨析两个易混词：reason 是真实原因（中性），excuse 是为掩盖真相编的借口（贬义）\n4. 语境是迟到道歉、表面说法不等于真相，锁定 excuse\n5. 代入读通整句再定：just an excuse 与 in fact 前后呼应", "need": ["excuse（借口）与 reason（真实原因）的辨析", "固定搭配：make an excuse、an excuse for being late", "语境信号词：just、in fact 提示表里不一"]}, {"subject": "英语", "question_no": "52", "full_score": 1.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "词汇辨析", "knowledge_point": "完形", "note": "", "key": "英语|52|1", "card_type": "redo", "stem": "完形填空：Hearing the news, I ___ for a second and didn't know what to say. A. sat B. slept C. knocked D. stood", "teach": "stood 是 stand 的过去式。stand 除「站立」外还有「停着不动、愣住」意：stand for a second 就是愣了一秒。判断两步：一看空后搭配——for a second 是一小段时间，需要能持续一小会儿的动作，stand 合适；knocked「敲、撞」必须有对象（knock on the door），直接跟 for a second 不成立。二看语境——听到消息后「不知说什么」是愣住，不是 sat（坐下）更不是 slept（睡着）。选 D。完形动词题先验「动词+空后成分」结构，再看词义。", "why": "不知道 stand 有「愣住、停着不动」的用法，被 knocked 的眼熟带偏了。", "check_q": "小检验：She ___ at the door for a minute before going in. A. knocked B. stood C. slept D. hit", "check_a": "B（stood）。at the door + for a minute 表示在门口停留一分钟，stand 合适；knock 后面要接 on/at 且不能持续一分钟。", "steps": "1. 先看空后成分：for a second 是一小段时间，空里的动词必须能持续这一小会儿\n2. 逐个验结构：knock 必须带对象（knock on the door），后面直接跟 for a second 不成立，先排除\n3. 再看语境：听到消息后「不知说什么」是愣住，对应 stand 的「停着不动」义\n4. 记 stand 的熟词僻义：stood for a second 就是愣了一秒\n5. 代入读完整段，确认动作和当时的情绪（吃惊发愣）一致再定", "need": ["stand 的僻义：停着不动、愣住；stood 是它的过去式", "knock 的用法：knock on/at + 对象，不能单独表示持续动作", "完形动词题先验「动词 + 空后成分」结构再看词义"]}, {"subject": "英语", "question_no": "55", "full_score": 1.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "词汇辨析", "knowledge_point": "完形", "note": "", "key": "英语|55|1", "card_type": "redo", "stem": "完形填空：After graduation, he decided to follow his ___ and became a painter. A. advice B. dream C. interest D. personality", "teach": "follow one's interest「遵从自己的兴趣」，是讲职业选择时的常用搭配。后半 became a painter 是结果——因兴趣在画画才去当画家，选 C（interest）。逐个排除：advice 建议，follow advice 是听从别人建议，与 he decided（他自己决定）矛盾；dream 梦想，follow one's dream 也成立，但强调「目标」，本句强调「热爱什么」；personality 性格，不与 follow 搭配。抓手：先看搭配，再看上下文指向热爱、目标还是别人的意见。", "why": "follow 和四个抽象名词的搭配没辨清，interest（兴趣）这个点没抓住。", "check_q": "小检验：You should follow your ___ and choose what you truly love to do. A. personality B. interest C. advice D. excuse", "check_a": "B（interest）。truly love 指向兴趣；advice 是别人的建议，personality 不与 follow 搭配。", "steps": "1. 先通读抓主线：毕业后他自己决定去当画家——抓住 decided（自己决定）这个词\n2. 看搭配框架：follow one's ___，先想哪些词能跟 follow 搭配表「遵从内心」\n3. 逐个排除：advice 是别人的建议，与「他自己决定」矛盾；personality 不与 follow 搭配\n4. dream 与 interest 二选一：句意强调「热爱什么」选 interest，强调「目标」才选 dream\n5. 代入后文验证：became a painter 是因兴趣当画家，逻辑闭合", "need": ["搭配区别：follow one's interest（遵从兴趣）与 follow one's dream（追逐梦想）", "advice、personality 与 follow 的搭配限制"]}, {"subject": "英语", "question_no": "56", "full_score": 1.5, "got_score": 0.0, "student_answer": "at", "std_answer": "For", "error_type": "知识盲区", "knowledge_point": "介词：句首\"For children…\"表对象，误用at", "note": "", "key": "英语|56|1", "card_type": "redo", "stem": "语法填空（填一个介词）：___ children, eating comfort food is not only about taste; it also brings back warm memories.", "teach": "答案是 For。for 放句首、后接人加逗号，意为「对于……来说」：For children, ... = 对孩子们来说。判断三步：一，空后是名词加逗号，后面是完整主句，空处填介词构成状语；二，排除 at——at children 不成立，at 只用于时间点和地点（at 7 o'clock，at school）；三，句意「对孩子而言」正是 for 表对象。搭配记牢：for example 例如，wait for 等待，be good for 对……有好处。她错在把 at 当万能介词。", "why": "句首表对象「对……来说」要用 For，她误用了 at，没先判断空后结构。", "check_q": "小检验：___ me, the best part of the trip was the food.（填一个介词）", "check_a": "For。「对我来说」句首引出评价对象，用 For，后接人加逗号。", "steps": "1. 先看空格位置和空后结构：空在句首，后面是名词 children 加逗号、再接完整主句，空处要填介词作状语\n2. 判断语义关系：整句是「对孩子们来说」，表对象、表「对于……而言」\n3. 排除 at：at 只用于时间点和地点（at 7 o'clock、at school），at children 不成立\n4. 定形式：句首 For 首字母大写，写出 For\n5. 代入读通自查：For children, ... 对孩子们来说……语义顺，定稿", "need": ["for 表对象：For + 人 + 逗号，「对……来说」", "at 的用法范围：只用于时间点和地点，不表对象", "for 的常见搭配：for example、wait for、be good for"], "points": ["本空1.5分，一次性给分：填对 For 得满分，填 at 或其他介词得0分，没有半分", "句首位置必须大写：写成小写 for 按拼写错误处理，本空同样不得分", "空着不写=0分：冠词、介词这类小词空和大空同分，不能跳过"], "frame": "先看空后结构：名词children+逗号+完整主句，空处是状语不是主干 → 再定语义：句意是\"对……来说\"表评价对象 → 排除法：at只配时间点和地点（at 7 o'clock/at school），at children不成立 → 落笔写For，先默念搭配for example、be good for对表对象有手感 → 写完回看一眼句首大写"}, {"subject": "英语", "question_no": "57", "full_score": 1.5, "got_score": 0.0, "student_answer": "to surprised", "std_answer": "to reduce", "error_type": "知识盲区", "knowledge_point": "不定式作目的状语，动词原形；且surprised词义亦错", "note": "", "key": "英语|57|1", "card_type": "redo", "stem": "语法填空：When people feel stressed, they often eat something sweet ___ (reduce) pressure.（用所给词的适当形式填空）", "teach": "答案 to reduce，考不定式作目的状语：吃甜食是为了减压，目的 = in order to do，所以用 to + 动词原形。判断三步：第一，句子已有谓语 eat，空处不是第二个谓语；第二，问「吃是为了什么」——能答出目的就用 to do；第三，to 后必须跟动词原形，这是铁律。她写 to surprised 错了两层：surprised 是形容词「感到惊讶的」，不是动词；就算用 surprise 也必须是原形。记住：-ed 结尾的形容词（surprised、tired）永远不能站在 to 后充当动作。", "why": "把 to 当成普通介词，后面填了形容词 surprised，没意识到表目的要用 to + 动词原形。", "check_q": "小检验：He got up early ___ (catch) the first bus.（用所给词的适当形式填空）", "check_a": "to catch。早起的目的是赶车，不定式作目的状语，to 后接动词原形。", "steps": "1. 先看全句有没有谓语：eat 已经是谓语，空处不是第二个谓语，先把谓语形式排除\n2. 问自己一句「吃甜食是为了什么」：能答出目的（减压），就用不定式作目的状语\n3. 定形式：目的状语等于 to + 动词原形，把括号里的 reduce 原形搬进去，写 to reduce\n4. 自查 to 后面站的是谁：必须是动词原形；surprised 这类 -ed 形容词永远不能站在 to 后充当动作\n5. 代入读通：eat something sweet to reduce pressure，顺，定稿", "need": ["不定式作目的状语：to do = in order to do", "to 后必跟动词原形", "-ed 形容词（surprised、tired）与动词原形的区别"], "points": ["本空1.5分，两部分缺一不可：to和动词原形reduce都对才得分", "只写reduce、漏掉to=0分：不定式符号丢了，整个结构就错了", "to后面跟非原形=0分：写成to surprised（形容词）、to reducing、to reduced都不得分"], "frame": "先找句子已有谓语eat，确认空处不是第二个谓语 → 再问一句\"吃甜食是为了什么\"，能答出目的就锁定不定式to do作目的状语 → 定形：to+所给词原形，surprised这类-ed形容词永远不能站在to后当动作 → 落笔to reduce → 代回原句读一遍：\"吃点甜的来减压\"，通顺即定"}, {"subject": "英语", "question_no": "59", "full_score": 1.5, "got_score": 0.0, "student_answer": "e（未完成）", "std_answer": "easier", "error_type": "知识盲区/时间不够", "knowledge_point": "比较级：未写出完整形式", "note": "", "key": "英语|59|1", "card_type": "redo", "stem": "语法填空：People like comfort food because it is ___ (easy) to prepare than the food in restaurants.（用所给词的适当形式填空）", "teach": "答案 easier。触发词是 than：句中有 than，前面的形容词多半用比较级，这是送分信号。再看变法：easy 以「辅音+y」结尾，变比较级把 y 改 i 再加 -er → easier；同类背一组：happy→happier，busy→busier，heavy→heavier。她只写了个开头 e，规则知道大概但没落实到笔头。做题动作固定：一扫 than / more 定比较级；二写变化 y→i 加 er；三检查没漏写。比较级不难，丢分全在手上不规范。", "why": "看到了比较语境却没写出完整比较级形式，y 变 i 加 er 的规则没落实。", "check_q": "小检验：This box is ___ (heavy) than that one.（用所给词的适当形式填空）", "check_a": "heavier。than 提示比较级，heavy 和 easy 同类：变 y 为 i 再加 er。", "steps": "1. 先扫全句找比较信号：than 就在空后不远处，这一空大概率考比较级\n2. 定词：括号给的是 easy（形容词），比较对象是 the food in restaurants，词没跑\n3. 变形式：easy 以「辅音 + y」结尾，变 y 为 i 再加 -er，写出 easier，一个字母不能省\n4. 落笔后默念拼写自查：e-a-s-i-e-r\n5. 代入读通：easier to prepare than ... 顺，定稿", "need": ["比较级触发词 than", "辅音 + y 结尾形容词的比较级变法：y 变 i 加 er（happy 变 happier、busy 变 busier、heavy 变 heavier）"], "points": ["本空1.5分：easier完整拼出才得分，拼错一字母（如easer、easyer）按错处理，0分", "只写原形easy或只起个头（如她只写了e）=未完成作答，0分：这类题不给\"意思分\"", "写成more easy=0分：easy是短形容词，用-er型比较级，不用more"], "frame": "先扫全句找标志词：看到than立刻定方向——前面形容词用比较级 → 再变形：easy以\"辅音+y\"结尾，变y为i加er，得easier（同组happy→happier一起记） → 一次写全，别写一半停笔 → 交卷前专项检查：凡空后或句中有than的空，回去确认都写成了比较级"}, {"subject": "英语", "question_no": "63", "full_score": 1.5, "got_score": 0.0, "student_answer": "（未辨认/0分）", "std_answer": "the", "error_type": "知识盲区", "knowledge_point": "冠词：特指the，空着或写错", "note": "", "key": "英语|63|1", "card_type": "redo", "stem": "语法填空（填冠词）：For many people, pizza is ___ number one comfort food in the world.", "teach": "答案 the。定冠词有个高频考点：序数词和「第一、唯一」类表达前必须加 the——the first，the number one，the best（最高级），the only。number one 是排名第一，全世界只有一个，是特指，用 the，绝不能用 a（a 表示任意一个）。判断两步：空后若是 first、second、best、only、same，先想 the；再自问「是不是独一无二的那一个」，是就坐实。她这空空着，是没想到冠词也单独设空考。口诀：序数最高级，唯一和特指，见面先给 the。", "why": "number one 前需要定冠词特指，她没意识到冠词也是考点，空着没写。", "check_q": "小检验：He was ___ first student to finish the exam.（填冠词）", "check_a": "the。first 是序数词，特指「第一个」，前面加 the。", "steps": "1. 先看空后词：number one 是「第一名」，全世界只有一个，属于特指\n2. 套规则：序数词、最高级、only、number one 前面必须加 the\n3. 排除 a：a 表示「任意一个」，和「独一无二」矛盾\n4. 写出 the（在句中用小写）\n5. 自查提醒：冠词也会单独设空考，再小的空也要给答案，不能空着", "need": ["定冠词 the 的特指用法：序数词、最高级、the only、the number one 前加 the", "a/an 表「任意一个」与 the 表「特指那个」的区分"], "points": ["本空1.5分：填the得满分，填a/an或空着都0分，没有半分", "这个空虽小，分值和词形大空完全一样：漏写一空就是实打实丢1.5分"], "frame": "先认空后词：number one是\"第一名\"，属于序数/唯一类表达 → 套口诀\"序数最高级，唯一和特指，见面先给the\"：全世界只有一个第一，用特指the → 排除a：a表示\"任意一个\"，与\"第一\"矛盾 → 落笔the → 全卷自查：凡first、best、only、same前的空，都回头补the"}, {"subject": "英语", "question_no": "64", "full_score": 1.5, "got_score": 0.0, "student_answer": "（未辨认/0分）", "std_answer": "aged", "error_type": "知识盲区", "knowledge_point": "过去分词作定语（aged children）", "note": "", "key": "英语|64|1", "card_type": "redo", "stem": "语法填空：The survey found that people ___ (age) 25 to 40 are most likely to eat comfort food when stressed.（用所给词的适当形式填空）", "teach": "答案 aged，考过去分词作后置定语：people aged 25 to 40 = 年龄在 25 到 40 岁的人。age 作动词时 aged 表示「年龄为……岁」。判断两步：一，名词 people 后缺定语、括号给动词，优先考虑分词；二，看关系——人是「被标明年龄」的，属状态、被动，用 -ed；若是名词自己的动作正在进行，用 -ing（the sleeping baby）。同类：the girl dressed in red，the boy named Tom。她没得分是「分词作定语」没启动。", "why": "不知道 aged 可以作后置定语表示「年龄在……岁」，分词作定语的用法没掌握。", "check_q": "小检验：The girl ___ (dress) in red is my sister.（用所给词的适当形式填空）", "check_a": "dressed。女孩是「被穿着」红衣，状态作定语用过去分词 dressed，和 aged 同理。", "steps": "1. 先看空的位置：名词 people 后面、数字 25 to 40 前面，空处缺一个修饰 people 的定语\n2. 再看括号词：age 是动词；名词后缺定语又给动词，先想分词作定语\n3. 判断主动还是被动：人是「被标明年龄」的状态，不是自己发出的动作，用过去分词 aged\n4. 写出 aged 25 to 40，意思就是「年龄在 25 到 40 岁的人」\n5. 代入读通，并和 -ing 对比自查：对象自己正在做动作才用 -ing（如 the sleeping baby）", "need": ["过去分词作后置定语：people aged 25 to 40", "分词主动/被动判断：-ing 表主动进行、-ed 表被动或状态", "同类结构：the girl dressed in red、the boy named Tom"], "points": ["本空1.5分：aged写对得满分；写age（原形）、aging（-ing）、ages都不得分", "本题没有备选形式可蒙：分词作定语是整个考点，形式选错即全错"], "frame": "先看位置：空在名词people之后、数字25 to 40之前，是给people加定语 → 再判关系：年龄是\"被标明\"的状态、不是people主动发出的动作，用过去分词-ed → 写aged（age作动词，aged 25 to 40=年龄在25到40岁） → 自查同类标本：the girl dressed in red、the boy named Tom，脑子里有标本才敢落笔"}, {"subject": "英语", "question_no": "66", "full_score": 0.0, "got_score": 0.0, "student_answer": "confident", "std_answer": "confidence", "error_type": "知识盲区", "knowledge_point": "词形：have confidence in，误用形容词", "note": "", "key": "英语|66|1", "card_type": "redo", "stem": "完成句子：他非常自信地回答了所有问题。He answered all the questions with great ___.", "teach": "答案 confidence（名词，自信），她填的 confident 是形容词，词性对不上。词形题先看位置：with great ___ 里 great 是形容词，后面必须接名词。搭配记牢：with (great) confidence 自信地，have confidence in sb./sth. 对……有信心。抓手：形容词 -ent 结尾（confident），名词换 -ence（confidence），同 different → difference。括号给形容词、空处要名词时，先想「换尾巴」。", "why": "空处需要名词，她填了形容词 confident，词性判断这一步没做。", "check_q": "小检验：She has great ___ in her own ability.（confident 的适当形式）", "check_a": "confidence。has great 后接名词，且 have confidence in 是固定搭配。", "steps": "1. 先看中文提示和英文半句：with great ___，great 是形容词，它后面只能接名词\n2. 先定词性再定词：这一空要名词，把词性这一步做掉再想具体词\n3. 做词形转换：confident 是形容词，换尾巴变名词 confidence，记 -ent 变 -ence 的规律\n4. 核对搭配：with great confidence（自信地）、have confidence in（对……有信心）都是固定搭配\n5. 拼写自查：con-fi-dence 分三段默念一遍再落笔", "need": ["搭配：have confidence in、with great confidence", "词性转换规律：形容词 -ent 变名词 -ence（confident 变 confidence、different 变 difference）", "位置判断法：形容词后面接名词"], "points": ["本空1分：confidence（名词）写对才得分", "写confident（形容词）词性错=0分：空处在great之后、句子末尾，只能放名词", "拼写错（如confidance、confidense）=0分，完成句子拼写与词形同等计分"], "frame": "先圈中文核心\"自信（地）\" → 再看空格位置定性：with great ___，great是形容词，后面必须接名词，先把词性定死 → 调词形规则：confident是形容词，名词换尾巴-ent→-ence得confidence → 落笔后拼写自查：con-fi-dence分三段默念 → 顺带记搭配with great confidence、have confidence in，写作能直接用"}, {"subject": "英语", "question_no": "67", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "confusing", "error_type": "知识盲区", "knowledge_point": "-ing/-ed形容词辨析", "note": "", "key": "英语|67|1", "card_type": "redo", "stem": "完成句子：这道数学题太令人困惑了，全班都做不出来。The maths problem was so ___ that nobody in the class could work it out.", "teach": "答案 confusing。-ing / -ed 形容词分工是高频考点：confusing「令人困惑的」修饰物或事，confused「感到困惑的」修饰人。口诀：物用 -ing，人用 -ed。对比记：the news is exciting（消息令人兴奋），I am excited（我感到兴奋）。本题修饰 problem（物），用 confusing。判断两步：先看修饰人还是物，再选形式。她 0 分就是规则没分清。so...that... 里形容词作表语跟在 was 后，选对形式即得分。", "why": "confusing 和 confused 的人/物分工没分清，修饰题目（物）误用了方向。", "check_q": "小检验：The students looked ___ when they saw the strange question.（confuse 的适当形式）", "check_a": "confused。修饰人 students 的感受，用 -ed 形式；题面令人困惑才用 confusing。", "steps": "1. 先圈中文提示的核心：「令人困惑」——带「令人……」字样，先想到 -ing 形式\n2. 看英文半句空的修饰对象：was so ___ 修饰的是 maths problem，是物不是人\n3. 套分工口诀：物用 -ing、人用 -ed，锁定 confusing\n4. 反向自查：若修饰的是 students 的感受才用 confused，本题不要选反\n5. 代入读通：The problem was so confusing that ... 顺，定稿", "need": ["-ing/-ed 形容词分工：confusing（令人困惑，修饰物）、confused（感到困惑，修饰人）", "so ... that ... 句型里表语形容词的选用"], "points": ["本空1分：confusing写对得分", "写confused=0分：方向反了——confused只能修饰人（感到困惑的），本题修饰maths problem（物）", "拼写错=0分"], "frame": "先圈中文\"令人困惑\"里的\"令人\"二字，这是-ing的信号 → 定修饰对象：空在was so ___ that结构里形容problem，是物不是人 → 套口诀\"物用-ing，人用-ed\"选confusing → 落笔后对照标本自查：the news is exciting / I am excited，一物一人别再反"}, {"subject": "英语", "question_no": "68", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "extremely", "error_type": "知识盲区", "knowledge_point": "副词修饰形容词", "note": "", "key": "英语|68|1", "card_type": "redo", "stem": "完成句子：春天的这座花园非常美丽。The garden is ___ beautiful in spring.", "teach": "答案 extremely（副词，极其、非常）。空在形容词 beautiful 前面，修饰形容词必须用副词，不能用形容词 extreme。extreme 加 -ly 变副词，拼写直接加 ly（e 不去掉）：extremely，强度比 very 还强。判断记死：空后是形容词或副词，填副词；空后是名词，才填形容词。同类记一组：careful → carefully，quick → quickly，real → really；但 true → truly 要去 e，是例外。她这题是没做词形转换，把原词直接搬上去了。", "why": "修饰形容词需要副词，她没做词形转换，extreme 和 extremely 分不清。", "check_q": "小检验：It is ___ hot today; you'd better stay inside.（extreme 的适当形式）", "check_a": "extremely。hot 是形容词，前面要用副词 extremely 修饰。", "steps": "1. 先看空后词：beautiful 是形容词，空处要修饰它，必须用副词\n2. 做词形转换：extreme 是形容词，加 -ly 变副词 extremely\n3. 拼写自查：extreme 加 ly 时末尾的 e 不去掉，直接拼 ex-treme-ly\n4. 与 very 对比强度：extremely 比 very 更强，和「非常美丽」对得上\n5. 代入读通：is extremely beautiful，顺，定稿", "need": ["副词修饰形容词：形容词前面填副词", "形容词变副词加 -ly：extreme 变 extremely（e 不去掉）；例外 true 变 truly 要去 e", "同类转换：careful 变 carefully、quick 变 quickly、real 变 really"], "points": ["本空1分：extremely写对得分", "只写extreme（形容词原形、没加ly）=0分：修饰形容词的位置不收形容词", "拼写错（如extremly漏e）=0分：extreme加ly时词尾e保留，写错即丢"], "frame": "先圈中文\"非常\" → 看空后词：beautiful是形容词，修饰形容词只能用副词，先定词性 → 做词形转换：extreme直接加-ly得extremely（e不脱落，和true→truly的例外分开记） → 落笔后拼写自查：extreme-ly两段拼合读一遍"}, {"subject": "英语", "question_no": "69", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "official", "error_type": "词汇量不足", "knowledge_point": "目标词汇拼写/ recalls", "note": "", "key": "英语|69|1", "card_type": "redo", "stem": "完成句子：官方报告称，事故中没有人受伤。The ___ report said that nobody was hurt in the accident.", "teach": "答案 official（形容词，官方的）：official report 官方报告，official news 官方消息。真正的考点是拼写：o-f-f-i-c-i-a-l，双 f，中间是 ci 不是 ce。抓手：official 来自 office（办公室）+ -al，「办公室发布的」就是「官方的」；但拼写时 ce 变 ci，把词拆三段默念——offi-ci-al。再和 officer（官员，指人）分开。她的问题是「背过但写不出」，这类词光看没用，必须动笔分段默写两遍。", "why": "official 的拼写没落实，双 f 和 cial 的写法写不出来。", "check_q": "小检验：Please check the ___ website of the school for the news.（官方的）", "check_a": "official。修饰 website 用形容词 official，注意拼写 offi-ci-al。", "steps": "1. 先看空的位置：___ report，空在名词 report 前面，要填形容词作定语\n2. 对中文提示：「官方报告」对应 official report，是固定说法\n3. 这题真正的坎是拼写：把 official 分三段默写——offi-ci-al，注意双 f、中间是 ci 不是 ce\n4. 和 officer 分清：officer 是名词「官员」指人，本题要的是形容词 official\n5. 落笔后逐字母再核对一遍才交卷", "need": ["official 的拼写：o-f-f-i-c-i-a-l（双 f、cial）", "official（形容词，官方的）与 officer（名词，官员）的区分", "词源抓手：official 来自 office + -al"], "points": ["本空1分：official拼写全对才得分", "意思选对但拼写错（offical少一个f、oficial把ci写成ce等）=0分：本题考的就是拼写，没有\"意思分\"", "写officer=0分：那是\"官员\"指人，不能修饰report"], "frame": "先圈中文\"官方（报告）\"，确认空处修饰report需形容词 → 调词条先想来源：office（办公室）+-al，\"办公室发布的\"就是\"官方的\" → 分段拼写落笔：offi-ci-al，双f和ci两处逐段默念着写 → 写完专项自查：f是不是两个、中间是ci不是ce，这两点是本题全部得分所在"}, {"subject": "英语", "question_no": "72", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "addicted to", "error_type": "词汇量不足", "knowledge_point": "be addicted to，目标短语不会", "note": "", "key": "英语|72|1", "card_type": "redo", "stem": "完成句子：他沉迷于电脑游戏，根本停不下来。He is ___ ___ computer games and simply can't stop.", "teach": "答案 addicted to：be addicted to「沉迷于、对……上瘾」，是本单元核心短语——写作劝诫信里老师改的范文开头用的就是它。三点记牢：一，addicted 是形容词，前面要有 be 动词；二，to 是介词，后接名词或动名词——addicted to playing games，不能写 to play；三，拼写双 d。抓手：add 是「加上」，addict 是「瘾君子」，加上就戒不掉的状态就是 addicted。她两空全错，是整条短语没默写过，只能整条背、整条写。", "why": "be addicted to 整条短语没背下来，两空都写不出。", "check_q": "小检验：She is addicted ___ chocolate and eats it every day.（填一个词）", "check_a": "to。be addicted to 是固定搭配，to 是介词，后面接名词 chocolate。", "steps": "1. 先圈中文提示的核心短语：「沉迷于」对应 be addicted to，整条短语一起调出来，不逐词现拼\n2. 看英文半句对位：He is ___ ___ computer games——is 已经给出，第一空填形容词 addicted，第二空填介词 to\n3. 两空逐个落实：addicted 注意双 d，to 不能漏\n4. 人称时态自查：主语 He 配 is 已在句中，不用再变\n5. 顺带记 to 的性质：这里的 to 是介词，后接名词或动名词（addicted to playing games），不能接动词原形", "need": ["be addicted to 整条短语（be 动词 + addicted + to）", "addicted 的拼写：双 d", "addicted to 里的 to 是介词，后接名词或动名词"], "points": ["共2空、每空1分：addicted（双d、形容词-ed结尾）写对得1分，to写对得1分", "少写to，第二空0分：addicted alone不成短语，必须整条be addicted to才算掌握", "addicted拼错（少一个d、写成addict/addicting）该空0分"], "frame": "先圈中文核心\"沉迷于\"，整条调出目标短语be addicted to，不许逐词现凑 → 落笔前查三项：be动词在不在（句中已有is）、addicted双d没、to后接名词或动名词（computer games是名词，直接跟） → 整条写出He is addicted to computer games → 自查拼写：ad-dict-ed分段默念"}, {"subject": "英语", "question_no": "73", "full_score": 0.0, "got_score": 1.0, "student_answer": "clean up（部分）", "std_answer": "clean up", "error_type": "粗心", "knowledge_point": "短语对一半（大小写/形式扣分）", "note": "", "key": "英语|73|1", "card_type": "redo", "stem": "完成句子：周末我们应该把公园打扫干净。We should ___ ___ the park on weekends.", "teach": "答案 clean up（打扫、清理干净）。她只对一半，丢分在小品词 up——只写 clean 是「清洁」这个动作，clean up 才强调「彻底收拾干净」的结果。完成句子按空给分，少一个词少一分。立规矩：动词短语必须整条背、整条默写，clean up、pick up（捡起）、give up（放弃）这类「动词+小品词」不能拆着记。再记一个细节：clean up 接地点名词可直接跟（clean up the park）；宾语是代词要放中间（clean it up）。她第 70、71 题短语全对，说明就是这类短语背得不全。", "why": "clean up 只写对一半，小品词 up 漏写，短语没整条落实。", "check_q": "小检验：Please ___ ___ your bedroom before your friends come.（打扫干净）", "check_a": "clean up。表示把房间收拾干净，动词和小品词两个词都要写全。", "steps": "1. 先圈中文提示：「打扫干净」重点在「干净」这个结果，不只是「打扫」这个动作\n2. 调短语：clean up 整条出现——clean 是动作，up 表示「彻底、收拾干净」的结果\n3. 两空逐个落实：第一空 clean、第二空 up，完成句子按空给分，小品词漏一个就丢一空\n4. 语境自查：宾语 the park 是地点名词，直接跟在短语后面没问题；宾语是代词时要放中间（clean it up）\n5. 交卷前专项检查：这一页所有动词短语的小品词（up、of、on）在不在", "need": ["动词短语整条记忆：clean up、pick up、give up，小品词不能漏", "小品词 up 表「彻底完成」的语感", "短语动词接代词宾语的位置：clean it up"], "points": ["共2空、每空1分：clean得1分，up得1分", "她实际得分1/2：只写对clean、漏了up，第二空0分——这就是本题丢分点：短语记一半，分数拿一半", "写成clean up以外的搭配（如clean down）第二空同样0分"], "frame": "先圈中文\"打扫干净\"，注意\"干净\"是结果不是动作 → 整条调短语：clean up（动词+小品词，缺一不可），先在心里把两词绑成一条再落笔 → 逐空写：第一空clean、第二空up → 交卷前数一遍：中文\"打扫干净\"对应两个空，空数对上了没有；同类短语pick up、give up都按\"整条背、整条写\"处理"}, {"subject": "英语", "question_no": "74", "full_score": 0.0, "got_score": 1.0, "student_answer": "took control of（部分）", "std_answer": "took control of", "error_type": "粗心", "knowledge_point": "同上", "note": "", "key": "英语|74|1", "card_type": "redo", "stem": "完成句子：去年他接管了这家小公司。He ___ ___ ___ the small company last year.", "teach": "答案 took control of（接管、掌管），三个空两个坑，她只对一空。短语 take control of 三词一个不能少，最后的 of 最易漏。时态是第二坑：句中有 last year，动作在过去，take 用过去式 took。交卷前三步检查：一，短语完整吗——of、up、on 在不在；二，时态对吗——last year、ago 用过去式，every day 用一般现在时；三，人称单复数对吗。另注意 control 前不加冠词，别写 take the control。她就是完整性和时态都没查。", "why": "take control of 没整条记住，又漏看了 last year 的过去时标志，took 没变出来。", "check_q": "小检验：When the teacher left, the monitor ___ control of the class.（take 的适当形式）", "check_a": "took。left 是过去时，接管的动作同样发生在过去，用 took。", "steps": "1. 先圈中文提示：「接管」对应 take control of，三个词一起调出来\n2. 数空对位：英文半句正好三个空，依次是 took、control、of；of 最容易漏，先把它填上\n3. 定时态：句中有 last year，动作发生在过去，take 用过去式 took\n4. 人称自查：过去时动词不随人称变化，不用再加 s\n5. 交卷三查：短语完整吗（of 在不在）、时态对吗（去年对应过去式）、拼写对吗（took 是双 o）", "need": ["take control of 三词短语（最后的 of 不能漏）", "不规则动词过去式：take 变 took", "时间标志词定时态：last year、ago 用过去时；every day 用一般现在时", "control 前不加冠词"], "points": ["共3空、每空1分：took得1分、control得1分、of得1分", "她实际得分1/3：时态took对了1空，其余丢分——of漏写该空0分，短语不完整不给\"接近分\"", "写take（原形）第一空0分：句中有last year，时态错整空错；写take the control多加冠词，该空按错处理"], "frame": "先圈中文\"接管\" → 第一步先定时态：扫到last year立刻锁定过去时，take→took，先把第一空定死 → 第二步整条调短语：take control of三词一个不能少，尤其句尾的of → 第三步落笔后三查：①短语完整吗（of在不在）②时态对吗（和last year对上没）③有没有多加冠词（control前不加the） → 三查过了再下一题"}, {"subject": "英语", "question_no": "75", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "other than", "error_type": "词汇量不足", "knowledge_point": "目标短语不会", "note": "", "key": "英语|75|1", "card_type": "redo", "stem": "完成句子：他整天除了学习什么都不做。He does nothing all day ___ study.", "teach": "答案 other than（除了）。它与 except 意思相近，最爱出现在否定语境：nothing、nobody、no 后跟 other than，表示「除了……没有别的」。本句有 does nothing，正是主场，后接动词原形 study。与 except for 分工：except for 用于「整体肯定、只挑一个例外」（如房间挺好 except for 有点吵），后接名词。她整条写不出，是短语没背过。对策：other than、except for、apart from 对比背，各配一例句。", "why": "other than 这个「除了」没背过，否定语境该用哪个短语完全没概念。", "check_q": "小检验：I have no friend in this city ___ Tom.（除了）", "check_a": "other than。no friend 是否定语境，「除了汤姆没有别的朋友」用 other than。", "steps": "1. 先看英文半句的语境：does nothing 是整句否定，「除了学习什么都不做」\n2. 定短语选型：否定语境（nothing、nobody、no）加「除了」，主场短语是 other than\n3. 写出 other than，它后面接动词原形 study，与前面的 does 保持对应\n4. 和 except for 分工自查：except for 用于「整体肯定、只挑一个小例外」，本句整句否定，不用它\n5. 代入读通：does nothing other than study，顺，定稿", "need": ["other than 在否定语境表「除了」", "except for 与 other than 的分工", "apart from 表「除了」的同义替换"], "points": ["共2空、每空1分：other得1分、than得1分，整条other than写全得2分", "写except for不得分：except for后只能接名词作例外补充，本句空后是动词原形study，结构不合", "只写except或than alone，各空按错处理"], "frame": "先圈中文\"除了\" → 看语境选短语：句首有does nothing是否定语境，且空后接动词原形，\"除了……没别的\"用other than（except for留给\"整体肯定只挑一个例外\"且后接名词） → 整条落笔other than → 自查：空前后读通\"He does nothing all day other than study\"，通顺即定"}, {"subject": "英语", "question_no": "作文", "full_score": 20.0, "got_score": 11.0, "student_answer": "建议信（Wang Peng沉迷游戏）", "std_answer": "—", "error_type": "表述不规范", "knowledge_point": "见下文作文专项评估", "note": "", "key": "英语|作文|1", "card_type": "concept", "teach": "劝诫信得 11/20，病在表达：句式单一、搭配随手造。老师改好的开头就是范本：\"You have become addicted to computer games recently.\" 先点沉迷，再表担心。结构三段：开头点问题；中间摆危害（do harm to your eyes），再给建议（had better、why not）；结尾鼓励。红线搭配：be addicted to 后接名词或 doing，spend time (in) doing，be harmful to。句式至少一句 because、一句 if。", "why": "句式单一、搭配不规范，开头没有点明问题和表态，整篇表达停留在短句堆砌。", "check_q": "小检验：把这句译成英文——「沉迷于手机对你的眼睛有害。」", "check_a": "Being addicted to the phone is harmful to your eyes.（也可用 ...does harm to your eyes.）两个搭配 be addicted to、be harmful to 都要写对。", "steps": "1. 动笔前先定三段结构：开头点问题加表担心、中间摆危害加给建议、结尾鼓励收尾\n2. 每段先列要点词再写句子：危害段 harm、eyes、health；建议段 had better、why not、spend time\n3. 开头套老师改好的范文句式：You have become addicted to computer games recently. 先点沉迷，再表担心\n4. 写作时至少用上一句 because、一句 if，把短句连成复合句，不全篇短句堆砌\n5. 写完专项自查三件事：be addicted to 的 to 后面接对没有、全文时态统一没有、搭配有没有中式直译（对……有害要写 do harm to）", "need": ["劝诫信三段结构：点问题、摆危害给建议、鼓励收尾", "核心搭配：be addicted to、do harm to、be harmful to、had better do、spend time (in) doing", "复合句工具：because、if 引导的状语从句"], "points": ["内容要点（约占一半权重）：劝诫信要点须齐——①点明Wang Peng沉迷游戏的现状 ②表达担心 ③摆危害（伤眼、影响学习/休息） ④给出2-3条具体建议 ⑤结尾鼓励并表态。漏一条要点就下调一档；她的开头没有点明问题和表态，第一要点先丢", "语言准确（她丢分第一位）：搭配写错一处影响一档——be addicted to、spend time (in) doing、be harmful to/do harm to这类红线搭配是阅卷先看的；她多处搭配随手造，11分里最大一块丢在这里", "句式多样（她丢分第二位）：通篇简单短句堆砌，分数封顶在中档；至少出现1个because/if状语从句、1个非谓语或建议句式（had better/why not）才能抬档，她基本没做到", "衔接连贯：段与段、句与句之间要有连接词（First、Besides、What's worse、Therefore、In a word）；没有连接词，内容再对也显得散，要点分打折", "字数与卷面：字数不足是硬扣分项（先数够词再谈质量）；涂改多、字迹潦草拉低印象分，同等语言水平下卷面整洁的能高1-2分"], "frame": "三段结构落笔：\n第一段【点题表态，2-3句】开门见山点现状——套范文句式\"You have become addicted to computer games recently.\"，再一句表达担心\"I'm really worried about you.\"收尾过渡。\n第二段【危害+建议，主体段】先摆危害：伤眼伤学习各一句（It does harm to your eyes and study.）；再转建议2-3条，每条一句建议+一句理由，句式轮换：had better + 动词原形提第一条，Why not...?提第二条，spend less time on...提第三条，理由用because/if从句接上；段内连接词First、Besides、Therefore别省。\n第三段【鼓励收尾，1-2句】表信任收束：\"I'm sure you can give it up if you try.\"再一句Looking forward to your reply.落款。\n写后专项自查（按丢分顺序查）：①红线搭配逐条核对be addicted to、be harmful to、spend time (in) doing ②时态以一般现在时为主，有没有混入莫名过去时 ③每个句子主谓齐不齐 ④字数够不够、卷面涂改多不多", "stem": "书面表达题目：以李华的名义，给沉迷网络游戏的朋友王鹏写一封劝诫信，约100词。"}, {"subject": "历史", "question_no": "3", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "审题偏差", "knowledge_point": "商王巡行与内外服制度：B\"政治认同\"是干扰项，题眼在\"宣示商王统治权力\"", "note": "", "stem": "商王每隔一段时间就会带着他的“子姓”分族巡行一方，所到之处，当地部族向其纳贡，获得赏赐，并派人加入商王的队伍。这种巡行（ ）", "paper_cause": "**概念不清**——只看到巡行\"宣示王权\"的一面，没抓住\"子姓分族、派人加入队伍\"背后的血缘认同功能", "key": "历史|3|1", "card_type": "redo", "options": {"A": "扩大了商朝的疆域范围", "B": "形成了部族之间的血缘认同", "C": "加强了内服外服的商业联系", "D": "宣示了商王的统治权力"}, "teach": "先看材料的动作链：巡行一方、部族纳贡、商王赏赐、派人加入商王队伍，这是一整套臣服与效忠的政治仪式，指向的是商王权威的宣示，所以正确答案是D。B项错在偷换主语：材料里的子姓分族，说的是商王把同姓子弟分派出去，属于王族内部的安排；选项却说部族之间形成了血缘认同，可被巡行的各部族与商王并不同姓，材料里也没有任何结亲、认同血缘的信息。C项材料只字未提商业贸易，A项巡行也不等于开疆拓土。这类题的看法是：把每个选项的核心词（血缘、商业、疆域、权力）逐一回材料找对应信息，找不到出处的先排除，不要被子姓这种眼熟字眼牵着走。", "why": "被子姓二字联想到血缘，没核对选项的主语是部族之间，材料根本没有血缘认同的信息。", "check_q": "西周实行分封制，周王把土地和人民分给同姓子弟、功臣等，让他们建立诸侯国。分封制在当时最直接的作用是（ ）A.扩大并巩固了周王室的统治 B.促进了各地的商业贸易 C.实现了地方的高度自治 D.消除了各族之间的差异", "check_a": "A。分封的核心功能是政治统治与疆域巩固；和本题一样，要抓住材料行为的政治功能，不要被次要信息带偏。", "steps": "1. 先看设问落点：问的是这一系列行为的'实质'，先提醒自己不能停在现象层。\n2. 回材料梳动作链：巡行、部族纳贡、商王赏赐、派人加入商王队伍——先把动作列全。\n3. 给动作链定性：这是一整套臣服与效忠的政治仪式，指向商王统治权力的宣示。\n4. 逐项验主语：B项把王族内部的子姓分族偷换成部族之间的血缘认同，主语对不上、材料也无此信息，排除；C项无中生有，A项停在表面。\n5. 选与'宣示商王统治权力'对位的一项，再核对材料每个动作都能被它统摄。", "need": ["商代内外服制度与商王的统治方式", "'实质'类设问的答法：透过仪式和现象看权力关系", "干扰项识别：偷换主语、无中生有"]}, {"subject": "历史", "question_no": "6", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "知识盲区", "knowledge_point": "春秋已能生产铁器（甘肃灵台铁剑）；A\"商朝青铜农具广泛使用\"表述有误", "note": "", "key": "历史|6|1", "card_type": "concept", "teach": "这道题输在一条时间线没记清。金属工具的演变是：商周是青铜时代，但青铜贵重，主要用来做礼器和兵器，真正的农具仍以石器、木器、骨蚌器为主，所以商朝青铜农具广泛使用是错误表述，见到广泛使用这种绝对化说法先打个问号。到了春秋时期，我国已经能够生产铁器，甘肃灵台出土的春秋早期铜柄铁剑就是证据；进入战国，铁农具才推广开来，牛耕也随之出现，生产力实现跃升。记忆锚点：青铜在庙堂（礼器兵器），不在田里；铁器春秋露头、战国下地。把这条线画在课本的时间轴上，这类题就不会再错。", "why": "不知道春秋已有铁器的实物证据，又误以为商朝青铜已经广泛用于农具。", "check_q": "下列说法正确的是（ ）A.商朝时青铜农具已广泛用于农业生产 B.春秋时期我国已出现铁器，战国时铁农具得到推广 C.西周时期铁器取代了青铜器 D.牛耕最早出现在商朝", "check_a": "B。A错在青铜主要用于礼器、兵器；C错在春秋战国是青铜与铁器并存、铁器逐步推广；D牛耕出现在春秋战国时期。", "steps": "1. 先给四个选项各标一个时间坐标（商、春秋、战国），时间对不上时代特征的先排。\n2. 调用金属演变线核对：商周青铜贵重、主要做礼器和兵器，农具仍以石器、木器、骨蚌器为主。\n3. 验A：'商朝青铜农具广泛使用'与青铜贵重的事实冲突，见到'广泛'这类绝对化表述先打问号。\n4. 验B：春秋已有铁器实物证据（甘肃灵台铜柄铁剑），与时间线吻合。\n5. 用'青铜做礼兵、春秋见铁器、战国铁农具推广'三个锚点再复核一遍定案。", "need": ["中国古代金属工具演变时间线（青铜礼器兵器→春秋铁器出现→战国铁农具推广）", "春秋战国生产力跃升的标志（铁农具、牛耕）", "绝对化表述（广泛、完全、全部）的警惕与核查"], "stem": "6. 下列选项中，材料与结论之间逻辑关系正确的是（ ）\n【表格】选项｜材料｜结论\nA｜安阳、济南分别出土过商朝青铜铲、青铜镰刀｜商朝广泛使用青铜农具\nB｜甘肃灵台的春秋早期墓中出土了人工冶炼的铁剑｜春秋时期，我国已能够生产铁器\nC｜春秋时期，楚国国君熊通要求提升爵位等级，遭到周王拒绝，熊通“乃自立，为（楚）武王”｜分封制度消亡\nD｜洞庭秦（太）守木牍：这片木牍属于郡县职官简，太守即郡守的尊称。｜郡县制最早在湖南推行\nA. A　B. B　C. C　D. D", "img": "his-6.jpg"}, {"subject": "历史", "question_no": "8", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "概念混淆", "knowledge_point": "二重证据法：传世文献与出土文献互证；B\"单独评价某类文献可靠性\"偏题", "note": "", "stem": "《史记》记载，秦统一后，对官方文书的名称、格式、用途作了严格的规定。从睡虎地秦简记载中，也可知官府公文的类别有书、封诊式、录、久书等。这体现了史学研究中（ ）", "paper_cause": "**概念不清**——《史记》（传世文献）与睡虎地秦简（出土文献）互相印证，考的是\"互证性\"，她误选了泛泛的\"可靠性\"", "key": "历史|8|1", "card_type": "redo", "options": {"A": "大胆假设与小心求证的严谨性", "B": "文献史料的可靠性", "C": "传世文献与出土文献的互证性", "D": "考古发掘的重要性"}, "teach": "这道题考的是二重证据法：把地下出土的实物文献和纸上流传下来的传世文献互相印证。材料里正好凑齐两类：《史记》是传世文献（后世传抄的书），睡虎地秦简是出土文献（考古挖出来的竹简），两者都记载了秦代的公文制度而且能对得上，这就叫互证性，正确答案是C。B项可靠性错在它只评价单一一种史料可不可信，而题目给了两种来源、强调的是互相对照，考点在互不在靠。以后遇到甲书的记载加乙地出土材料、内容一致这种结构，直接锁定互证；只给一份孤零零的材料谈真伪时，才谈可靠性。", "why": "没识别出《史记》与秦简是传世加出土两种来源的组合，被泛泛的可靠性带走了。", "check_q": "殷墟出土的甲骨文记载了商王占卜、祭祀等活动，与《史记·殷本纪》中商王世系的记载大体吻合。这最能体现（ ）A.甲骨文是唯一可靠的史料 B.传世文献与出土文献的互证 C.考古发掘比文献更重要 D.《史记》的记载绝对无误", "check_a": "B。两种来源互相印证，就是二重证据法的互证性；A、C、D都犯了绝对化、单一化的毛病。", "steps": "1. 先看材料给了几种来源：《史记》和睡虎地秦简，先给来源分类再答题。\n2. 给来源贴标签：《史记》是传世文献，秦简是出土文献，两类凑齐了。\n3. 看设问落点：问的是两种文献之间的关系与方法，不是问某一种可不可信。\n4. 逐项验落点：B'可靠性'只评价单一史料，落点偏了，排除；C'互证性'正对两类来源互相印证，选它。\n5. 复核动作词：两种来源的记载能对得上就叫互证，这个词就是题眼。", "need": ["二重证据法（王国维）：传世文献与出土文献互证", "史料类型的划分：传世文献与出土文献", "'互证性'与'可靠性'两种设问落点的区别"]}, {"subject": "历史", "question_no": "11", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "知识盲区", "knowledge_point": "汉代中朝崛起：决策权由外朝丞相转向以皇帝为首的中朝，皇权集中", "note": "", "stem": "史料记载，汉武帝时“以（原属少府的）尚书掌文书，常侍从左右备顾问；丞相总揽百僚，然而事皆决于内朝”。至汉元帝时，中朝官弘恭、石显“贵幸倾朝，百僚皆敬事”。这一变化反映的实质是（ ）", "paper_cause": "**概念不清**——题目问\"实质\"，她停在\"丞相职能变化\"的表象，没看到内朝兴起的实质是皇帝收权、决策权向皇帝集中", "key": "历史|11|1", "card_type": "redo", "options": {"A": "丞相职能从决策转向执行", "B": "内朝官僚化威胁皇权", "C": "行政体系专业化程度提升", "D": "决策权向皇帝集中"}, "teach": "先把两个概念分清：外朝是以丞相为首的正式朝廷机构，掌握决策与行政；内朝（中朝）是皇帝在宫中用尚书、侍中、常侍等亲信组成的小圈子。材料的两句话说的是同一件事：事皆决于内朝，大事已经不由丞相拍板了；中朝官贵幸倾朝、百僚皆敬事，连百官都要看内朝的脸色。决策权正从丞相手里转到皇帝和他的亲信手里，实质就是决策权向皇帝集中，正确答案是D。A项丞相职能从决策转向执行，只是表面现象的改述，而且丞相是被架空，并不是改行去做执行。做实质、本质、根本这类题有个固定动作：先问谁的权力变大了、谁的变小了，答案往权力归属上落，基本不会错。B项说内朝威胁皇权，方向正好反了，内朝恰恰是皇帝用来夺权的工具。", "why": "停在丞相职能变化的表象上，没有继续追问决策权最终归了谁。", "check_q": "唐朝实行三省六部制，遇有军国大事，往往由皇帝召集三省长官共同商议。这一制度运行的实质是（ ）A.三省长官的权力高于皇帝 B.相权被分割，皇权得到加强 C.丞相制度正式废除 D.地方权力扩大", "check_a": "B。把相权拆分给三省、最终决策出自皇帝，与汉代内朝一样，实质都是皇权加强；判断实质题，先看权力最终归谁。", "steps": "1. 先分清材料里的两组人：以丞相为首的外朝，和皇帝亲信组成的中朝，主体先定清。\n2. 回材料抓权力动词：'事皆决于内朝''百僚皆敬事'——专找'谁拍板、听谁的'这类词。\n3. 追问实质：决策权从丞相手里转到皇帝和他的亲信手里，本质是皇权集中。\n4. 逐项验深度：A项'丞相职能变化'只描述表象、没回答权归谁，停在半路，排除；D项与实质对位。\n5. 自查一句：我的选项有没有回答'决策权最终归谁'，没回答就还没到实质层。", "need": ["汉武帝时期中朝（内朝）与外朝的构成和职能", "'实质'类设问：追问权力最终归属的方法", "皇权加强的历史脉络（中朝的崛起与尚书台）"]}, {"subject": "历史", "question_no": "15", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "审题偏差", "knowledge_point": "隋末统治危机：\"吏皆惧法，莫肯赈救\"恰说明法令有效，C\"法令废弛\"与材料矛盾", "note": "", "stem": "《隋书》载，大业九年（613）“百姓废业，屯集城堡，无以自给。然所在仓库，犹大充韧（满），吏皆惧法，莫肯赈救”。材料揭示了隋朝（ ）", "paper_cause": "**审题错误**——材料三层信息（百姓无以自给／官仓充盈／官吏不敢赈救）合起来指向\"统治危机\"，她大概率只抓住\"吏不敢赈", "key": "历史|15|1", "card_type": "redo", "options": {"A": "吏治腐败", "B": "经济发展失衡", "C": "法令废弛", "D": "隋朝统治危机"}, "teach": "这道材料题要把三层信息合起来读：第一层，百姓废业、屯集城堡、无以自给，民生已经崩了；第二层，所在仓库犹大充满，朝廷并不是没有粮食；第三层，吏皆惧法、莫肯赈救，官吏害怕触犯法令，不敢开仓赈灾。三层拼在一起，就是有粮不救、百姓等死，这已经不是某个环节的小毛病，而是整个统治秩序出了大问题，指向统治危机，正确答案是D。你选的C法令废弛，恰恰与材料相反：官吏惧法，说明法令正在被严格执行，甚至严苛到不敢变通。A项吏治腐败，材料里没有贪污受贿的信息，属于无中生有。做题方法：每个选项都回材料里找一句对应证据，找不到、或者与原文反着说的，立即划掉。", "why": "只抓住官吏不救灾一层就选了法令废弛，没发现惧法恰恰证明法令在执行，与所选项直接矛盾。", "check_q": "材料：安史之乱后，藩镇割据，赋税多被地方截留，中央财政困窘，宦官专权，党争不断。这段材料最能揭示唐朝后期的（ ）A.经济繁荣 B.统治危机 C.对外开放 D.文化昌盛", "check_a": "B。割据、财政、专权、党争多个层面的问题叠加，指向整体性的统治危机；材料题要综合全部信息，选概括性最强的选项。", "steps": "1. 先把材料分三层读并逐层标注：民生层（百姓废业、屯集城堡）、仓储层（仓库犹大充满）、官吏层（吏皆惧法、莫肯赈救）。\n2. 三层合起来再下判断：有粮、不救、民困——先拼全图，不抓一层就选。\n3. 逐项回材料对位验：C'法令废弛'与'惧法'正相反——怕法恰恰说明法令在执行，与材料直接矛盾，排除。\n4. 三层拼出的结论是整个统治秩序出了大问题，指向统治危机，与D对位。\n5. 复核纪律：每个选项都要能在材料里指到一句原话依据，指不到的不选。", "need": ["隋末统治危机与农民战争爆发的背景", "材料题逐层提取信息、再综合判断的方法", "干扰项类型：与材料信息直接矛盾"]}, {"subject": "历史", "question_no": "19", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 A，无题干无解析", "note": "", "key": "历史|19|1", "card_type": "concept", "teach": "先说清楚：这一题的题干和解析暂时缺失，只剩答题记录（你选B、正确答案A），没法像其他题那样逐项拆解，先不硬编，等补拍到这道原题，再把它换成重做卡。在此之前，用它记一条通用的选择题纪律：第一步时空定位，看清材料的时间、朝代、人物，再检查选项里有没有时代错位的机构、地名、制度，比如唐代的题里出现行省、清代的题里出现三省，时代对不上的选项不用细读就能排除；第二步主体对位，选项的主语是谁做的、谁受益，必须和材料的主语一致，不一致的先排除。很多错题不是知识不会，而是这两步没做，凭眼熟就选了。", "why": "本题题干缺失，具体错因待补拍原题后确认；先按时空定位与主体对位的纪律复盘。", "check_q": "下列选项中，属于唐代政治制度的是（ ）A.行省 B.三省六部 C.军机处 D.内阁", "check_a": "B。行省是元代的，军机处是清代的，内阁是明代的；用时代排除法，时段对不上的选项先划掉。", "steps": "1. 原题暂时缺失，先用通用纪律复盘这类题：拿到题第一步做时空定位，看清材料的时间、朝代、人物。\n2. 用时代线索排雷：选项里的机构、地名、制度与材料时代对不上的直接排除（如唐代题里出现行省）。\n3. 做主体对位检查：选项的主语（皇帝/大臣、中央/地方）与材料主体不是同一方时，警惕偷换主体。\n4. 逐项回材料对位：每个选项都要在材料里找到原话依据，无依据的表述再像也不选。\n5. 等补拍到原题后，按上面四步把这道题完整重做一遍，再归档确认错因。", "need": ["历史选择题的时空定位法", "各时代标志性制度坐标（防时代错位型干扰项）", "干扰项类型：主体偷换、无依据引申"], "stem": "19. 据梁方仲先生统计，唐代前期和后期户均人口数有显著变化，如639年户均人口数为4.31口，821年为6.63口。导致这一变化的主要原因是（ ）\nA. 赋税制度的变化\nB. 唐朝政局的稳定\nC. 儒学观念的复兴\nD. 均田制度的实施"}, {"subject": "历史", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 A，无题干无解析", "note": "", "stem": "贞观年间，宰相岑文本辞华美，精通典章制度，皇帝文书皆出其手。据此推知，岑文本最有可能供职的部门是（ ）", "paper_cause": "**概念不清**——\"皇帝文书皆出其手\"＝草拟诏令，是中书省的活；她把中书、门下的职能记反了  ## 非选择题（作答未拍", "key": "历史|20|1", "card_type": "redo", "options": {"A": "中书省", "B": "门下省", "C": "尚书省", "D": "枢密院"}, "teach": "三省的职能必须并排着记，一个字都不能反：中书省负责决策、草拟诏令，是出令的；门下省负责审议、封驳，诏令有问题可以退回去，是把关的；尚书省负责执行，统领六部办事，是落实的。记忆口诀是中出、门审、尚行。材料给的信号非常明确：辞华美、精通典章、皇帝文书皆出其手，皇帝的文书都经他的手写出来，这就是草拟诏令，锁定中书省，正确答案是A。再并排看门下省：它管的是审核封驳，尚书省管的是执行。再看D项枢密院，那是宋朝才有的机构，掌军政，与中书省并称二府，唐代的题里出现宋代机构，光靠时代就能排除。你这次选了D，是职能没对上、时代也没把关，双重失守。", "why": "三省职能记反、记混，又没用时代线索排除宋代才有的枢密院。", "check_q": "唐朝某官员发现皇帝下达的诏令有不妥之处，将其封还、拒绝副署。这名官员最可能任职于（ ）A.中书省 B.门下省 C.尚书省 D.礼部", "check_a": "B。封驳（封还诏令）是门下省的专职：中书出令、门下审驳、尚书执行，记住中出、门审、尚行就不会记反。", "steps": "1. 先用时代线索排雷：材料是三省语境，选项里的枢密院是宋代才有的机构，先标为可疑。\n2. 回材料抓职能动词：'辞华美、精通典章、皇帝文书皆出其手'——关键词锁定'草拟诏令'。\n3. 调用职能表对位：中书出令（决策、草拟）、门下审驳、尚书执行，'草拟'正对中书省。\n4. 逐项验：D枢密院既错时代（宋）又错职能（管军政），双重排除。\n5. 落笔前用'中出、门审、尚行'口诀默一遍，确认三个职能没记反再选。", "need": ["三省六部制中中书/门下/尚书三省的职能分工", "枢密院的设立时代与职能（宋代、军政）", "职能类选择题：抓材料中的职能动词对位"]}, {"subject": "历史", "question_no": "21(2)", "full_score": 8.0, "got_score": 3.0, "student_answer": "（手写，辨认见下）", "std_answer": "背景：商鞅变法推行县制；秦统一六国；法家思想确立。意义：强化中央集权；促进地区交流；贵族政治→官僚政治；后世地方治理基本制度", "error_type": "表述不规范/知识盲区", "knowledge_point": "郡县制推行的背景与意义。背景只写\"战国变法\"太笼统，未点名商鞅变法/县制/秦统一/法家思想；意义答出\"集权、收归地方权力\"，但\"为秦统一奠定基础\"因果倒置（郡县制是统一后推行）", "note": "", "key": "历史|21(2)|1", "card_type": "concept", "teach": "背景加意义是大题最常见的组合问法，各有固定框架。背景这样凑：①制度基础，商鞅变法时已在秦国推行县制，有现成经验；②政治条件，秦统一六国，需要管理空前辽阔的疆域；③集权需要，要废除分封、防止诸侯割据重演；④思想依据，法家思想提供支持。意义这样凑：①对中央，加强中央集权，郡县长官由皇帝直接任免；②对地方治理，官僚政治取代世袭贵族政治；③对后世，成为历代地方行政的基本制度；④对统一，促进各地交流、巩固统一。你丢分有两处：一是背景只写战国变法太空，没点名商鞅变法和县制；二是因果写反了，郡县制是统一之后才全面推行的，不能写成为秦统一奠定基础，统一是它的背景，不是意义。写意义前，先过一遍时间顺序。", "why": "背景没点名商鞅变法、县制等关键词，还把统一这个背景误写成了郡县制的意义，因果倒置。", "check_q": "下列哪一句是郡县制的意义而不是背景？A.商鞅变法在秦国推行县制 B.秦统一六国后疆域空前辽阔 C.郡县制使官僚政治取代贵族政治，成为后世地方治理的基本制度 D.法家思想受到秦王朝推崇", "check_a": "C。A、B、D都是推行郡县制之前已经存在的条件，属于背景；C说的是推行之后产生的影响，属于意义。判断标准就是看时间在前还是在后。", "steps": "1. 先审设问类型：'背景＋意义'组合问，两个框分开答，先背景后意义，框架先搭好。\n2. 背景按维度凑：制度基础（商鞅变法已推行县制）、政治条件（秦统一后要治理空前疆域）、集权需要（废分封、防割据）、思想依据（法家）。\n3. 意义按维度凑：对中央（加强集权、长官由皇帝任免）、对地方治理（官僚政治取代贵族政治）、对后世（成为历代地方行政的基本制度）。\n4. 落笔只用关键词：商鞅变法、县制、秦统一、法家要点名写出，不许用'战国变法'这种笼统话代替。\n5. 自查因果方向：郡县制是统一之后才推行的，'为秦统一奠定基础'是因果倒置，发现就划掉。", "need": ["秦朝郡县制推行的背景（商鞅变法县制、法家思想、统一形势）", "郡县制的意义及与分封制的对比", "'背景＋意义'组合设问的答题框架与因果方向检查"], "points": ["背景得分点1（约 1 分）：制度基础——商鞅变法时已在秦国推行县制，有现成经验。她只写了'战国变法'四个字，没点名商鞅变法和县制，这一点只拿到零星分。", "背景得分点2（约 1 分）：政治条件——秦统一六国，需要管理空前辽阔的疆域。她没有写清。", "背景得分点3（约 1 分）：集权需要——废除分封、防止诸侯割据重演。她约略答到。", "背景得分点4（约 1 分）：思想依据——法家思想提供支持。她没有写。", "意义得分点1（约 1 分）：对中央——加强中央集权，郡县长官由皇帝直接任免。她答到了，是主要得分来源。", "意义得分点2（约 1 分）：对地方治理——官僚政治取代世袭贵族政治。她写了'收归地方权力'的意思，部分给分。", "意义得分点3（约 1 分）：对后世——成为历代地方行政的基本制度。她没有写。", "意义得分点4（约 1 分）：对统一——促进各地交流、巩固统一。她反而把'为秦统一奠定基础'写成了意义，因果倒置（郡县制是统一之后才全面推行的），这一点不得分。", "她的账：8 分只得 3 分，丢分＝背景太空（没点名）＋意义漏两点＋一个因果倒置。"], "frame": "'背景＋意义'组合题分两栏落笔，栏内再分点。背景按'制度基础 → 政治条件 → 集权需要 → 思想依据'四维清单逐维想，落笔必须带专名（商鞅变法、县制、法家），只写大方向词不给分。意义按'对中央 → 对地方治理 → 对后世 → 对统一'四维落笔。动笔前先做一件事：把事件的时间位置钉死（郡县制全面推行在统一之后），凡是发生在它之前的事只能写进背景、绝不能写进意义。写完自查：每个维度有没有点、有没有专名、时间顺序有没有倒置。", "stem": "第21题 材料二（大意）：商鞅变法设县，秦统一后推行郡县制。\n设问：秦朝在全国推广郡县制的背景及意义。（8分）"}, {"subject": "历史", "question_no": "22(1)", "full_score": 6.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "任答三点：圩田/闸坝灌溉体系；开田万顷；岁增粟帛；耕作效率提高", "error_type": "表述不规范", "knowledge_point": "江南农业发展的表现。未用关键词（圩田、灌溉体系、开田万顷、岁增粟帛），表述混乱", "note": "", "key": "历史|22(1)|1", "card_type": "concept", "teach": "表现类设问有个特点：答案几乎全在材料里，不用你发明，只需要提取信息再换成关键词。这则材料里现成的得分词是：杜预在荆州修陂塘（水利设施）、太湖流域修圩田（围湖造田、配闸坝形成灌溉体系）、开田万顷（耕地面积扩大）、岁增粟帛（粮食和布帛产量增加）、耕作效率提高，任答三点就能拿满。你只得2分，问题不在不懂，而是答题动作错了：脱离材料自己组织语言，写得又乱又没有关键词，阅卷按点给分，自然找不到得分点。固定动作是：先在材料上把关键短语逐个划出来，答案就照着划线处改写成短句，一点一行、序号标清，宁可像抄材料，也不要自由发挥。", "why": "脱离材料自己编话，没有提取圩田、灌溉体系、开田万顷等关键词，阅卷按点找不到得分点。", "check_q": "材料：宋代，江南地区水稻种植面积大增，占城稻得到推广，苏州、湖州成为重要粮仓，民间有苏湖熟、天下足的谚语。请用三个关键词概括这一时期江南农业发展的表现。", "check_a": "①种植面积扩大（水稻推广、占城稻引进）；②粮食产量大增（苏湖成为重要粮仓）；③经济地位上升（苏湖熟、天下足）。表现题就是从材料里提炼关键词短句，不用自编。", "steps": "1. 先审设问类型：'表现'类设问——答案几乎全在材料里，先回材料，不许脱离材料自编。\n2. 逐句扫材料圈信息点：修陂塘、圩田、开田万顷、岁增粟帛、耕作效率提高，圈一个记一个。\n3. 把圈出的信息换成关键词表述：圩田/闸坝灌溉体系、开田万顷、岁增粟帛，阅卷按词找点。\n4. 任选三点分条写，每点'关键词＋材料原话依据'配套，不写大白话长句。\n5. 交卷前自查：每一点都能在材料里指出出处，没有一句是自己编的。", "need": ["'表现/特点'类设问的材料信息提取法", "江南地区开发的表现（圩田、水利设施、粮食增产）", "主观题关键词化表述：按点给分、点后跟依据"], "points": ["得分点（任答三点得满，每点约 2 分）：圩田、闸坝灌溉体系——太湖流域修圩田，围湖造田并配套闸坝形成灌溉系统。材料里现成有词，她没有提取出来。", "得分点：开田万顷——耕地面积大幅扩大。她没有写到这个量化表述。", "得分点：岁增粟帛——粮食和布帛产量逐年增加。她没有提取。", "得分点：耕作效率提高——生产工具与方式进步带来的效率提升。她表述混乱、没有落到关键词上。", "她的账：任答三点即可满分，她得 2/6，相当于只零星碰到一点。丢分不在知识，在动作：脱离材料自己编话，阅卷按点给分时找不到得分点。"], "frame": "'表现'类设问的答案几乎全在材料里，落笔流程固定：第一步先在材料上把关键短语逐个划出来（圩田、灌溉、开田万顷、岁增粟帛这类名词和量化词）；第二步照着划线处改写成短句落笔，一点一行、序号标清，每点就是'关键词＋一句出处'；第三步数点，任答三点的题写满三点再停。铁规矩：宁可像抄材料，也不自由发挥；写完自查每一点里有没有一个材料原词，没有就回去重划。", "stem": "第22题 材料一（大意）：西晋荆州刺史杜预修陂塘，唐代太湖流域修圩田。\n设问：魏晋至唐代江南农业发展的具体表现。（6分）"}, {"subject": "历史", "question_no": "22(2)", "full_score": 6.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "任答三点：北民南迁；曲辕犁/龙骨水车/圩田水利；土断/赋税改革/漕运；政府重视水利", "error_type": "知识盲区/表述不规范", "knowledge_point": "江南农业发展的主要因素。自编\"气候适宜\"非得分点；\"北民南迁/朝廷重视\"方向对但缺关键词（曲辕犁、土断、漕运）", "note": "", "key": "历史|22(2)|1", "card_type": "concept", "teach": "因素、原因类设问，用人口、技术、政策、环境四维框架往里装。这道题的标准得分点是：①人口，北方人口南迁带来劳动力，土断政策把南迁人口编入户籍；②技术，曲辕犁、龙骨水车等农具进步，加上圩田水利；③政策，政府重视农业，赋税改革、漕运开通保障流通。你写的气候适宜为什么不得分？因为设问问的是这一时期推动发展的因素，气候几千年来一直适宜，它是背景条件，不是这一时期新出现的推动变量，阅卷不会给分。你想到的北民南迁、朝廷重视方向是对的，可惜没有落到土断、曲辕犁、漕运这些术语上。记住：因素题专挑这一时期新出现的变化来写，并且尽量用课本原词。", "why": "把恒常的自然条件当成了推动因素，想到的方向又写成了大白话，没有落到土断、曲辕犁等关键词上。", "check_q": "下列哪项最适合作为魏晋南北朝时期江南得到开发的推动因素？A.江南气候温暖湿润 B.北方人口大量南迁，带来劳动力和技术 C.江南雨量充沛、河流众多 D.江南自古就是鱼米之乡", "check_a": "B。A、C、D都是长期存在的自然或历史条件，不是这一时期新出现的变量；推动因素要选这一时期发生的新变化。", "steps": "1. 先审设问类型：'因素/原因'类——问的是这一时期新出现的推动力量，先把'新出现'三个字圈住。\n2. 定四维框架往里装：人口、技术、政策、环境，每维先想一条再回材料核对。\n3. 逐维找得分点：人口—北民南迁、土断编户；技术—曲辕犁、龙骨水车、圩田水利；政策—赋税改革、漕运开通、政府重视水利。\n4. 剔除伪因素：'气候适宜'几千年一直如此，是恒常背景不是变量，当推动因素写不得分。\n5. 分点落笔，每点带关键词，自查四维至少覆盖三维、没有把背景条件混进因素。", "need": ["'因素/原因'类设问的四维框架（人口/技术/政策/环境）", "江南开发的关键史实（土断、曲辕犁、龙骨水车、北民南迁）", "变量因素与恒常背景条件的区别"], "points": ["得分点（任答三点得满，每点约 2 分）：人口——北方人口南迁，带来劳动力。她想到了'北民南迁'，方向对，是得分来源之一。", "得分点：政策——土断政策把南迁人口编入户籍、赋税改革。她只写了'朝廷重视'的空话，没落到'土断'这个术语，丢分。", "得分点：技术——曲辕犁、龙骨水车等农具进步，加上圩田水利。她没有写到任何一个农具名词。", "得分点：政策——政府重视水利、漕运开通保障流通。她同样停在空话层。", "零分项（要专门记）：她写的'气候适宜'不给分——气候几千年一直适宜，是恒常背景条件，不是这一时期新出现的推动因素，'因素'题只认变量不认常量。", "她的账：得 2/6。方向对了两个，却全写成大白话；又把一个常量当因素写了进去，等于有效点只剩一两个。"], "frame": "'因素/原因'类设问先默四维框架再落笔：人口 → 技术 → 政策 → 环境，逐维问自己'这一时期新出现了什么变化'，只写变量、不写常量（气候、地形这类千年不变的先划掉）。每维落笔必须带课本术语（土断、曲辕犁、漕运），写不出术语的那一维宁可空着也不要用大白话凑。自查：每一点是不是'这一时期才有'的；每一点里有没有一个专名。", "stem": "第22题 材料二（大意）：东晋南朝“土断”，唐开元二十五年江南纳税与租调布。\n设问：推动江南农业发展的主要因素。（6分）"}, {"subject": "历史", "question_no": "23", "full_score": 12.0, "got_score": 6.0, "student_answer": "（手写，辨认见下）", "std_answer": "主题(3)+三部分标题(3×1)+内容方向(3×2)：背景/学派人物主张/历史影响", "error_type": "审题偏差/表述不规范", "knowledge_point": "百家争鸣。三段结构完整；背景、学派部分部分踩点；第三部分写\"秦统一终结百家争鸣（焚书坑儒）\"，偏离\"对后世文化与治理的实践价值\"得分方向；主题句潦草难辨", "note": "", "key": "历史|23|1", "card_type": "concept", "teach": "这是一道策划学习手册的活动设计题，给分点就写在题目里：主题3分，三个部分的目录标题各1分，每个部分的内容方向各2分，共12分。你的结构是完整的，丢分丢在第三部分的方向上：你写了秦统一终结百家争鸣、焚书坑儒，这属于政治史的后续事件，偏离了手册思想文化的主题；这一部分应该写百家争鸣的历史影响与价值，比如儒家思想成为传统文化主流、法家思想影响后世治理、道家思想滋养文艺、各家争鸣开创了学术自由讨论的传统。还有一个小失分：主题句潦草难辨，阅卷看不清就等于没写。这类题动笔前先把给分点在草稿上拆开（主题加3个目录加3个方向），逐项配齐内容再写，方向必须紧扣题目限定的主题词。", "why": "第三部分写偏到秦统一、焚书坑儒的政治事件，脱离思想文化主题；主题句又潦草难辨。", "check_q": "为百家争鸣学习手册设计第三部分历史影响，下列内容方向最合适的是（ ）A.秦始皇焚书坑儒的经过 B.儒、法、道思想对后世文化与治理的深远影响 C.诸子百家的生平年表 D.春秋战国的战争进程", "check_a": "B。手册主题是思想文化，影响部分要落在思想对后世文化与治理的价值上；A、D偏政治军事，C是人物资料而非影响。", "steps": "1. 先拆题目的给分结构：主题3分＋三个部分标题各1分＋每部分内容方向各2分，结构分先拿稳。\n2. 先写主题句：一句能统摄三个部分的主题先工整写出来，主题句就是3分，不许潦草。\n3. 三个部分按逻辑链排目录：背景→学派人物与主张→历史影响，标题逐个写清。\n4. 写每部分内容方向前先自问一句：它扣不扣这本手册'思想文化'的主题。\n5. 第三部分只落影响与价值（儒家成文化主流、法家影响后世治理、道家滋养精神），不写秦统一、焚书坑儒这类政治后续事件。\n6. 最后自查：三个部分的方向是否都绕回主题，有没有跑题的段落混在里面。", "need": ["百家争鸣的历史影响与各学派核心主张", "活动设计/学习手册类题目的给分结构拆解", "主观题主题一致性自查（防内容方向跑偏）"], "points": ["得分点1（3 分）：主题——学习手册的主题句。她写了主题，但字迹潦草难辨，阅卷看不清就等于没写，这 3 分实际大打折扣。主题分是整道题里单点分值最高的，先丢在这里最亏。", "得分点2（3 分）：三个部分的目录标题，各 1 分。她的三段结构完整，标题基本齐全，这部分是她的主要得分。", "得分点3（2 分）：第一部分内容方向——百家争鸣的背景。她部分踩点，拿到部分分。", "得分点4（2 分）：第二部分内容方向——各学派的人物与主张。她部分踩点，拿到部分分。", "得分点5（2 分）：第三部分内容方向——百家争鸣的历史影响与价值（儒家成为传统文化主流、法家影响后世治理、道家滋养文艺、开创学术争鸣传统）。她写成了'秦统一终结百家争鸣、焚书坑儒'，偏离思想文化主题，这 2 分基本丢光。", "她的账：6/12。丢分构成＝主题潦草（约丢一半主题分）＋第三部分方向写偏（丢约 2 分）＋前两部分内容各漏细节。"], "frame": "这类活动设计题，给分点就写在题目里，动笔前先在草稿上把给分点拆成清单：主题（1 项）＋目录标题（3 项）＋内容方向（3 项），共 7 个格子，逐格配内容再往答题卡上写。落笔顺序：主题句单独一行、写工整（它值 3 分）；然后每个部分'标题一行＋方向两三句'，方向句必须紧扣题目限定的主题词（本题是'思想文化'，凡写到政治事件先问自己扣不扣题）。写完自查：7 个格子是不是格格有内容；第三部分有没有滑到主题之外的后续事件；主题句自己能不能一眼读清。", "stem": "第23题：根据材料（春秋战国“百家争鸣”）并结合所学，策划一份春秋战国时期思想文化的学习手册（须有明确主题、至少三个部分目录、每个目录注明主要内容方向）。（12分）"}, {"subject": "地理", "question_no": "5", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|5|1", "card_type": "concept", "teach": "太阳大气由里到外分三层：光球层、色球层、日冕层。活动与层对应着记：光球层上是黑子（温度比周围低，所以显得暗）；色球层上是耀斑和日珥；日冕层向外吹出太阳风。最易混的两点：第一，黑子在光球、耀斑在色球，别记串层；第二，太阳活动强弱的主要标志是黑子，周期约11年，耀斑是太阳活动最激烈的显示。影响也成串记：扰乱电离层、干扰无线电短波通信；扰动地球磁场产生\"磁暴\"；在两极高纬地区产生极光；还可能影响气候。判断顺序固定为\"先定位是哪一层，再想这一层对应什么活动、什么影响\"，不要看到\"太阳活动\"就凭眼熟乱选。", "why": "她选C、正解B；同一张卷的太阳大气填空她能答对，说明知识是碎片化的——记住了词，却没把\"层—活动—影响\"对应成链来记。", "check_q": "太阳黑子和耀斑分别位于太阳大气的哪一层？太阳活动强弱的主要标志是什么？", "check_a": "黑子在光球层，耀斑在色球层；主要标志是黑子的多少，周期约11年。", "steps": "1. 先定位：题目问的是太阳大气哪一层——由里到外光球、色球、日冕，先定层再想活动。\n2. 按层对活动：光球→黑子，色球→耀斑和日珥，日冕→太阳风；选项把活动安错层的直接排除。\n3. 再连影响：黑子多少是活动强弱的主要标志（周期约11年），影响走扰乱电离层、磁暴、极光这条线。\n4. 防串层：她同卷填空能答对单点、选择却选错，说明要整链对表后再落笔，不能凭某个词眼熟就选。", "need": ["太阳大气三层结构：光球层、色球层、日冕层", "各层太阳活动类型：黑子、耀斑、日珥、太阳风及11年周期", "太阳活动对地球的影响：磁暴、极光、干扰无线电短波通信"], "points": ["层序点：太阳大气由里到外写对——光球层、色球层、日冕层（顺序本身即得分点）", "活动对位点：黑子在光球层、耀斑和日珥在色球层、太阳风来自日冕层——她错在活动与层串位", "标志点：黑子是太阳活动强弱的主要标志，周期约11年；耀斑是活动最激烈的显示", "影响点（设问问影响时）：扰乱电离层干扰无线电短波通信、产生磁暴、两极极光"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先定位\"问的是哪一层\"，再答\"这一层有什么活动、什么影响\"，层与活动锁死对应，不跨层乱答。", "stem": "（地理原卷未拍到，题干待补）本题考查：太阳大气的分层与太阳活动的对应关系——光球层、色球层、日冕层分别对应黑子、耀斑与日珥、太阳风等哪种活动，以及太阳活动强弱的标志和对地球的影响。"}, {"subject": "地理", "question_no": "6", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|6|1", "card_type": "concept", "teach": "地质年代表的层级从大到小是：宙—代—纪。最常考的对调坑有两个：第一，古生代和中生代——古生代是早期生命的时代，无脊椎动物和鱼类繁盛，两栖类出现；中生代是\"爬行动物的时代\"，恐龙繁盛，末期恐龙灭绝，鸟类和小型哺乳动物出现。第二，新生代和第四纪不是同一级：新生代是\"代\"，第四纪是新生代里面最新的一\"纪\"，人类就出现在第四纪。记法：问\"哪个时代有什么动物\"先定位到代（古—中—新按先后排），问\"人类出现\"直接答第四纪、属新生代。层级和先后是两个维度，出题人最爱把它们交叉起来挖坑，必须分开记。", "why": "她选B、正解D；同卷综合题里她把爬行动物繁盛答成古生代、把第四纪与新生代并列，层级和先后两个维度都没分开，这道题是同一毛病的复现。", "check_q": "恐龙繁盛和恐龙灭绝发生在哪个代？人类出现在哪个纪，它属于哪个代？", "check_a": "都在中生代（繁盛于中生代，灭绝于中生代末期）；人类出现在第四纪，第四纪属于新生代。", "steps": "1. 先分清问的是哪个维度：层级（宙—代—纪）还是先后顺序，两个维度分开答。\n2. 定\"代\"：古生代→中生代→新生代按先后排，生物标志跟着代走——爬行动物繁盛在中生代，不要记到古生代。\n3. 再定\"纪\"：第四纪是新生代内部最新的一纪，人类出现在第四纪；选项把第四纪与新生代并列同级的，判错。\n4. 最后整链对表：宙>代>纪的包含关系和各代生物标志逐项核对再选。", "need": ["地质年代层级：宙—代—纪", "各代生物演化标志：中生代爬行动物繁盛与恐龙灭绝", "第四纪与新生代的包含关系及人类的出现"], "points": ["层级点：地质年代层级从大到小是宙—代—纪，层级不能错位", "代际生物点：古生代——无脊椎动物、鱼类繁盛，两栖类出现；中生代——爬行动物（恐龙）时代；新生代——哺乳动物与人类——她错在古生代/中生代对调", "定位点：人类出现在第四纪，第四纪是新生代里的一个纪——\"代\"与\"纪\"两个维度分开答，不能把新生代和第四纪当同一级"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先分两个维度——问先后用代（古—中—新），问层级用宙—代—纪，两维分开定位再答生物对应。", "stem": "（地理原卷未拍到，题干待补）本题考查：地质年代表的层级与先后关系——宙、代、纪的层级大小，古生代、中生代、新生代各自的生物繁盛标志，以及第四纪隶属于新生代这一包含关系。"}, {"subject": "地理", "question_no": "10", "full_score": 2.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|10|1", "card_type": "concept", "teach": "地球内部圈层靠两个界面和一串数字记。由外到内：地壳—莫霍界面（平均深度约17千米）—地幔—古登堡界面（地下约2900千米）—地核。地幔中，上地幔顶部有一层熔融状的软流层，它是岩浆的主要发源地；软流层以上的地壳加上地幔顶部，合称岩石圈——岩石圈不等于地壳，这是最常见的对调坑。探测靠地震波：纵波速度快，固、液、气三态都能传播；横波速度慢，只能在固体中传播；横波在古登堡界面附近消失，正是推断外核为液态的证据。数字只钉三个：17（莫霍平均深度）、2900（古登堡深度）、软流层在上地幔。", "why": "她选A、正解D；同卷综合题里她把古登堡界面深度记成了4000、软流层位置也答错，这道选择题大概率栽在同一组数字和位置上——纯记忆点没钉死。", "check_q": "古登堡界面位于地下约多少千米？岩石圈由哪两部分组成？", "check_a": "约2900千米；岩石圈由地壳和上地幔顶部（软流层以上部分）组成。", "steps": "1. 先排大顺序：地壳→地幔→地核，两个界面卡在中间——莫霍界面在地壳与地幔之间，古登堡界面在地幔与地核之间。\n2. 钉数字：莫霍平均深度约17千米，古登堡深度约2900千米，数字记错一位整题错，先默对数字再看选项。\n3. 定位特殊层：软流层在上地幔顶部，是岩浆主要发源地；岩石圈=地壳+上地幔顶部（软流层以上），选项把岩石圈说成地壳的判错。\n4. 用地震波验证：横波只能过固体、在古登堡界面附近消失→外核为液态，与选项互相印证后再选。", "need": ["莫霍界面与古登堡界面的位置和深度（约17 km、约2900 km）", "岩石圈的组成：地壳与上地幔顶部", "地震波纵波与横波的传播特点及对外核状态的推断"], "points": ["界面数字点（对应综合题26(1)，6分得3分）：莫霍界面平均深度约17千米、古登堡界面约2900千米——两个数字写准各占分，记反或漏写即丢", "软流层点：软流层位于上地幔，是岩浆的主要发源地", "岩石圈点：岩石圈=地壳+上地幔顶部，不等于地壳——概念边界点，她混淆在此", "证据点：横波在古登堡界面附近消失，是推断外核为液态的证据（纵波三态可传、横波只能固体传）"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先按由外到内默出圈层链（地壳—莫霍—地幔—古登堡—地核），再逐点钉数字与定位，最后才答设问。", "stem": "（地理原卷未拍到，题干待补）本题考查：地球内部圈层结构——地壳、地幔、地核的排列与莫霍界面（约17千米）、古登堡界面（约2900千米）两个分界面的深度，软流层的位置、岩石圈的构成，以及横波、纵波的传播特征。"}, {"subject": "地理", "question_no": "11", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|11|1", "card_type": "concept", "teach": "大气的受热过程整条链只记一句话：太阳暖大地、大地暖大气、大气还大地。展开成三段：第一段，太阳辐射（短波辐射）穿过大气时只被削弱一小部分，大部分到达地面，地面吸收后增温；第二段，地面增温后放出地面辐射（长波辐射），对流层大气中的水汽、二氧化碳强烈吸收地面辐射，大气随之增温——所以地面是近地面大气主要的、直接的热源，大气直接吸收的太阳辐射很少；第三段，大气增温后也向外辐射，其中射向地面的部分叫大气逆辐射，把热量还给地面，起保温作用。做这类题先定位题目问的是哪一段：问\"大气热源\"答地面辐射，问\"夜间保温\"答逆辐射，三段不能串。", "why": "她所在的11—14题组连续四道全错，说明整条受热链在她脑子里是散的；做题时没先定位\"问的是哪一段\"，就凭环节名称的眼熟程度乱选。", "check_q": "近地面大气主要的、直接的热源是什么？", "check_a": "地面（地面辐射）。大气对太阳短波辐射吸收很少，大部分太阳辐射到达地面；地面放出的长波辐射绝大部分被大气吸收。", "steps": "1. 先定设问问哪一段：大气受热三段链——太阳辐射到达地面、地面辐射加热大气、大气逆辐射返还地面，问\"热源\"\"保温\"分别落在不同段。\n2. 调出整链默一遍：太阳暖大地、大地暖大气、大气还大地。\n3. 逐环节对选项：问近地面大气热源→地面辐射；问夜间保温→大气逆辐射；把地面辐射说成太阳辐射、把逆辐射说成反射的，都是偷换环节，判错。\n4. 她11—14题组连错四道，就是没先定位\"问哪一段\"，本题起每道先定位再选。", "need": ["大气受热过程三环节：太阳辐射、地面辐射、大气逆辐射", "地面是近地面大气主要的、直接的热源", "短波辐射与长波辐射的区别"], "points": ["第一环节点：太阳辐射（短波）穿过大气只被削弱一小部分，大部分到达地面，地面吸收增温", "第二环节点（得分大头，对应综合题27(2)，6分仅得1分）：地面辐射（长波）被对流层水汽、二氧化碳强烈吸收——地面是近地面大气主要的、直接的热源；她丢分就是这一环节没写清", "第三环节点：大气逆辐射把热量返还地面，起保温作用", "不串环节点：问\"大气热源\"只答地面辐射，问\"夜间保温\"只答逆辐射，三段各答各的"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：原理链固定三段——太阳暖大地、大地暖大气、大气还大地；动笔先把三段链默在草稿上，再对着设问圈出问的是哪一段，只展开那一段。", "stem": "（地理原卷未拍到，题干待补）本题考查：大气受热过程的环节定位——在“太阳辐射到达地面、地面辐射加热大气、大气逆辐射返还地面”三段链中判断设问指向哪一段，如近地面大气主要的、直接的热源是什么。"}, {"subject": "地理", "question_no": "12", "full_score": 2.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|12|1", "card_type": "concept", "teach": "大气对太阳辐射的削弱作用有三种形式，靠例子分清：吸收——有选择性，如臭氧吸收紫外线、水汽和二氧化碳吸收红外线；反射——无选择性，云层和较大的尘埃颗粒把太阳辐射反射回宇宙空间，云越厚反射越强，阴天白天凉爽主要靠它；散射——有选择性，空气分子散射波长较短的蓝紫光，所以晴朗的天空呈蔚蓝色。最要紧的一对辨析是\"反射\"和\"大气逆辐射\"：反射发生在太阳辐射到达地面之前，把短波辐射挡回去；逆辐射发生在地面增温之后，把长波热量还回来，时间和方向都正好相反。选项里把这两个词互换着说，基本就是错误项。", "why": "她选A、正解C；她在同卷大题中明确把\"大气逆辐射\"写成了\"反射\"，削弱作用里的反射和保温作用里的逆辐射在她那里是一个模糊印象，没有按发生时机分开。", "check_q": "阴天时白天不太热、夜晚不太冷，分别主要与哪种作用有关？", "check_a": "白天不太热：云层反射作用强，削弱了到达地面的太阳辐射；夜晚不太冷：云层使大气逆辐射增强，保温作用强。", "steps": "1. 先定时机：削弱作用发生在太阳辐射到达地面之前，逆辐射发生在地面增温之后——先分清前后，再看具体名称。\n2. 削弱三形式靠例子分清：吸收看臭氧吸紫外线、水汽和二氧化碳吸红外线；反射看云层（无选择性、云厚反射强）；散射看蓝紫光（天空蔚蓝）。\n3. 重点排雷：反射是把短波辐射挡回宇宙空间，逆辐射是把长波热量还给地面，方向和时机都相反；选项把两者互换表述的，基本就是错误项。\n4. 结合情境验证：阴天白天凉（反射强）、夜晚暖（逆辐射强），两个现象分别对上号再落笔。", "need": ["大气削弱作用三形式：吸收、反射、散射及各自实例", "大气逆辐射的发生时机与方向", "反射与大气逆辐射的区别（她大题中的原话错误点）"], "points": ["吸收点：削弱有选择性——臭氧吸收紫外线，水汽、二氧化碳吸收红外线", "反射点：无选择性——云层和大颗粒尘埃反射，云越厚反射越强，阴天白天凉爽主因是反射", "散射点：有选择性——空气分子散射蓝紫光，晴空蔚蓝", "辨析点（她最易丢）：反射发生在太阳辐射到达地面之前、挡的是短波；逆辐射发生在地面增温之后、返还的是长波——两个词互换出现即错误项"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先按\"时机\"定位——辐射到达地面之前发生的是削弱（吸收/反射/散射），之后发生的是辐射与逆辐射，时机对上再分形式。", "stem": "（地理原卷未拍到，题干待补）本题考查：大气对太阳辐射的削弱作用——吸收、反射、散射三种形式各自的特点与实例，并与发生在地面增温之后的大气逆辐射相区分。"}, {"subject": "地理", "question_no": "13", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|13|1", "card_type": "concept", "teach": "保温作用的完整链条是：地面吸收太阳辐射后增温，放出地面辐射；大气几乎全部吸收地面长波辐射而增温；大气增温后产生大气辐射，其中射向地面的部分叫大气逆辐射，它把大部分热量返还地面，弥补地面损失的热量——这就是大气的保温作用（温室效应）。三个要点钉死：第一，逆辐射的方向是大气射向地面，和\"反射回宇宙空间\"正好相反，把它写成\"反射\"是她在综合题里丢整段分的原话错误；第二，逆辐射强弱看水汽、二氧化碳和云量，阴天、多云的夜晚逆辐射强、气温较高，晴朗的夜晚逆辐射弱、容易出现霜冻；第三，题干问\"保温\"时，只认逆辐射这一个关键词。", "why": "她选C、正解A；这正是她整张地理卷的病根——综合题27(2)她把大气逆辐射直接写成\"反射\"、夜间保温机制整段没答，这道选择题错在同一处。", "check_q": "为什么晴朗的秋夜比阴雨的秋夜更容易出现霜冻？", "check_a": "晴天云少，大气逆辐射弱、保温作用差，地面热量散失快，降温幅度大，容易结霜；阴雨天云层厚，逆辐射强，降温慢。", "steps": "1. 先扣设问关键词：题干出现\"保温\"\"夜间降温\"\"霜冻\"，直接锁定第三段——大气逆辐射。\n2. 调出保温链默写：地面吸收太阳辐射增温→放出地面辐射→大气吸收长波辐射增温→大气逆辐射把热量返还地面。\n3. 看条件判强弱：云量多、水汽足→逆辐射强、夜温高；晴朗干燥→逆辐射弱、降温快、易霜冻。\n4. 排除偷换项：凡把逆辐射说成\"反射回宇宙空间\"的判错——那是她在综合题里丢整段分的原话错误，本题正解只认逆辐射。", "need": ["大气逆辐射与保温作用（温室效应）的完整机制", "大气逆辐射强弱的影响因素：云量、水汽、二氧化碳", "晴朗夜晚易霜冻的成因"], "points": ["方向点（整段丢分点，对应综合题27(2)(3)）：大气逆辐射的方向是大气射向地面——她在综合题里把逆辐射写成\"反射\"，方向一错整段不得分", "链条完整点：地面吸收太阳辐射增温→放出地面辐射→大气几乎全部吸收长波辐射增温→逆辐射返还地面弥补热量损失，四个环节缺一不可", "强弱点：逆辐射强弱看水汽、二氧化碳和云量——多云阴夜逆辐射强、气温高；晴朗夜逆辐射弱、易出现霜冻", "关键词点：设问出现\"保温/温室效应\"，答案只锁\"大气逆辐射\"一个术语，不写反射、散射"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先定位设问关键词\"保温\"→调受热过程链的第三段→只写逆辐射的方向与机制→用夜晚天气（多云/晴朗）收尾举例。", "stem": "（地理原卷未拍到，题干待补）本题考查：大气的保温作用——大气逆辐射把热量返还地面的机制、方向，以及云量和水汽对逆辐射强弱、夜间降温与霜冻的影响。"}, {"subject": "地理", "question_no": "14", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|14|1", "card_type": "concept", "teach": "对流层的气温规律只有一句：随高度升高而降低，平均每升高100米，气温下降约0.6℃。原因紧接着记：对流层大气的直接热源是地面，离地面越远，获得的地面辐射越少，所以越高越冷，这就是\"高处不胜寒\"、山顶积雪的原理。再分清一个例外：逆温——某层大气中气温随高度升高反而升高，多出现在晴朗无风的夜间，会阻碍空气对流、加重污染，但它不是对流层的常态。最易串的对子是平流层：平流层恰恰随高度升高而升高，因为那里有臭氧层吸收紫外线增温。做题先问自己\"题目说的是哪一层\"：对流层答递减，平流层答递增。", "why": "她选B、正解A；同卷综合题里她把对流层气温变化直接答成了\"升高\"，规律是记反了的原样复现——这类一字之差的规律要当口诀背，不能凭感觉。", "check_q": "某山山脚气温28℃、山顶10℃，按对流层气温递减率估算，两地相对高度约是多少米？", "check_a": "温差18℃，18÷0.6×100=3000米。", "steps": "1. 先定层：题干说的是对流层还是平流层——两层规律正好相反，先定层再套规律。\n2. 对流层套递减律：随高度升高气温降低，约0.6℃/100米，需要估算高度差时直接用这个率算。\n3. 原因回扣热源：对流层直接热源是地面，离地面越远得热越少，所以越高越冷。\n4. 排除例外冒充常态：逆温只是特殊天气下的局部现象，选项拿逆温当对流层普遍规律的判错；平流层增温靠臭氧吸紫外线，别串层。", "need": ["对流层气温垂直递减率（0.6℃/100 m）及成因", "平流层气温随高度升高与臭氧吸收紫外线", "逆温现象及其与常态规律的区别"], "points": ["规律点（对应综合题26(4)，5分得2分）：对流层气温随高度升高而降低，约每升高100米下降0.6℃——数值要写准", "成因点：对流层直接热源是地面，离地面越远获得的地面辐射越少，所以越高越冷", "辨析点：平流层恰好随高度升高而升高（臭氧吸收紫外线增温）——她错在两层规律串用", "例外点：逆温是局部例外现象（晴朗无风夜间多见），不是对流层常态，不能拿它否定递减规律"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先定位\"题目说的是哪一层\"——对流层答递减+地面热源，平流层答递增+臭氧，定层之后规律不许混用。", "stem": "（地理原卷未拍到，题干待补）本题考查：大气垂直分层中对流层的气温变化规律——随高度升高而降低（约0.6℃/100米）及其与平流层气温规律相反的区别，并涉及逆温现象。"}, {"subject": "地理", "question_no": "16", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|16|1", "card_type": "concept", "teach": "热力环流是大气运动最基本的形式，成因链按顺序背：地面冷热不均→空气垂直运动（受热处膨胀上升、受冷处收缩下沉）→同一水平面上产生气压差（近地面：上升处形成低压、下沉处形成高压；高空的气压高低与近地面恰好相反）→水平气流由高压流向低压，形成风。两个判断钉子：第一，看等压面——向上凸的地方是高压、向下凹的地方是低压，记\"高凸低凹\"四个字判读所有热力环流图；第二，近地面和高空的气压永远相反，近地面是低压，高空就是高压。经典应用成串记：白天海风、夜晚陆风，城市热岛环流，山谷风。做图题顺序固定：先找冷热源，再画垂直运动，再标气压，最后画风向。", "why": "她选C、正解D；热力环流图里冷热源位置一换，箭头全反，必须按\"冷热—垂直—气压—风向\"的顺序推，她做读图题时习惯凭图形眼熟下手，顺序意识缺位。", "check_q": "白天沿海地区吹海风还是陆风？用热力环流原理解释近地面风向。", "check_a": "吹海风。白天陆地增温快，空气上升，近地面形成低压；海洋相对较冷，空气下沉形成高压；近地面风由海洋（高压）吹向陆地（低压）。", "steps": "1. 读图第一步先找冷热源：地面哪里受热、哪里受冷，冷热定了，全图方向就定了。\n2. 第二步画垂直运动：受热处空气膨胀上升，受冷处收缩下沉，箭头先竖后横。\n3. 第三步标气压：近地面上升处低压、下沉处高压；高空与近地面恰好相反；等压面判读记\"高凸低凹\"。\n4. 最后画水平风向：空气由高压流向低压，海陆风、山谷风、热岛环流都按这四步推，不要凭图形眼熟直接选——她这道就是顺序缺位、箭头全反。", "need": ["热力环流的形成顺序：冷热不均→垂直运动→气压差→水平运动", "等压面判读口诀“高凸低凹”", "近地面与高空气压高低相反的关系", "热力环流的应用：海陆风、山谷风、城市热岛环流"], "points": ["起点点：热力环流始于地面冷热不均——图上先标出冷源、热源，起点标错后面全错", "垂直运动点：受热处空气膨胀上升、受冷处收缩下沉，垂直箭头方向要对", "气压点：近地面热处低压、冷处高压；高空气压与近地面相反；等压面\"高凸低凹\"判读——她的问题是凭图眼熟、箭头全反", "风向点：水平气流由高压流向低压，在近地面即为风，箭头从高压指向低压收尾"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题是图题：顺序钉死四步——找冷热源→画垂直运动→标气压高低→最后才画水平风向；任何一步跳过都会连环错。", "stem": "（地理原卷未拍到，题干待补）本题考查：热力环流图的判读——根据地面冷热源位置推断空气垂直运动方向、近地面与高空的气压高低和水平风向，以及等压面“高凸低凹”的判读。"}, {"subject": "地理", "question_no": "24", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|24|1", "card_type": "concept", "teach": "我国年太阳辐射总量的分布记两句：西多东少、南多北少——但两个方向的原因完全不同，这是出题核心。东西差异的主因是天气状况：西部内陆降水少、晴天多，太阳辐射强；东部季风区阴雨天多、云量大，削弱作用强。南北差异的主因是纬度因素：纬度越低，正午太阳高度角越大，获得的太阳辐射越多。再钉两个极值：最丰富的是青藏高原（海拔高、空气稀薄、晴天多），最贫乏的是四川盆地（阴雨、云雾天多）。做题配对口诀：看到\"东西差异\"先想降水和晴天数，看到\"南北差异\"先想纬度；海拔只是青藏高原这一个点的原因，不能拿来解释全国的东西差异。", "why": "她选B、正解A；同卷28(1)她把太阳辐射东西差异的主因误答为海拔高度，与青藏高原的思路串了题，这道选择题极可能错在同一个原因配对上。", "check_q": "我国太阳辐射总量最丰富和最贫乏的地区分别是哪里？主要原因各是什么？", "check_a": "最丰富：青藏高原（海拔高、空气稀薄、晴天多，削弱作用弱）；最贫乏：四川盆地（阴雨、云雾天多，大气削弱作用强）。", "steps": "1. 先看设问问的是哪个方向的差异：东西差异还是南北差异——两个方向的原因不能混用。\n2. 东西配天气：西部内陆降水少、晴天多→辐射强；东部季风区阴雨多、云量大→削弱强。南北配纬度：纬度低、正午太阳高度角大→辐射多。\n3. 钉两个极值点：最丰富青藏高原（海拔高、空气稀薄、晴天多），最贫乏四川盆地（阴雨云雾多）。\n4. 排雷：海拔只解释青藏高原这一个点，选项拿海拔解释全国东西差异的判错——她大题28(1)正是把东西主因误答成海拔。", "need": ["我国年太阳辐射总量分布规律：西多东少、南多北少", "影响太阳辐射分布的因素：纬度、天气状况、海拔", "青藏高原辐射最强与四川盆地最贫乏的原因"], "points": ["总格局点（对应综合题28(1)，8分得6分）：我国年太阳辐射总量西多东少、南多北少——格局句先写", "东西归因点：东西差异主因是天气状况——西部内陆降水少、晴天多；东部季风区阴雨多、云量大、削弱强（答成纬度即错位）", "南北归因点：南北差异主因是纬度——纬度低、正午太阳高度角大、辐射多", "极值点：最丰富青藏高原（海拔高、空气稀薄、晴天多），最贫乏四川盆地（阴雨云雾多）——海拔只解释青藏这一个极值点，不能拿来解释全国东西差异；她得6/8，丢分在归因细节"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先写格局（东西、南北各一句）→再分方向归因（东西看天气、南北看纬度，两套原因不许混）→最后钉两个极值点收尾。", "stem": "（地理原卷未拍到，题干待补）本题考查：我国年太阳辐射总量的空间分布差异及成因——东西差异主要由天气状况（降水、晴天数）造成、南北差异主要由纬度造成，并涉及青藏高原（最丰富）与四川盆地（最贫乏）两个极值区。"}, {"subject": "地理", "question_no": "25", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|25|1", "card_type": "concept", "teach": "青藏高原是这张卷最值得背透的辨析：同一个地方，太阳辐射最强，气温却偏低，靠的是两个方向相反的作用。先看削弱：高原海拔高、空气稀薄，水汽和尘埃少，晴天又多，太阳辐射被削弱得少，所以到达地面的辐射强。再看保温：空气稀薄意味着吸收地面辐射的能力差，大气逆辐射也弱，地面热量容易散失，所以气温低。结论句要记牢：辐射强弱看\"削弱\"，气温高低看\"保温\"，两个问题用两套机制回答。她在综合题里写过\"太阳辐射强度与气温成反比\"——这就是把两套机制混成一句话的错误表述；凡看到\"辐射强所以气温低\"\"成反比\"这类结论句，先判错，再回到削弱与保温分头找原因。", "why": "她选C、正解D；同卷28(2)这道大题她得0分，原话就是把削弱作用和保温作用混为一谈、得出\"成反比\"的错误结论，这道选择题是同一病根的复现。", "check_q": "\"太阳辐射越强的地方气温就越高\"为什么不对？用青藏高原说明。", "check_a": "不对。青藏高原太阳辐射最强，但空气稀薄、大气逆辐射弱、保温作用差，气温反而偏低。辐射强弱由削弱作用决定，气温高低还取决于保温作用，两者不是一回事。", "steps": "1. 先把问题拆成两个：辐射为什么强？气温为什么低？两问用两套机制，禁止一句话带过。\n2. 辐射强走\"削弱\"：青藏高原海拔高、空气稀薄、水汽尘埃少、晴天多，太阳辐射被削弱得少，到达地面多。\n3. 气温低走\"保温\"：空气稀薄吸收地面辐射能力差，大气逆辐射弱，地面热量散失快，所以气温低。\n4. 排雷结论句：凡\"辐射强所以气温低\"\"辐射与气温成反比\"这类把两套机制混成因果的表述，先判错，再回到削弱与保温分头找原因——她大题28(2)就是这样得0分的。", "need": ["大气削弱作用与海拔、空气稀薄程度的关系", "大气保温作用与逆辐射：空气稀薄为何保温差", "青藏高原“辐射强、气温低”的成因辨析"], "points": ["削弱面点（对应综合题28(2)，6分得0分）：青藏高原海拔高、空气稀薄、水汽尘埃少、晴天多→太阳辐射被削弱少→到达地面的辐射强", "保温面点：空气稀薄→吸收地面辐射能力差→大气逆辐射弱→地面热量易散失→气温低", "表述红线点：严禁用\"太阳辐射强度与气温成反比\"这类混谈句——她在综合题里正是写了这句，辐射与气温两套机制混成一句，整问0分"], "frame": "地理综合题统一落笔顺序：第一步定位（先定题目问的区域、图层或时段，把对象钉死）；第二步调原理链（把原理按环节顺序默出来，如受热过程三段链）；第三步逐环节落材料（每个环节对一句材料/图中信息，不跳步）；第四步结论回设问（用设问的关键词收尾）。本题具体化：先把设问拆成两问——\"辐射为什么强\"走削弱线、\"气温为什么低\"走保温线，两条线分开写、最后不许合并成一句因果。", "stem": "（地理原卷未拍到，题干待补）本题考查：青藏高原“太阳辐射强而气温低”的成因辨析——辐射强用削弱作用弱（空气稀薄、晴天多）解释，气温低用保温作用弱（大气逆辐射弱）解释，两套机制分开作答。"}, {"subject": "政治", "question_no": "9", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 C，无题干无解析", "note": "", "key": "政治|9|1", "card_type": "concept", "teach": "教材原话：1919年五四运动标志着中国新民主主义革命的开端。判断\"开端\"要看三点新变化：第一，工人阶级开始以独立的姿态登上政治舞台，成为运动后期的主力；第二，五四运动促进了马克思主义在中国的传播，并开始同中国工人运动相结合；第三，先进知识分子开始走同工农相结合的道路。两个易混点要分清：一是时间，五四运动在1919年，发生在1921年建党之前，领导者是先进青年知识分子，还不是共产党；二是\"开端\"问的是新变化从哪一年出现，不是党哪一年成立。把开端记成1921年（建党），是这类题最常见的坑。", "why": "原题题干未留存，但紧挨着的第10题她把新旧民主主义革命的范畴也判错了，说明\"五四开端\"这一段的时间锚和新变化她没有成串记牢。", "check_q": "新民主主义革命的开端是哪个事件、发生在哪一年？", "check_a": "1919年五四运动。它使工人阶级登上政治舞台、马克思主义开始与工人运动相结合，革命面貌从此不同于旧民主主义革命。", "steps": "1. 先看设问落点：问的是\"开端/标志\"，先在时间轴上定位——候选年份只有1919和1921两个，先别急着选。\n2. 抠主体：1919年五四运动的领导者是先进青年知识分子，那时共产党还没成立；1921年是建党，建党不是新民主主义革命的\"开端事件\"。\n3. 逐项验\"新变化\"：工人阶级是否登上政治舞台、马克思主义是否开始与工人运动相结合、知识分子是否走工农相结合道路——三条都指向五四。\n4. 与教材原话对表：\"1919年五四运动标志着中国新民主主义革命的开端\"，原话对得上才落笔。", "need": ["五四运动的意义：新民主主义革命的开端与三大新变化", "五四运动（1919）与中国共产党成立（1921）的先后关系", "新旧民主主义革命的分界线是五四运动"], "stem": "9. 某同学绘制了一条1921年至1949年标志性事件数轴图。对此，下列理解正确的有（ ）\n【数轴】1921年 中国共产党成立 → 1927年 南昌起义 → 1936年 西安事变 → 1945年 中共七大 → 1949年 新中国成立\n①共产党是各国工人政党中始终起推动作用的部分\n②共产党领导中国人民积极探索社会主义建设新模式\n③共产党的领导是新民主主义革命取得胜利的重要因素\n④武装斗争是新民主主义革命取得胜利的法宝之一\nA. ①②　B. ①③　C. ③④　D. ②④"}, {"subject": "政治", "question_no": "10", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 D，无题干无解析", "note": "", "key": "政治|10|1", "card_type": "concept", "teach": "新旧民主主义革命的分界线是五四运动，区别要成对记四组：领导阶级——旧：资产阶级；新：无产阶级（通过中国共产党领导）。所属范畴——旧民主主义革命属于资产阶级革命的范畴，是世界资产阶级革命的一部分；新民主主义革命属于无产阶级革命的范畴，是世界无产阶级社会主义革命的一部分。老师在她卷子上批的\"旧：资产阶级\"点的就是这一组。革命前途——旧：建立资产阶级共和国、走资本主义道路；新：前途是社会主义。革命任务相同——都反帝反封建，这是两者唯一的共同点，也是干扰项最爱做文章的地方：任务相同不等于性质相同，判断性质先看领导阶级。", "why": "她在\"新旧民主主义革命均属于世界无产阶级革命的一部分\"这类表述上栽了跟头，只记住了任务相同，没抓住领导阶级这个根本分界。", "check_q": "\"新旧民主主义革命都属于世界无产阶级革命的一部分\"——这句话错在哪？", "check_a": "旧民主主义革命由资产阶级领导，属于资产阶级革命范畴，是世界资产阶级革命的一部分；只有新民主主义革命由无产阶级领导，属于世界无产阶级革命的一部分。", "steps": "1. 先看设问：两个概念对比，先找根本区别——领导阶级，其余维度都跟着它走。\n2. 逐组对表：领导（资产阶级 vs 无产阶级）、所属范畴（资产阶级革命 vs 无产阶级革命）、前途（资本主义 vs 社会主义）、任务（同为反帝反封建）。\n3. 重点防偷换：看到\"任务相同\"就想推\"性质相同\"的表述直接判错；看到\"均属于世界无产阶级革命\"先查旧民主主义革命那一半——它属于资产阶级革命范畴。\n4. 老师批注\"旧：资产阶级\"就是锚点：每组对比先写领导阶级，再展开其他三组。", "need": ["新旧民主主义革命的领导阶级区别", "新旧民主主义革命所属革命范畴的区别", "新旧民主主义革命的前途区别与相同任务（反帝反封建）"], "stem": "10. 2019年是五四运动爆发100周年，五四运动是中国新旧民主主义革命的分界线。关于新旧民主主义革命下列判断错误的是（ ）\nA. 新旧民主主义革命的共同任务是推翻帝国主义和本国封建势力\nB. 区分新旧民主主义革命的主要依据是领导阶级的阶级属性\nC. 新旧民主主义革命，不同的领导阶级决定中国两种不同的发展方向\nD. 新旧民主主义革命均属于世界无产阶级革命的一部分"}, {"subject": "政治", "question_no": "15", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 D，无题干无解析", "note": "", "stem": "我国的改革开放创造了发展奇迹，今后还要以更大气魄深化改革、扩大开放，续写更多\"春天的故事\"。我国的改革开放不是一蹴而就的。下列关于我国改革开放的进程，排序正确的是（ ）①我国成功加入世界贸易组织（2001年）②设立中国（上海）自由贸易试验区（2013年）③推行家庭联产承包责任制（1978年起）④明确实施社会主义市场经济体制（1992年）", "paper_cause": "**记忆缺失**——四个大事件的时间顺序没记牢，尤其\"确立社会主义市场经济体制（1992）\"与\"入世（2001）\"的先后", "key": "政治|15|1", "card_type": "redo", "options": {"A": "①②③④", "B": "③①④②", "C": "④③①②", "D": "③④①②"}, "teach": "排序题不靠感觉，给每个事件钉一个年份锚：③1978年——改革从农村起步，家庭联产承包责任制是改革开放的开端标志；④1992年——党的十四大明确提出建立社会主义市场经济体制的目标；①2001年——加入世界贸易组织，对外开放进入新阶段；②2013年——上海自贸试验区设立，是全面深化改革开放的新动作。最容易对调的是④和①：记住\"先定自家的市场经济体制（1992），再融入世界市场（2001）\"。四个锚连成一句口诀：78承包、92市场、01入世、13自贸，排任何改革开放时序题都按这条链对号。", "why": "她把1992年确立市场经济体制和2001年入世的先后记反了，四个事件只记了大概，没有逐个钉住年份。", "check_q": "按时间先后排列：设立上海自贸试验区、确立社会主义市场经济体制目标、推行家庭联产承包责任制、加入世贸组织。", "check_a": "家庭联产承包责任制（1978）→确立社会主义市场经济体制目标（1992）→加入世贸组织（2001）→设立上海自贸试验区（2013）。", "steps": "1. 排序题第一步：给四个事件逐个钉年份锚——③联产承包1978、④市场经济体制1992、①入世2001、②上海自贸区2013，锚钉完顺序自然出来。\n2. 先定头尾：最早必是1978年的③，最晚必是2013年的②，先排除头尾不对的选项。\n3. 专辨最易对调的一对：先在国内确立市场经济体制（1992），之后才加入世贸融入世界市场（2001）——\"先定自家体制，再进世界市场\"。\n4. 把锚链\"78承包、92市场、01入世、13自贸\"与剩余选项逐字对照再落笔。", "need": ["家庭联产承包责任制与改革开放起步（1978）", "社会主义市场经济体制目标的确立（1992年党的十四大）", "加入世界贸易组织（2001）与上海自贸试验区设立（2013）"]}, {"subject": "政治", "question_no": "17", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 C，无题干无解析", "note": "", "stem": "习近平总书记指出，尽管我们所处的时代同马克思所处的时代相比发生了巨大而深刻的变化，但从世界社会主义500年的大视野来看，我们依然处在马克思主义所指明的历史时代。这表明（ ）①科学社会主义是人类社会的终极真理 ②（原卷字迹不清） ③科学社会主义依然具有真理的光芒和改造现实的力量 ④中国特色社会主义是科学社会主义在中国的实践与发展", "paper_cause": "**概念不清**——没识破\"终极真理\"这类绝对化表述的坑", "key": "政治|17|1", "card_type": "redo", "options": {"A": "①②", "B": "①④", "C": "②③", "D": "③④"}, "teach": "组合选择题的固定打法：先逐项判断、杀绝对化表述，再对组合。①\"终极真理\"是经典错误项——科学社会主义是科学真理，但它随着实践不断丰富和发展，不存在一成不变的\"终极\"形态；凡出现\"终极、永恒不变、彻底解决一切\"这类把话说死的词，先划掉，含①的A、B随之排除，只在C、D里选。再看题干指向：题干强调\"时代变了，但我们依然处在马克思主义所指明的历史时代\"，扣住\"依然\"二字——资本主义基本矛盾没有变，所以③\"依然具有真理的光芒和改造现实的力量\"正是对题干的回应。记住顺序：先排绝对化、再对题干指向、最后对组合，不要从组合倒推。", "why": "她没识破①\"终极真理\"的绝对化陷阱，第一步逐项判断就漏了，把含错误项的组合选了进去。", "check_q": "判断正误：\"科学社会主义揭示了人类社会发展的最终规律，是不可超越的终极真理。\"", "check_a": "错。科学社会主义是发展的、开放的真理，随着实践深化不断丰富，不存在\"终极真理\"；这类把话说死的绝对化表述在政治选择题里基本都是错误项。", "steps": "1. 组合题铁律：先逐项判断，暂时不看组合。\n2. 第一刀先杀绝对化：①\"终极真理\"把话说死——科学社会主义是发展的真理，没有\"终极\"形态，①错，含①的组合（A、B）全部排除。\n3. 回题干抠指向：题干强调\"时代变了，但依然处在马克思主义所指明的历史时代\"，扣住\"依然\"——对应③\"依然具有真理的光芒和改造现实的力量\"。\n4. 在剩下的C、D之间用③定案，再回头验④是否与题干无关（④本身对，但组合须由入选项共同成立，③④与②③按题干指向取舍）。", "need": ["科学社会主义是发展的、开放的真理（不存在“终极真理”）", "教材标志性表述：“依然处在马克思主义所指明的历史时代”", "中国特色社会主义是科学社会主义在中国的实践与发展"]}, {"subject": "政治", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "B", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 B，无题干无解析", "note": "", "key": "政治|20|1", "card_type": "concept", "teach": "十一届三中全会的核心动词是\"重新确立\"，不是\"首次确立\"。教材表述：这次全会重新确立了马克思主义的思想路线、政治路线和组织路线——这些路线本来就有，是被\"文化大革命\"破坏后又恢复的，只能说\"重新\"，说\"首次\"就错。再并排记三件大事：一是作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；二是实现了新中国成立以来党的历史上具有深远意义的伟大转折；三是开启了改革开放和社会主义现代化建设新时期。三个动词各配各的对象：路线是\"重新确立\"，工作中心是\"转移\"，历史地位是\"伟大转折\"，出题人最爱把这三个动词互相换位，换一个就错。", "why": "她没分清\"首次\"和\"重新\"——\"文革\"后恢复原有正确路线只能叫重新确立，这正是出题人埋的一字之差。", "check_q": "\"十一届三中全会首次确立了马克思主义的思想路线\"错在哪里？准确表述是什么？", "check_a": "错在\"首次\"。马克思主义思想路线本来就存在，是十一届三中全会\"重新确立\"了它（连同政治路线、组织路线）。", "steps": "1. 先看设问里的动词：出现\"确立\"先问一句——是\"首次\"还是\"重新\"？这是本题的题眼。\n2. 回想背景：马克思主义的思想、政治、组织路线本来就有，是被\"文革\"破坏后在十一届三中全会上恢复的，本来有过的只能\"重新确立\"。\n3. 动词配对自查：路线→重新确立；工作中心→转移到经济建设；历史地位→伟大转折；新时期→开启。选项把动词换位的，一律判错。\n4. 最后与教材原话整句对表，对得上才选。", "need": ["十一届三中全会的内容：重新确立马克思主义思想路线、政治路线、组织路线", "十一届三中全会的历史地位：伟大转折、开启改革开放和社会主义现代化建设新时期", "“首次确立”与“重新确立”的辨析"], "stem": "20. 回顾党的历史，三中全会已成为改革和发展的代名词。改革开放40多年来，中国共产党已召开了10次三中全会，改革与发展始终是贯穿其中的不变主题。其中，党的十一届三中全会（ ）\n①实现党和国家工作中心战略转移\n②开启了社会主义革命和建设新时期\n③首次确立了马克思主义的思想路线、政治路线和组织路线\n④实现了新中国成立以来党的历史上具有深远意义的伟大转折\nA. ①②　B. ①④　C. ②③　D. ③④"}, {"subject": "政治", "question_no": "21", "full_score": 10.0, "got_score": 4.0, "student_answer": "（手写，辨认见下）", "std_answer": "①是历史进步(1)+②生产关系适应生产力规律/判断标准(3)+③原始社会末期阻碍生产力、奴隶制组织大协作(3)+④金属工具/城市/脑体分工(3)", "error_type": "表述不规范/知识盲区", "knowledge_point": "奴隶社会代替原始社会的进步性。答出\"历史进步\"+\"生产力被束缚/相适应\"等零散表述；缺\"金属工具、城市出现、脑体分工\"等具体史实得分点，未展开论证", "note": "", "key": "政治|21|1", "card_type": "concept", "teach": "材料题答法固定三段：先写观点句，再写规律句，最后落到具体史实论据——她丢分最狠的正是第三段。本题得分点清单（10分）：①观点（1分）：奴隶社会代替原始社会是历史的进步；②规律（3分）：判断社会形态更替是进步还是倒退，标准是生产关系是否适应生产力发展要求，原始社会末期的生产关系已经束缚了生产力；③奴隶制解放生产力（3分）：奴隶主可以组织大规模协作劳动，生产规模扩大；④具体表现（3分）：金属工具广泛使用、城市出现、脑体分工出现，为文化繁荣创造条件。组织答案时按\"观点句+教材规律表述+材料关键词/史实\"逐点排，老师扫关键词给分：只写观点和规律、不落史实，最多拿到4分左右。", "why": "她整段只写了\"是历史进步\"和\"生产力被束缚/相适应\"的零散原话，金属工具、城市、脑体分工一个都没写，论证空转，10分丢了6分。", "check_q": "论证\"奴隶社会代替原始社会是进步\"，必须写出的两个具体史实是什么？", "check_a": "示例：金属工具的广泛使用、城市的出现（或脑体分工的出现）。只写观点和规律不落史实，拿不到论据分。", "steps": "1. 先读设问定角度：问\"为什么是进步\"，先定判断标准——生产关系是否适应生产力发展要求，观点句从标准里出。\n2. 动笔前在草稿上列三段骨架：观点（是进步）→规律（判断标准+原始社会末期已束缚生产力）→史实（奴隶制如何解放生产力）。\n3. 读材料划关键词，并回想具体史实清单：金属工具广泛使用、城市出现、脑体分工——论据段必须落到这些具体词，只写规律拿不到论据分。\n4. 逐点组装：每点一句观点句+教材规律表述+一个史实，写完自查三段齐不齐、第三段有没有空转。", "need": ["社会形态更替进步性的判断标准：生产关系是否适应生产力发展要求", "奴隶制解放生产力的具体表现：金属工具、城市、脑体分工", "原始社会末期生产关系束缚生产力的表现"], "points": ["观点点（约1分）：明确表态\"奴隶社会代替原始社会是历史的进步\"——【她答到了，有这层意思】", "规律点（约3分）：写出判断标准——一种社会形态代替另一种是否进步，看生产关系是否适应生产力发展要求；原始社会末期生产关系已经束缚生产力——【她只零散写了\"生产力被束缚/相适应\"，没组装成完整的判断标准句，这是丢分点之一】", "史实论据点（约3分）：奴隶制解放生产力的表现——奴隶主能组织大规模协作劳动、生产规模扩大——【缺】", "史实论据点（约3分）：金属工具广泛使用、城市出现、脑体分工出现，为文化繁荣创造条件——【全缺，这是本题丢分的主体：她得4/10，丢的6分基本都在这段具体史实上】"], "frame": "证明型材料题三段式：第一段只写观点句（先表态：是进步）；第二段写规律句（判断标准=生产关系是否适应生产力，一句教材表述说完）；第三段集中堆史实论据（协作劳动、金属工具、城市、脑体分工逐个名词点出）。顺序不能乱：只写观点和规律不落史实，最多拿4分左右。", "stem": "第21题 材料：学生甲、乙关于“奴隶社会代替原始社会是进步还是倒退”的讨论。\n设问：判断奴隶社会代替原始社会是历史的进步还是倒退，运用生产力与生产关系的知识说明理由。（10分）"}, {"subject": "政治", "question_no": "22", "full_score": 8.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "①四个\"彻底结束\"+伟大飞跃(3)+②过渡前提/改变发展方向/展示前景(3)+③东方战线/世界政治力量对比/鼓舞被压迫民族(2)", "error_type": "知识盲区/表述不规范", "knowledge_point": "新中国成立的意义。未用关键词（彻底结束、半殖民地半封建、人民民主、过渡前提、东方战线），表述空泛", "note": "", "key": "政治|22|1", "card_type": "concept", "teach": "\"意义类\"材料题按\"对内—过渡—对外\"三层组织，每层一句观点句加教材原词。本题得分点清单（8分）：①\"四个彻底结束\"（3分）——彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，彻底结束了极少数剥削者统治广大劳动人民的历史；中国人民从此站起来了，这是中华民族发展史上的一次伟大飞跃。②过渡前提（3分）——为从新民主主义向社会主义过渡创造了前提条件，中国历史进入新纪元，发展方向就此改变。③国际意义（2分）——壮大了世界和平、民主和社会主义的力量，鼓舞了世界被压迫民族和被压迫人民争取解放的斗争。注意：\"彻底结束\"\"站起来了\"这些原词本身就是得分点，不要用自己的话改写。", "why": "她写了一大段\"为世界作出了贡献、中国摆脱了……\"的空泛表述，\"四个彻底结束\"一个都没写出来，8分只拿到2分。", "check_q": "\"四个彻底结束\"的第一个和最后一个分别是什么？", "check_a": "第一个：彻底结束了旧中国半殖民地半封建社会的历史；最后一个：彻底结束了极少数剥削者统治广大劳动人民的历史。", "steps": "1. 先读设问定范围：问\"意义\"，按\"对内—过渡—对外\"三层搭框架，每层预留一个得分点。\n2. 对内层先默教材原词：\"四个彻底结束\"逐字写出（半殖民地半封建、一盘散沙、不平等条约与特权、剥削者统治），原词本身就是分，禁止用自己的话改写。\n3. 过渡层落关键词：为新民主主义向社会主义过渡创造前提条件、中国历史进入新纪元。\n4. 对外层补国际意义：壮大世界和平、民主和社会主义力量，鼓舞被压迫民族解放斗争。\n5. 写完自查：三层是否齐全，\"彻底结束\"\"站起来了\"等原词有没有被空泛表述替换掉。", "need": ["新中国成立的意义之一：“四个彻底结束”完整表述", "新中国成立与向社会主义过渡的前提条件", "新中国成立的国际意义：壮大世界和平、民主和社会主义力量"], "points": ["核心表述点（约3分）：\"四个彻底结束\"逐个写全——彻底结束旧中国半殖民地半封建社会的历史、彻底结束旧中国一盘散沙的局面、彻底废除列强强加的不平等条约和帝国主义在华一切特权、彻底结束极少数剥削者统治广大劳动人民的历史；外加\"中国人民从此站起来了\"——【全缺：她一个关键词都没用，只写空泛表述，这是本题只得2/8的主因】", "过渡前提点（约3分）：新中国的成立为从新民主主义向社会主义过渡创造了前提条件，中国历史进入新纪元——【缺】", "国际意义点（约2分）：壮大了世界和平、民主和社会主义的力量，鼓舞了世界被压迫民族和被压迫人民争取解放的斗争——【缺】"], "frame": "意义类材料题按\"对内—过渡—对外\"三层推进：每层先一句观点句起头（对国家/对过渡/对世界），再用教材原词填充。铁规矩：教材里的标志性原词（彻底结束、站起来了、前提条件）本身就是得分点，绝不用自己的话改写或概括。", "stem": "第22题 材料：1949年10月1日开国大典。\n设问：结合材料，运用《中国特色社会主义》的知识，谈谈为什么说中华人民共和国的诞生是20世纪的伟大历史事件。（8分）"}, {"subject": "政治", "question_no": "23", "full_score": 10.0, "got_score": 5.0, "student_answer": "（手写，辨认见下）", "std_answer": "①四个面貌+三个飞跃(4)+②必由之路/关键一招(4)+③只有进行时/活力之源(2)", "error_type": "知识盲区（部分）", "knowledge_point": "改革开放的意义。答出\"四个面貌/三个飞跃\"和\"活力之源\"；缺\"必由之路/关键一招\"表述", "note": "", "key": "政治|23|1", "card_type": "concept", "teach": "问\"改革开放为什么是活力之源\"，答案从教材给改革开放的定位表述里组织。得分点清单（10分）：①改变的面貌（4分）：改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌、中华文明的面貌；②实现的飞跃（并入上项）：中华民族迎来了从站起来、富起来到强起来的伟大飞跃，中国人民迎来了从温饱不足到小康富裕的伟大飞跃；③定位表述（4分）：改革开放是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现中华民族伟大复兴的关键一招；④回扣设问（2分）：改革开放只有进行时、没有完成时，是当代中国发展进步的活力之源。答这类题先把教材的\"定位句\"整句默出来再展开——定位句就是分值最重的那几分。", "why": "她写出了\"四个面貌/三个飞跃\"和\"活力之源\"，却漏写了分值最重的\"必由之路、关键一招\"这组定位表述，骨架缺了一根主梁，10分只得5分。", "check_q": "教材给改革开放的两个定位表述：\"坚持和发展中国特色社会主义的＿＿\"和\"决定当代中国命运的＿＿\"。", "check_a": "\"必由之路\"；\"关键一招\"。", "steps": "1. 先读设问扣问法：问\"为什么是活力之源\"，这类题先默定位句再展开——定位句分值最重。\n2. 草稿先列骨架：定位表述（必由之路、关键一招）→改变与飞跃（四个面貌、三个飞跃）→回扣设问（只有进行时、活力之源）。\n3. 逐点组装成段：每点先写教材原句再略展开，不要先写感想把原句挤掉。\n4. 自查一遍：\"必由之路\"\"关键一招\"两个定位词在不在——她上次正是漏了这一根主梁丢了4分。", "need": ["教材标志性表述：改革开放是坚持和发展中国特色社会主义的必由之路、决定当代中国命运的关键一招", "改革开放改变的“四个面貌”与实现的“三个飞跃”", "改革开放只有进行时、没有完成时：当代中国发展进步的活力之源"], "points": ["改变面貌点（约4分）：改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌、中华文明的面貌（民族从站起来、富起来到强起来的飞跃，人民从温饱不足到小康富裕的飞跃可并入此点）——【她答到了，\"四个面貌/飞跃\"都有】", "定位表述点（约4分）：改革开放是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现中华民族伟大复兴的关键一招——【全缺：这是本题分值最重的一块，她得5/10，丢分主要丢在这里】", "回扣设问点（约2分）：改革开放只有进行时、没有完成时，是当代中国发展进步的活力之源——【她答到了\"活力之源\"】"], "frame": "定位型材料题顺序：先把教材\"定位句\"整句默出来打头（必由之路+关键一招，这是主梁）→再展开改变与飞跃（四个面貌、两个飞跃）→末句用\"活力之源\"回扣设问收尾。她这次是中间有、两头空：定位句缺失、回扣虽有但主梁没立住。", "stem": "第23题 材料：2023年习近平在广东考察（前海、渔民村、北站社区、光启研究院）。\n设问：运用《中国特色社会主义》的知识，说明改革开放为什么是当代中国发展进步的活力之源。（10分）"}, {"subject": "政治", "question_no": "24", "full_score": 12.0, "got_score": 3.0, "student_answer": "（手写，辨认见下）", "std_answer": "①资本主义道路走不通(3)+②党的诞生与新民主主义革命胜利(3)+③新中国成立改变发展方向(3)+④社会主义改造完成(3)+总结句", "error_type": "知识盲区/表述不规范", "knowledge_point": "只有社会主义能救中国。只有\"资本主义走不通\"+\"一化三改/社会主义改造\"+总结句碎片；缺\"党的诞生与新民主主义革命胜利\"\"新中国成立改变发展方向\"两大得分块", "note": "", "key": "政治|24|1", "card_type": "concept", "teach": "\"只有社会主义才能救中国\"是证明型材料题，用四段骨架答，每段一句观点句加教材关键词：①旧路走不通（3分）——农民阶级、地主阶级、资产阶级改良派和革命派的探索都失败了，资本主义道路在中国走不通；②党找到新路（3分）——中国共产党的诞生使中国革命面貌焕然一新，党领导人民取得新民主主义革命的胜利；③新中国改变方向（3分）——中华人民共和国的成立实现了民族独立、人民解放，为国家富强、人民幸福和向社会主义过渡创造了前提，中国的发展方向从此根本改变；④改造建制度（3分）——社会主义改造完成，确立了社会主义基本制度。最后加一句总结回扣题干。动笔前先在草稿上列①②③④四个小标题再填内容，就不会写成词语串烧。", "why": "她只写了\"资本主义走不通\"和\"一化三改\"两个碎片，中间\"党的诞生与革命胜利\"\"新中国成立改变方向\"两大段全空，12分只得3分。", "check_q": "用四段骨架复述\"只有社会主义才能救中国\"的论证顺序（只说每段主题词）。", "check_a": "①资本主义道路走不通→②共产党诞生、新民主主义革命胜利→③新中国成立、改变发展方向→④社会主义改造完成、确立社会主义制度。", "steps": "1. 先读设问定题型：\"只有……才能……\"是证明型材料题，用历史线索分段论证，不能写成词语串烧。\n2. 动笔前在草稿上列四个小标题：①旧路走不通→②党找到新路→③新中国改变方向→④改造确立制度，标题列齐再填内容。\n3. 每段一句观点句+教材关键词：①农民、地主、资产阶级改良派与革命派探索都失败；②党的诞生使革命面貌焕然一新、新民主主义革命胜利；③新中国成立实现民族独立人民解放、创造过渡前提；④社会主义改造完成、确立社会主义基本制度。\n4. 末尾加总结句回扣题干，自查四段有没有整段缺失——她上次②③两段全空，12分只得3分。", "need": ["近代中国各阶级探索的失败与资本主义道路走不通", "中国共产党的诞生与新民主主义革命的胜利", "中华人民共和国成立与发展方向的根本改变", "社会主义改造的完成与社会主义基本制度的确立"], "points": ["旧路走不通（约3分）：农民阶级、地主阶级、资产阶级改良派和革命派的探索都失败了，资本主义道路在中国走不通——【只部分答到：她只有\"资本主义走不通\"一句，四个阶级的探索主体没列出】", "党找到新路（约3分）：中国共产党的诞生使中国革命面貌焕然一新，党领导人民取得新民主主义革命的胜利——【全缺，整段没写】", "新中国改变方向（约3分）：中华人民共和国的成立实现了民族独立、人民解放，为国家富强、人民幸福和向社会主义过渡创造了前提，中国的发展方向从此根本改变——【全缺，整段没写】", "改造建制度（约3分）：社会主义改造完成，确立了社会主义基本制度——【只部分答到：有\"一化三改/社会主义改造\"碎片，没有组装成完整观点句】", "（另）总结回扣句：末尾一句回扣题干\"只有社会主义才能救中国\"——【她有总结句碎片，但前面两大段缺失，总结无根】"], "frame": "证明型材料题四段骨架，顺序固定：旧路失败→党的领导→新中国成立→社会主义改造。动笔前先在草稿上列①②③④四个小标题，再逐段填\"观点句+教材关键词\"，最后加总结句回扣题干。她得3/12就是因为跳过了列提纲这一步，中段两块整段漏写。", "stem": "第24题 材料：近代仁人志士探索失败、中国共产党成立并建立新中国、过渡时期“一化三改”总路线。\n设问：运用《中国特色社会主义》相关知识，回答为什么说只有社会主义才能救中国。（12分）"}, {"subject": "数学", "question_no": "4", "full_score": 5.0, "got_score": 0.0, "student_answer": "在 B 与 C 之间反复涂改（先写 B 划掉，又改 C），两个都是错的；旁边虽写了\"x−2≠0\"的提醒，仍未选对。", "std_answer": "D。分式不等式要求分母不为零，x=2 必须排除：分子零点 x=1 可取，分母零点 x=2 不可取，故解集为 x≤1 或 x>2。B 错在把 x=2 包含进去，C 则整体方向都错。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "分式不等式的解法（分母不为零、零点取舍）", "note": "错因：概念不清——\"≥0 时分母也不能为零\"这条规则没有落实，在两个错误选项间摇摆。", "stem": "不等式 (x−1)/(x−2) ≥ 0 的解集为（ ）", "paper_cause": "概念不清——\"≥0 时分母也不能为零\"这条规则没有落实，在两个错误选项间摇摆。", "key": "数学|4|1", "card_type": "redo", "options": {"A": "{x | 1≤x≤2}", "B": "{x | x≤1 或 x≥2}", "C": "{x | 1≤x<2}", "D": "{x | x>2 或 x≤1}"}, "teach": "分式不等式有一条压倒一切的铁律：分母永远不能为零，所以 x=2 无论不等号朝哪、带不带等号都必须排除；而分子可以为零，x=1 可以取。标准解法：把分子零点 1 和分母零点 2 标在数轴上，分成三段逐段试号，正负一目了然，得 x≤1 或 x>2，即 D。B 错就错在写了 x≥2 把 2 包含进去。她其实在旁边写了 x−2≠0 的提醒，却没用上。检验习惯：解集出来后把分母零点代回去自查，凡是包含它的选项直接划掉。", "why": "虽然写了 x≠2 的提醒，最后还是在包含 x=2 的错误选项上摇摆，规则没落实到选项。", "check_q": "不等式 (x+1)/(x−3) ≥ 0 的解集中，x=3 能取吗？x=−1 能取吗？", "check_a": "x=3 不能取（分母为零无意义）；x=−1 能取（分子为零，不等式成立）。", "steps": "1. 先立铁律：分母不能为零，x=2 永远排除；分子可以为零，x=1 可以取到。\n2. 找出两个零点：分子零点 1、分母零点 2，标在数轴上分成三段。\n3. 逐段试号（或穿根）：x>2 两因子同正、1<x<2 为负、x<1 两负得正，结合 ≥0 取正的段。\n4. 写出解集 {x|x≤1 或 x>2} 对照选项选 D；最后把 x=2 代回自查，凡解集包含 2 的选项（如 B）直接排除。", "need": ["分式不等式的解法（等价转化且分母不为零）", "数轴标根分段试号（穿根法）", "解集端点取舍：分子零点可取、分母零点不可取"]}, {"subject": "数学", "question_no": "6", "full_score": 5.0, "got_score": 0.0, "student_answer": "选 A，卷面红笔订正为 B。", "std_answer": "B。p 的范围 (0,2) 是 q 的范围 (−1,3) 的子集，由 p 可以推出 q，但由 q 推不出 p。题目问的是\"q 是 p 的什么条件\"：q 是 p 的必要不充分条件。她把充分、必要的方向答反了。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "充分条件与必要条件的判断（小范围推出大范围）", "note": "错因：概念不清——充分/必要方向感反了，没有抓住\"谁推出谁\"和\"问的是谁是谁的条件\"。", "stem": "已知 p：0<x<2，q：−1<x<3，则 q 是 p 的（ ）", "paper_cause": "概念不清——充分/必要方向感反了，没有抓住\"谁推出谁\"和\"问的是谁是谁的条件\"。", "key": "数学|6|1", "card_type": "redo", "options": {"A": "充分不必要条件", "B": "必要不充分条件", "C": "充要条件", "D": "既不充分也不必要条件"}, "teach": "判断方向的方法是先写推导链，再套名称：p 的范围 (0,2) 落在 q 的范围 (−1,3) 里面，所以 p⇒q 成立；反过来 q⇒p 不成立（比如 x=2.5 满足 q 但不满足 p）。命名规则：能推出别人的叫充分条件，被别人推出的叫必要条件。q 是被 p 推出的，所以 q 是 p 的必要不充分条件，选 B。口诀“小推大”：小范围是充分、大范围是必要。最后一步务必把答案代回原问法“q 是 p 的__条件”里读一遍，她选 A 就是跳过推导链、把方向读反了。", "why": "没先写 p⇒q 的推导链就直接套名称，把充分和必要的方向答反了。", "check_q": "p：x>3，q：x>1，则 p 是 q 的什么条件？", "check_a": "充分不必要条件。小范围 (3,+∞) 能推出大范围 (1,+∞)，反之不行，p 是充分条件。", "steps": "1. 先画范围：p 是 (0,2)，q 是 (−1,3)，在数轴上一画就看出 p 的范围整个落在 q 里面。\n2. 写推导链：满足 p 一定满足 q，即 p⇒q 成立；反过来取 x=2.5 满足 q 却不满足 p，q⇒p 不成立。\n3. 套命名规则“小推大”：能推出别人的是充分条件，被别人推出的是必要条件，q 是被 p 推出的那一个。\n4. 回到原问法读一遍：“q 是 p 的必要不充分条件”，选 B，别把被问的对象弄反。", "need": ["充分条件与必要条件的定义", "用集合包含关系判断条件（小范围充分、大范围必要）", "举反例否定一个推出关系"]}, {"subject": "数学", "question_no": "9", "full_score": 6.0, "got_score": 0.0, "student_answer": "选 AD（卷旁有扣分痕迹）。", "std_answer": "AC。分情况：若 x+2=3，得 x=1，此时 x²−2x=−1，与集合中已有的 −1 重复，违反互异性，舍去；若 x²−2x=3，解得 x=3 或 x=−1，代入检验元素互异均成立。故 x 可为 3 或 −1。她选的 D（x=1）正是被互异性淘汰的情形，漏选的 C（x=−1）反而成立。多选含错选项，一般得 0 分。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "集合元素的互异性（分类讨论后必须回代检验）", "note": "错因：概念不清——只解方程不验互异性，分类讨论\"只求解、不检验\"。", "stem": "设集合 A={−1, x+2, x²−2x}，且 3∈A，则 x 的值可以为（ ）（多选）", "paper_cause": "概念不清——只解方程不验互异性，分类讨论\"只求解、不检验\"。", "key": "数学|9|1", "card_type": "redo", "options": {"A": "3", "B": "−3", "C": "−1", "D": "1"}, "teach": "多选题的纪律是逐项独立验证，含参数的集合题还要多最后一步：回代查互异性。3∈A 分情况讨论：若 x+2=3，得 x=1；若 x²−2x=3，解得 x=3 或 x=−1。关键在回代——x=1 时 x²−2x=−1，与集合里已有的 −1 撞车，违反元素互异性，必须舍去；x=3、−1 代回后三个元素互不相同，保留。所以选 AC。她选的 D(x=1) 恰是被互异性淘汰的。抓手：凡解出参数，落笔前强制自己代回去看一眼元素重不重复，只解方程不检验是这类题的头号死法。", "why": "只解方程选了 AD，没把 x=1 代回检验互异性，正好选进了被淘汰的情形，还漏了 −1。", "check_q": "集合 {2, m, m−3} 中，若 m−3=2，则 m 是多少？这个情形符合元素互异性吗？", "check_a": "m=5，但此时元素为 2、5、2，出现重复，违反互异性，该情形不成立、必须舍去。", "steps": "1. 看到“3∈A”先分类：让含 x 的元素轮流等于 3——x+2=3 或 x²−2x=3。\n2. 分别解方程：第一种得 x=1；第二种 x²−2x−3=0 得 x=3 或 x=−1。\n3. 强制回代验互异性：x=1 时 x²−2x=−1，与已有的 −1 重复，舍去；x=3、−1 代回后三个元素互不相同，保留。\n4. 对照选项：x 可取 3 和 −1，选 AC；没回代验过的候选值不要急着勾。", "need": ["集合元素的互异性", "元素属于集合时的分类讨论", "解出参数后回代检验"]}, {"subject": "数学", "question_no": "10", "full_score": 6.0, "got_score": 2.0, "student_answer": "只选 A，选项 C 被她划掉；卷面红笔在多选区标有\"−9\"（与第 9 题全扣 6 分、第 11 题漏选扣 3 分合算，第 10 题应为漏选扣约 3 分，据此推断，存疑度中）。", "std_answer": "AC。A 作差得 (a−b)(a+b+c)>0，成立；C 是真分数\"糖水不等式\"，a>b>1、c>0 时 a/b>(a+c)/(b+c)，成立；B 在 c<1 时不成立；D 等价于 b²>a²，不成立。她把成立的 C 划掉了。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "不等式性质、作差比较法、糖水不等式", "note": "错因：概念不清——对 C 这类分式不等式的判断没有把握，会做 A 的作差法，却在 C 上犹豫误划。（答题卡核定：漏选得2分）", "stem": "若 a>b>1，c>0，则下列不等式一定成立的是（ ）（多选）", "paper_cause": "概念不清——对 C 这类分式不等式的判断没有把握，会做 A 的作差法，却在 C 上犹豫误划。", "key": "数学|10|1", "card_type": "redo", "options": {"A": "a²−bc > b²−ac", "B": "c ≥ (b+ac)/(a+bc)", "C": "a/b > (a+c)/(b+c)", "D": "bc/a > ac/b"}, "teach": "逐项验证：A 用作差法，a²−bc−(b²−ac)=(a−b)(a+b+c)，三个因子都为正，成立；C 是糖水不等式——a/b 是大于 1 的分数，分子分母同加正数 c，分数被“稀释”向 1 靠拢而变小，所以 a/b>(a+c)/(b+c)，成立。她恰恰把对的 C 划掉了，说明对分式大小没直觉。抓手：分式比大小别靠感觉，统一用作差：a/b−(a+c)/(b+c)=c(a−b)/(b(b+c))>0，一算便知。B 取 c=0.5 代入即可举出反例；D 两边约去 c 得 b/a>a/b，等价于 b²>a²，与 a>b 矛盾。", "why": "A 的作差法会用，但 C 没把握、靠感觉划掉，漏选丢了部分分。", "check_q": "若 x>y>0，z>0，比较 x/y 与 (x+z)/(y+z) 的大小。", "check_a": "x/y 更大。作差得 z(x−y)/(y(y+z))>0，所以 x/y>(x+z)/(y+z)（糖水不等式）。", "steps": "1. 多选题逐项独立验。先处理 A：作差 a²−bc−(b²−ac)，因式分解得 (a−b)(a+b+c)，由 a>b>1、c>0 三因子全正，A 成立。\n2. 验 C（糖水不等式）：a/b>1，分子分母同加正数 c，分数被稀释向 1 靠拢而变小，即 a/b>(a+c)/(b+c)；不放心就作差，差为 c(a−b)/(b(b+c))>0，C 成立。\n3. 验 B、D 用特殊值或化简找反例：B 取 c=0.5 代入即不成立；D 约去 c 后等价于 b²>a²，与 a>b 矛盾，不成立。\n4. 汇总成立的是 A、C，选 AC；觉得“好像不对”的选项必须算一遍或举出反例，不能凭感觉划掉。", "need": ["作差比较法（作差后因式分解判号）", "糖水不等式（大于1的分数分子分母同加正数变小）", "用特殊值举反例否定命题"]}, {"subject": "数学", "question_no": "11", "full_score": 6.0, "got_score": 2.0, "student_answer": "只选 A。", "std_answer": "AD。A：ab = ½·(2a·b) ≤ ½·((2a+b)/2)² = 1/8，成立；B：1/a+1/b = (2a+b)(1/a+1/b) = 3 + 2a/b + b/a ≥ 3+2√2，不是 4，不成立；C 不成立；D：b=1−2a 代入，a²+b² = 5a²−4a+1，a=2/5 时取最小值 1/5，成立。她漏选了 D。卷面草稿写了 (a+b)²/2 ≤ a²+b²，但没结合 2a+b=1 的条件走通。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "基本不等式、消元法求最值（二次函数配方）", "note": "错因：方法不会——A 用基本不等式能判，但 D 需要消元加配方，她没有这条解题路径，直接漏选。（答题卡核定：漏选得2分）", "stem": "已知正数 a，b 满足 2a+b=1，则（ ）（多选）", "paper_cause": "方法不会——A 用基本不等式能判，但 D 需要消元加配方，她没有这条解题路径，直接漏选。", "key": "数学|11|1", "card_type": "redo", "options": {"A": "ab 的最大值为 1/8", "B": "1/a + 1/b 的最小值为 4", "C": "√(2a) + √b 的最小值为 √2", "D": "a² + b² 的最小值为 1/5"}, "teach": "逐项验证：A 用基本不等式，ab=½·(2a·b)≤½×((2a+b)/2)²=1/8，成立；B 把条件乘进去展开：(2a+b)(1/a+1/b)=3+2a/b+b/a≥3+2√2≈5.83，不是 4，不成立。她漏的 D 没有现成公式可用后备路径——消元：由 b=1−2a 代入，a²+b²=5a²−4a+1，配方得 5(a−2/5)²+1/5，最小值 1/5，成立。抓手：遇到“一次等式条件求二次式最值”，没有公式就消元成一元二次函数配方，这是通用后备打法；她草稿写了 (a+b)²/2≤a²+b² 却没代入条件，等于没走通。", "why": "A 能用基本不等式判断，D 需要消元加配方，她没有这条解题路径，直接漏选。", "check_q": "正数 x、y 满足 x+y=1，x²+y² 的最小值是多少？", "check_a": "消元配方：x²+(1−x)²=2(x−½)²+½，当 x=y=½ 时取最小值 ½。", "steps": "1. 逐项验。A：把 ab 凑成 ½·(2a·b)，用基本不等式 ≤½·((2a+b)/2)²=½×(1/2)²=1/8，成立。\n2. B：把条件整体乘入，(2a+b)(1/a+1/b) 展开得 3+2a/b+b/a，再用基本不等式 ≥3+2√2，不是 4，不成立。\n3. C：按同样方法展开估界，逐项算清，判不成立，不跳过。\n4. D 没有现成公式，走后备路径——消元：由 b=1−2a 代入 a²+b² 得 5a²−4a+1，配方为 5(a−2/5)²+1/5，最小值 1/5，成立；汇总选 AD。", "need": ["基本不等式求最值（和定积最大）及配凑技巧", "整体代入法（条件乘入展开）处理分式最值", "消元化为一元二次函数配方求最值"]}, {"subject": "数学", "question_no": "14", "full_score": 5.0, "got_score": 0.0, "student_answer": "写\"B⊆A\"被划改，又写\"A⊇B\"，卷面有订正痕迹，判错。", "std_answer": "A=B。A 是函数 y=x²−2x−8=(x−1)²−9 的值域，为 [−9, +∞)；B 是函数 y=√(x+9) 的定义域，由 x+9≥0 得 [−9, +∞)。两集合完全相同。她草稿里把 A 的最小值 −9、B 的起点 −9 都算出来了，却没意识到两者是同一个区间。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "函数值域与定义域、集合相等与包含的区分", "note": "错因：概念不清——最后一步关系判断失误：两集合相等时写成包含关系，说明\"相等也是包含的特例、问关系时应答最精确者\"没吃透（与第 6 题同属关系类概念薄弱）。  ## 存疑题（不计入确定错题）", "stem": "已知 A={y | y=x²−2x−8, x∈R}，B={x | y=√(x+9)}，那么集合 A 与 B 的关系为 ___。", "paper_cause": "概念不清——最后一步关系判断失误：两集合相等时写成包含关系，说明\"相等也是包含的特例、问关系时应答最精确者\"没吃透（与第", "key": "数学|14|1", "card_type": "redo", "teach": "这类题分两步：先把两个集合分别算到底，再比关系。A 是二次函数 y=x²−2x−8=(x−1)²−9 的值域，为 [−9,+∞)；B 是函数 y=√(x+9) 的定义域，由根号下非负 x+9≥0 得 [−9,+∞)。两边化成区间并排一写，完全相同，关系就是 A=B。她草稿里两个 −9 都算出来了，却写成包含——记住判断原则：相等是包含的特殊情况，题目问“关系”时要答最精确的那个；两个集合互相包含当且仅当它们相等。抓手：比关系前先把两边都化成最简区间，相同就果断写 =。", "why": "A、B 的范围都算对了，最后一步把“相等”写成了“包含”，关系判断不精确。", "check_q": "A={y | y=x²+1}，B={y | y≥1}，A 与 B 是什么关系？", "check_a": "A=B，因为 x²+1 的值域正是 [1,+∞)，与 B 完全相同。", "steps": "1. 先把 A 算到底：A 是 y=x²−2x−8 的值域，配方 (x−1)²−9≥−9，得 A=[−9,+∞)。\n2. 再把 B 算到底：B 是 y=√(x+9) 的定义域，根号下非负 x+9≥0，得 B=[−9,+∞)。\n3. 两边都化成区间并排比：完全相同。\n4. 写最精确的关系 A=B：相等是包含的特殊情况，问“关系”时相同就写 =，不要降格写成包含。", "need": ["函数值域的求法（二次函数配方法）", "函数定义域（根式有意义的条件）", "集合相等与包含关系的判定"], "points": ["求 A：配方 y=(x−1)²−9≥−9，得 A=[−9,+∞)（约2分）", "求 B：由 x+9≥0 得定义域 B=[−9,+∞)（约2分）", "两集合完全相同，填 A=B（约1分；她写成包含关系 B⊆A，问关系必须答最精确的一个，判 0 分）"], "frame": "填空题草稿分两行并排写：左行'算 A（值域）'、右行'算 B（定义域）'→两行结果对齐比较→是同一个区间就写等号关系再落笔。先算齐两边再定关系符号，禁止凭眼熟先写 ⊆。"}, {"subject": "数学", "question_no": "5", "full_score": 5.0, "got_score": 0.0, "student_answer": "D", "std_answer": "（见试卷分析补遗）", "error_type": "待定（答题卡坐实错）", "knowledge_point": "见试卷第5题", "note": "答题卡涂卡：选D，判错。题干见数学试卷照片。", "key": "数学|5|1", "card_type": "redo", "stem": "已知集合 A={x | 0≤x<4, x∈N*}，则集合 A 的子集的个数为（ ）", "options": {"A": "32", "B": "16", "C": "8", "D": "4"}, "teach": "子集个数题三步走：先列举、再数数、后套公式。第一步把 A 的元素逐个写出：x∈N* 表示 x 是正整数（N* 从 1 开始，0 不是正整数，哪怕 0 满足 0≤x<4 也不能算），结合 0≤x<4 得 A={1,2,3}；第二步数清元素个数 n=3；第三步套公式：n 个元素的集合有 2ⁿ 个子集，这里 2³=8，选 C。易混点：真子集才是 2ⁿ−1（要再挖掉集合本身）。凡是描述法给出的集合，先翻译成列举法再动手，别凭感觉估 n。", "why": "没先把 A 的元素列出来，元素个数估错，2ⁿ 里的 n 取错，选了 D(4)。", "check_q": "集合 M={x | −1<x<3, x∈Z} 的子集个数是多少？", "check_a": "先列举：M={0,1,2}（注意 x∈Z 包含 0），共 3 个元素，子集个数 2³=8。", "steps": "1. 先翻译集合：x∈N* 表示正整数（从 1 开始，不含 0），再叠上 0≤x<4，逐个列举 A={1,2,3}。\n2. 数清元素个数 n=3，别凭感觉估。\n3. 套公式：n 元集合的子集个数是 2ⁿ=2³=8，选 C。\n4. 防混自查：问子集用 2ⁿ，问真子集才是 2ⁿ−1；列举时特别盯住 0 和端点 4 这两个边界。", "need": ["自然数集 N 与正整数集 N* 的区别", "子集个数公式 2ⁿ（真子集为 2ⁿ−1）", "描述法集合化为列举法"]}, {"subject": "数学", "question_no": "7", "full_score": 5.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "方法不会", "knowledge_point": "A∩B=A 即 A⊆B 求参数：必须分 A 为空集与非空集讨论", "note": "正确答案 (−∞,1]。她的草稿只写出 a≤−2 等片断，空集情况讨论不完整。", "key": "数学|7|1", "card_type": "redo", "stem": "已知集合 A={x | a−1≤x≤2a+1}，B={x | −3≤x≤3}，且 A∩B=A，则实数 a 的取值范围是（ ）", "options": {"A": "[−2,1]", "B": "(−2,1)", "C": "(−∞,−2)", "D": "(−∞,1]"}, "teach": "看到 A∩B=A 先翻译成 A⊆B，而由包含关系求参必须先分空集。第一步判空：A 为空集 ⟺ 左端大于右端，即 a−1>2a+1 ⟺ a<−2，此时 A⊆B 自动成立，不能漏。第二步 A 非空（a≥−2）时端点对齐：左端不小于 −3、右端不大于 3，即 a−1≥−3 且 2a+1≤3，得 −2≤a≤1。第三步把两段合并：a≤1，即 (−∞,1]，选 D。她选的 [−2,1] 正是只写了非空的一段。记住口诀：集合求参，空集先行。", "why": "只讨论了 A 非空的情况，漏掉 A 为空集（a<−2）时 A⊆B 也成立，范围少了左边一截。", "check_q": "已知 A={x | 2a≤x≤a+1}，B={x | 0≤x≤3}，若 A⊆B，求 a 的取值范围。", "check_a": "先分空集：A=∅ ⟺ 2a>a+1 ⟺ a>1，此时成立；A≠∅ 时 a≤1，还需左端 2a≥0、右端 a+1≤3，得 0≤a≤1。两段合并：a≥0，即 [0,+∞)。", "steps": "1. 先翻译条件：A∩B=A 等价于 A⊆B，看到“交集等于自身”先换成包含关系。\n2. 空集先行：A 为空 ⟺ a−1>2a+1 ⟺ a<−2，此时 A⊆B 自动成立，先把这一段收入。\n3. A 非空（a≥−2）时端点对齐 B=[−3,3]：a−1≥−3 且 2a+1≤3，解得 −2≤a≤1。\n4. 两段取并集合并：a≤1，即 (−∞,1]，选 D；只写非空一段就会漏掉左边一截。", "need": ["A∩B=A 与 A⊆B 的等价转化", "空集是任何集合的子集（含参求范围先讨论空集）", "由包含关系列端点不等式组"]}, {"subject": "数学", "question_no": "8", "full_score": 5.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "方法不会", "knowledge_point": "恒成立问题：4/(x+1)+1/(y+2) 用权方和/柯西求最小值", "note": "正确答案 m≤1/16。她用通分硬算，方法笨且算错。", "key": "数学|8|1", "card_type": "redo", "stem": "已知 x>0，y>0，且 x+y=5，若 4/(x+1) + 1/(y+2) ≥ 2m+1 恒成立，则实数 m 的取值范围是（ ）", "options": {"A": "m≤1/16", "B": "m≤2/5", "C": "m≤1/2", "D": "m≤1/4"}, "teach": "恒成立先转最值：'左边 ≥2m+1 恒成立'等价于 2m+1≤左边的最小值，所以核心是求最小值。求法用权方和（柯西）一步到位：把分子 4 看成 2²、1 看成 1²，再换元 a=x+1、b=y+2，则 a+b=(x+y)+3=8，于是 2²/a+1²/b ≥ (2+1)²/(a+b)=9/8。回代：2m+1≤9/8，解得 m≤1/16，选 A。关键动作是换元凑出'分母之和为定值'，而不是通分硬算——通分后式子臃肿、计算量爆炸。等号在 a:b=2:1 时成立，最小值取得到。", "why": "用通分硬算求最小值，方法笨重且算错；没看出换元后分母之和为定值、可用权方和一步求最值。", "check_q": "x>0，y>0，x+y=3，求 1/(x+1) + 4/(y+1) 的最小值。", "check_a": "设 a=x+1、b=y+1，则 a+b=5；权方和：1²/a+2²/b ≥ (1+2)²/5=9/5，最小值为 9/5。", "steps": "1. 先转化：左边 ≥2m+1 对所有 x、y 恒成立，等价于 2m+1≤左边的最小值，问题变成求最小值。\n2. 别急着通分，先看分母结构：令 a=x+1、b=y+2，由 x+y=5 得 a+b=8 是定值，这是用权方和的信号。\n3. 套权方和：把 4 看成 2²、1 看成 1²，2²/a+1²/b≥(2+1)²/(a+b)=9/8，等号在 a:b=2:1 时取得，最小值 9/8。\n4. 回代解 m：2m+1≤9/8，得 m≤1/16，选 A。", "need": ["恒成立问题转化为最值问题", "权方和不等式（柯西不等式的 Engel 形式）", "换元凑出分母之和为定值"]}, {"subject": "数学", "question_no": "13", "full_score": 5.0, "got_score": 0.0, "student_answer": "5<9x−y≤12（两式直接加减）", "std_answer": "[−1, 20]", "error_type": "方法不会", "knowledge_point": "已知 x−y 与 4x−y 范围求 9x−y：待定系数法，不能直接加减", "note": "9x−y = −(5/3)(x−y) + (8/3)(4x−y)，代入两范围得 [−1,20]。", "key": "数学|13|1", "card_type": "redo", "stem": "已知实数 x, y 满足 −4≤x−y≤−1，−1≤4x−y≤5，则 t=9x−y 的取值范围是 ______。", "teach": "这类'已知两个式子的范围、求第三个式子的范围'只能用待定系数法，绝不能把两个不等式直接加减——因为 x、y 在两式中是同一个人、联动的，直接加减等于默认 x、y 能同时取到各自极值，求出的范围会失真。标准三步：设 9x−y=m(x−y)+n(4x−y)，比对系数得 m+4n=9、−m−n=−1，解得 m=−5/3、n=8/3；把已知范围分别乘 m、n（乘负数不等号要变向）后相加：−(5/3)(x−y)∈[5/3,20/3]，(8/3)(4x−y)∈[−8/3,40/3]，相加得 9x−y∈[−1,20]。她写的 5<9x−y≤12 就是直接加减的产物。", "why": "把两个已知不等式直接相加减去凑 9x−y，没意识到 x、y 在两式中联动，不能独立取极值。", "check_q": "已知 −1≤x+y≤3，2≤2x+y≤6，求 3x+2y 的取值范围。", "check_a": "待定系数：3x+2y=(x+y)+(2x+y)，把两范围相加得 [−1+2, 3+6]=[1,9]。", "steps": "1. 先认禁区：x、y 在两式中是联动的，不能把两个不等式直接加减去凑 9x−y，那样等于默认 x、y 能同时取到极值，范围必然失真。\n2. 设待定系数：令 9x−y=m(x−y)+n(4x−y)，比对系数得 m+4n=9、−m−n=−1。\n3. 解得 m=−5/3、n=8/3；把已知范围分别乘上系数（乘负数 −5/3 时不等号要变向），得两段范围。\n4. 两段相加：−(5/3)(x−y)∈[5/3,20/3] 与 (8/3)(4x−y)∈[−8/3,40/3] 相加，得 9x−y∈[−1,20]。", "need": ["待定系数法表示目标式", "不等式性质（乘负数不等号变向）", "变量联动时不能独立取极值的原理"], "points": ["设待定系数：写 9x−y=m(x−y)+n(4x−y)，对照系数列方程（约2分）", "解出 m=−5/3、n=8/3（约1分）", "按系数正负交叉取界代入两个已知范围，得下界 −1、上界 20（约1分）", "合成区间填 [−1, 20]（约1分）", "把两个已知不等式直接相加减是错误路线（她写 5<9x−y≤12），得 0 分"], "frame": "草稿四行走完再填空：第一行写待定系数等式→第二行解 m、n→第三行按'系数为正用同向界、为负用反向界'代入→第四行合成一个区间。中间结果一行一行排好不跳步，最后才把 [−1, 20] 抄进答题空。"}, {"subject": "数学", "question_no": "15", "full_score": 13.0, "got_score": 8.0, "student_answer": "(1)解集端点写错；(2)A∩B={x|2<x<3}；(3)补集端点含糊", "std_answer": "见讲解", "error_type": "概念不清", "knowledge_point": "集合的并、交、补运算与解集端点开闭", "note": "答题卡得8/13。(1)问解不等式端点出错，连带后面集合范围偏差。", "key": "数学|15|1", "card_type": "concept", "stem": "已知 A={x | −1≤x<3}，B={x | 1<3x−5<16}，求 (1) A∪B；(2) A∩B；(3) ∁_R(A∩B)。满分 13 分，她得 8 分，丢分集中在端点开闭。", "teach": "集合运算先化简、再画数轴，端点开闭全程盯住。第一步解 B：1<3x−5<16 → 6<3x<21 → 2<x<7，两端都是开的。第二步读并集：A∪B 取覆盖范围的最外侧端点——左端 −1 在 A 中是闭（≤）所以并集左端闭，右端 7 在 B 中是开所以并集右端开，得 {x | −1≤x<7}；交集取重叠段 {x | 2<x<3}。第三步补集口诀：端点开闭与原集合正好反过来——A∩B 在 2、3 处都不含，补集里就要含，得 ∁_R(A∩B)={x | x≤2 或 x≥3}。每写一个端点，都回头看一眼原不等式是 ≤ 还是 <。", "why": "B 的化简和交集都会，但写并集、补集时端点开闭出错，没逐个端点回看原不等号。", "check_q": "A={x | 0≤x<2}，B={x | 1<x≤3}，求 A∩B 和 ∁_R(A∩B)。", "check_a": "A∩B={x | 1<x<2}；补集端点反过来取：∁_R(A∩B)={x | x≤1 或 x≥2}。", "steps": "1. 先各自化简：解 B 的不等式 1<3x−5<16 得 2<x<7，A 的范围也解到底，两个集合都写成区间放到数轴上。\n2. 求并集取最外侧端点，并逐个端点回看来源集合的开闭：左端 −1 在 A 中取到（闭），右端 7 在 B 中取不到（开），A∪B={x|−1≤x<7}。\n3. 求交集取重叠段：A∩B={x|2<x<3}，端点开闭同样逐个核对。\n4. 求补集记住“开闭反过来”：∁_R(A∩B)={x|x≤2 或 x≥3}，原集合不含的端点，补集里要含上。", "need": ["集合的并集、交集、补集运算", "解集端点的开闭判定（≤为闭、<为开）", "用数轴表示集合运算"], "points": ["(1) 先解 B：由 1<3x−5<16 得 2<x<7（约2分，端点开闭跟着原不等号走）", "(1) A∪B={x|−1≤x<7}（约3分；左端 −1 取等、右端 7 不取等，她错在端点）", "(2) A∩B={x|2<x<3}（约4分；两端都不取等）", "(3) ∁R(A∩B)={x|x≤2 或 x≥3}（约4分；补集端点开闭与原集合恰好相反——原开变闭、原闭变开）"], "frame": "三问一条链：第一段先把 B 的解集单独解出来成行→第二段写并集（先在草稿画数轴，两区间并起来再逐个定端点）→第三段写交集→第四段直接由交集写补集。每段先写集合运算符号再写结果，四个端点逐个回查原不等式，不凭印象。"}, {"subject": "数学", "question_no": "17", "full_score": 15.0, "got_score": 8.0, "student_answer": "讨论了 m=0 成立、m<0 且 Δ<0 得 −4<m<0", "std_answer": "−4<m≤0（第(1)问口径）", "error_type": "表达不规范", "knowledge_point": "含参二次不等式恒成立：分类讨论后结论必须合并完整", "note": "答题卡得8/15。过程讨论基本都在，丢分疑在结论漏并 m=0 或第(2)问不完整。", "key": "数学|17|1", "card_type": "concept", "stem": "已知 f(x)=mx²−mx−1。(1) m=1/2 时求 f(x)<0 的解集；(2) 若 f(x)<0 对一切 x∈R 恒成立，求 m 的取值范围。满分 15 分，她得 8 分。", "teach": "含参二次不等式恒成立，分类框架固定：先单独验 m=0，再看 m≠0 时的'开口方向+Δ'。第 (2) 问要 f(x)<0 恒成立：m=0 时 f(x)=−1<0 成立，先记下不能丢；m≠0 时图像须开口向下（m<0）且与 x 轴无交点（Δ=m²+4m<0），解得 −4<m<0。最后一步最关键——合并结论：把各段取并集，将 m=0 并回去，得 −4<m≤0。她讨论过程基本都在，却疑似收尾时漏并 m=0。记住：分类讨论写完，每种情况都要在最终结论里'对号入座'，写完回头数一遍，一段都不能丢。", "why": "分类讨论的过程基本正确，但最后合并结论时疑似漏并 m=0，结论不完整被扣分。", "check_q": "若关于 x 的不等式 mx²−mx+1>0 对一切 x∈R 恒成立，求 m 的取值范围（注意最后合并结论）。", "check_a": "m=0 时 1>0 成立；m>0 且 Δ=m²−4m<0 得 0<m<4；两段合并：0≤m<4，即 [0,4)。", "steps": "1. 用固定分类框架：先单独验参数为零的情形——m=0 时不等式是否恒成立，先把结论记下，别丢。\n2. m≠0 时先看开口：恒成立（恒负）要求二次项系数为负，即 m<0 才可能。\n3. 再用判别式：图像与 x 轴无交点 ⟺ Δ<0，Δ=m²+4m<0，解得 −4<m<0。\n4. 收尾合并：把 m=0 并回去，各段取并集，得 −4<m≤0；写完回头数一遍，讨论过的每种情况都要在最终结论里出现。", "need": ["含参二次不等式恒成立的分类讨论（先验参数为零）", "开口方向与判别式 Δ 的联合判定", "分类讨论后各段结论的并集合并"], "points": ["(1) 代入 m=1/2，化为一元二次不等式并求出根 x₁=−1、x₂=2（约3分）", "(1) 写解集 {x|−1<x<2}（约2分）", "(2) 单独讨论 m=0：此时 f(x)=−1<0 恒成立（约2分——她结论里漏并的就是这段）", "(2) m≠0 时列条件组：开口向下 m<0 且 Δ=m²+4m<0（约3分）", "(2) 由 Δ<0 解得 −4<m<0（约2分）", "(2) 最后一行合并两段结论：−4<m≤0（约3分；只写 −4<m<0 不合并，结论分拿不全）"], "frame": "两问分开落笔：(1) '代入—求根—写解集'三行走完；(2) 按'① m=0 时… ② m<0 且 Δ<0 时…'分段各写一段，每段末尾留一个小结论→全文最后一行必须出现'综上'，把两段并成一个区间单独成行。含参题不写综上行，等于没答完。"}, {"subject": "数学", "question_no": "18", "full_score": 17.0, "got_score": 4.0, "student_answer": "设 xy 后列式混乱，出现 x²−30x+500<0 等错误，涂改多", "std_answer": "见讲解", "error_type": "计算失误", "knowledge_point": "基本不等式实际应用（围栏面积最大/材料最省）", "note": "答题卡仅得4/17：正式作答涂改混乱、关键常数算错（500 应为 200）。试卷上较完整的推导系考后评讲订正。", "key": "数学|18|1", "card_type": "concept", "stem": "一边靠墙围矩形菜园，长 x 米、宽 y 米。(1) 面积为 36 平方米时，x、y 为何值所用篱笆总长最小？(2) 篱笆总长为 30 米时，把面积 S 表示为长 x 的函数，并求 S≥100 时 x 的范围与 S(x) 的值域。满分 17 分，她只得 4 分。", "teach": "建模三步：设元——先把'一边靠墙'翻译清楚：篱笆总长=x+2y（靠墙的长边不占篱笆）；列约束与目标——(1) 约束 xy=36，目标 x+2y 最小，用基本不等式 x+2y≥2√(2xy)=12√2；(2) 约束 x+2y=30，先解出 y=(30−x)/2 并写定义域 0<x<30，再得目标函数 S=xy=−½x²+15x。她答题卡上的正式作答涂改混乱，还把 S≥100 的式子写成 x²−30x+500<0（常数应为 200），只得 4 分；试卷上较完整的推导是考后评讲订正补的。铁规矩：建模题先把'设元—约束—目标'三行框架写下来再算，每步算完回代验算一次，别一条道算到黑。", "why": "正式作答建模过程混乱、关键一步常数算错；试卷上的完整推导是考后评讲订正的", "check_q": "一边靠墙，用 20 米篱笆围矩形菜园（长 x 与墙平行，宽 y），求面积的最大值及此时 x、y 的值。", "check_a": "约束 x+2y=20，S=xy=½·(x·2y)≤½·((x+2y)/2)²=50，当 x=2y 即 x=10、y=5 时取最大，最大值 50 平方米。", "steps": "1. 先画图设元：矩形一边靠墙，设与墙平行的边为 x、宽为 y；靠墙的那条边不占篱笆，先把总长关系 x+2y 翻译对。\n2. 按小问列约束与目标：(1) 约束 xy=36，目标是 x+2y 最小；(2) 约束 x+2y=30，目标是面积 S=xy 最大。\n3. 分别求解：(1) 用基本不等式 x+2y≥2√(2xy)=12√2；(2) 先由约束解出 y=(30−x)/2 并写定义域 0<x<30，再得 S=−½x²+15x，用二次函数求最大值。\n4. 每步回代验算：把求出的 x、y 代回约束和面积核对（如由 S≥100 展开的式子常数应是 200 而不是 500），对不上就回头查展开。", "need": ["基本不等式的实际应用（积为定值时和最小）", "二次函数建模求最值（先写定义域）", "靠墙围栏问题的篱笆总长表示"], "points": ["(1) 先翻译篱笆总长：靠墙一边不占篱笆，L=x+2y（约2分）", "(1) 约束 xy=36 下用基本不等式 L≥2√(2xy)=12√2（约3分）", "(1) 写取等条件 x=2y 并解出 x=6√2、y=3√2（约3分；只写最小值不写取等，扣分）", "(2) 由 x+2y=30 得 y=(30−x)/2，并写定义域 0<x<30（约2分）", "(2) 写出 S(x)=x·(30−x)/2=−½x²+15x（约2分）", "(2) S≥100 化为 x²−30x+200≤0，解得 10≤x≤20（约3分；她把常数写成 500，错从这里开始）", "(2) 由抛物线顶点 x=15 写 S(x) 的值域（约2分）"], "frame": "建模题三段定式：第一段'设元+翻译'——把靠墙、总长、面积逐句翻成式子单独成行；第二段处理 (1)：先抄目标（求 L 最小）再用基本不等式，公式后立刻跟取等条件；第三段处理 (2)：先解出 y 并写定义域→再写 S(x)→解不等式、求值域分行写。每步算完回代验算一次（尤其常数项），涂改宁可划掉重写一行，不在原式上叠改。"}, {"subject": "数学", "question_no": "19", "full_score": 17.0, "got_score": 0.0, "student_answer": "答题卡上写成 mx(2x+1) 一套，得出 m<1", "std_answer": "M=(−∞,0)∪(1,+∞)（草稿结论）", "error_type": "方法不会", "knowledge_point": "含参二次方程/不等式：按 m=0、m<0、m>0 分类讨论", "note": "答题卡得0/17，正式作答跑偏。试卷上有完整且正确的分类讨论，但系考后评讲订正的成果——订正能跟上，独立限时做还不行，按不会重练。", "key": "数学|19|1", "card_type": "concept", "stem": "已知 ∃x∈R 使 2mx²+mx+1/8<0，实数 m 的取值范围记为集合 M。(1) 求 M；(2) 若集合 N={x | x²+(1−a)x−a>0}，且 'x∈N' 是 'x∈M' 的充分不必要条件，求 a 的取值范围。满分 17 分，她得 0 分。", "teach": "含参二次'存在性'问题框架：∃x 使式子 <0，只需函数能取到负值。逐类验：m=0 时式子恒为 1/8>0，不成立；m<0 开口向下、两端趋于 −∞，必然取到负值，成立；m>0 开口向上，需最小值 <0 即 Δ=m²−m>0，得 m>1。合并 M=(−∞,0)∪(1,+∞)。注意：答题卡上她写的是另一套跑偏解法（拆成 mx(2x+1) 硬凑），考试当时并没有做出来；试卷上这套完整讨论是考后评讲订正时补的——订正能跟上说明讲解听得懂，但限时独立做还不行。这类题按'不会'重练：把分类框架练成固定套路（先验 m=0、再看开口、最后才用 Δ），拿到题先把框架写下来再动笔。", "why": "考试当时没做出来：答题卡上是跑偏的解法；试卷上的完整讨论是考后评讲订正补的，不算当时会", "check_q": "若 ∃x∈R 使 mx²+2x+1<0，求实数 m 的取值范围。", "check_a": "m=0 时 2x+1<0 有解，成立；m<0 开口向下必能取负，成立；m>0 需 Δ=4−4m>0 得 0<m<1。合并：m<1，即 (−∞,1)。", "steps": "1. 先翻译存在性：∃x 使 mx²+mx+1/8<0 成立，等价于这个函数能取到负值，按这个目标逐类验证。\n2. 验 m=0：式子恒为 1/8>0，取不到负值，不成立，先排除。\n3. 验 m<0：开口向下，两端趋于 −∞，必然取到负值，成立，整段收入。\n4. 验 m>0：开口向上，需要最小值<0，即 Δ=m²−m>0，解得 m>1；最后合并三段：M=(−∞,0)∪(1,+∞)。", "need": ["存在性问题（∃）转化为函数能否取到负值", "含参二次函数的分类讨论（参数为零与开口方向）", "判别式 Δ 与函数最小值符号的判定"], "points": ["(1) m=0 时：式子恒为 1/8>0，不存在 x 使其 <0，不成立（约2分）", "(1) m<0 时：开口向下，函数必取负值，成立（约3分）", "(1) m>0 时：需最小值<0，即 Δ=m²−m>0，解得 m>1（约3分）", "(1) 合并写出 M=(−∞,0)∪(1,+∞)（约2分）", "(2) 先解 N：x²+(1−a)x−a=(x+1)(x−a)>0，按 a 与 −1 的大小写出 N（约3分）", "(2) 把'x∈N 是 x∈M 的充分不必要'翻译为 N 是 M 的真子集，列端点不等式（约3分）", "(2) 解出 a 的范围并回代验证等号不能取（约1分）", "注：她答题卡上写成 mx(2x+1) 一套跑偏解法，两问均未踩点，整题 0 分"], "frame": "分类讨论题定式：(1) 按 m=0、m<0、m>0 三段各起一行，段首先写类别、段末留小结论→最后'综上'一行合并成集合 M。(2) 先把 N 完整解出来→在旁边把'充分不必要=N⊊M'这句翻译写下来→按端点列式求 a→回代验等号。两问之间空一行，所有结论都用集合或区间形式收尾，不写散句。"}], "practice": [{"id": "phy-01", "subject": "物理", "type": "single", "points": 4, "knowledge": "时间间隔 vs 时刻", "source": "高一上第一次月考", "stem": "下列计时数据指时间间隔的是（ ）", "options": {"A": "北京时间2026年5月24日23时08分，搭载神舟二十三号载人飞船的长征二号F遥二十三运载火箭在酒泉卫星发射中心点火发射", "B": "某同学在校运动会上110m跨栏成绩是14.10s", "C": "一辆汽车在第10s末开始加速行驶", "D": "我们12时15分开始吃午饭"}, "answer": "B", "explain": "A：2026年5月24日23时08分是时刻，错；B：14.10s是时间间隔，对；C：第10s末是时刻，错；D：12时15分是时刻，错。故选B。"}, {"id": "phy-02", "subject": "物理", "type": "single", "points": 4, "knowledge": "质点模型", "source": "高一上第一次月考", "stem": "下列情形中，可以把人或物体看成质点的是（ ）", "options": {"A": "研究地球的自转", "B": "研究跳水运动员的空中姿态", "C": "观察苏炳添百米赛跑的起跑动作", "D": "测量动车从宁德站到上海站的时间"}, "answer": "D", "explain": "A：研究地球自转需考虑地球大小形状，不能看成质点；B：研究跳水姿态需考虑身体大小形状，不能；C：观察起跑动作需考虑身体，不能；D：测量动车运行时间可忽略动车大小形状，可以看成质点。故选D。"}, {"id": "phy-03", "subject": "物理", "type": "single", "points": 4, "knowledge": "参考系", "source": "高一上第一次月考", "stem": "这是宋代诗人陈与义的一首诗：\"飞花两岸照船红，百里榆堤半日风，卧看满天云不动，不知云与我俱东\"，在诗人看来云是不动的，他选择的参照物是（ ）", "options": {"A": "岸边的江堤", "B": "江边的树", "C": "树上的飞花", "D": "诗人的小船"}, "answer": "D", "explain": "\"不知云与我俱东\"说明相对于地面，诗人与云都向东运动、运动状态相同、相对静止。诗人以自己乘坐的小船为参照物看云，就会出现\"卧看满天云不动\"的效果。故选D。"}, {"id": "phy-04", "subject": "物理", "type": "single", "points": 4, "knowledge": "匀变速直线运动速度与位移关系", "source": "高一上第一次月考", "stem": "【注：原卷中加速度数值转换丢失，据答案反推为5m/s²】航空母舰上有帮助飞机起飞的弹射系统，已知某战斗机离开弹射系统后，在跑道上做加速度大小为5m/s²的匀加速直线运动，战斗机在跑道上自主滑行100m时起飞，飞机离开跑道的速度大小为55m/s，则弹射系统赋予战斗机的初速度大小为（ ）", "options": {"A": "35m/s", "B": "40m/s", "C": "45m/s", "D": "50m/s"}, "answer": "C", "explain": "由 v²−v₀²=2ax 得 v₀=√(v²−2ax)=√(55²−2×5×100)=√(3025−1000)=√2025=45m/s。故选C。"}, {"id": "phy-05", "subject": "物理", "type": "multi", "points": 6, "knowledge": "速度与加速度的关系", "source": "高一上第一次月考", "stem": "关于速度和加速度的关系，下列说法中正确的是（ ）", "options": {"A": "物体的加速度等于零，速度一定等于零", "B": "物体的加速度越大，速度一定越大", "C": "物体的加速度越大，速度一定改变越快", "D": "物体的加速度增大，速度可能减小"}, "answer": "CD", "explain": "A：光滑平面上匀速直线运动的滑块，加速度为零但速度不为零，错；B：a=Δv/Δt，加速度大小与速度大小无关，错；C：加速度是描述速度变化快慢的物理量，对；D：当加速度方向与速度方向相反时，加速度增大、速度减小，对。故选CD。"}, {"id": "phy-06", "subject": "物理", "type": "multi", "points": 6, "knowledge": "位移/路程、平均速度/平均速率、参考系", "source": "高一上第一次月考", "stem": "【注：原卷中部分数字转换丢失，据答案反推复原：路程5.4km、用时1h、M、N直线距离1.8km】一游客在武夷山九曲溪乘竹筏漂流，途经双乳峰附近的M点和玉女峰附近的N点。已知该游客从M点漂流到N点的路程为5.4km，用时1h，M、N间的直线距离为1.8km，则从M点漂流到N点的过程中（ ）", "options": {"A": "该游客的位移大小为5.4km", "B": "该游客的平均速率为5.4km/h", "C": "该游客的平均速度大小为1.8m/s", "D": "若以所乘竹筏为参考系，玉女峰在这段时间内的平均速度大小为0.5m/s"}, "answer": "BD", "explain": "A：位移是M→N的有向线段，大小为1.8km≠5.4km，错；B：平均速率=路程/时间=5.4km/1h=5.4km/h，对；C：平均速度=位移/时间=1.8km/1h=1.8km/h=0.5m/s≠1.8m/s，错；D：以竹筏为参考系，玉女峰相对竹筏运动，位移大小1.8km、时间1h，平均速度大小0.5m/s，对。故选BD。"}, {"id": "phy-07", "subject": "物理", "type": "multi", "points": 6, "knowledge": "初速为零的匀加速直线运动规律", "source": "高一上第一次月考", "stem": "从静止开始做匀加速直线运动的物体，第1s内通过的位移为0.5m，则（ ）", "options": {"A": "第1s末物体的速度为1m/s", "B": "第1s末物体的速度为2m/s", "C": "第1s内物体的平均速度为1m/s", "D": "物体的加速度为1m/s²"}, "answer": "AD", "explain": "由 x=½at² 得 0.5=½×a×1²，a=1m/s²（D对）；第1s末速度 v=at=1×1=1m/s（A对、B错）；第1s内平均速度=x/t=0.5/1=0.5m/s（C错）。故选AD。"}, {"id": "phy-08", "subject": "物理", "type": "multi", "points": 6, "knowledge": "初速为零匀加速直线运动的比例推论", "source": "高一上第一次月考", "stem": "如图所示，光滑斜面AE被分成长度相等的四段（AB=BC=CD=DE），一个物体由A点静止释放后做匀加速直线运动，下面结论中正确的是（ ）", "options": {"A": "经过每一部分时，其速度增量均相同", "B": "物体到达B、C、D、E各点的速度大小之比为1:√2:√3:2", "C": "物体通过AB、BC、CD、DE段所需的时间之比为1:(√2−1):(√3−√2):(2−√3)", "D": "若该物体从A点运动到E点共用时4s，则物体在第2s末的速度等于B点速度"}, "answer": "BD", "explain": "B：由 v²=2ax（初速为0），v∝√x，vB:vC:vD:vE=1:√2:√3:2，对；C：通过连续相等位移时间之比确为1:(√2−1):(√3−√2):(2−√3)，但原卷该选项表述有误，按详解判错；A：每段速度增量Δv=aΔt，各段时间不同，增量不同，错；D：AB:BE=1:3，B为中间时刻（总时间4s），2s末速度=中间时刻速度=vB，对。故选BD。"}, {"id": "phy-09", "subject": "物理", "type": "fill", "points": 4, "knowledge": "平均速度（路程/时间两种情形）", "source": "高一上第一次月考", "stem": "一物体做直线运动，它经过前一半路程的平均速度为6m/s，经过后一半路程的平均速度为9m/s，则物体全过程的平均速度为____m/s。如果它经过前一半时间的平均速度为4m/s，经过后一半时间的平均速度为8m/s，则物体全过程的平均速度为____m/s。", "answer": ["7.2", "6"], "explain": "[1]设总路程为s，前一半路程用时 t1=(s/2)/6=s/12，后一半用时 t2=(s/2)/9=s/18，全程时间 t=s/12+s/18=5s/36，全程平均速度=s/t=7.2m/s。[2]设总时间为t，前一半时间路程=4×(t/2)=2t，后一半=8×(t/2)=4t，总路程=6t，平均速度=6t/t=6m/s。"}, {"id": "phy-10", "subject": "物理", "type": "fill", "points": 10, "knowledge": "x-t图像", "source": "高一上第一次月考", "stem": "某物体沿x轴做直线运动，其位置坐标随时间的变化如图乙所示（x-t图像：t=0时x=2m；0~1s直线上升到x=3m；1~3s保持x=3m不动；3~4s直线下降到x=0；图像据详解数据反推）。在第3s末的坐标为 x3=____m，第4s内物体坐标变化量 Δx=____m；在第1s内物体平均速度为____m/s，在第4s内物体平均速度为____m/s；在前4s内通过的路程是____m。", "answer": ["3", "−3", "1", "−3", "4"], "explain": "[1]第3s末坐标 x3=3m。[2]第4s内坐标变化量 Δx=x末−x初=0−3=−3m（注意符号）。[3]第1s内平均速度 v1=Δx1/t=(3−2)/1=1m/s。[4]第4s内平均速度 v2=(0−3)/1=−3m/s。[5]前4s路程 s=(3−2)+(3−0)=4m（先上后下，路程相加）。"}, {"id": "phy-11", "subject": "物理", "type": "exp", "points": 6, "knowledge": "光电门测瞬时速度、加速度", "source": "高一上第一次月考", "stem": "【注：原卷中数字转换丢失，据答案反推复原】用气垫导轨和光电门测物体的加速度。数字毫秒计记录了遮光板通过第一个光电门的时间为0.125s，通过第二个光电门的时间为0.020s，遮光板从开始遮住第一个光电门到开始遮住第二个光电门的时间为3.00s，已知遮光板的宽度为1.00cm。分别求出滑块通过第一个光电门的速度大小、第二个光电门的速度大小，以及滑块的加速度（结果均保留两位小数）。", "answer": ["0.08", "0.50", "0.14"], "explain": "遮光板通过光电门时间极短，平均速度可视为瞬时速度，v=d/Δt。[1]v1=0.0100/0.125=0.08m/s。[2]v2=0.0100/0.020=0.50m/s。[3]a=(v2−v1)/Δt=(0.50−0.08)/3.00=0.14m/s²。"}, {"id": "phy-12", "subject": "物理", "type": "exp", "points": 6, "knowledge": "打点计时器纸带、逐差法", "source": "高一上第一次月考", "stem": "某同学用如图所示装置研究小车运动的速度随时间变化的规律（纸带图略）。(1)电火花打点计时器使用的电源为____（选填\"直流220V\"或\"交流220V\"）电源。(2)实验打出的纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，打点计时器所接电源的频率为50Hz，根据打出的纸带计算出打B点时小车的速度____m/s，小车运动的加速度____m/s²（结果均保留2位有效数字；关键数据：计数点间隔T=0.1s，详解取纸带数据用逐差法）。", "answer": ["交流220V", "0.81", "2.0"], "explain": "(1)电火花打点计时器使用交流220V电源。(2)打点周期0.02s，相邻计数点间还有四个计时点未标出，故计数点时间间隔 T=5×0.02s=0.1s。打B点速度用B点前后两段位移的平均：vB=(xAB+xBC)/(2T)=0.81m/s。加速度用逐差法：a=[(9.10−7.10)×10⁻²]/(0.1²)m/s²=2.0m/s²（数据引自详解）。"}, {"id": "phy-13", "subject": "物理", "type": "calc", "points": 8, "knowledge": "速度变化量的矢量性、加速度定义式", "source": "高一上第一次月考", "stem": "一质量为0.4kg的足球，以10m/s的速度迎面飞来，足球守门员将球以8m/s的速度反向踢出，守门员与球接触的时间为0.1s，求：(1)足球在与守门员接触的这段时间内的速度的变化量大小；(2)足球在与守门员接触的这段时间内的平均加速度大小。", "answer": ["18m/s", "180m/s²"], "explain": "取足球返回的方向为正方向（先写正方向！）。(1)速度的变化量 Δv=v2−v1=8−(−10)=18m/s（2分），=18m/s（1分）。答：足球速度的变化量大小为18m/s（1分）。注意迎面飞来取负，反向踢回两者相加不是相减。(2)加速度 a=Δv/t=18/0.1=180m/s²（2分），=180m/s²（1分）。答：足球加速度大小180m/s²（1分）。"}, {"id": "phy-14", "subject": "物理", "type": "calc", "points": 10, "knowledge": "v-t图像（斜率、面积）", "source": "高一上第一次月考", "stem": "一摩托车由静止开始在平直的公路上行驶，其运动过程的v-t图像如图所示（v-t图像：0~20s从0匀加速到30m/s；20~45s保持30m/s匀速；45~75s匀减速到0；后段据详解梯形面积反推）。求：(1)摩托车在0~20s这段时间的加速度大小；(2)摩托车在0~75s这段时间的平均速度大小。", "answer": ["1.5m/s²", "20m/s"], "explain": "(1)v-t图像斜率=加速度：a=Δv/Δt=30/20=1.5m/s²（2分），=1.5m/s²（1分）。答：0~20s加速度大小为1.5m/s²（1分）。(2)v-t图像面积=位移：x=½×(25+75)×30=1500m（2分，梯形：上底25s匀速段、下底75s总时间）。平均速度 v=x/t=1500/75=20m/s（2分）。"}, {"id": "phy-15", "subject": "物理", "type": "calc", "points": 16, "knowledge": "刹车陷阱（先算停止时间）", "source": "高一上第一次月考", "stem": "【注：原卷中初速度与加速度数值转换丢失，据详解反推复原为18m/s、6m/s²】以18m/s的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为6m/s²。求：(1)汽车在刹车1s末的速度；(2)汽车在刹车2s内的位移；(3)汽车在刹车4s内的位移。", "answer": ["12m/s", "24m", "27m"], "explain": "取汽车初速度方向为正方向。刹车问题第一步：先算停止时间 t₀=v₀/a=18/6=3s！(1)v=v₀+at=18−6×1=12m/s（2分），=12m/s（1分）。答：刹车1s末速度大小为12m/s，方向与初速度相同（1分）。(2)t=2s<t₀，用 x=v₀t−½at²=18×2−½×6×4=36−12=24m（3分），=24m（1分）。答：刹车2s内位移24m（1分）。(3)t=4s>t₀，汽车3s已停住，刹车4s内的位移=3s内的位移：x=18×3−½×6×9=54−27=27m（2分），=27m（1分）。答：位移大小27m（1分）。陷阱：直接代t=4s会得到24m的错误答案。"}, {"id": "math-01", "subject": "数学", "type": "single", "points": 5, "knowledge": "集合符号（∈/⊆）", "source": "高一上第一次月考", "stem": "下列关系中，正确的有（ ）", "options": {"A": "∅∈{0}", "B": "√2∈Q", "C": "Q⊆Z", "D": "−2∈Z"}, "answer": "D", "explain": "A错：∅是集合不是元素，应为∅⊆{0}；B错：√2是无理数，√2∉Q；C错：Q⊄Z，如1/2∈Q但1/2∉Z；D对：−2是整数。"}, {"id": "math-02", "subject": "数学", "type": "single", "points": 5, "knowledge": "Venn图与集合运算", "source": "高一上第一次月考", "stem": "已知全集U={0,1,2,3,4}，集合A={0,2,4}，集合B={2,3,4}，则如图所示的阴影部分表示的集合为（ ）。（图中阴影部分为矩形内除A、B两圆相交部分之外的所有区域，即A∩B在全集U中的补集）", "options": {"A": "{0,2,3,4}", "B": "{0,1,3}", "C": "{2,4}", "D": "{1}"}, "answer": "B", "explain": "A∩B={2,4}，阴影部分为∁U(A∩B)={0,1,3}。"}, {"id": "math-03", "subject": "数学", "type": "single", "points": 5, "knowledge": "全称量词命题的否定", "source": "高一上第一次月考", "stem": "已知命题p：∀x>0，x²−1≥0，则命题p的否定为（ ）", "options": {"A": "∀x≤0，x²−1<0", "B": "∀x>0，x²−1<0", "C": "∃x₀≤0，x₀²−1<0", "D": "∃x₀>0，x₀²−1<0"}, "answer": "D", "explain": "全称量词命题的否定：∀改∃，结论否定，量词的范围（x>0）保持不变。"}, {"id": "math-04", "subject": "数学", "type": "single", "points": 5, "knowledge": "分式不等式", "source": "高一上第一次月考", "stem": "不等式(x−1)/(x−2)≥0的解集为（ ）", "options": {"A": "{x|1≤x≤2}", "B": "{x|x≤1或x≥2}", "C": "{x|1≤x<2}", "D": "{x|x>2或x≤1}"}, "answer": "D", "explain": "等价于{(x−1)(x−2)≥0, x−2≠0}，解得x>2或x≤1。注意分母不为零，x=2要舍去。"}, {"id": "math-05", "subject": "数学", "type": "single", "points": 5, "knowledge": "子集个数", "source": "高一上第一次月考", "stem": "已知集合A={x|0≤x<4, x∈N*}，则集合A的子集的个数为（ ）", "options": {"A": "32", "B": "16", "C": "8", "D": "4"}, "answer": "C", "explain": "N*是正整数集，A={1,2,3}，共3个元素，子集个数为2³=8。"}, {"id": "math-06", "subject": "数学", "type": "single", "points": 5, "knowledge": "充分必要条件", "source": "高一上第一次月考", "stem": "已知p：0<x<2，q：−1<x<3，则q是p的（ ）", "options": {"A": "充分不必要条件", "B": "必要不充分条件", "C": "充要条件", "D": "既不充分也不必要条件"}, "answer": "B", "explain": "p⇒q（(0,2)⊂(−1,3)），但q⇏p，所以p是q的充分不必要条件，即q是p的必要不充分条件。"}, {"id": "math-07", "subject": "数学", "type": "single", "points": 5, "knowledge": "集合包含关系求参数", "source": "高一上第一次月考", "stem": "已知集合A={x|a−1≤x≤2a+1}，B={x|−3≤x≤3}，且A∩B=A，则实数a的取值范围是（ ）", "options": {"A": "[−2,1]", "B": "(−2,1)", "C": "(−∞,−2)", "D": "(−∞,1]"}, "answer": "D", "explain": "A∩B=A即A⊆B。若A=∅（a<−2）显然成立；若A≠∅，需a−1≥−3且2a+1≤3，得−2≤a≤1。合并得a≤1。易漏点：A为空集的情形。"}, {"id": "math-08", "subject": "数学", "type": "single", "points": 5, "knowledge": "基本不等式与恒成立", "source": "高一上第一次月考", "stem": "已知x>0，y>0，且x+y=5，若4/(x+1)+1/(y+2)≥2m+1恒成立，则实数m的取值范围是（ ）", "options": {"A": "m≤1/16", "B": "m≤2/5", "C": "m≤1/2", "D": "m≤1/4"}, "answer": "A", "explain": "x+1+y+2=8。4/(x+1)+1/(y+2)=(1/8)[4/(x+1)+1/(y+2)][(x+1)+(y+2)]≥(1/8)(5+2√4)=9/8，当且仅当x=13/3、y=2/3时取等。由2m+1≤9/8得m≤1/16。"}, {"id": "math-09", "subject": "数学", "type": "multi", "points": 6, "knowledge": "集合元素的互异性", "source": "高一上第一次月考", "stem": "设集合A={−1, x+2, x²−2x}，且3∈A，则x的值可以为（ ）", "options": {"A": "3", "B": "−3", "C": "−1", "D": "1"}, "answer": "AC", "explain": "若x+2=3得x=1，此时A={−1,3,−1}违背互异性，舍去；若x²−2x=3得x=3或x=−1，x=3时A={−1,5,3}成立，x=−1时A={−1,1,3}成立。故x=3或x=−1。（注：答案整理表备注误作x=−3，已据原卷核对更正。）"}, {"id": "math-10", "subject": "数学", "type": "multi", "points": 6, "knowledge": "不等式的性质", "source": "高一上第一次月考", "stem": "十六世纪中叶，英国数学家雷科德在《砺智石》一书中首先把“=”作为等号使用，后来英国数学家哈利奥特引入“<”和“>”符号，对不等式的发展影响深远。若a>b>1，c>0，则下列不等式一定成立的是（ ）。", "options": {"A": "a²−bc>b²−ac", "B": "c≥(b+ac)/(a+bc)", "C": "a/b>(a+c)/(b+c)", "D": "bc/a>ac/b"}, "answer": "AC", "explain": "A：a²−b²>bc−ac即(a−b)(a+b+c)>0，成立；B：等价于c²≥1，c>0不能保证，取c=0.5即为反例；C：等价于ac>bc即a>b，成立；D：等价于b²>a²，与a>b矛盾。"}, {"id": "math-11", "subject": "数学", "type": "multi", "points": 6, "knowledge": "基本不等式求最值", "source": "高一上第一次月考", "stem": "已知正数a，b满足2a+b=1，则（ ）", "options": {"A": "ab的最大值为1/8", "B": "1/a+1/b的最小值为4", "C": "√(2a)+√b的最小值为√2", "D": "a²+b²的最小值为1/5"}, "answer": "AD", "explain": "A：ab=(2a·b)/2≤((2a+b)/2)²/2=1/8；B：1/a+1/b的最小值为3+2√2≠4；C：令u=√(2a)、v=√b，则u²+v²=1，u+v>1无最小值（下确界为1）；D：由柯西不等式(4+1)(a²+b²)≥(2a+b)²=1，得a²+b²≥1/5。"}, {"id": "math-12", "subject": "数学", "type": "fill", "points": 5, "knowledge": "分段函数求值", "source": "高一上第一次月考", "stem": "已知f(x)={x²+1, x≥0; −x+1, x<0}，则f[f(−2)]=______。", "answer": "10", "explain": "先算内层：f(−2)=−(−2)+1=3；再算外层：f(3)=3²+1=10。关键：根据自变量的范围选对解析式。"}, {"id": "math-13", "subject": "数学", "type": "fill", "points": 5, "knowledge": "不等式范围（待定系数法）", "source": "高一上第一次月考", "stem": "已知实数x，y满足−4≤x−y≤−1，−1≤4x−y≤5，则t=9x−y的取值范围是______。", "answer": "[−1,20]", "explain": "待定系数：设9x−y=a(x−y)+b(4x−y)，解得a=−5/3，b=8/3。则t=−5/3(x−y)+8/3(4x−y)。由−4≤x−y≤−1得5/3≤−5/3(x−y)≤20/3，由−1≤4x−y≤5得−8/3≤8/3(4x−y)≤40/3，相加得−1≤t≤20。"}, {"id": "math-14", "subject": "数学", "type": "fill", "points": 5, "knowledge": "集合的表示（值域/定义域）", "source": "高一上第一次月考", "stem": "已知A={y|y=x²−2x−8, x∈R}，B={x|y=√(x+9)}，那么集合A与B的关系为______。", "answer": "B=A", "explain": "A是二次函数的值域：y=(x−1)²−9≥−9，即A={y|y≥−9}；B是函数y=√(x+9)的定义域：x+9≥0即B={x|x≥−9}。作为实数集两者都是[−9,+∞)，故B=A。易错点：代表元素y/x只是记号，不影响集合本身。"}, {"id": "math-15", "subject": "数学", "type": "solve", "points": 13, "knowledge": "集合的交并补运算", "source": "高一上第一次月考", "stem": "已知集合A={x|−1≤x<3}，B={x|1<3x−5<16}，（1）求A∪B；（2）求A∩B；（3）求∁R A∩B。", "answer": "（1）A∪B={x|−1≤x<7}；（2）A∩B={x|2<x<3}；（3）∁R A∩B={x|3≤x<7}", "explain": "关键步骤：先化简B：1<3x−5<16得2<x<7。（1）并集取两集合的合并：{x|−1≤x<7}；（2）交集取公共部分：{x|2<x<3}；（3）先求补集∁R A={x|x<−1或x≥3}，再与B取交得{x|3≤x<7}。注意端点开闭。"}, {"id": "math-16", "subject": "数学", "type": "solve", "points": 15, "knowledge": "函数定义域与集合包含", "source": "高一上第一次月考", "stem": "已知函数f(x)=√(3−x)+1/√(x+2)的定义域为集合A，B={x|x<a}。（1）求集合A；（2）若A⊆B，求a的取值范围。", "answer": "（1）A={x|−2<x≤3}；（2）a>3，即(3,+∞)", "explain": "（1）√(3−x)有意义需3−x≥0即x≤3；1/√(x+2)有意义需x+2>0即x>−2（分母不为零且根号内为正）。取交集得A={x|−2<x≤3}。（2）A⊆B={x|x<a}，A中最大元素x=3必须满足3<a，故a>3。"}, {"id": "math-17", "subject": "数学", "type": "solve", "points": 15, "knowledge": "一元二次不等式恒成立", "source": "高一上第一次月考", "stem": "已知函数f(x)=mx²−mx−1。（1）若m=1/2，求不等式f(x)<0的解集；（2）若关于x的不等式f(x)<0对一切x∈R恒成立，求实数m的取值范围。", "answer": "（1）{x|−1<x<2}；（2）{m|−4<m≤0}", "explain": "（1）m=1/2时化为x²−x−2<0，因式分解(x+1)(x−2)<0，解得−1<x<2。（2）m=0时−1<0恒成立；m≠0时需开口向下（m<0）且判别式Δ=m²+4m<0，解得−4<m<0。合并得−4<m≤0。易漏点：m=0的单独讨论。"}, {"id": "math-18", "subject": "数学", "type": "solve", "points": 17, "knowledge": "基本不等式应用与二次函数", "source": "高一上第一次月考", "stem": "如图，某人计划用篱笆围成一个一边靠墙（墙足够长）的矩形菜园。设菜园的长为x米，宽为y米。（1）若菜园面积为36平方米，则x，y为何值时，所用篱笆总长最小？（2）若使用的篱笆总长为30米，把菜园面积S表示为长x的函数：①当菜园面积不小于100平方米时，求x的取值范围；②求函数S(x)的值域，并指出面积最大时x，y的值。", "answer": "（1）x=6√2米，y=3√2米时篱笆总长最小；（2）S(x)=−x²/2+15x（0<x<30）；①10≤x≤20；②值域(0,225/2]，x=15、y=7.5时面积最大225/2", "explain": "（1）xy=36，篱笆总长为x+2y≥2√(2xy)=12√2，当且仅当x=2y即x=6√2、y=3√2时取等。（2）由x+2y=30得y=(30−x)/2，S(x)=x(30−x)/2=−x²/2+15x（0<x<30）。①S≥100化为x²−30x+200≤0，分解(x−10)(x−20)≤0，得10≤x≤20。②配方S(x)=−(x−15)²/2+225/2，开口向下，对称轴x=15在定义域内，故Smax=225/2，此时y=7.5；x→0或30时S→0，值域为(0,225/2]。"}, {"id": "math-19", "subject": "数学", "type": "solve", "points": 17, "knowledge": "存在量词命题与充分必要条件", "source": "高一上第一次月考", "stem": "已知∃x∈R，2mx²+mx+1/8<0，记实数m的取值范围为集合M。（1）求集合M；（2）已知集合N={x|x²+(1−a)x−a>0}，若“x∈N”是“x∈M”的充分不必要条件，求实数a的取值范围。", "answer": "（1）M={m|m<0或m>1}；（2）a≥1", "explain": "（1）m=0时1/8<0不成立；m<0时开口向下，必存在x使不等式成立；m>0时需Δ=m²−m>0，解得m>1。综上M={m|m<0或m>1}。（2）“x∈N是x∈M的充分不必要条件”即N⫋M。由x²+(1−a)x−a>0得(x−a)(x+1)>0。分类：a=−1时N={x|x≠−1}⊄M；a<−1时N={x|x<a或x>−1}⊄M；a>−1时N={x|x<−1或x>a}，要N⊂M需a≥1。综上a≥1。"}, {"id": "che-01", "subject": "化学", "type": "single", "points": 4, "knowledge": "化学实验安全", "source": "化学专题练习卷（2026-10-19）", "stem": "下列做法符合实验安全要求的是（ ）", "options": {"A": "剩余的钠块放回原试剂瓶", "B": "金属钠着火时使用泡沫灭火器灭火", "C": "浓硫酸与氢氧化钠固体放在同一实验橱内", "D": "新制氯水保存在棕色广口瓶中，置于避光阴凉处"}, "answer": "A", "explain": "A 对：钠是活泼金属，剩余钠块应放回原试剂瓶，不能随意丢弃；B 错：钠着火不能用泡沫灭火器（泡沫中的水和二氧化碳都会与钠反应），应用沙土扑灭；C 错：酸和碱应分开存放；D 错：氯水是液体，应保存在棕色细口瓶中，不是广口瓶。故选 A。"}, {"id": "che-02", "subject": "化学", "type": "single", "points": 4, "knowledge": "化学基本观念", "source": "化学专题练习卷（2026-10-19）", "stem": "构建化学基本观念是学好化学的基础。下列认识错误的是（ ）", "options": {"A": "元素观：物质是由元素组成的", "B": "分类观：H2O 和 Al2O3 均是氧化物", "C": "守恒观：1g 碳与 1g 氧气充分反应，生成 2g 二氧化碳", "D": "转化观：化学变化有新物质生成，其本质是原子的重新组合"}, "answer": "C", "explain": "A 对：物质都是由元素组成的；B 对：H2O 和 Al2O3 都是由两种元素组成、其中一种是氧元素的化合物，属于氧化物；C 错：1g 碳完全燃烧需要约 2.67g 氧气，1g 氧气只够生成约 1.375g 二氧化碳（氧气不足、碳有剩余），不可能生成 2g；D 对：化学变化的本质就是原子的重新组合。故选 C。"}, {"id": "che-03", "subject": "化学", "type": "single", "points": 4, "knowledge": "阿伏加德罗常数", "source": "化学专题练习卷（2026-10-19）", "stem": "NA 表示阿伏加德罗常数的值，下列叙述正确的是（ ）", "options": {"A": "22g CO2 所含有的分子数为 0.5NA", "B": "含 0.1mol BaCl2 的溶液中 Cl⁻ 数为 0.1NA", "C": "11.2L CO2 所含有的分子数为 0.5NA", "D": "7.8g Na2O2 中含有的离子总数为 0.4NA"}, "answer": "A", "explain": "A 对：22g CO2 为 0.5mol，分子数为 0.5NA；B 错：0.1mol BaCl2 电离出 0.2mol Cl⁻，应为 0.2NA；C 错：没说标准状况，11.2L 气体的物质的量不一定是 0.5mol；D 错：7.8g Na2O2 为 0.1mol，含 0.2mol Na⁺ 和 0.1mol O₂²⁻，离子总数为 0.3NA。故选 A。"}, {"id": "che-04", "subject": "化学", "type": "single", "points": 4, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "下列关于钠及其化合物的说法正确的是（ ）", "options": {"A": "Na2O 久置于空气中，最终转化为 NaHCO3", "B": "Na2O 与 Na2O2 都能和水反应生成碱，它们都是碱性氧化物", "C": "Na2CO3 溶液能与酸溶液反应，但不能与碱溶液反应", "D": "Na 投入 MgCl2 溶液中生成白色沉淀和无色气体"}, "answer": "D", "explain": "A 错：Na2O 久置空气中先变成 NaOH，最终变成 Na2CO3，不是 NaHCO3；B 错：Na2O2 与水反应除生成碱外还有 O2 生成，不属于碱性氧化物；C 错：Na2CO3 能与澄清石灰水等碱反应生成 CaCO3 沉淀；D 对：Na 先与水反应生成 NaOH 和 H2，NaOH 再与 MgCl2 反应生成白色 Mg(OH)2 沉淀。故选 D。"}, {"id": "che-05", "subject": "化学", "type": "single", "points": 4, "knowledge": "实验现象与结论", "source": "化学专题练习卷（2026-10-19）", "stem": "下列有关实验现象与分析或结论都正确的是（ ）", "options": {"A": "光照新制氯水有气泡冒出——氯水中含有 Cl2，光照 Cl2 逸出", "B": "氯水中加入 NaOH 溶液，氯水黄绿色消失——氯水中有 HClO 分子存在", "C": "向镁粉中加入久置的氯水，有无色无味的气体产生——产生的气体是 H2", "D": "向氯水中加入盐酸酸化，再加入硝酸银溶液产生白色沉淀——氯水中有 Cl⁻ 存在"}, "answer": "C", "explain": "A：现象对但结论错——光照氯水冒气泡是因为 HClO 见光分解放出 O2，不是 Cl2 逸出；B：黄绿色消失只能证明有 Cl2（被 NaOH 吸收了），不能证明有 HClO；C 对：久置的氯水相当于稀盐酸，Mg 与盐酸反应放出无色无味的 H2；D：加盐酸酸化引入了 Cl⁻，再加 AgNO3 有沉淀不能证明原氯水中有 Cl⁻。故选 C。"}, {"id": "che-06", "subject": "化学", "type": "single", "points": 4, "knowledge": "阿伏加德罗定律", "source": "化学专题练习卷（2026-10-19）", "stem": "温度、压强相同时，等体积的两容器内，一个盛 CO2，另一个盛 H2，则两容器内所盛气体相比，下列结论一定不正确的是（ ）", "options": {"A": "分子个数比为 1∶1", "B": "密度比为 22∶1", "C": "原子个数比为 1∶1", "D": "质量比为 22∶1"}, "answer": "C", "explain": "同温同压同体积 → 两容器气体分子数相等。A 对：分子数比 1∶1；B 对：密度比 = 摩尔质量比 = 44∶2 = 22∶1；C 错：CO2 每个分子 3 个原子、H2 每个分子 2 个原子，原子数比应为 3∶2，所以\"1∶1\"一定不正确；D 对：质量比 = 44∶2 = 22∶1。故选 C。"}, {"id": "che-07", "subject": "化学", "type": "single", "points": 4, "knowledge": "氯气和氯水", "source": "化学专题练习卷（2026-10-19）", "stem": "下列关于氯气和氯水的说法中正确的是（ ）", "options": {"A": "红热的铁丝在 Cl2 中剧烈燃烧生成 FeCl2", "B": "氯气是一种无色、密度比空气大的有毒气体", "C": "新制氯水能杀菌消毒是因为 Cl2 有毒，能毒杀细菌", "D": "氯水放置数天后酸性增强"}, "answer": "D", "explain": "A 错：红热铁丝在 Cl2 中燃烧生成 FeCl3（氯气强氧化性，铁被氧化到 +3 价）；B 错：氯气是黄绿色气体，不是无色；C 错：新制氯水杀菌是因为 HClO 有强氧化性，不是 Cl2 的毒性；D 对：HClO 见光分解生成 HCl，久置的氯水酸性增强。故选 D。"}, {"id": "che-08", "subject": "化学", "type": "single", "points": 4, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "下列物质所含原子数由大到小排列的是（ ）①0.5mol NH3  ②4g H2  ③标准状况下，0.3mol CO2  ④0.2mol H3PO4", "options": {"A": "①④③②", "B": "④③②①", "C": "②③④①", "D": "②①④③"}, "answer": "D", "explain": "① 0.5mol NH3 含 0.5×4 = 2mol 原子；② 4g H2 为 2mol，含 2×2 = 4mol 原子；③ 0.3mol CO2 含 0.3×3 = 0.9mol 原子；④ 0.2mol H3PO4 含 0.2×8 = 1.6mol 原子。由大到小：②①④③。故选 D。"}, {"id": "che-09", "subject": "化学", "type": "single", "points": 4, "knowledge": "气体摩尔体积", "source": "化学专题练习卷（2026-10-19）", "stem": "下列说法正确的是（ ）", "options": {"A": "同温、同压下，相同质量的气体都占有相同的体积", "B": "在标准状况下，1mol 任何物质的体积均为 22.4L", "C": "1mol 某气体的体积约为 22.4L，该气体所处的状况一定是标准状况", "D": "同温、同压下，相同体积的气体都含有相同数目的分子"}, "answer": "D", "explain": "A 错：应为\"相同物质的量\"的气体，不是相同质量；B 错：应为\"1mol 任何气体\"，不是任何物质；C 错：1mol 气体体积约为 22.4L 时，温度和压强可以有多种组合，不一定是标准状况；D 对：阿伏加德罗定律——同温同压下，相同体积的气体含有相同数目的分子。故选 D。"}, {"id": "che-10", "subject": "化学", "type": "multi", "points": 6, "knowledge": "化学实验装置", "source": "化学专题练习卷（2026-10-19）", "stem": "用下列实验装置进行相应实验，装置正确且能达到相应实验目的的是（ ）甲：气体依次通过饱和 NaCl 溶液、浓硫酸（长进短出）；乙：坩埚中放钠块加热；丙：稀释浓硫酸；丁：加热 Na2CO3 固体", "options": {"A": "用图甲除去 Cl2 中的 HCl 并干燥", "B": "用图乙装置进行钠的燃烧实验", "C": "用图丙装置稀释浓硫酸", "D": "用图丁制备二氧化碳"}, "answer": "AB", "explain": "甲：除 Cl2 中 HCl 先经饱和食盐水（Cl2 溶解度小、HCl 极易溶），再经浓硫酸干燥，长进短出正确，能达到目的；乙：坩埚加热钠块进行钠的燃烧实验，装置正确；丙：稀释浓硫酸若在烧杯中将浓硫酸沿玻璃棒缓慢倒入水中并搅拌则正确，请对照原卷图确认容器；丁错：Na2CO3 受热不分解，不能用加热法制备 CO2。故选 AB（C 以原卷图为准）。"}, {"id": "che-11", "subject": "化学", "type": "fill", "points": 12, "knowledge": "化学方程式书写", "source": "化学专题练习卷（2026-10-19）", "stem": "写出下列过程发生的化学方程式：（1）钠块在氧气中加热，生成淡黄色固体：＿＿；（2）氢气在氯气中燃烧：＿＿；（3）细铁丝在氯气中燃烧：＿＿；（4）次氯酸见光分解：＿＿；（5）工业生产漂白粉：＿＿；（6）往 CuSO4 溶液中滴加 NaOH 溶液：＿＿。", "options": null, "answer": ["2Na + O2 = 【条件：△】 Na2O2", "H2 + Cl2 = 【条件：点燃】 2HCl", "2Fe + 3Cl2 = 【条件：点燃】 2FeCl3", "2HClO = 【条件：光照】 2HCl + O2↑", "2Cl2 + 2Ca(OH)2 = CaCl2 + Ca(ClO)2 + 2H2O", "CuSO4 + 2NaOH = Cu(OH)2↓ + Na2SO4"], "explain": "（1）钠在氧气中加热生成淡黄色固体 Na2O2，注意是加热不是点燃；（2）H2 在 Cl2 中燃烧生成 HCl；（3）Fe 在 Cl2 中燃烧生成 FeCl3——氯气氧化性强，铁直接被氧化到 +3 价，不生成 FeCl2；（4）HClO 见光分解是氯水久置变质、酸性增强的原因；（5）Cl2 通入石灰乳制漂白粉，有效成分是 Ca(ClO)2；（6）生成蓝色 Cu(OH)2 沉淀。条件（点燃/加热/光照）和 ↑↓ 别漏。"}, {"id": "che-12a", "subject": "化学", "type": "fill", "points": 8, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "（1）1.204×10²³ 个 NO 的物质的量为＿＿mol，其 N 原子的质量为＿＿g；（2）质量相同的 SO2 和 SO3，物质的量之比是＿＿，所含氧原子个数比是＿＿。", "options": null, "answer": ["0.2", "2.8", "5:4", "5:6"], "explain": "（1）1.204×10²³ ÷ 6.02×10²³ = 0.2mol；N 原子 0.2mol，质量 0.2×14 = 2.8g。（2）设质量同为 m：n(SO2) = m/64，n(SO3) = m/80，物质的量之比 = 80∶64 = 5∶4；氧原子个数比 = (5×2)∶(4×3) = 10∶12 = 5∶6。"}, {"id": "che-12b", "subject": "化学", "type": "fill", "points": 6, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "（3）标准状况下，3.4g NH3 与＿＿L H2S 气体含有相同数目的氢原子；（4）标准状况下，1.28g 气态氧化物 RO2 的体积为 448mL，则 R 的相对原子质量为＿＿；（5）标准状况下，V L CH4 气体中含有 a 个氢原子，则阿伏加德罗常数的值可表示为＿＿。", "options": null, "answer": ["6.72", "32", "5.6a/V||22.4a/4V"], "explain": "（3）3.4g NH3 为 0.2mol，含 H 原子 0.6mol；需要 H2S 0.3mol，标况体积 0.3×22.4 = 6.72L。（4）448mL = 0.02mol，M = 1.28÷0.02 = 64g/mol，R = 64−32 = 32。（5）n(CH4) = V/22.4，H 原子数 = (4V/22.4)×NA = a，得 NA = 22.4a/4V = 5.6a/V。"}, {"id": "che-13a", "subject": "化学", "type": "fill", "points": 10, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "（1）Na 与水反应的化学方程式为＿＿；（2）Na2O2 与二氧化碳反应的化学方程式为＿＿；（3）Na2CO3 粉末与过量盐酸反应的化学方程式为＿＿；（4）NaH 中氢元素的化合价为＿＿价，NaH 与水反应的化学方程式为＿＿。", "options": null, "answer": ["2Na + 2H2O = 2NaOH + H2↑", "2Na2O2 + 2CO2 = 2Na2CO3 + O2", "Na2CO3 + 2HCl = 2NaCl + H2O + CO2↑", "-1", "NaH + H2O = NaOH + H2↑"], "explain": "（1）钠与水剧烈反应放出 H2；（2）Na2O2 与 CO2 反应放出 O2，可作供氧剂；（3）盐酸过量，碳酸钠中的碳全部以 CO2 放出；（4）NaH 中 H 为 −1 价（活泼金属的氢化物中 H 显 −1 价），与水反应：NaH + H2O = NaOH + H2↑，生成的 H2 可燃。"}, {"id": "che-13b", "subject": "化学", "type": "single", "points": 2, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "将一小块钠投入 CuSO4 溶液中，观察到的现象是（ ）①钠浮于液面上 ②熔化成小球 ③发出嘶嘶的响声，放出气体 ④有蓝色沉淀产生 ⑤析出红色的铜", "options": {"A": "①②③", "B": "①②③④", "C": "②③④⑤", "D": "①③④⑤"}, "answer": "B", "explain": "Na 先与水反应：浮于液面（密度比水小）、熔成小球（熔点低、反应放热）、嘶嘶响并放出 H2；生成的 NaOH 再与 CuSO4 反应生成蓝色 Cu(OH)2 沉淀。钠不能从 CuSO4 溶液中置换出铜（它先跟水反应了），⑤错。故选 B。"}, {"id": "che-14a", "subject": "化学", "type": "fill", "points": 10, "knowledge": "氯气的实验室制备", "source": "化学专题练习卷（2026-10-19）", "stem": "实验室用 MnO2 与浓盐酸制备干燥纯净的氯气（B 瓶除杂、C 瓶干燥、E 烧杯 NaOH 尾气吸收）。（1）装置 A 中反应的化学方程式为＿＿；（2）B 中所盛试剂为＿＿（填序号：A.氢氧化钠溶液 B.饱和食盐水 C.浓硫酸 D.澄清石灰水），C 中所盛试剂为＿＿；（3）尾气处理反应的化学方程式为＿＿；（4）新制氯水呈黄绿色说明其中含有＿＿（填化学式）；将紫色石蕊溶液滴入氯水，观察到的现象是＿＿，说明其中含有＿＿。", "options": null, "answer": ["MnO2 + 4HCl(浓) = 【条件：△】 MnCl2 + Cl2↑ + 2H2O", "B", "C", "Cl2 + 2NaOH = NaCl + NaClO + H2O", "Cl2", "先变红后褪色||变红后褪色", "H+、HClO||H+和HClO||氢离子、次氯酸||氢离子和次氯酸"], "explain": "（1）MnO2 与浓盐酸加热制 Cl2，注意盐酸要标\"浓\"、要加热；（2）B 用饱和食盐水除 HCl（Cl2 在其中溶解度小），C 用浓硫酸干燥——先除杂后干燥；（3）Cl2 尾气用 NaOH 溶液吸收；（4）黄绿色是 Cl2 的颜色；紫色石蕊先变红（氯水显酸性，有 H⁺）后褪色（HClO 的漂白性），说明同时含有 H⁺ 和 HClO。"}, {"id": "che-14b", "subject": "化学", "type": "fill", "points": 12, "knowledge": "漂白粉变质探究", "source": "化学专题练习卷（2026-10-19）", "stem": "有一瓶密封不严的漂白粉样品，肯定含有 CaCl2。假设①：该漂白粉未变质，含有＿＿；假设②：该漂白粉全部变质，含有＿＿。实验 1：取样加稀盐酸，有气泡产生 → 则假设＿＿不成立；实验 2：向实验 1 反应后的试管中滴加品红溶液，振荡。若品红褪色，结合实验 1 则假设＿＿成立；若品红不褪色，则假设＿＿成立。（假设③：部分变质，既含 Ca(ClO)2 又含 CaCO3）", "options": null, "answer": ["Ca(ClO)2", "CaCO3", "①||1", "③||3", "②||2"], "explain": "漂白粉变质原理：Ca(ClO)2 + CO2 + H2O = CaCO3↓ + 2HClO。实验 1 加稀盐酸有气泡 → 有 CaCO3 → \"未变质\"的假设①不成立；实验 2 品红褪色 → 还有 Ca(ClO)2（能使品红褪色）→ 部分变质，假设③成立；品红不褪色 → Ca(ClO)2 已耗尽 → 全部变质，假设②成立。"}], "dictation": [{"answer": "2Na + 2H2O = 2NaOH + H2↑", "explain": "思路：钠是活泼金属，与水剧烈反应生成氢氧化钠和氢气。四步checklist：化学式写对→配平（Na 2个、H2O 2个）→无特殊条件→H2是气体加↑。易错：漏写H2、漏↑。她13-(1)漏写H2且未配平被扣光。", "id": "chem-01", "prompt": "钠与水反应", "set": "方程式默写", "subject": "化学", "tags": ["钠", "配平", "气体符号"]}, {"answer": "4Na + O2 = 2Na2O", "explain": "思路：常温下钠被氧化生成氧化钠。关键：条件决定产物——常温→Na2O，点燃→Na2O2。她11-(1)自创了不明条件“R△”，产物也写错，0分。", "id": "chem-02", "prompt": "钠在常温下与氧气反应", "set": "方程式默写", "subject": "化学", "tags": ["钠", "条件决定产物"]}, {"answer": "2Na + O2 = 【条件：点燃】 Na2O2", "explain": "思路：点燃时生成淡黄色的过氧化钠Na2O2。对比记忆：常温→Na2O，点燃→Na2O2。易错：把Na2O2写成NaO2。", "id": "chem-03", "prompt": "钠在氧气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["钠", "条件", "过氧化钠"]}, {"answer": "2Na2O2 + 2H2O = 4NaOH + O2↑", "explain": "思路：Na2O2中O为-1价，歧化为O2（0价）和OH-中的O（-2价）。配平：先定Na2O2为2，再配H2O为2。易错：漏O2↑。", "id": "chem-04", "prompt": "过氧化钠与水反应", "set": "方程式默写", "subject": "化学", "tags": ["过氧化钠", "配平"]}, {"answer": "2Na2O2 + 2CO2 = 2Na2CO3 + O2", "explain": "思路：呼吸面具/潜水艇供氧剂原理，CO2→O2。她13-(2)写成Na2O2+CO2=2Na2CO3+O2未配平被扣1分——配平是按规则必扣分的，亲手配10遍。", "id": "chem-05", "prompt": "过氧化钠与二氧化碳反应（呼吸面具供氧原理）", "set": "方程式默写", "subject": "化学", "tags": ["过氧化钠", "配平", "13题错题"]}, {"answer": "2NaHCO3 = 【条件：加热】 Na2CO3 + CO2↑ + H2O", "explain": "思路：NaHCO3不稳定，受热分解。配平：2个NaHCO3。易错：漏条件加热、漏↑。", "id": "chem-06", "prompt": "碳酸氢钠受热分解", "set": "方程式默写", "subject": "化学", "tags": ["碳酸氢钠", "条件"]}, {"answer": "Na2CO3 + 2HCl = 2NaCl + CO2↑ + H2O", "explain": "思路：强酸制弱酸，碳酸盐+酸→CO2↑。她13-(2)这个写对拿了满分，会写的要保持。注意：盐酸少量时先生成NaHCO3，足量才放出CO2。", "id": "chem-07", "prompt": "碳酸钠与足量盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["碳酸钠", "气体符号"]}, {"answer": "2Al + 6HCl = 2AlCl3 + 3H2↑", "explain": "思路：Al是活泼金属，与非氧化性酸生成AlCl3和H2。配平：Al 2个、HCl 6个、H2 3个。", "id": "chem-08", "prompt": "铝与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "配平"]}, {"answer": "2Al + 2NaOH + 2H2O = 2NaAlO2 + 3H2↑", "explain": "思路：Al既能与酸反应又能与强碱反应（两性金属的特性）。产物是偏铝酸钠NaAlO2和H2。配平：Al 2、NaOH 2、H2O 2。易错：漏写H2O、漏↑。", "id": "chem-09", "prompt": "铝与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性", "配平"]}, {"answer": "Al2O3 + 6HCl = 2AlCl3 + 3H2O", "explain": "思路：Al2O3是两性氧化物，与酸生成盐和水。配平：HCl 6个。", "id": "chem-10", "prompt": "氧化铝与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性氧化物"]}, {"answer": "Al(OH)3 + NaOH = NaAlO2 + 2H2O", "explain": "思路：Al(OH)3是两性氢氧化物，溶于强碱生成偏铝酸钠。注意H2O是2个，配平不要漏。", "id": "chem-11", "prompt": "氢氧化铝与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性"]}, {"answer": "2Fe + 3Cl2 = 【条件：点燃】 2FeCl3", "explain": "思路：Cl2是强氧化剂，把Fe氧化到+3价，生成FeCl3（棕褐色烟）。对比：Fe与盐酸只生成FeCl2+H2↑——她11-(3)把两者混了，还写出Fe3Cl2这种不存在的化学式。记住：氧化剂强弱决定价态，Cl2强→+3价，HCl弱→+2价。", "id": "chem-12", "prompt": "铁在氯气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["铁", "氯气", "11题错题"]}, {"answer": "Fe + 2HCl = FeCl2 + H2↑", "explain": "思路：Fe与非氧化性酸反应，Fe只到+2价，生成FeCl2和H2↑。对比记忆：Fe+Cl2→FeCl3，Fe+HCl→FeCl2。", "id": "chem-13", "prompt": "铁与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铁", "对比"]}, {"answer": "2FeCl2 + Cl2 = 2FeCl3", "explain": "思路：Cl2把Fe2+氧化为Fe3+，溶液由浅绿色变为棕黄色。这是Fe2+的检验思路之一。", "id": "chem-14", "prompt": "氯化亚铁溶液中通入氯气", "set": "方程式默写", "subject": "化学", "tags": ["铁", "氧化还原"]}, {"answer": "4Fe(OH)2 + O2 + 2H2O = 4Fe(OH)3", "explain": "思路：白色Fe(OH)2→灰绿色→红褐色Fe(OH)3。配平：Fe(OH)2 4个、O2 1个、H2O 2个。现象记忆：颜色渐变是考点。", "id": "chem-15", "prompt": "氢氧化亚铁在空气中被氧化", "set": "方程式默写", "subject": "化学", "tags": ["铁", "配平", "现象"]}, {"answer": "Fe2O3 + 6HCl = 2FeCl3 + 3H2O", "explain": "思路：Fe2O3（铁红）是碱性氧化物，与酸生成盐和水。配平：HCl 6个。", "id": "chem-16", "prompt": "氧化铁与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铁"]}, {"answer": "H2 + Cl2 = 【条件：点燃】 2HCl", "explain": "思路：苍白色火焰，生成HCl。她11-(2)涂改混乱得0分——这个式子必须一笔写对：H2+Cl2点燃→2HCl。", "id": "chem-17", "prompt": "氢气在氯气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "11题错题"]}, {"answer": "Cl2 + H2O ⇌ HCl + HClO", "explain": "思路：可逆反应（⇌）。氯水中含Cl2、HClO、H+、Cl-等。HClO是弱酸，有漂白性。易错：写成等号、漏写HClO。", "id": "chem-18", "prompt": "氯气与水反应（氯水的成分）", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "可逆", "漂白"]}, {"answer": "2HClO = 【条件：光照】 2HCl + O2↑", "explain": "思路：HClO不稳定，见光分解为HCl和O2——这就是氯水要避光保存、新制氯水久置变成稀盐酸的原因。她11-(4)写成HClO=H2O+Cl2↑，产物全错。", "id": "chem-19", "prompt": "次氯酸见光分解", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "11题错题", "光照"]}, {"answer": "Cl2 + 2NaOH = NaCl + NaClO + H2O", "explain": "思路：产物是NaClO（次氯酸钠）不是HClO——她14-(3)写成HClO被扣光。记忆：碱吸收氯气，Cl2歧化为Cl-和ClO-。配平：NaOH 2个。", "id": "chem-20", "prompt": "氯气与氢氧化钠溶液反应（尾气吸收）", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "14题错题", "尾气吸收"]}, {"answer": "MnO2 + 4HCl(浓） = 【条件：加热】 MnCl2 + Cl2↑ + 2H2O", "explain": "思路：二氧化锰+浓盐酸加热。四要素缺一不可：MnO2、浓HCl、加热、配平（HCl 4个、H2O 2个）。她14-(1)未配平、缺“浓”和“加热”被扣2分——按规则配平/条件/气体符号有问题各扣1分。", "id": "chem-21", "prompt": "实验室制取氯气", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "实验室制法", "14题错题"]}, {"answer": "2Ca(OH)2 + 2Cl2 = CaCl2 + Ca(ClO)2 + 2H2O", "explain": "思路：氯气通入石灰乳。漂白粉是混合物（CaCl2·Ca(ClO)2），有效成分是Ca(ClO)2——她14-(5)把两者混淆。配平：Ca(OH)2 2个、Cl2 2个、H2O 2个。她11-(5)配平也错了，重默10遍。", "id": "chem-22", "prompt": "工业制漂白粉", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "漂白粉", "14题错题"]}, {"answer": "Cu + 2H2SO4(浓） = 【条件：加热】 CuSO4 + SO2↑ + 2H2O", "explain": "思路：浓硫酸的强氧化性（+6价S→+4价SO2），Cu被氧化为CuSO4。必须加热、必须浓硫酸。配平：H2SO4 2个。", "id": "chem-23", "prompt": "铜与浓硫酸反应（加热）", "set": "方程式默写", "subject": "化学", "tags": ["浓硫酸", "氧化性"]}, {"answer": "C + 2H2SO4(浓） = 【条件：加热】 CO2↑ + 2SO2↑ + 2H2O", "explain": "思路：C被浓硫酸氧化为CO2，浓硫酸被还原为SO2。两个气体产物都要加↑。配平：H2SO4 2个、SO2 2个。", "id": "chem-24", "prompt": "碳与浓硫酸反应（加热）", "set": "方程式默写", "subject": "化学", "tags": ["浓硫酸", "配平"]}, {"answer": "SO2 + H2O ⇌ H2SO3", "explain": "思路：可逆反应，生成亚硫酸H2SO3（二元弱酸）。SO2是酸性氧化物。", "id": "chem-25", "prompt": "二氧化硫与水反应", "set": "方程式默写", "subject": "化学", "tags": ["硫", "可逆"]}, {"answer": "4NH3 + 5O2 = 【条件：催化剂、加热】 4NO + 6H2O", "explain": "思路：工业制硝酸第一步。NH3中N（-3价）→NO中N（+2价）。配平：NH3 4个、O2 5个、NO 4个、H2O 6个。条件催化剂（铂铑合金）+加热缺一不可。", "id": "chem-26", "prompt": "氨的催化氧化", "set": "方程式默写", "subject": "化学", "tags": ["氨", "催化氧化", "配平"]}, {"answer": "2NO + O2 = 2NO2", "explain": "思路：无色NO遇空气变红棕色NO2，是NO的特征检验。配平：NO 2个、NO2 2个。", "id": "chem-27", "prompt": "一氧化氮与氧气反应", "set": "方程式默写", "subject": "化学", "tags": ["氮", "现象"]}, {"answer": "3NO2 + H2O = 2HNO3 + NO", "explain": "思路：NO2与水歧化，生成硝酸和NO。配平：NO2 3个、HNO3 2个。", "id": "chem-28", "prompt": "二氧化氮与水反应", "set": "方程式默写", "subject": "化学", "tags": ["氮", "配平"]}, {"answer": "SiO2 + 2NaOH = Na2SiO3 + H2O", "explain": "思路：SiO2是酸性氧化物，与碱生成硅酸钠和水。这就是“盛碱液的玻璃瓶不能用玻璃塞”的原因（会生成Na2SiO3把瓶塞粘住）。", "id": "chem-29", "prompt": "二氧化硅与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["硅", "酸性氧化物"]}, {"answer": "SiO2 + 4HF = SiF4↑ + 2H2O", "explain": "思路：SiO2的特性——只与HF反应（其他酸都不反应），用于雕刻玻璃。配平：HF 4个，SiF4是气体加↑。", "id": "chem-30", "prompt": "二氧化硅与氢氟酸反应", "set": "方程式默写", "subject": "化学", "tags": ["硅", "特性"]}, {"answer": "奴隶社会代替原始社会是历史的进步。", "explain": "21题1分得分点。观点句先写，这是送分的第一句，写完再跟论据。她这句写出来了，要保持。", "id": "pol-01", "prompt": "21题得分点①：奴隶社会代替原始社会是什么性质？", "set": "标志性表述", "subject": "政治", "tags": ["社会形态更替", "21题"]}, {"answer": "生产关系一定要适应生产力状况的规律是人类社会发展的一般规律。一种社会形态代替另一种社会形态，究竟是历史的进步还是倒退，判断的主要标准，是看生产关系是否适应生产力的发展要求，是否符合人类社会发展的总趋势。", "explain": "21题3分得分点。她只写了零散表述丢了分。关键词：生产关系适应生产力、是否符合人类社会发展的总趋势。", "id": "pol-02", "prompt": "21题得分点②：判断社会形态更替是进步还是倒退的主要标准", "set": "标志性表述", "subject": "政治", "tags": ["历史规律", "21题"]}, {"answer": "奴隶社会代替原始社会后，金属工具的广泛使用、城市的出现、脑力劳动和体力劳动的分工等，这是历史的进步。", "explain": "21题3分得分点。她一个论据没写，观点空转。三个关键词必须一字不差：金属工具、城市、脑力劳动和体力劳动的分工。", "id": "pol-03", "prompt": "21题得分点④：奴隶社会进步性的具体表现（三个）", "set": "标志性表述", "subject": "政治", "tags": ["史实论据", "21题"]}, {"answer": "中华人民共和国的成立，彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃。", "explain": "22题3分得分点。她这题只拿2/8分，关键词全缺。四个“彻底结束”＋“从封建专制政治向人民民主的伟大飞跃”，一字不差背下来。", "id": "pol-04", "prompt": "22题得分点①：中华人民共和国成立的意义（“四个彻底结束”＋伟大飞跃）", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "中华人民共和国的成立，为实现由新民主主义向社会主义的过渡创造了前提条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路。", "explain": "22题3分得分点。关键词：过渡创造了前提条件、根本上改变发展方向、美好前景和现实道路。", "id": "pol-05", "prompt": "22题得分点②：新中国成立为过渡创造的前提条件", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "新中国的诞生，冲破了帝国主义的东方战线，极大地改变了世界政治力量的对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。", "explain": "22题2分得分点。关键词：东方战线、世界政治力量对比、被压迫民族。", "id": "pol-06", "prompt": "22题得分点③：新中国成立的世界意义", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。", "explain": "23题4分得分点。她缺了“必由之路/关键一招”丢5分。关键词：重要法宝、必由之路、关键一招（出现两次）。", "id": "pol-07", "prompt": "23题得分点②：改革开放的地位（“必由之路”“关键一招”）", "set": "标志性表述", "subject": "政治", "tags": ["改革开放", "23题"]}, {"answer": "①在半殖民地半封建社会的近代中国，资本主义道路走不通。②中国共产党的诞生使中国人民有了前进的主心骨，党领导各族人民夺取了新民主主义革命的伟大胜利。③中华人民共和国的成立，从根本上改变了中国社会的发展方向。④社会主义改造的完成，在中国建立起社会主义制度。总之：只有社会主义才能救中国。", "explain": "24题12分她只拿3分，缺②③两大得分块。先背四段骨架再填肉：旧路不通→党领导革命胜利→新中国转方向→社会主义改造建制度→总结句。", "id": "pol-08", "prompt": "24题骨架：“只有社会主义能救中国”四段论证＋总结句", "set": "标志性表述", "subject": "政治", "tags": ["社会主义", "24题"]}, {"answer": "不是。反射是太阳辐射被云层、地面直接弹回太空，属于削弱作用；大气逆辐射是大气吸收地面长波辐射后、再以长波辐射形式返还给地面的部分，属于保温作用。", "explain": "27(2)就栽在这：把“大气逆辐射”写成“反射”，6分只拿1分。记忆钩：逆辐射是“大气回赠给地面的热量”，方向是朝下的。", "id": "con-01", "prompt": "大气逆辐射和反射是一回事吗？", "set": "概念辨析", "subject": "地理", "tags": ["大气", "27题错题"]}, {"answer": "削弱作用：大气对太阳辐射的吸收、反射、散射，使到达地面的太阳辐射减少（白天降温）。保温作用：大气吸收地面辐射，并以大气逆辐射形式返还热量给地面（夜间保温）。", "explain": "28(2)把两者混为一谈，得出“太阳辐射强度与气温成反比”的错误结论，6分挂零。记住：削弱管白天，保温管夜晚。", "id": "con-02", "prompt": "大气的削弱作用和保温作用各指什么？", "set": "概念辨析", "subject": "地理", "tags": ["大气", "28题错题"]}, {"answer": "太阳辐射→（被大气削弱：吸收/反射/散射）→地面吸收→地面增温→地面辐射（长波）→大气吸收→大气增温→大气逆辐射→返还地面（保温）。根本热源是太阳辐射，直接热源是地面。", "explain": "27、28题的共同病根，约13分。每天默画一遍这张图，标出削弱三种形式和保温链条，直到闭眼能复述。", "id": "con-03", "prompt": "复述“大气的受热过程”完整链条", "set": "概念辨析", "subject": "地理", "tags": ["大气", "链条"]}, {"answer": "古登堡面约2900km，是地幔与地核的分界面；莫霍面平均约17km深，是地壳与地幔的分界面；软流层位于上地幔顶部，是岩浆的发源地。", "explain": "26(1)她把古登堡面写成4000，纯记忆分丢了。2900这个数字贴书桌——这是卷面直接考的。", "id": "con-04", "prompt": "古登堡面、莫霍面的深度和软流层的位置", "set": "概念辨析", "subject": "地理", "tags": ["地球圈层", "数字"]}, {"answer": "由里到外：光球层→色球层→日冕层。对应太阳活动：黑子在光球层，耀斑（日珥）在色球层。口诀：黑子在光球，耀斑在色球。", "explain": "26(3)她这题拿了满分，说明记得住——保持住，别还回去。", "id": "con-05", "prompt": "太阳大气层由里到外是哪三层？对应的太阳活动是什么？", "set": "概念辨析", "subject": "地理", "tags": ["太阳", "记忆"]}, {"answer": "对流层气温随高度升高而降低。近地面大气的主要直接热源是地面（地面辐射），不是太阳直接加热。", "explain": "26(4)她把“降低”写成“升高”，规律记反丢分。记忆：越高越冷，因为热源在脚下（地面）。", "id": "con-06", "prompt": "对流层气温随高度如何变化？近地面大气的直接热源是什么？", "set": "概念辨析", "subject": "地理", "tags": ["对流层", "26题错题"]}, {"answer": "古生代、中生代、新生代是“代”；第四纪是新生代里的一个“纪”，层级比代低。", "explain": "26(2)她把“新生代”等同于“第四纪”，是层级混淆丢2分。记住：代和纪是上下级，第四纪属于新生代。", "id": "con-07", "prompt": "地质年代：古生代、中生代、新生代和第四纪是什么关系？", "set": "概念辨析", "subject": "地理", "tags": ["地质年代", "26题错题"]}, {"answer": "辐射强：①纬度低太阳高度大；②晴天多，削弱作用弱；③海拔高空气稀薄，削弱作用弱。气温低：④空气稀薄，大气吸收地面辐射少，保温作用弱。", "explain": "28(2)她只答出②③，还推出“成反比”的错误结论，6分挂零。记住：辐射强弱看“削弱”，气温高低看“保温”，两套逻辑别串。", "id": "con-08", "prompt": "为什么青藏高原“太阳辐射强、气温却低”？", "set": "概念辨析", "subject": "地理", "tags": ["青藏高原", "28题错题"]}, {"answer": "病毒无细胞结构（只有蛋白质外壳+核酸）；蓝藻是原核细胞生物，有细胞结构（无核膜、无叶绿体）。", "explain": "21-(1)她疑似写成“无细胞结构”得0分——题干问的是有细胞结构的生物，别把病毒和蓝藻搞反。", "id": "con-09", "prompt": "病毒有细胞结构吗？蓝藻呢？", "set": "概念辨析", "subject": "生物", "tags": ["细胞", "21题错题"]}, {"answer": "有无以核膜为界限的细胞核。有→真核细胞，无→原核细胞（如细菌、蓝藻）。", "explain": "21-(2)她这个答对了。根本标准只有一个：核膜。", "id": "con-10", "prompt": "区分原核细胞和真核细胞的根本标准是什么？", "set": "概念辨析", "subject": "生物", "tags": ["细胞"]}, {"answer": "蓝藻含有藻蓝素和叶绿素，能进行光合作用，但没有叶绿体（原核生物没有叶绿体、线粒体等复杂细胞器）。", "explain": "21-(3)她写成“叶绿体”得0分——典型易错点：有叶绿素≠有叶绿体。", "id": "con-11", "prompt": "蓝藻含有什么色素？有叶绿体吗？", "set": "概念辨析", "subject": "生物", "tags": ["蓝藻", "21题错题"]}, {"answer": "自由水：游离态，可自由流动，是良好溶剂、参与化学反应、运输物质；结合水：与细胞内其他物质结合，是细胞结构的重要组成成分。代谢越旺盛，自由水与结合水的比值越高。", "explain": "22题连丢6分：自由水功能（良好溶剂）没写出来。记住：自由水管“活”（代谢），结合水管“结构”。", "id": "con-12", "prompt": "自由水和结合水有什么区别？", "set": "概念辨析", "subject": "生物", "tags": ["水", "22题错题"]}, {"answer": "①脱水数＝氨基酸数－肽链数；②蛋白质相对分子质量＝氨基酸总分子质量－18×脱水数；③一条肽链至少含1个游离氨基和1个游离羧基。", "explain": "23题她脱水数直接写51（氨基酸总数），正确是51-2=49；分子量882 vs 888漏项。这三公式默到条件反射。", "id": "con-13", "prompt": "蛋白质计算三公式", "set": "概念辨析", "subject": "生物", "tags": ["蛋白质", "23题错题", "公式"]}, {"answer": "中心碳原子上连接：一个氨基（-NH2）、一个羧基（-COOH）、一个氢原子（-H）、一个R基。结构式：H2N—C(R)(H)—COOH。", "explain": "23-(1)她用文字描述代替画图得0分——题目要求画图就必须画，文字描述不给分。亲手画50遍。", "id": "con-14", "prompt": "画出氨基酸的结构通式", "set": "概念辨析", "subject": "生物", "tags": ["氨基酸", "23题错题"]}, {"answer": "条件：水浴加热（50-65℃）。现象：出现砖红色沉淀。", "explain": "24-(1)她写“没有加热”得0分——“水浴”是关键限定词，直接加热不行。实验题先圈限定词。", "id": "con-15", "prompt": "斐林试剂检测还原糖的关键条件和现象是什么？", "set": "概念辨析", "subject": "生物", "tags": ["实验", "24题错题"]}, {"answer": "不能。Although本身已表转折，再加but重复。改法：Although he is tired, he keeps working. 或 He is tired, but he keeps working.", "explain": "作文硬伤第1条：Although play computer games can…, but it…——although和but连用是典型中式错误，见到就改。", "id": "con-16", "prompt": "Although和but能连用吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "连词"]}, {"answer": "不可数。a piece of advice（一则建议），不能说advices。", "explain": "作文：follow my advices→follow my advice。不可数名词没有复数形式。", "id": "con-17", "prompt": "advice可数吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "名词"]}, {"answer": "不对。a是单数冠词，后面必须跟单数：it is not a good thing。单复数必须一致：a thing / good things。", "explain": "作文硬伤：a good things——冠词a和复数things打架。写完检查：a/an后面一定是单数。", "id": "con-18", "prompt": "it is not a good things对吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "单复数"]}, {"answer": "stop doing：停止正在做的事（Stop playing games.）；stop to do：停下来去做另一件事。forget doing：忘记做过的事；forget to do：忘记去做（还没做）。", "explain": "作文：stop play→stop playing；don't forget do→don't forget to do。先判断“这件事做没做”，再选doing/to do。", "id": "con-19", "prompt": "stop doing和stop to do有什么区别？forget呢？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "非谓语"]}, {"answer": "跟名词：have confidence in sb/sth（对……有信心）。confident是形容词（be confident of/about），confidence是名词。", "explain": "完成句子66题：have confidence in后面写了confident（形容词）得0分。in是介词，后面只能跟名词/动名词。", "id": "con-20", "prompt": "have confidence in后面跟什么词形？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "词形"]}, {"answer": "have confidence in", "explain": "66题错：写了confident（形容词）。in是介词，后面跟名词confidence。整句：We should have confidence in ourselves.", "id": "eng-01", "prompt": "have ______ in（对……有信心）", "set": "词句急救", "subject": "英语", "tags": ["词形", "完成句子"]}, {"answer": "confusing", "explain": "67题0分。-ing形容词修饰物（令人……的），-ed形容词修饰人（感到……的）：confusing movie / confused person。", "id": "eng-02", "prompt": "The movie is ______（令人困惑的）", "set": "词句急救", "subject": "英语", "tags": ["形容词", "完成句子"]}, {"answer": "extremely", "explain": "68题0分。副词修饰形容词/副词：extremely fast。extreme是形容词，不能直接修饰fast。", "id": "eng-03", "prompt": "He runs ______（极其）fast", "set": "词句急救", "subject": "英语", "tags": ["副词", "完成句子"]}, {"answer": "be addicted to", "explain": "72题0分，目标短语直接不会。addicted是形容词：be addicted to sth/doing sth（沉迷于……）。", "id": "eng-04", "prompt": "be ______ to games（沉迷于游戏）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "other than", "explain": "75题0分。other than＝除了……之外。注意than的拼写。", "id": "eng-05", "prompt": "______ than watching TV（除了看电视之外）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "clean up", "explain": "73题部分给分。clean up＝打扫干净，up是副词不是介词。", "id": "eng-06", "prompt": "______ up the room（打扫房间）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "take control of / took control of", "explain": "74题部分给分。take control of＝控制、接管，注意时态用took。", "id": "eng-07", "prompt": "______ control of the company（接管公司）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "concentrate on / focus on", "explain": "76题部分给分。concentrate on＝focus on＝专注于，后面跟名词/动名词。", "id": "eng-08", "prompt": "______ on your study（专注于学习）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "leave alone", "explain": "70题全对。leave sb alone＝别打扰某人，让某人独自待着。", "id": "eng-09", "prompt": "leave the baby ______（别管婴儿，让他自己待着）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "look forward to", "explain": "71题全对。look forward to中to是介词，后面跟名词/动名词：look forward to hearing from you。", "id": "eng-10", "prompt": "look ______ to hearing from you（期待收到你的来信）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "to reduce", "explain": "57题错写成to surprised。不定式to do表目的，后面必须跟动词原形：to reduce（为了减少）。", "id": "eng-11", "prompt": "______ reduce stress, he runs daily.（为了减压）", "set": "词句急救", "subject": "英语", "tags": ["不定式", "语法填空"]}, {"answer": "easier", "explain": "59题未写出完整形式。easy→easier，比较级变化：y变i加er。", "id": "eng-12", "prompt": "This book is ______（更容易）than that one", "set": "词句急救", "subject": "英语", "tags": ["比较级", "语法填空"]}, {"answer": "the", "explain": "63题0分。特指双方都知道的人/物用the：the children＝那些孩子们。", "id": "eng-13", "prompt": "______ children are playing there.（那些孩子，特指）", "set": "词句急救", "subject": "英语", "tags": ["冠词", "语法填空"]}, {"answer": "aged", "explain": "64题0分。aged是age的过去分词作定语：children aged 5-10＝5到10岁的孩子们。", "id": "eng-14", "prompt": "______ children aged 5-10（5-10岁的孩子们）", "set": "词句急救", "subject": "英语", "tags": ["分词", "语法填空"]}, {"answer": "For", "explain": "56题错写成at。句首表对象/范围用For：For children, …＝对于孩子们来说。", "id": "eng-15", "prompt": "______ children, playing outside is fun.（对于孩子们来说）", "set": "词句急救", "subject": "英语", "tags": ["介词", "语法填空"]}], "concepts": [{"subject": "政治", "name": "生产力与生产关系的关系", "core": "生产力决定生产关系，生产关系反作用于生产力；生产关系一定要适合生产力状况，是社会形态更替的根本规律。", "wrong": true, "keys": ["政治|21|1"]}, {"subject": "政治", "name": "社会形态更替进步性的判断标准", "core": "判断一种社会形态取代另一种是进步还是倒退，标准是新的生产关系是否适应并促进生产力的发展要求。", "wrong": true, "keys": ["政治|21|1"]}, {"subject": "政治", "name": "奴隶社会代替原始社会的进步表现", "core": "奴隶社会使用金属工具、出现城市和脑体分工，极大解放了生产力，所以代替原始社会是历史的进步而非倒退。", "wrong": true, "keys": ["政治|21|1"]}, {"subject": "政治", "name": "封建社会的基本矛盾", "core": "封建社会的基本矛盾是生产力与生产关系之间的矛盾，不能把地主与农民的阶级矛盾当作基本矛盾。", "wrong": false, "keys": []}, {"subject": "政治", "name": "地主阶级剥削农民的主要方式", "core": "地主阶级凭借土地所有权收取地租来剥削农民，地租剥削是封建剥削的主要方式，而非高利贷。", "wrong": false, "keys": []}, {"subject": "政治", "name": "封建社会的主要矛盾", "core": "封建社会的主要矛盾是农民阶级同地主阶级的矛盾，它是封建社会其他阶级矛盾的根源。", "wrong": false, "keys": []}, {"subject": "政治", "name": "剩余价值的来源", "core": "工人劳动分必要劳动和剩余劳动两部分，剩余价值由雇佣工人在剩余劳动时间内创造、被资本家无偿占有。", "wrong": false, "keys": []}, {"subject": "政治", "name": "科学社会主义的理论基石", "core": "唯物史观和剩余价值学说揭示了社会发展一般规律和资本主义运行特殊规律，为科学社会主义奠定理论基石。", "wrong": false, "keys": []}, {"subject": "政治", "name": "科学社会主义产生的历史条件", "core": "资本主义的发展和工人运动的兴起是科学社会主义产生的社会历史条件，它是'条件'而非'理论基石'。", "wrong": false, "keys": []}, {"subject": "政治", "name": "五四运动：新民主主义革命的开端", "core": "1919年五四运动中工人阶级登上政治舞台、马克思主义加速传播，标志着中国新民主主义革命的开端。", "wrong": true, "keys": ["政治|9|1"]}, {"subject": "政治", "name": "新旧民主主义革命的区别", "core": "分界线是五四运动：旧由资产阶级领导、属资产阶级革命范畴；新由无产阶级领导、属无产阶级革命范畴，任务同为反帝反封建。", "wrong": true, "keys": ["政治|10|1"]}, {"subject": "政治", "name": "半殖民地半封建社会的主要矛盾", "core": "近代中国社会性质是半殖民地半封建社会，主要矛盾是帝国主义与中华民族的矛盾，即民族矛盾最主要。", "wrong": false, "keys": []}, {"subject": "政治", "name": "新民主主义革命与社会主义革命的关系", "core": "教材原话：新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主义革命的必然趋势，主宾不可对调。", "wrong": false, "keys": []}, {"subject": "政治", "name": "新民主主义革命的时期（1919—1949年）", "core": "新民主主义革命时期以1919年五四运动为起点、1949年新中国成立为终点，不能误记为1921年建党开始。", "wrong": false, "keys": []}, {"subject": "政治", "name": "家庭联产承包责任制与改革开放的开端（1978年）", "core": "1978年起推行的家庭联产承包责任制从农村突破，是改革开放起步的标志性事件，排序题中钉住年份1978。", "wrong": true, "keys": ["政治|15|1"]}, {"subject": "政治", "name": "社会主义市场经济体制目标的确立（1992年）", "core": "1992年党的十四大明确提出建立社会主义市场经济体制的目标，时间在2001年入世之前，不能记反。", "wrong": true, "keys": ["政治|15|1"]}, {"subject": "政治", "name": "加入世界贸易组织（2001年）与上海自贸试验区（2013年）", "core": "2001年加入世界贸易组织使对外开放进入新阶段，2013年设立上海自贸试验区是全面深化改革的新动作。", "wrong": true, "keys": ["政治|15|1"]}, {"subject": "政治", "name": "科学社会主义是发展的真理（没有终极真理）", "core": "科学社会主义是科学真理，但随实践不断丰富发展，不存在一成不变的'终极真理'，这类绝对化表述必错。", "wrong": true, "keys": ["政治|17|1"]}, {"subject": "政治", "name": "中国特色社会主义与科学社会主义的关系", "core": "中国特色社会主义是科学社会主义基本原理同中国具体实际相结合的产物，是科学社会主义在中国的实践与发展。", "wrong": false, "keys": []}, {"subject": "政治", "name": "十一届三中全会：重新确立三条路线", "core": "十一届三中全会重新确立马克思主义的思想路线、政治路线和组织路线，被文革破坏后恢复的路线只能说'重新'。", "wrong": true, "keys": ["政治|20|1"]}, {"subject": "政治", "name": "十一届三中全会的历史地位", "core": "这次全会作出把工作中心转移到经济建设、实行改革开放的决策，是新中国成立以来党的历史上具有深远意义的伟大转折。", "wrong": true, "keys": ["政治|20|1"]}, {"subject": "政治", "name": "中共八大关于主要矛盾的正确论断", "core": "八大指出国内主要矛盾是人民对经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。", "wrong": false, "keys": []}, {"subject": "政治", "name": "新中国成立的意义：四个彻底结束", "core": "新中国成立彻底结束半殖民地半封建历史、一盘散沙局面、不平等条约与特权、少数剥削者统治的历史，意义题先写此四句。", "wrong": true, "keys": ["政治|22|1"]}, {"subject": "政治", "name": "新中国成立与向社会主义过渡的前提", "core": "中华人民共和国的诞生为新民主主义向社会主义过渡创造了前提条件，中国历史从此开启新纪元。", "wrong": true, "keys": ["政治|22|1"]}, {"subject": "政治", "name": "新中国成立的国际意义", "core": "新中国成立壮大了世界和平、民主和社会主义的力量，改变了世界政治格局，是20世纪的伟大历史事件之一。", "wrong": true, "keys": ["政治|22|1"]}, {"subject": "政治", "name": "改革开放的定位表述：必由之路、关键一招、活力之源", "core": "改革开放是坚持和发展中国特色社会主义的必由之路、决定当代中国命运的关键一招、当代中国发展进步的活力之源。", "wrong": true, "keys": ["政治|23|1"]}, {"subject": "政治", "name": "改革开放改变的四个面貌", "core": "改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌和中华文明的面貌。", "wrong": false, "keys": []}, {"subject": "政治", "name": "改革开放实现的三个飞跃", "core": "中华民族迎来从站起来、富起来到强起来的伟大飞跃，中国人民迎来从温饱不足到小康富裕的伟大飞跃。", "wrong": false, "keys": []}, {"subject": "政治", "name": "近代中国各阶级探索的失败", "core": "农民阶级、地主阶级、资产阶级改良派和革命派的探索都失败了，证明资本主义道路在中国走不通。", "wrong": true, "keys": ["政治|24|1"]}, {"subject": "政治", "name": "中国共产党的诞生与新民主主义革命的胜利", "core": "中国共产党的诞生使中国革命面貌焕然一新，党领导人民经过28年奋斗取得新民主主义革命的伟大胜利。", "wrong": true, "keys": ["政治|24|1"]}, {"subject": "政治", "name": "新中国成立改变中国发展方向", "core": "新中国的成立从根本上改变了中国的发展方向，使中国走上独立、统一、走向社会主义的道路。", "wrong": true, "keys": ["政治|24|1"]}, {"subject": "政治", "name": "社会主义改造与社会主义基本制度的确立", "core": "过渡时期总路线是'一化三改'，1956年社会主义改造基本完成，标志着社会主义基本制度在我国确立。", "wrong": false, "keys": []}, {"subject": "政治", "name": "人民是历史的主体", "core": "人民群众是历史的创造者和历史主体；工人阶级是革命的领导阶级，中国共产党是无产阶级政党，三者不能混同。", "wrong": false, "keys": []}, {"subject": "政治", "name": "生产资料社会主义公有制", "core": "宪法规定矿藏、水流等自然资源属于国家所有即全民所有，但全民所有制不等于人人平均分配、实行平均主义。", "wrong": false, "keys": []}, {"subject": "地理", "name": "太阳大气的分层结构", "core": "太阳大气由里到外分为光球层、色球层、日冕层，判断某现象在哪层发生，先定层再想对应的太阳活动。", "wrong": true, "keys": ["地理|5|1"]}, {"subject": "地理", "name": "太阳活动的主要类型与标志", "core": "光球层有黑子、色球层有耀斑和日珥、日冕层有太阳风；黑子是太阳活动强弱的主要标志，周期约11年。", "wrong": true, "keys": ["地理|5|1"]}, {"subject": "地理", "name": "太阳活动对地球的影响", "core": "太阳活动会扰乱电离层干扰无线电短波通信，引发磁暴现象，并在高纬度地区产生极光。", "wrong": true, "keys": ["地理|5|1"]}, {"subject": "地理", "name": "地质年代表的层级", "core": "地质年代的层级从大到小是宙、代、纪，答题时先分清问的是层级大小还是时间先后，两个维度不能混。", "wrong": true, "keys": ["地理|6|1"]}, {"subject": "地理", "name": "各代的生物演化标志", "core": "古生代无脊椎动物和鱼类繁盛，中生代是爬行动物的时代、末期恐龙灭绝，新生代哺乳动物繁盛、人类出现。", "wrong": true, "keys": ["地理|6|1"]}, {"subject": "地理", "name": "第四纪与新生代的包含关系", "core": "第四纪是新生代内部最新的一个纪，二者是包含关系而非并列关系，人类就出现在第四纪。", "wrong": true, "keys": ["地理|6|1"]}, {"subject": "地理", "name": "地球内部圈层与两个界面", "core": "由外到内是地壳、地幔、地核，莫霍界面在壳幔之间（平均约17千米），古登堡界面在幔核之间（约2900千米）。", "wrong": true, "keys": ["地理|10|1"]}, {"subject": "地理", "name": "岩石圈的组成", "core": "岩石圈由地壳和上地幔顶部（软流层以上）共同组成，范围大于地壳，把岩石圈等同于地壳是最常见的错误。", "wrong": true, "keys": ["地理|10|1"]}, {"subject": "地理", "name": "软流层的位置与意义", "core": "软流层位于上地幔顶部，呈熔融状态，被认为是岩浆的主要发源地，它之上才是岩石圈。", "wrong": true, "keys": ["地理|10|1"]}, {"subject": "地理", "name": "地震波纵波与横波的传播特点", "core": "纵波速度快、能在固液气三态传播，横波速度慢、只能在固体传播，据此可推断地球内部各层的物质状态。", "wrong": true, "keys": ["地理|10|1"]}, {"subject": "地理", "name": "大气受热过程的三个环节", "core": "受热链为太阳暖大地、大地暖大气、大气还大地：太阳辐射到达地面、地面辐射加热大气、大气逆辐射返还地面。", "wrong": true, "keys": ["地理|11|1"]}, {"subject": "地理", "name": "地面是近地面大气的直接热源", "core": "对流层大气主要吸收地面长波辐射增温，地面是近地面大气主要的、直接的热源，而非太阳辐射本身。", "wrong": true, "keys": ["地理|11|1"]}, {"subject": "地理", "name": "短波辐射与长波辐射的区别", "core": "太阳辐射是短波辐射，地面和大气辐射是长波辐射，大气对短波的吸收弱、对长波的吸收强，是受热链的前提。", "wrong": true, "keys": ["地理|11|1"]}, {"subject": "地理", "name": "大气削弱作用的三种形式", "core": "削弱作用有吸收（有选择性）、反射（无选择性、云厚则强）、散射（空气分子散射蓝紫光使天空蔚蓝）三种。", "wrong": true, "keys": ["地理|12|1"]}, {"subject": "地理", "name": "反射与大气逆辐射的区别", "core": "反射发生在太阳辐射到达地面之前、把短波挡回宇宙空间；逆辐射发生在地面增温之后、把长波热量还给地面。", "wrong": true, "keys": ["地理|12|1"]}, {"subject": "地理", "name": "大气逆辐射与保温作用", "core": "大气吸收地面长波辐射增温后产生大气辐射，射向地面的大气逆辐射把热量返还地面，起保温作用即温室效应。", "wrong": true, "keys": ["地理|13|1"]}, {"subject": "地理", "name": "大气逆辐射强弱与晴朗夜晚霜冻", "core": "云量多、水汽足时逆辐射强、夜温高；晴朗干燥时逆辐射弱、地面降温快，所以晴朗的夜晚容易出现霜冻。", "wrong": true, "keys": ["地理|13|1"]}, {"subject": "地理", "name": "对流层气温垂直递减律", "core": "对流层气温随高度升高而降低，平均每升高100米下降约0.6摄氏度，因离直接热源地面越远获得热量越少。", "wrong": true, "keys": ["地理|14|1"]}, {"subject": "地理", "name": "平流层气温随高度升高而升高", "core": "平流层中的臭氧吸收紫外线增温，气温随高度升高而升高，与对流层规律正好相反，答题先定层再套规律。", "wrong": true, "keys": ["地理|14|1"]}, {"subject": "地理", "name": "大气的垂直分层", "core": "大气自下而上分对流层、平流层和高层大气，各层的气温变化规律和大气运动特点各不相同、不能互相套用。", "wrong": true, "keys": ["地理|14|1"]}, {"subject": "地理", "name": "逆温现象", "core": "某层大气中气温随高度升高反而升高叫逆温，多在晴朗无风的夜间形成，会阻碍对流、加重空气污染。", "wrong": true, "keys": ["地理|14|1"]}, {"subject": "地理", "name": "热力环流的形成过程", "core": "热力环流的顺序是地面冷热不均、空气垂直运动、同一水平面产生气压差、空气由高压流向低压形成风。", "wrong": true, "keys": ["地理|16|1"]}, {"subject": "地理", "name": "等压面判读：高凸低凹", "core": "等压面向上凸出的地方对应高压、向下凹陷的地方对应低压，读热力环流图时先标气压再定风向。", "wrong": true, "keys": ["地理|16|1"]}, {"subject": "地理", "name": "近地面与高空气压高低相反", "core": "受热上升处近地面形成低压、其高空形成高压，受冷下沉处恰好相反，同一地点高空与近地面气压高低相反。", "wrong": true, "keys": ["地理|16|1"]}, {"subject": "地理", "name": "热力环流的常见应用", "core": "海陆风、山谷风和城市热岛环流都是热力环流的具体表现，判断风向都按冷热、垂直、气压、水平四步推。", "wrong": true, "keys": ["地理|16|1"]}, {"subject": "地理", "name": "我国年太阳辐射总量的分布规律", "core": "我国年太阳辐射总量总体上西多东少、南多北少，东西差异主因是天气状况，南北差异主因是纬度高低。", "wrong": true, "keys": ["地理|24|1"]}, {"subject": "地理", "name": "影响太阳辐射分布的因素", "core": "太阳辐射多少主要受纬度（太阳高度角）、天气状况（云量）和海拔（空气稀薄程度）三类因素共同影响。", "wrong": true, "keys": ["地理|24|1"]}, {"subject": "地理", "name": "四川盆地太阳辐射最贫乏的原因", "core": "四川盆地阴雨天多、云雾量大，大气削弱作用强，是我国年太阳辐射总量最贫乏的地区，与海拔无关。", "wrong": true, "keys": ["地理|24|1"]}, {"subject": "地理", "name": "青藏高原太阳辐射强的原因", "core": "青藏高原海拔高、空气稀薄，水汽尘埃少且晴天多，太阳辐射被削弱得少，到达地面的辐射为全国最强。", "wrong": true, "keys": ["地理|25|1"]}, {"subject": "地理", "name": "青藏高原气温低的原因", "core": "高原空气稀薄，吸收地面辐射的能力差、大气逆辐射弱，地面热量容易散失，所以辐射虽强而气温偏低。", "wrong": true, "keys": ["地理|25|1"]}, {"subject": "英语", "name": "介词 for 的用法（表对象/原因）", "core": "for 可表示对象（为……）、原因或目的；选介词不能凭眼熟，要看它与动词、名词的搭配及整句语义。", "wrong": true, "keys": ["英语|56|1"]}, {"subject": "英语", "name": "不定式 to 与介词 to 的区别", "core": "不定式 to 后接动词原形，常作目的状语（to help / to reduce）；look forward to 中的 to 是介词，后接名词或动名词。", "wrong": true, "keys": ["英语|57|1"]}, {"subject": "英语", "name": "形容词比较级的构成（辅音+y 结尾）", "core": "easy 等以“辅音字母+y”结尾的形容词，比较级要变 y 为 i 再加 -er：easy→easier；句中有 than 时先想到比较级。", "wrong": true, "keys": ["英语|59|1"]}, {"subject": "英语", "name": "定冠词 the 表特指", "core": "the 用于特指双方都明白的人或物，也用于序数词和最高级之前，如 the number one 表示“第一位的、最重要的”。", "wrong": true, "keys": ["英语|63|1"]}, {"subject": "英语", "name": "过去分词作定语", "core": "过去分词作定语表示被动或已经完成，放在所修饰名词之后：people aged 34 指“34 岁的人”，aged 不能用动词原形代替。", "wrong": true, "keys": ["英语|64|1"]}, {"subject": "英语", "name": "-ing 与 -ed 形容词的辨析", "core": "-ing 形容词修饰物，表示“令人……的”（confusing 令人困惑）；-ed 形容词修饰人，表示“感到……的”（confused 感到困惑）。", "wrong": true, "keys": ["英语|67|1"]}, {"subject": "英语", "name": "副词修饰形容词", "core": "形容词前面要用副词来修饰，副词多由形容词加 -ly 构成：extremely beautiful；extremely 这类词的拼写也要落实到能写对。", "wrong": true, "keys": ["英语|68|1"]}, {"subject": "英语", "name": "confidence 的名词词形与 have confidence in", "core": "confident 是形容词“自信的”，名词形式是 confidence；搭配有 have confidence in sb/sth 或 with great confidence。", "wrong": true, "keys": ["英语|66|1"]}, {"subject": "英语", "name": "official 的拼写与搭配", "core": "official 意为“官方的”，常搭配 official report、official news；拼写注意双 f 和词尾 -cial，别与 office、officer 混淆。", "wrong": true, "keys": ["英语|69|1"]}, {"subject": "英语", "name": "be addicted to 搭配", "core": "be addicted to 意为“沉迷于……、对……上瘾”，其中 to 是介词，后接名词或动名词；addicted 的拼写和 to 都不能漏。", "wrong": true, "keys": ["英语|72|1"]}, {"subject": "英语", "name": "except for / other than 表“除了”", "core": "except for、apart from、other than 都可表示“除了……”，后接名词作除外成分；这类短语要整条记牢，只写一半就整题丢分。", "wrong": true, "keys": ["英语|75|1"]}, {"subject": "英语", "name": "clean up 动词短语", "core": "clean up 意为“打扫干净、清理”，是动词加副词构成的短语；宾语是代词时放在中间（clean it up），书写必须完整。", "wrong": true, "keys": ["英语|73|1"]}, {"subject": "英语", "name": "take control of 搭配与时态", "core": "take control of 意为“掌控、接管”，三个词缺一不可；叙述过去的事情时要用过去式 took control of，时态随上下文走。", "wrong": true, "keys": ["英语|74|1"]}, {"subject": "英语", "name": "focus on / concentrate on 搭配", "core": "focus on 与 concentrate on 都表示“集中精力于……”，介词 on 不能丢；本次只写对一半，短语必须整条背诵并默写过关。", "wrong": true, "keys": []}, {"subject": "英语", "name": "leave sb alone", "core": "leave sb alone 意为“别打扰某人、让某人独处”；本次完成句子第 70 题全对，这个短语已经掌握。", "wrong": false, "keys": []}, {"subject": "英语", "name": "look forward to 搭配", "core": "look forward to 意为“盼望、期待”，其中 to 是介词，后接名词或动名词 doing；本次第 71 题全对，已经掌握。", "wrong": false, "keys": []}, {"subject": "英语", "name": "excuse 的语境词义（完形辨析）", "core": "excuse 作名词是“借口、托词”；it was just an excuse 指“那只是个借口”，完形选词要服从上下文逻辑，不能只看眼熟。", "wrong": true, "keys": ["英语|48|1"]}, {"subject": "英语", "name": "stand 的语境义（完形辨析）", "core": "stand 除“站立”外还可表示“停留、愣住”；I stood for a second 是“我愣了一秒”，要结合动作发生的情境来辨义。", "wrong": true, "keys": ["英语|52|1"]}, {"subject": "英语", "name": "lead to 后接名词的辨析（完形）", "core": "lead to 表示“导致”，后面接结果性名词；选词时要回看前文（如 nervousness）引出的具体后果，actions、words 等要逐个代入验证。", "wrong": true, "keys": ["英语|44|1"]}, {"subject": "英语", "name": "interest 的语境义（完形辨析）", "core": "following my interest 中的 interest 是“兴趣、爱好”；名词辨析要整句代入验证，personality（性格）这类形近义异的干扰项要排除。", "wrong": true, "keys": ["英语|55|1"]}, {"subject": "英语", "name": "段落写作目的的判断", "core": "问段落作用时看它在文中的功能：首段摆出反常例子多半是引入话题（introduce the topic），不要被例子本身的内容带偏。", "wrong": true, "keys": ["英语|28|1"]}, {"subject": "英语", "name": "细节定位与同义替换识别", "core": "细节题先划出题干关键词，回原文定位依据句，再比对选项的同义替换说法；perfect book 好在哪里，要以原文对它的评价句为准。", "wrong": true, "keys": ["英语|29|1"]}, {"subject": "英语", "name": "比率类短语的含义理解", "core": "one tourist for each person 表示游客与当地人数之比为 1:1，即“平均每个当地人对应一个游客”；for each 是“每……对应一个”的比率表达。", "wrong": true, "keys": ["英语|33|1"]}, {"subject": "英语", "name": "否定信息的反推推理", "core": "文中说游客 don't mind A、allow B，等于把 A、B 排除；问“什么毁了兴致”时，要从没有被否定的选项里反推，比如阴雨天气。", "wrong": true, "keys": ["英语|34|1"]}, {"subject": "英语", "name": "七选五的语篇衔接", "core": "七选五靠代词指代、关键词复现和逻辑连接词找衔接点，顺着上下文的衔接关系判断空缺；本次全对，这个方法已经掌握。", "wrong": false, "keys": []}, {"subject": "英语", "name": "听力具体细节的听辨（颜色/地点/职业/活动）", "core": "细节题要抓颜色、地点、职业、活动方式等具体名词；听前先看选项预判要听哪类细节，听到关键词立刻记下来，别等听完再回忆。", "wrong": true, "keys": ["英语|2|1", "英语|7|1", "英语|13|1"]}, {"subject": "英语", "name": "听力时间与日程信息的听辨", "core": "涉及 when 和日程安排的问题，要紧盯时间点与先后顺序的表述（at、before、after 等），提到的其他时间多半是干扰项。", "wrong": true, "keys": ["英语|5|1"]}, {"subject": "英语", "name": "听力活动方式的听辨", "core": "问“通过什么方式”时抓 by 加动名词的表述，如 by jogging outdoors；方式类细节常一闪而过，要带着问题听，不能只听大意。", "wrong": true, "keys": ["英语|3|1"]}, {"subject": "英语", "name": "听力态度与感受词的听辨", "core": "问看法、感受时抓评价类形容词，如 favorable（有利的）、stressful（有压力的）；这类词常出现在句尾或转折之后，是得分点。", "wrong": true, "keys": ["英语|8|1", "英语|14|1"]}, {"subject": "英语", "name": "听力主旨与目的的听辨", "core": "独白主旨题要听首尾句和反复出现的主题词；问目的（purpose）时选概括性表述，如 to introduce different cultures。", "wrong": true, "keys": ["英语|19|1"]}, {"subject": "英语", "name": "听力转折信号词 but / however", "core": "but、however、actually、in fact 之后往往才是真正答案，先听到的信息可能只是铺垫或陷阱；没等到拍板信号之前不要急着改答案。", "wrong": true, "keys": ["英语|15|1"]}, {"subject": "英语", "name": "建议信（劝诫信）的结构与语域", "core": "劝诫信按“开头点明担忧、中间分条给出建议和理由、结尾表达期望”来组织，用语委婉恳切，符合以朋友身份写信的语域。", "wrong": true, "keys": ["英语|作文|1"]}, {"subject": "英语", "name": "写作表达的准确性（搭配与句式）", "core": "写作丢分多在搭配和句式不规范上：写完逐句检查动词搭配（如 become addicted to）、时态和主谓一致，避免按中文逐字直译。", "wrong": true, "keys": ["英语|作文|1"]}, {"subject": "物理", "name": "时刻与时间间隔的区别", "core": "时刻是时间轴上的一个点（如第3s末），时间间隔是两时刻之差、对应一段过程（如第3s内）。", "wrong": false, "keys": []}, {"subject": "物理", "name": "质点模型（可看作质点的条件）", "core": "物体的大小、形状对所研究问题没有影响时可看作质点，与物体本身大小无关，只看问题性质。", "wrong": false, "keys": []}, {"subject": "物理", "name": "参考系与运动的相对性", "core": "描述运动必须先选参考系，选不同的参考系，同一物体的运动情况可能不同（诗中\"云不动\"是以船为参考系）。", "wrong": false, "keys": []}, {"subject": "物理", "name": "速度—位移关系式 v²−v₀²=2ax", "core": "不涉及时间时用速度—位移公式，由已知初末速度和加速度直接求位移（或反求加速度）。", "wrong": false, "keys": []}, {"subject": "物理", "name": "速度与加速度的关系", "core": "加速度是速度变化的快慢，与速度大小、速度变化量大小都无关；a 与 v 反向时物体做减速运动，a 增大速度反而减小得更快。", "wrong": true, "keys": ["物理|5|1"]}, {"subject": "物理", "name": "位移与路程的区别", "core": "位移是矢量、只看初末位置，路程是实际轨迹长度、是标量；只有单向直线运动时两者大小才相等。", "wrong": false, "keys": []}, {"subject": "物理", "name": "平均速率与平均速度的区别", "core": "平均速率=路程÷时间，平均速度=位移÷时间，两者大小一般不相等，平均速度还带方向。", "wrong": false, "keys": []}, {"subject": "物理", "name": "初速度为零的匀加速运动：等时间比例规律", "core": "从静止开始，相邻相等时间内的位移比为 1:3:5:…，各时刻速度比为 1:2:3:…。", "wrong": false, "keys": []}, {"subject": "物理", "name": "初速度为零的匀加速运动：等位移比例规律", "core": "通过相邻相等位移的速度比为 1:√2:√3:2，所用时间比为 1:(√2−1):(√3−√2):(2−√3)。", "wrong": true, "keys": ["物理|8|1"]}, {"subject": "物理", "name": "等位移与等时间规律的区分（速度增量）", "core": "相等位移段的速度增量并不相等（越来越小），相等时间段的速度增量才相等，两套比例规律不能混用。", "wrong": true, "keys": ["物理|8|1"]}, {"subject": "物理", "name": "等路程平均速度（调和平均）", "core": "前后半段路程相等时，全程平均速度=2v₁v₂/(v₁+v₂)，必须回到\"总位移÷总时间\"算，不能用算术平均。", "wrong": true, "keys": ["物理|9空1|1"]}, {"subject": "物理", "name": "等时间平均速度（算术平均）", "core": "前后半段时间相等时，全程平均速度=(v₁+v₂)/2，因为总位移就是两段位移直接相加。", "wrong": false, "keys": []}, {"subject": "物理", "name": "x-t 图像的基本读法", "core": "x-t 图像纵坐标就是位置坐标：水平段表示静止，斜率向下表示反向运动，先读关键时刻的坐标值。", "wrong": false, "keys": []}, {"subject": "物理", "name": "位移（坐标变化量）的矢量性", "core": "位移 Δx=末位置−初位置，必须带正负号；反向运动时 Δx 为负，不能只写大小。", "wrong": true, "keys": ["物理|10空2|1"]}, {"subject": "物理", "name": "平均速度的矢量性", "core": "平均速度是矢量，方向与位移方向一致；物体反向运动的那一段，平均速度为负值。", "wrong": true, "keys": ["物理|10空4|1"]}, {"subject": "物理", "name": "光电门测瞬时速度", "core": "遮光板宽度除以遮光时间近似等于通过光电门的瞬时速度，遮光板越窄近似程度越好。", "wrong": false, "keys": []}, {"subject": "物理", "name": "加速度定义式 a=Δv/Δt 的计算", "core": "加速度等于速度变化量除以所用时间，分清哪段的速度差、哪段的时间，单位统一后再代入。", "wrong": true, "keys": ["物理|11空3|1", "物理|13(2)|1"]}, {"subject": "物理", "name": "打点计时器的基本常识", "core": "电火花打点计时器用交流 220V 电源，电源频率 50Hz 时每隔 0.02s 打一个点。", "wrong": false, "keys": []}, {"subject": "物理", "name": "计数点时间间隔的确定", "core": "\"相邻计数点间还有 n 个计时点未标出\"时，计数周期 T=(n+1)×0.02s，本卷 n=4 故 T=0.1s。", "wrong": true, "keys": ["物理|12(2)a|1"]}, {"subject": "物理", "name": "纸带中间时刻速度的求法", "core": "某计数点的瞬时速度等于它前后一段位移的平均速度，v_B=(x_AB+x_BC)/(2T)。", "wrong": true, "keys": ["物理|12(2)a|1"]}, {"subject": "物理", "name": "逐差法求纸带加速度", "core": "相邻相等时间位移差恒定，a=(x_BC−x_AB)/T²，先确认计数周期 T 再代入，保留有效数字。", "wrong": true, "keys": ["物理|12(2)b|1"]}, {"subject": "物理", "name": "速度变化量 Δv 的矢量性", "core": "Δv=末速度−初速度，必须先定正方向、反向速度取负号；反向踢回时 |Δv| 是两速度大小之和。", "wrong": true, "keys": ["物理|13(1)|1"]}, {"subject": "物理", "name": "v-t 图像的斜率表示加速度", "core": "v-t 图像的斜率就是加速度：斜率正负表方向、陡缓表大小，匀速段斜率为零。", "wrong": false, "keys": []}, {"subject": "物理", "name": "v-t 图像的面积表示位移", "core": "v-t 图线与时间轴所围面积等于位移，分段算面积再求和即得总位移。", "wrong": false, "keys": []}, {"subject": "物理", "name": "平均速度=总位移÷总时间", "core": "求一段时间内的平均速度只认总位移和总时间，与中间过程快慢无关，除法要算准。", "wrong": true, "keys": ["物理|14(2)|1"]}, {"subject": "物理", "name": "匀变速速度公式 v=v₀+at 的规范使用", "core": "解答题必须先写公式、再代入、最后给结果和单位，只写结果会丢公式分；减速时 a 取负值。", "wrong": true, "keys": ["物理|15(1)|1"]}, {"subject": "物理", "name": "匀变速位移公式 x=v₀t+½at²", "core": "位移由初速度、时间和加速度共同决定，匀减速时 a 以负值代入，不能拼凑或凭感觉估。", "wrong": true, "keys": ["物理|15(2)|1"]}, {"subject": "物理", "name": "刹车问题先求停止时间", "core": "刹车类问题第一步先算停止时间 t₀=v₀/a，所问时间超过 t₀ 的，车已经停下，不能再套原公式。", "wrong": true, "keys": ["物理|15(3)|1"]}, {"subject": "物理", "name": "停止后位移的计算（逆向思维）", "core": "车停下后的总位移只算到停止时刻，可用 x=v₀²/(2a) 或把减速过程反着看成初速为零的加速。", "wrong": true, "keys": ["物理|15(3)|1"]}, {"subject": "数学", "name": "集合符号 ∈、⊆、∉ 的读法与使用", "core": "元素与集合用 ∈/∉，集合与集合用 ⊆/⊈，\"属于\"和\"包含\"不能混用。", "wrong": false, "keys": []}, {"subject": "数学", "name": "用 Venn 图与数轴辅助集合运算", "core": "集合的交、并、补先画图再下笔：交取公共、并取合并、补取全集里剩下的部分。", "wrong": false, "keys": []}, {"subject": "数学", "name": "全称量词命题的否定", "core": "\"∀x，p(x)\"的否定是\"∃x，非 p(x)\"：量词换 existential，结论取否定，两处都要改。", "wrong": false, "keys": []}, {"subject": "数学", "name": "分式不等式的解法（分母不为零）", "core": "解分式不等式时分母零点永远不能取：分子零点在 ≥ 时可取，分母零点必须排除后再定区间。", "wrong": true, "keys": ["数学|4|1"]}, {"subject": "数学", "name": "子集个数公式 2ⁿ", "core": "含 n 个元素的集合有 2ⁿ 个子集；先把元素个数数对，尤其注意 N* 不含 0、区间端点取舍。", "wrong": true, "keys": ["数学|5|1"]}, {"subject": "数学", "name": "充分条件与必要条件的判断", "core": "由 p 能推出 q，则 p 是 q 的充分、q 是 p 的必要；小范围推出大范围，先看清题目问的是\"谁是谁的条件\"。", "wrong": true, "keys": ["数学|6|1"]}, {"subject": "数学", "name": "A∩B=A 与 A⊆B 的等价转化", "core": "A∩B=A 等价于 A⊆B，A∪B=A 等价于 B⊆A，求参数时先转化成包含关系再列端点不等式。", "wrong": true, "keys": ["数学|7|1"]}, {"subject": "数学", "name": "含参集合问题必须讨论空集", "core": "集合含参数时先想 A 是否可能为 ∅：空集是任何集合的子集，漏掉空集情形答案就会缺一段。", "wrong": true, "keys": ["数学|7|1"]}, {"subject": "数学", "name": "恒成立问题转化为最值问题", "core": "\"式子 ≥ 常数恒成立\"等价于式子的最小值 ≥ 该常数，先把恒成立翻译成求最值。", "wrong": true, "keys": ["数学|8|1"]}, {"subject": "数学", "name": "权方和不等式（柯西形式）求分式最值", "core": "形如 a²/x+b²/y 的式子在 x+y 为定值时用权方和一步得最小值，比通分硬算可靠。", "wrong": true, "keys": ["数学|8|1"]}, {"subject": "数学", "name": "集合元素的互异性", "core": "同一集合的元素互不相同；由方程分类求出参数后必须回代检验，撞上已有元素的情形要舍去。", "wrong": true, "keys": ["数学|9|1"]}, {"subject": "数学", "name": "作差比较法", "core": "判断不等式是否成立先作差，再因式分解看符号，这是证明不等式最通用的起手方法。", "wrong": false, "keys": []}, {"subject": "数学", "name": "不等式的基本性质", "core": "不等式同加同减不变号，同乘正数不变号、同乘负数要变号；判断选项逐条对照性质验。", "wrong": false, "keys": []}, {"subject": "数学", "name": "糖水不等式（真分数同加正数）", "core": "真分数 a/b（a<b）的分子分母同加正数 c，分数值变大：a/b<(a+c)/(b+c)。", "wrong": true, "keys": ["数学|10|1"]}, {"subject": "数学", "name": "基本不等式：和定积大（凑系数）", "core": "两正数和为定值时积有最大值；系数不配时先凑系数（如 ab=½·2a·b）再用基本不等式。", "wrong": false, "keys": []}, {"subject": "数学", "name": "常数代换（乘1）求分式和最值", "core": "求 1/a+1/b 型最小值时乘以等于 1 的条件式（如 2a+b）展开，再用基本不等式收尾。", "wrong": false, "keys": []}, {"subject": "数学", "name": "消元法求最值（代入后二次函数配方）", "core": "有线性约束时用一个变量表示另一个，目标化为一元二次函数，配方找顶点得最值。", "wrong": true, "keys": ["数学|11|1"]}, {"subject": "数学", "name": "分段函数求值", "core": "分段函数求值由内到外算，每一步先判断自变量落在哪一段，再套对应的解析式。", "wrong": false, "keys": []}, {"subject": "数学", "name": "待定系数法求式子范围", "core": "已知两个式子的范围求第三个式子，先把目标式写成两式子的线性组合再代入范围，不能把不等式直接加减。", "wrong": true, "keys": ["数学|13|1"]}, {"subject": "数学", "name": "二次函数值域的求法（配方）", "core": "二次函数的值域靠配方找顶点：开口向上有最小值，值域是 [顶点值, +∞)。", "wrong": false, "keys": []}, {"subject": "数学", "name": "由解析式求函数定义域", "core": "定义域看限制：根号下 ≥0、分母 ≠0，两条限制取交集，端点开闭跟着限制走。", "wrong": false, "keys": []}, {"subject": "数学", "name": "集合相等与包含的区分", "core": "相等是包含的特例；两集合求出的区间完全相同时关系是相等，问关系要答最精确的那个。", "wrong": true, "keys": ["数学|14|1"]}, {"subject": "数学", "name": "集合交、并、补运算与解集端点开闭", "core": "解答题里交并补要逐步化简集合再运算，端点能不能取由原不等式的等号决定，写错一个端点就丢分。", "wrong": true, "keys": ["数学|15|1"]}, {"subject": "数学", "name": "由 A⊆B 求参数（端点比较）", "core": "A⊆B 求参数就是比较两端点列不等式，端点等号能否成立要单独验，不能默认取等。", "wrong": false, "keys": []}, {"subject": "数学", "name": "一元二次不等式的解法", "core": "解一元二次不等式先求对应方程的根，开口向上时 f<0 取两根之间、f>0 取两根之外。", "wrong": false, "keys": []}, {"subject": "数学", "name": "含参一元二次不等式恒成立", "core": "先单独讨论参数为 0 的情形，再按开口方向与判别式 Δ 分类；讨论完必须把各段结论合并成完整范围。", "wrong": true, "keys": ["数学|17|1"]}, {"subject": "数学", "name": "基本不等式的实际应用建模", "core": "应用题先设元、翻译约束（如靠墙时篱笆只算三边），再把目标量化成基本不等式或函数模型。", "wrong": true, "keys": ["数学|18|1"]}, {"subject": "数学", "name": "二次函数模型求最值（实际问题）", "core": "面积类应用题把面积写成自变量的二次函数，配方或用对称轴求最值，并写清自变量的取值范围。", "wrong": true, "keys": ["数学|18|1"]}, {"subject": "数学", "name": "存在量词命题的转化", "core": "\"∃x 使不等式成立\"只需函数能取到目标值域：开口向下自动成立，开口向上看最小值（判别式）。", "wrong": true, "keys": ["数学|19|1"]}, {"subject": "数学", "name": "含参二次问题按参数符号分类讨论", "core": "参数在二次项系数上时，按 m=0、m<0、m>0 三类逐一验：零时降为一次/常数，负时开口向下，正时才用判别式。", "wrong": true, "keys": ["数学|19|1"]}, {"subject": "历史", "name": "商朝内外服制度", "core": "商王直接管辖王畿为内服，畿外部族通过联盟、纳贡服从商王为外服，是早期国家松散的统治形态。", "wrong": true, "keys": ["历史|3|1"]}, {"subject": "历史", "name": "血缘纽带与早期统治（子姓分族）", "core": "商王以同姓分族与血缘亲疏维系部族关系，血缘认同是分封、宗法等后世制度的源头逻辑。", "wrong": true, "keys": ["历史|3|1"]}, {"subject": "历史", "name": "西周分封制", "core": "周王把土地与子民分封给同姓子弟、功臣和先代贵族，建立诸侯国拱卫王室、拓展疆域。", "wrong": false, "keys": []}, {"subject": "历史", "name": "宗法制", "core": "以嫡长子继承制为核心，按血缘亲疏区分大宗与小宗，与分封制互为表里维系等级秩序。", "wrong": false, "keys": []}, {"subject": "历史", "name": "分封制的衰落", "core": "血缘渐疏、诸侯坐大而周王室衰微，分封秩序逐步瓦解，春秋战国走向兼并与礼崩乐坏。", "wrong": false, "keys": []}, {"subject": "历史", "name": "商鞅变法与县制的起源", "core": "商鞅在秦国变法中废除分封、普遍设县，县令由国君任免，开郡县制之先河。", "wrong": true, "keys": ["历史|21(2)|1"]}, {"subject": "历史", "name": "郡县制的推行背景", "core": "秦统一后推广郡县，背景包括战国变法设县的经验、统一形势的需要和法家集权思想的支撑。", "wrong": true, "keys": ["历史|21(2)|1"]}, {"subject": "历史", "name": "郡县制的意义", "core": "郡县长官由皇帝任免、中央垂直管理，强化中央集权、维护统一；它巩固统一而非奠定统一。", "wrong": true, "keys": ["历史|21(2)|1"]}, {"subject": "历史", "name": "法家思想与中央集权", "core": "法家主张以法治国、君主集权，为变法和郡县制提供理论支撑，是秦政的思想底色。", "wrong": true, "keys": ["历史|21(2)|1"]}, {"subject": "历史", "name": "历史因果的方向判断", "core": "判断因果先看时间先后：结果不可能出现在原因之前，如郡县推广在统一之后，只能是巩固而非奠定。", "wrong": true, "keys": ["历史|21(2)|1"]}, {"subject": "历史", "name": "二重证据法", "core": "王国维提出以传世文献与出土材料相互印证来研究古史，是史料考证的基本方法。", "wrong": true, "keys": ["历史|8|1"]}, {"subject": "历史", "name": "史料类型：传世文献与出土文献", "core": "传世文献是流传下来的典籍，出土文献是简牍碑刻等地下材料；两类对照才能判断史料价值。", "wrong": true, "keys": ["历史|8|1"]}, {"subject": "历史", "name": "汉代中朝（内朝）与外朝", "core": "汉武帝提拔尚书等近臣组成中朝决策，外朝丞相百官渐成执行机构，决策环节被皇帝收回。", "wrong": true, "keys": ["历史|11|1"]}, {"subject": "历史", "name": "皇权与相权的消长", "core": "中朝崛起的实质是皇权压倒相权、决策权向皇帝集中，是君主专制强化的主线之一。", "wrong": true, "keys": ["历史|11|1"]}, {"subject": "历史", "name": "隋朝的统治危机", "core": "隋炀帝滥用民力、屡征高句丽，社会矛盾总爆发；官仓充盈而吏不敢赈，恰暴露统治已经失能。", "wrong": true, "keys": ["历史|15|1"]}, {"subject": "历史", "name": "材料题的分层解读", "core": "读材料先分层抓全信息点，再向上推一层实质；只抓一层表层信息最容易错选。", "wrong": true, "keys": ["历史|15|1"]}, {"subject": "历史", "name": "中书省：草拟诏令", "core": "唐代中书省掌草拟、颁布皇帝诏令，题干出现“文书皆出其手”就是中书省的职能信号。", "wrong": true, "keys": ["历史|20|1"]}, {"subject": "历史", "name": "门下省：审核封驳", "core": "门下省掌审议诏令，有封还驳正之权，与中书省一拟一审，是最容易成对记反的一组。", "wrong": true, "keys": ["历史|20|1"]}, {"subject": "历史", "name": "尚书省与六部：执行政令", "core": "尚书省是最高行政执行机构，下辖吏、户、礼、兵、刑、工六部，负责贯彻落实政令。", "wrong": false, "keys": []}, {"subject": "历史", "name": "枢密院的时代坐标", "core": "枢密院始置于五代、定型于宋代掌军政，唐代并无此机构；选项见枢密院先排除唐代背景。", "wrong": true, "keys": ["历史|20|1"]}, {"subject": "历史", "name": "铁器与牛耕的推广", "core": "铁器出现于春秋、战国得到推广，牛耕渐兴，生产力跃升是变法与兼并战争的物质基础。", "wrong": true, "keys": ["历史|6|1"]}, {"subject": "历史", "name": "青铜器的用途辨析", "core": "商周青铜主要用于铸造礼器、兵器，农具仍以木、石、骨蚌为主，“青铜农具广泛使用”多为错项。", "wrong": true, "keys": ["历史|6|1"]}, {"subject": "历史", "name": "江南农业的表现：圩田与陂塘", "core": "魏晋至唐江南修陂塘、围湖成圩田，开田增产、岁增粟帛；答“表现”题要用这类关键词踩点。", "wrong": true, "keys": ["历史|22(1)|1"]}, {"subject": "历史", "name": "北方人口南迁", "core": "战乱推动北民南迁，为南方带去劳动力与先进生产技术，是江南开发的首要因素。", "wrong": true, "keys": ["历史|22(2)|1"]}, {"subject": "历史", "name": "土断政策", "core": "东晋南朝清查户籍、把侨寓人口土著化，既增加国家赋役，也让南迁人口安定下来从事生产。", "wrong": true, "keys": ["历史|22(2)|1"]}, {"subject": "历史", "name": "农具进步：曲辕犁", "core": "唐代曲辕犁灵活轻便、适应南方水田，是江南农业技术进步的标志性得分点。", "wrong": true, "keys": ["历史|22(2)|1"]}, {"subject": "历史", "name": "经济重心南移", "core": "经济重心从魏晋开始南移，唐中后期加速，南宋最终完成，江南逐渐成为国家财赋重地。", "wrong": false, "keys": []}, {"subject": "历史", "name": "区域经济：因地制宜", "core": "区域发展要发挥本地资源与区位优势、扬长避短，这是江南开发史给今天区域经济的启示落点。", "wrong": false, "keys": []}, {"subject": "历史", "name": "百家争鸣的社会背景", "core": "分封崩解、士阶层崛起、私学兴起与诸侯争霸求贤，使春秋战国思想文化空前活跃。", "wrong": true, "keys": ["历史|23|1"]}, {"subject": "历史", "name": "百家争鸣的主要学派", "core": "儒、道、法、墨为核心：儒倡仁礼、道主无为、法尚法治集权、墨主兼爱非攻，须成对辨清主张。", "wrong": true, "keys": ["历史|23|1"]}, {"subject": "历史", "name": "百家争鸣的历史影响", "core": "百家争鸣奠定中国传统文化格局，其治国理念与人文精神对后世治理与文化影响深远。", "wrong": true, "keys": ["历史|23|1"]}, {"subject": "语文", "name": "论述类文本：观点与论据对应（防张冠李戴）", "core": "论述文里谁的观点、哪句是论据必须对位，选项常把作者观点安到被引者头上，须回原文核对人称。", "wrong": true, "keys": ["语文|1|1"]}, {"subject": "语文", "name": "论述类文本：逐项比对与逆向设问", "core": "“不正确的一项”要反着选；每个选项逐项回原文核对细微表述，差一个词即为错项。", "wrong": false, "keys": []}, {"subject": "语文", "name": "简答题：按分值定点数、分点提炼", "core": "6分题先预设3到4个得分点，回材料分层提炼，再用原文术语作答，避免口语化与漏角度。", "wrong": true, "keys": ["语文|4|1"]}, {"subject": "语文", "name": "小说标题的多重内涵", "core": "标题常兼指地点、事件、人物命运与主题象征，答内涵要从表层义挖到象征义、主题义。", "wrong": true, "keys": ["语文|8|1"]}, {"subject": "语文", "name": "小说中的象征手法", "core": "象征是借具体物象寄托抽象意义；找象征义要联系人物命运与主题，别只答出第一层。", "wrong": true, "keys": ["语文|8|1"]}, {"subject": "语文", "name": "小说中反复意象的作用", "core": "反复出现的声音、景物等意象可渲染氛围、结构全篇、暗示人物心境与主题，答作用要多角度。", "wrong": false, "keys": []}, {"subject": "语文", "name": "文言文断句方法", "core": "断句抓语气词后断、句首虚词前断、主谓宾结构验断，再结合句意通读检验。", "wrong": true, "keys": ["语文|9|1"]}, {"subject": "语文", "name": "文言特殊句式：“得无…乎”", "core": "“得无…乎”是表推测的反问句式，译为“莫非…吗”，最忌把推测语气译反。", "wrong": true, "keys": ["语文|12(1)|1"]}, {"subject": "语文", "name": "通假字（“被”通“披”）", "core": "古书以音同音近字代替本字，“被”通“披”即穿着之义；翻译遇不通处先想通假。", "wrong": true, "keys": ["语文|12(1)|1"]}, {"subject": "语文", "name": "文言句式：状语后置", "core": "介词短语作状语常后置，如“钓于渭滨”应译“在渭水边钓鱼”，翻译时须调回状中顺序。", "wrong": true, "keys": ["语文|12(1)|1"]}, {"subject": "语文", "name": "文言翻译：字字落实", "core": "翻译按留、删、换、调、补逐字落实，得分点多在实词、虚词与句式上，漏一词丢一分。", "wrong": true, "keys": ["语文|12(1)|1", "语文|12(2)|1"]}, {"subject": "语文", "name": "文言实词：语境义与一词多义", "core": "实词须结合语境定夺，如“击水”在中流语境中是游泳；只背常用义最容易掉进选项的坑。", "wrong": true, "keys": ["语文|12(2)|1", "语文|18|1"]}, {"subject": "语文", "name": "文言虚词“之”的用法", "core": "“之”可作助词“的”、代词、动词“到”、音节助词；判断时用替换法逐句检验。", "wrong": true, "keys": ["语文|19|1"]}, {"subject": "语文", "name": "古今异义", "core": "古今异义指词义古今发生演变；判断题须逐词核对古义，不能凭现代语感猜，形同义异者最坑。", "wrong": true, "keys": ["语文|20|1"]}, {"subject": "语文", "name": "字音：多音字与易错字音", "core": "字音题专考多音字与形近字，如揳入、忸怩、皱褶、包扎读音各异，须按词义与语境定读音。", "wrong": true, "keys": ["语文|17|1"]}, {"subject": "语文", "name": "修辞：借代", "core": "借代是不直说本体，用与之相关的事物代称，如以“杜康”代酒；关键看代体与本体的相关性。", "wrong": true, "keys": ["语文|23|1"]}, {"subject": "语文", "name": "修辞：互文", "core": "互文是上下句词语相互呼应、参互成义，须合起来理解，不能把两句拆开各自硬解。", "wrong": true, "keys": ["语文|23|1"]}, {"subject": "语文", "name": "诗歌意象与意境", "core": "赏析诗歌先抓意象组合营造的意境，再落到情感；王维田园诗以清幽恬淡见长。", "wrong": false, "keys": []}, {"subject": "语文", "name": "诗歌情感比较阅读", "core": "同题材诗歌比情感，先各自定情感基调，再从题材、意象、措辞找异同点分点作答。", "wrong": false, "keys": []}, {"subject": "语文", "name": "材料概括题：抓共同指向", "core": "多则材料题先逐则提炼要点，再找共同指向作答，如三则材料同指曹操求贤若渴。", "wrong": true, "keys": ["语文|13|1"]}, {"subject": "语文", "name": "名篇名句默写", "core": "默写靠理解性记忆，《沁园春·长沙》《短歌行》《归园田居》等须不错字、不漏字、不添字。", "wrong": false, "keys": []}, {"subject": "语文", "name": "作文立意：多则材料找共同指向", "core": "材料作文先逐则抓关键词，再提炼共同指向定立意，如由曹操、李白、黄文秀收束到新时代青年。", "wrong": true, "keys": ["语文|25|1"]}, {"subject": "语文", "name": "作文结构：分论点递进", "core": "议论文用递进式分论点推进，段首立论点、段中给事例、段末加分析句，避免只堆材料。", "wrong": true, "keys": ["语文|25|1"]}, {"subject": "语文", "name": "作文选材与事例分析", "core": "题目自带的事例要转化角度使用，事例后必须跟一句分析扣回论点，否则沦为抄材料。", "wrong": true, "keys": ["语文|25|1"]}, {"subject": "语文", "name": "成语辨析", "core": "成语题防望文生义、对象误用与褒贬误置，须先想准成语的含义与适用对象再代入句子。", "wrong": false, "keys": []}, {"subject": "语文", "name": "病句辨析", "core": "病句常考成分残缺、搭配不当、语序不当、句式杂糅，压缩句子主干最容易让问题现形。", "wrong": false, "keys": []}, {"subject": "语文", "name": "语句歧义", "core": "歧义来自多义词、指代不明与断句不同，判断时要能说出同一句话的两种不同理解。", "wrong": false, "keys": []}, {"subject": "语文", "name": "书写规范与卷面", "core": "卷面书写潦草可能被扣卷面分，主观题与作文尤其要字迹工整、分段清晰。", "wrong": false, "keys": []}, {"subject": "化学", "name": "化学实验安全与试剂存放规范", "core": "剩余金属钠放回原试剂瓶；钠着火用沙土灭；氯水避光存于棕色瓶；浓硫酸与强碱须分开存放。", "wrong": true, "keys": ["化学|1|1"]}, {"subject": "化学", "name": "氧化物的概念与判断", "core": "氧化物只含两种元素且其中一种是氧元素；H2SO4含氢、硫、氧三种元素，是酸不是氧化物。", "wrong": false, "keys": []}, {"subject": "化学", "name": "化学变化的本质与守恒观念", "core": "化学变化有新物质生成，本质是原子的重新组合，反应前后原子种类与数目守恒。", "wrong": false, "keys": []}, {"subject": "化学", "name": "钠投入盐溶液的反应顺序", "core": "钠先与水反应生成NaOH和H2，NaOH再与盐发生复分解；钠不会置换出溶液中的金属。", "wrong": true, "keys": ["化学|4|1"]}, {"subject": "化学", "name": "氯气与氯水的成分", "core": "氯气黄绿色、有毒；新制氯水含Cl2、HClO、盐酸等，杀菌消毒靠HClO而非Cl2本身。", "wrong": true, "keys": ["化学|7|1"]}, {"subject": "化学", "name": "次氯酸的性质（强氧化性与见光分解）", "core": "HClO有强氧化性、能漂白杀菌，见光易分解为HCl和O2，故氯水须避光保存。", "wrong": true, "keys": ["化学|7|1", "化学|11-(4)|1"]}, {"subject": "化学", "name": "物质的量与微粒数换算", "core": "微粒数之比等于物质的量之比；求原子总数要乘以每个分子的原子个数后再比较。", "wrong": true, "keys": ["化学|8|1"]}, {"subject": "化学", "name": "气体摩尔体积的适用条件", "core": "22.4 L/mol只适用于标准状况下的气体，固体、液体和非标况气体都不能直接套用。", "wrong": true, "keys": ["化学|9|1"]}, {"subject": "化学", "name": "阿伏加德罗定律", "core": "同温同压下，相同体积的任何气体含有相同数目的分子，物质的量也相等。", "wrong": true, "keys": ["化学|9|1"]}, {"subject": "化学", "name": "摩尔质量与质量换算（n=m/M）", "core": "物质的量等于质量除以摩尔质量；等质量气体物质的量之比与摩尔质量成反比。", "wrong": false, "keys": []}, {"subject": "化学", "name": "由气体体积反推摩尔质量与相对原子质量", "core": "标况下先由体积求物质的量，再用质量除以物质的量得摩尔质量，进而求相对原子质量。", "wrong": false, "keys": []}, {"subject": "化学", "name": "气体的除杂与干燥（试剂选择与顺序）", "core": "除Cl2中的HCl用饱和食盐水，干燥用浓硫酸；顺序先除杂后干燥，防止水汽重新带入。", "wrong": true, "keys": ["化学|10|1", "化学|14-(1)-BDC|1"]}, {"subject": "化学", "name": "实验装置评价与基本操作规范", "core": "钠的燃烧用坩埚；稀释浓硫酸要酸入水、不断搅拌，不能在量筒中稀释。", "wrong": true, "keys": ["化学|10|1"]}, {"subject": "化学", "name": "化学方程式的配平", "core": "依据质量守恒配平各元素原子个数，原子团作整体处理，配平后逐个元素核对。", "wrong": true, "keys": ["化学|11-(1)|1", "化学|11-(2)|1", "化学|11-(3)|1", "化学|11-(4)|1", "化学|11-(5)|1", "化学|11-(6)|1", "化学|13-(1)|1", "化学|13-(2)-方程1|1", "化学|14-(1)-方程|1", "化学|14-(3)|1"]}, {"subject": "化学", "name": "反应条件的标注（点燃、加热、光照）", "core": "燃烧标点燃、见光分解标光照、需要加热标加热；条件漏写或写错，方程式不规范。", "wrong": true, "keys": ["化学|11-(1)|1", "化学|11-(2)|1", "化学|11-(3)|1", "化学|11-(4)|1", "化学|14-(1)-方程|1"]}, {"subject": "化学", "name": "气体与沉淀符号的标注（↑、↓）", "core": "反应物无气体而生成气体标↑，溶液中生成难溶物标↓；H2、Cu(OH)2等都不能漏标。", "wrong": true, "keys": ["化学|11-(4)|1", "化学|11-(6)|1", "化学|13-(1)|1", "化学|14-(1)-方程|1"]}, {"subject": "化学", "name": "常见化学方程式书写（产物判断）", "core": "先判对产物再写方程式：钠加热得Na2O2、铁在氯气中得FeCl3、氢气在氯气中得HCl。", "wrong": true, "keys": ["化学|11-(1)|1", "化学|11-(2)|1", "化学|11-(3)|1", "化学|13-(1)|1", "化学|13-(2)-方程1|1"]}, {"subject": "化学", "name": "金属在氯气中燃烧的产物价态", "core": "氯气氧化性强，变价金属在Cl2中生成高价氯化物，如铁生成FeCl3，与盐酸反应不同。", "wrong": true, "keys": ["化学|11-(3)|1"]}, {"subject": "化学", "name": "钠与氧气反应的产物随条件变化", "core": "钠常温氧化生成Na2O，加热时生成淡黄色的Na2O2，条件决定产物。", "wrong": true, "keys": ["化学|11-(1)|1"]}, {"subject": "化学", "name": "钠与水反应的方程式与现象", "core": "钠与水生成NaOH和H2；现象浮、熔、响、游，钠熔成小球浮在水面并放出气体。", "wrong": true, "keys": ["化学|13-(1)|1"]}, {"subject": "化学", "name": "过氧化钠的性质与用途", "core": "Na2O2为淡黄色固体，与水、CO2反应放出O2，可作供氧剂，是强氧化剂。", "wrong": true, "keys": ["化学|13-(2)-方程1|1"]}, {"subject": "化学", "name": "碳酸钠与盐酸的反应", "core": "Na2CO3与过量盐酸生成NaCl、水和CO2；酸少量时先生成NaHCO3，反应分步进行。", "wrong": false, "keys": []}, {"subject": "化学", "name": "化合价的判断（特殊氢化物）", "core": "按元素得失电子定化合价：NaH中钠为+1价、氢为-1价；NaH遇水生成NaOH和H2。", "wrong": false, "keys": []}, {"subject": "化学", "name": "钠投入硫酸铜溶液的实验现象", "core": "钠浮、熔、响并放出气体，同时生成蓝色Cu(OH)2沉淀；不会析出红色的铜。", "wrong": true, "keys": ["化学|13-(5)|1"]}, {"subject": "化学", "name": "复分解反应与沉淀生成", "core": "两种化合物交换成分生成沉淀、气体或水时复分解发生；CuSO4与NaOH生成蓝色沉淀。", "wrong": true, "keys": ["化学|11-(6)|1"]}, {"subject": "化学", "name": "氯气的实验室制法", "core": "MnO2与浓盐酸加热反应制取Cl2，属固液加热型装置，用分液漏斗添加浓盐酸。", "wrong": true, "keys": ["化学|14-(1)-方程|1"]}, {"subject": "化学", "name": "氯气的尾气处理", "core": "Cl2有毒，多余氯气用NaOH溶液吸收，生成NaCl、NaClO和水，防止污染空气。", "wrong": true, "keys": ["化学|14-(3)|1"]}, {"subject": "化学", "name": "漂白粉的制取与有效成分", "core": "氯气通入石灰乳制得漂白粉，主要成分CaCl2和Ca(ClO)2，有效成分是Ca(ClO)2。", "wrong": true, "keys": ["化学|11-(5)|1", "化学|14-(5)|1"]}, {"subject": "化学", "name": "漂白粉的变质与检验", "core": "漂白粉久置与CO2、水作用生成CaCO3失效；加稀盐酸冒气泡证明变质，品红褪色证明仍有效。", "wrong": true, "keys": ["化学|14-(5)|1"]}, {"subject": "化学", "name": "氯水的成分随时间变化（久置氯水）", "core": "新制氯水含Cl2和HClO；久置后HClO全部分解，最终变为稀盐酸，光照气泡是O2。", "wrong": false, "keys": []}, {"subject": "生物", "name": "细胞学说的内容", "core": "细胞是一个有机体，一切动植物都由细胞发育而来；新细胞由老细胞分裂产生。", "wrong": true, "keys": ["生物|1|1"]}, {"subject": "生物", "name": "细胞学说的意义", "core": "阐明动植物的统一性，把生物学研究推进到细胞水平；不涉及原核真核分类和分子水平。", "wrong": true, "keys": ["生物|1|1"]}, {"subject": "生物", "name": "蛋白质的显色检测（双缩脲试剂）", "core": "双缩脲试剂与肽键反应呈紫色，只能检测蛋白质；氨基酸无肽键，不显紫色。", "wrong": true, "keys": ["生物|3|1"]}, {"subject": "生物", "name": "脂肪的显色检测（苏丹Ⅲ）", "core": "苏丹Ⅲ染液使脂肪呈现橘黄色，检测时制片后在显微镜下观察橘黄色颗粒。", "wrong": true, "keys": ["生物|3|1"]}, {"subject": "生物", "name": "淀粉的显色检测（碘液）", "core": "淀粉遇碘液变蓝色，是鉴定淀粉最常用的显色反应，常用于检测组织中是否含有淀粉。", "wrong": true, "keys": ["生物|3|1"]}, {"subject": "生物", "name": "斐林试剂的使用方法", "core": "甲液乙液等量混合后立即使用，必须水浴加热才出现砖红色沉淀，未加热不能下结论。", "wrong": true, "keys": ["生物|17|1", "生物|24-(1)-③|1"]}, {"subject": "生物", "name": "还原糖与非还原糖", "core": "葡萄糖等是还原糖，蔗糖、淀粉是非还原糖；定量对照只能用还原糖标准液。", "wrong": true, "keys": ["生物|17|1"]}, {"subject": "生物", "name": "细胞是生命活动的基本单位", "core": "一切生命活动都以细胞为基础，单细胞生物靠一个细胞、多细胞生物靠细胞协同完成。", "wrong": true, "keys": ["生物|6|1"]}, {"subject": "生物", "name": "病毒无细胞结构", "core": "病毒没有细胞结构、不属于原核生物，只能寄生在活细胞内，不能独立代谢。", "wrong": true, "keys": ["生物|12|1", "生物|21-(1)|1"]}, {"subject": "生物", "name": "无机盐在细胞中的存在形式", "core": "无机盐在细胞中大多数以离子形式存在，少数构成复杂化合物，如血红蛋白中的铁。", "wrong": false, "keys": []}, {"subject": "生物", "name": "无机盐的功能", "core": "无机盐维持细胞和生物体的生命活动，还维持渗透压和酸碱平衡，如钙盐的作用。", "wrong": false, "keys": []}, {"subject": "生物", "name": "大量元素与微量元素", "core": "大量元素有C、H、O、N、P、S、K、Ca、Mg；Zn、Fe、Cu等是微量元素，Zn不是大量元素。", "wrong": false, "keys": []}, {"subject": "生物", "name": "特征元素与化合物的对应", "core": "缺Mg影响叶绿素合成使叶片发黄，缺Fe影响血红蛋白可导致贫血，磷参与构成磷脂和核酸。", "wrong": false, "keys": []}, {"subject": "生物", "name": "细胞中含量最多的化合物", "core": "活细胞中含量最多的化合物是水，含量最多的有机化合物是蛋白质。", "wrong": true, "keys": ["生物|22-(1)-①|1"]}, {"subject": "生物", "name": "自由水与结合水的区别", "core": "自由水可自由流动、参与代谢和运输；结合水与其他物质结合，是细胞结构的组成成分。", "wrong": true, "keys": ["生物|22-(1)-①|1"]}, {"subject": "生物", "name": "自由水/结合水比值与代谢、抗逆性", "core": "比值高则代谢旺盛、抗逆性弱；种子萌发时比值上升，晒干休眠时自由水减少。", "wrong": true, "keys": ["生物|22-(1)-①|1", "生物|22-(3)|1"]}, {"subject": "生物", "name": "自由水的功能", "core": "自由水是细胞内良好的溶剂，参与化学反应，运输营养物质和代谢废物。", "wrong": true, "keys": ["生物|22-(4)|1"]}, {"subject": "生物", "name": "种子晒干与燃烧灰烬的成分", "core": "种子晒干主要失去自由水，结合水基本保留；充分燃烧后剩余的灰烬主要是无机盐。", "wrong": true, "keys": ["生物|22-(1)-①|1", "生物|22-(2)-②|1"]}, {"subject": "生物", "name": "原核细胞与真核细胞的划分依据", "core": "以有无核膜为界限的细胞核划分：原核细胞无成形细胞核，真核细胞有。", "wrong": true, "keys": ["生物|21-(2)-②|1"]}, {"subject": "生物", "name": "原核生物的常见代表", "core": "细菌、蓝细菌是原核生物；酵母菌、草履虫和动植物细胞都是真核生物。", "wrong": true, "keys": ["生物|21-(2)-②|1"]}, {"subject": "生物", "name": "原核与真核细胞的统一性", "core": "两者都具有细胞膜、细胞质、核糖体和遗传物质DNA，体现细胞结构的统一性。", "wrong": true, "keys": ["生物|21-(2)-③|1"]}, {"subject": "生物", "name": "蓝细菌的光合作用与水华", "core": "蓝细菌无叶绿体，但含叶绿素和藻蓝素能进行光合作用；大量繁殖可引起水华。", "wrong": true, "keys": ["生物|21-(3)-②|1"]}, {"subject": "生物", "name": "氨基酸的结构通式与结构特点", "core": "每个氨基酸至少一个氨基和一个羧基连在同一碳原子上，该碳还连一个氢和一个R基。", "wrong": true, "keys": ["生物|23-(1)|1"]}, {"subject": "生物", "name": "脱水缩合与肽键数计算", "core": "脱去的水分子数等于形成的肽键数，等于氨基酸总数减去肽链条数。", "wrong": true, "keys": ["生物|23-(3)-②|1", "生物|20|1"]}, {"subject": "生物", "name": "氨基酸种类由R基决定（个数≠种类数）", "core": "氨基酸种类看R基是否相同：R基只有四种时，五个氨基酸也只是四种。", "wrong": true, "keys": ["生物|20|1"]}, {"subject": "生物", "name": "蛋白质相对分子质量计算与二硫键", "core": "减少量等于脱去水的质量再加二硫键脱去的氢，每个二硫键形成时再脱去2个H。", "wrong": true, "keys": ["生物|23-(3)-③|1"]}, {"subject": "生物", "name": "R基与游离氨基、羧基的辨认", "core": "R基是中心碳上的侧链基团；游离氨基、羧基分布在肽链两端和R基上，要逐个数清。", "wrong": true, "keys": ["生物|23-(4)-②|1"]}, {"subject": "生物", "name": "蛋白质的变性", "core": "高温等破坏蛋白质的空间结构使其失活，但肽键不断裂，变性后更易被蛋白酶水解。", "wrong": true, "keys": ["生物|18|1", "生物|20|1"]}, {"subject": "生物", "name": "蛋白质结构与功能的关系", "core": "蛋白质的生物活性取决于空间结构，二硫键的数目和位置会影响空间结构进而影响活性。", "wrong": false, "keys": []}, {"subject": "生物", "name": "实验材料的选择与变量控制", "core": "探究某物质的作用时，材料本身应不含、也不能合成该物质，避免内源因素干扰。", "wrong": true, "keys": ["生物|24-(2)-①|1"]}, {"subject": "生物", "name": "对照实验的设计（等量与单一变量）", "core": "实验组与对照组只差一个自变量，其余条件等量且相同，如对照加等量不含该物质的培养液。", "wrong": true, "keys": ["生物|24-(2)-③|1"]}, {"subject": "生物", "name": "实验条件的关键限定（低温处理）", "core": "验证保护作用必须把两组都置于题目限定的不良条件下处理，漏掉限定词实验不成立。", "wrong": true, "keys": ["生物|24-(2)-③|1"]}, {"subject": "生物", "name": "预期结果与结论的对应表述", "core": "预期要写全两种走向：实验组优于对照则假设成立，无显著差异则不成立，一一对应。", "wrong": true, "keys": ["生物|24-(2)-⑤|1"]}, {"subject": "生物", "name": "实验中无关变量的排除（脱色处理）", "core": "材料本身的颜色会干扰显色观察，脱色等预处理是为了排除无关变量对结果的干扰。", "wrong": false, "keys": []}, {"subject": "生物", "name": "细胞的多样性", "core": "不同细胞形态结构差异很大，是细胞多样性的表现，但都具有细胞的基本结构。", "wrong": false, "keys": []}], "pairs": [{"subject": "英语", "a_name": "-ing 形容词（confusing / stressful）", "a_def": "修饰物或事，表示'令人……的'；判断特征：主语或所修饰的名词是事情本身，如 The problem is confusing.（这道题令人困惑）", "b_name": "-ed 形容词（confused / stressed）", "b_def": "修饰人，表示'感到……的'；判断特征：主语是人，常跟在 feel、be 后面，如 I feel stressed.（我感到有压力）", "diff": "差在感受的方向：-ing 是'发出去'的，事物让人产生感觉；-ed 是'收回来'的，人接收到感觉。判断步骤：先看修饰谁——名词是物（problem、news）用 -ing，是人或跟在 feel 后面用 -ed。她这次两头栽：完成句子里 maths problem 后面选错形式得 0 分，听力问感受时又挑了 stressful 的方向。抓手：物用 -ing，人用 -ed；听力里先听到 feel，笔就往 -ed 落。", "check_q": "选词填空（exciting / excited，各用一次）：① The news was so ___ that everyone cheered. ② We were all ___ at the news.", "check_a": "① exciting（news 是物，'令人兴奋'）；② excited（we 是人，'感到兴奋'）", "keys": ["英语|67|1", "英语|14|1"]}, {"subject": "英语", "a_name": "不定式 to（to do）", "a_def": "后接动词原形，表目的；判断特征：句子已有谓语，能用'为了……'提问，且 to 后必须能还原成一个动作，如 eat something to reduce pressure（吃东西来减压）", "b_name": "介词 to（固定短语里的 to）", "b_def": "是短语的一部分，后接名词或动名词 -ing；判断特征：to 不能单译、属于 be addicted to、look forward to 这类整条短语，如 addicted to playing games（沉迷于玩游戏）", "diff": "两个 to 长得一样、脾气相反：不定式 to 后只跟动词原形，介词 to 后跟名词或 -ing。判断步骤：先看 to 前面是不是固定短语（be addicted to、look forward to）——是，to 就是介词，后面用 doing；不是短语、又能问出'为了什么'，就是不定式，用原形。她这次一题写 to surprised，把 -ed 形容词塞进不定式；一题 addicted to 整条不会。抓手：先认短语，再看 to 后。", "check_q": "用所给词的正确形式填空：① He went to the library ___ (borrow) some books. ② He is addicted to ___ (play) mobile games.", "check_a": "① borrow（不定式表目的，to 后跟动词原形）；② playing（be addicted to 的 to 是介词，后接动名词）", "keys": ["英语|57|1", "英语|72|1"]}, {"subject": "英语", "a_name": "excuse（借口）", "a_def": "为掩盖真相编出的说法，带贬义；判断特征：后面常跟着真相被揭穿，如 just an excuse（不过是个借口）", "b_name": "reason（原因、理由）", "b_def": "真实的原因或正当理由，中性词；判断特征：经得起追问，常与 for 连用，如 the reason for being late（迟到的真实原因）", "diff": "差在真假：reason 是事实本身，excuse 是为了脱身编的壳。判断步骤：盯语境信号——出现 just（不过是）、in fact（其实）时，前面的说法多半是编的，选 excuse；正经回答'为什么'时选 reason。她这次完形里破折号后写着 in fact he had overslept，真相已点破，她还是选了 reason。抓手：有揭穿信号就选 excuse，看到 just 和 in fact 先警惕。", "check_q": "选词填空（excuse / reason）：He said his bike was broken, but that was just an ___ — he simply didn't want to go.", "check_a": "excuse（just 加上后文拆穿'只是不想去'，说明前面的说法是借口，不是真实原因）", "keys": ["英语|48|1"]}, {"subject": "英语", "a_name": "other than（除了）", "a_def": "常跟在 nothing、nobody、no 等否定词后面，后接动词原形或名词；判断特征：整句带否定，如 He does nothing other than study.（他除了学习什么都不做）", "b_name": "except for（除了）", "b_def": "用在肯定句里，先整体肯定、只挑出一个例外，后接名词；判断特征：句子可以先夸一遍再转折，如 The room is nice except for the noise.（房间挺好，就是有点吵）", "diff": "差在句子的底色：other than 站在否定句里（nothing... other than...），except for 站在肯定句里（先肯定整体，再挑一个刺）。判断步骤：先看整句有没有 nothing、nobody 这类否定词——有，优先 other than；先肯定再挑例外，用 except for。她这次两个都写不出来，是整条没背。抓手：'什么都不，只…'用 other than，'样样都好就差一点'用 except for，成对背。", "check_q": "选词填空（other than / except for）：① The classroom was empty ___ a few desks. ② She eats nothing ___ fruit for dinner.", "check_a": "① except for（先肯定'空'这个整体状态，再挑出课桌这个例外，后接名词）；② other than（句中有 nothing 否定词，是 other than 的主场）", "keys": ["英语|75|1"]}, {"subject": "英语", "a_name": "confidence（名词）", "a_def": "-ence 结尾的名词'自信'；判断特征：能站在形容词、冠词或介词后面，如 with great confidence（自信地）、have confidence in（对……有信心）", "b_name": "confident（形容词）", "b_def": "-ent 结尾的形容词'自信的'；判断特征：修饰名词作定语，或跟在 be 后作表语，如 a confident smile（自信的微笑）、be confident of（对……有把握）", "diff": "差在词性：空前面是形容词（great）或介词（with），槽位要名词，用 confidence；空在名词前作定语、或在 be 后作表语，才用形容词 confident。判断步骤：先看空的邻居——'形容词+空'或'介词+空'填名词，'空+名词'或'be+空'填形容词。她这次 with great ___ 填了 confident，位置看对、词性看错，0 分。抓手认尾巴：-ence 是名词，-ent 是形容词。", "check_q": "选词填空（confidence / confident）：① Speak with ___ and the audience will trust you. ② She gave a ___ answer without any hesitation.", "check_a": "① confidence（with 是介词，后面必须接名词）；② confident（a ___ answer，空后是名词 answer，要形容词作定语）", "keys": ["英语|66|1"]}, {"subject": "英语", "a_name": "For（对于……来说）", "a_def": "句首 For + 人或人群 + 逗号，表'就……而言'；判断特征：后面跟的是完整主句，是在讲对某一类对象的情况，如 For children, sleep matters.（对孩子来说，睡眠很重要）", "b_name": "at（在……时刻/地点）", "b_def": "只管时间和地点的小点；判断特征：后接钟点或场所，如 at 7 o'clock（在七点）、at school（在学校），永远不能用来对人说'对于'", "diff": "差在管辖范围：at 钉的是一个时间点或地点，for 站在句首管的是一整类对象。判断步骤：空后是人或人群、带逗号、后面是完整句子，先想 for（对于……来说）；空后是钟点、时刻、校门口这类点位，才用 at。她这次把 at 当成万能介词填进句首，可 at children 根本不成立——at 从不'对于'人。抓手：句首'对于'必 for，at 只配时间和地点这两个'点'，动笔前先看空后跟的是人还是钟点。", "check_q": "选词填空（For / At）：① ___ teenagers, music is a way to relax. ② The train leaves ___ half past seven.", "check_a": "① For（对青少年来说：后接人群加完整主句）；② At（后接钟点 half past seven，at 管时间点）", "keys": ["英语|56|1"]}, {"subject": "语文", "a_name": "借代", "a_def": "不用本体，用与本体相关的特征、工具或人物来代替它，如以造酒者“杜康”代酒。", "b_name": "互文", "b_def": "上下两句各说一半、意思互相补充，必须合起来理解，如“秦时明月汉时关”实指秦汉共有的明月与关隘。", "diff": "差在一句话能不能独立成立。借代是单句内部的替换：用特征、工具或相关人物顶替本体，换回本体句子照样通，如杜康代酒。互文是跨句的拼接：上下句各藏一半意思，单看残缺，必须合起来读，如秦时明月汉时关。她这次把 A 项的互文当成了借代，就是没做这一步检验。判断抓手：先把句子单独读，意思残缺、要靠邻句补全的是互文；能找到一个“替身词”并换回本体的是借代。口诀：借代找替身，互文找拼图。", "check_q": "“开我东阁门，坐我西阁床”用的是借代还是互文？为什么？", "check_a": "互文。上下句的动作是交叉着说的，实际是开门、坐床在东西阁都做，必须合起来读才完整；句中没有“以特征代本体”的替身词，所以不是借代。", "keys": ["语文|23|1"]}, {"subject": "语文", "a_name": "作者观点", "a_def": "文章写作者本人的主张和评价，是全文要证明的结论，常出现在议论句、总结句里。", "b_name": "论据人物观点", "b_def": "材料中被引用的人物及其言行，只是作者用来证明主张的例子，人物本人未必持有作者的评价。", "diff": "差在“谁在表态”。作者观点是写文章的人自己的主张；论据人物的言行只是被引用来证明主张的材料。这道题里，批评有人写诗像机器拼凑、缺乏诗意的是文章作者，江湜只是被拿来讨论的诗人例子，他的话是论据。她没圈选项主语，凭印象把作者的话安到江湜头上，正中张冠李戴的套。判断抓手：先圈选项里的主语（谁说、谁认为），再回原文找这个人名所在的段落逐字比对，主语对不上、找不到出处的立刻排除。", "check_q": "材料引用诗人江湜的诗，借此批评“当下写诗只会拼凑”。选项说“江湜认为当下写诗只会拼凑”，对不对？", "check_a": "不对。批评是作者借材料发表的观点，江湜只是被引用的论据人物；选项把作者观点安到论据人物头上，是典型的张冠李戴。", "keys": ["语文|1|1"]}, {"subject": "语文", "a_name": "助词“之”（的）", "a_def": "放在定语和中心词之间表修饰，相当于“的”，如“水陆草木之花”。", "b_name": "动词“之”（到、往）", "b_def": "实义动词，意思是到、往，后面常跟地点名词，如“送孟浩然之广陵”。", "diff": "差在能不能替换。助词之放在名词性成分之间表修饰，换成“的”读得通，如水陆草木之花；动词之是实义动词“到、往”，后面跟地点，换成“的”立刻不通，如送孟浩然之广陵。她这次的问题不是不知道有区别，而是凭语感猜、没逐项替换检验，连 C 项两个之都是“的”都没看出来。判断抓手：把每个之依次试换“的”“他/它”“到”，哪个通顺就是哪种用法，做完再回头比较各项是否相同。", "check_q": "“送杜少府之任蜀州”与“水陆草木之花”中的两个“之”，用法相同吗？各是什么用法？", "check_a": "不同。前者是动词“之”，意为到、去（送他赴任蜀州）；后者是助词“之”，相当于“的”。抓手：能换成“的”的是助词，后跟地点、能换成“到/前往”的是动词。", "keys": ["语文|19|1"]}, {"subject": "语文", "a_name": "古今异义", "a_def": "词形没变，词义随时代改变，如“卑鄙”古指地位低微、见识浅陋，今指品德坏；“妻子”古指妻和子，今只指配偶。", "b_name": "通假字", "b_def": "古人借一个同音字代替本字来写，字是借的、词义不变，如“辟”通“避”、“说”通“悦”，认出本字意思就通。", "diff": "差在变的是字还是义。古今异义：字还是那个字，词义随时代变了，如卑鄙、妻子。通假字：意思没变，只是古人借了同音字来写，如辟通避。她这次在古今异义题里拿现代义硬套古句，把相同与不同判反，病根是没把词放回原句翻译检验。判断抓手：按今义译不通时分两步走——先想这个词的古义是不是与今义不同（古今异义），再想它是不是同音借字（通假），两步分开，别混成一团。", "check_q": "《出师表》“先帝不以臣卑鄙”的“卑鄙”，和“由是则可以辟患而有不为也”的“辟”，哪个是古今异义、哪个是通假字？", "check_a": "“卑鄙”是古今异义：古义地位低微、见识浅陋（自谦），今义品德坏。“辟”是通假字，通“避”，躲避的意思，字借用而义不变。", "keys": ["语文|20|1"]}, {"subject": "历史", "a_name": "中书省", "a_def": "三省之首，负责决策、草拟诏令，皇帝的文书出自其手，是“出令”的。", "b_name": "门下省", "b_def": "负责审议诏令，把关纠错，认为不妥可以封还驳回，是“把关”的；其后的尚书省只负责执行。", "diff": "差在诏令流程的哪一关。中书省在最前面：决策、草拟诏令，文书出自其手；门下省在中间：审议把关，不妥可以封还驳回；尚书省在最后：统领六部执行落实。她这次选了枢密院——那是宋朝才有、掌军政的机构，唐代的题光靠时代就能排除，是职能没对上、时代也没把关的双重失守。判断抓手：记口诀“中出、门审、尚行”，做题先抓材料动词：草拟、文书出其手找中书，封驳、退回找门下，执行、六部找尚书。", "check_q": "一份诏令拟好后被某省退回重写，行使退回权的是哪个省？最初拟诏的又是哪个省？", "check_a": "退回重写的是门下省（审议封驳）；拟诏的是中书省。尚书省只管执行，不参与拟诏与封驳。", "keys": ["历史|20|1"]}, {"subject": "历史", "a_name": "中朝（内朝）", "a_def": "皇帝在宫内用尚书、侍中、常侍等亲信组成的决策小圈子，本无正式名分，却能先定决策。", "b_name": "外朝", "b_def": "以丞相为首的正式朝廷机构，名义上总领百官、参与决策，是法定的行政中枢。", "diff": "差在离皇帝远近、权力归谁。外朝是以丞相为首的正式朝廷，名义上总领政务；中朝是皇帝在宫内用亲信临时搭起的小圈子。材料说“事皆决于内朝”，就是决策权从外朝丞相手里转进皇帝的中朝，实质是皇权集中。她停在“丞相职能从决策转向执行”的表象，没有继续追问决策权最终归了谁。判断抓手：凡遇到问“实质、本质”的题，先数谁的权力变大、谁的变小，答案往权力归属上落，基本不会错。", "check_q": "汉武帝时出现“事决于尚书”的局面，决策权是从谁手里转到了谁手里？实质是什么？", "check_a": "从外朝丞相手里转到皇帝亲信组成的中朝（尚书等）手里，实质是决策权向皇帝集中、皇权加强，而不是丞相改行做执行。", "keys": ["历史|11|1"]}, {"subject": "历史", "a_name": "互证性", "a_def": "两种不同来源的史料记载能相互印证，如传世文献与出土文献内容对得上，即二重证据法所看重的。", "b_name": "可靠性", "b_def": "单独一份史料本身可不可信，要看它的来源、成书年代和作者立场，是对单一史料的评价。", "diff": "差在评价对象是一个还是两个。可靠性评的是一份史料自己可不可信，看来源、年代、立场；互证性看的是两种不同来源的史料能不能对上。这道题同时给了《史记》（传世文献）和睡虎地秦简（出土文献），两者记载能对应，考点在“互”不在“靠”，她没数清材料是两种来源，被泛泛的“可靠性”带走。判断抓手：先数材料来源——只有一份，谈可靠性；两份以上且内容能对上，先锁定互证性。", "check_q": "出土竹简的记载与《史记》的对应记载一致，这主要证明了史料的互证性还是可靠性？为什么？", "check_a": "互证性。因为是传世文献与出土文献两种不同来源相互印证（二重证据）；可靠性是对单独一份史料本身的评价，这里评价对象是两者的对应关系。", "keys": ["历史|8|1"]}, {"subject": "历史", "a_name": "分封制", "a_def": "君主把土地和人口分封给王族、功臣镇守治理，是分权任事的政治安排。", "b_name": "宗法制", "b_def": "以嫡长子继承为核心、按血缘亲疏确定尊卑等级与继承顺序的家族秩序。", "diff": "差在靠什么维系。分封制是政治安排：君主分土封人、任事镇守，核心是分权治理；宗法制是血缘秩序：以嫡长子继承为核心，按血缘亲疏排尊卑，核心是家族内部排位。这道题里，子姓分族是商王把王族子弟分派出去任事，属政治安排；选项却说被巡行的各部族与商王形成血缘认同——部族与商王并不同姓，材料里也没有结亲、认祖的信息。她被“子姓”二字勾去联想血缘，没核对选项主语。判断抓手：先分清说的是“分地任事”还是“血缘排位”，再核对选项主语在材料里有没有出处。", "check_q": "商王把同姓子弟分派到各地任职，这更接近分封式的政治安排还是宗法制的血缘排位？说“各部族与商王形成血缘认同”错在哪？", "check_a": "是分土任事的政治安排。错在无中生有：被巡行的部族与商王并不同姓，材料只写纳贡、赏赐、效忠等政治仪式，没有任何血缘认同的信息。", "keys": ["历史|3|1"]}, {"subject": "历史", "a_name": "法令废弛", "a_def": "政令推行不下去、官吏有法不依、阳奉阴违，法度名存实亡。", "b_name": "法令严苛僵化", "b_def": "法令正在被严格执行，官吏惧法怕责、不敢变通，连救灾这类急事也层层观望不动。", "diff": "同一副“官吏不动”的表象，底下是两个相反的结论。法令废弛是政令推行不下去、官吏有法不依；法令严苛僵化是法令正在被严格执行，官吏怕触法担责，连开仓赈灾都不敢变通。这道题材料明说“吏皆惧法，莫肯赈救”——怕法，恰恰证明法在生效，她却选了法令废弛，与原文正相反，多半是只扫到“不救灾”的结果就下了判断。判断抓手：结论词先回原文找动词对位，“惧法、畏罪”锁严苛，“不行、贪腐、无人理会”才对废弛，方向反了立刻划掉。", "check_q": "材料说隋末官吏“惧法，莫肯赈救”，能否据此得出“法令废弛”的结论？为什么？", "check_a": "不能。“惧法”恰恰说明法令在被严格执行，官吏怕担责才不敢开仓，是法令严苛僵化，与“废弛”（有法不依）正好相反。", "keys": ["历史|15|1"]}, {"subject": "政治", "a_name": "新民主主义革命", "a_def": "由无产阶级（通过中国共产党）领导的民主革命，属于无产阶级革命的范畴，前途是社会主义，1919年五四运动是它的开端。", "b_name": "旧民主主义革命", "b_def": "由资产阶级领导的民主革命，属于资产阶级革命的范畴，前途是建立资产阶级共和国、走资本主义道路。", "diff": "差在领导阶级：旧由资产阶级领导、属资产阶级革命范畴、前途是资本主义；新由无产阶级（共产党）领导、属无产阶级革命范畴、前途是社会主义。两者只有革命任务相同（都反帝反封建）。她这次只记住“任务相同”，把旧民主主义革命也划进世界无产阶级革命，漏了根本分界。抓手：判断性质先问“谁领导”。口诀：任务都一样，领导定性质；资产对无产，旧新自分明。", "check_q": "辛亥革命属于新民主主义革命还是旧民主主义革命？判断依据是什么？", "check_a": "旧民主主义革命。辛亥革命由资产阶级领导，属于资产阶级革命范畴；新民主主义革命的标志是无产阶级（共产党）领导。判断性质先看领导阶级，不看任务。", "keys": ["政治|10|1", "政治|9|1"]}, {"subject": "政治", "a_name": "必然趋势", "a_def": "指历史发展注定要出现的方向与结果，如社会主义代替资本主义是历史发展的必然趋势；关键词是“方向、注定、归宿”，主语是那个大结果本身。", "b_name": "必要准备", "b_def": "指一件大事发生前必须先铺好的前提条件，如五四运动为中国共产党的成立作了思想上和干部上的准备；关键词是“为……创造条件、作了准备”，主语是打基础的那件事。", "diff": "差在句子讲的是“结果”还是“条件”：必然趋势说的是注定出现的历史方向，主语是那个大结果本身；必要准备说的是事前必须铺好的前提，主语是打基础的事，宾语才是被准备的大事。她在卷面上把两者主宾对调，把“谁为谁作准备”写反了。抓手：先看句尾落点——落在“趋势、方向”是结果，落在“准备、条件、前提”是铺垫；再验时间，作准备的必在前面。口诀：趋势是归宿，准备是前提；准备在事前，别把主宾颠。", "check_q": "判断正误：“中国共产党的成立为五四运动作了思想上和干部上的准备。”", "check_a": "错，主宾和时间都反了。是五四运动（1919年）在前，为中国共产党的成立（1921年）作了思想上和干部上的准备；作准备的事必须发生在被准备的事之前。", "keys": []}, {"subject": "政治", "a_name": "理论基石", "a_def": "科学社会主义赖以成立的理论根基，即马克思的两大发现——唯物史观和剩余价值学说；回答的是“靠哪套理论立起来”。", "b_name": "产生的条件", "b_def": "科学社会主义诞生的历史土壤，即资本主义的发展和工人运动的兴起（空想社会主义是其重要思想来源）；回答的是“在什么条件下长出来”。", "diff": "差在回答的问题不同：理论基石回答“靠哪套理论立起来”——是唯物史观和剩余价值学说这两大发现；产生的条件回答“在什么土壤里长出来”——是资本主义的发展和工人运动的兴起，空想社会主义提供思想来源。她这次把“产生的条件”填到了“理论基石”的位置上，条件和理论混作一团。抓手：题干见“基石、支柱、发现”选两大发现，见“前提、条件、土壤”选资本主义发展加工人运动。口诀：基石是理论，两大发现；条件是土壤，资本加工运。", "check_q": "科学社会主义的理论基石是什么？它产生的历史前提又是什么？", "check_a": "理论基石是唯物史观和剩余价值学说（马克思的两大发现）；产生的历史前提（条件）是资本主义的发展和工人运动的兴起。一个是理论，一个是土壤，不能互换位置。", "keys": []}, {"subject": "政治", "a_name": "重新确立", "a_def": "指本来就存在、被破坏后又恢复确立，如十一届三中全会重新确立了马克思主义的思想路线、政治路线和组织路线。", "b_name": "首次确立", "b_def": "指某件事从无到有、历史上第一次出现；用在“恢复原有正确路线、方针”这类事上，就是错误表述。", "diff": "差在一个“先”背后的历史：“首次确立”指从古到今第一次出现；“重新确立”指本来就有、被破坏后又恢复。马克思主义思想路线、政治路线、组织路线本来就存在，被“文革”破坏，十一届三中全会是把它们恢复回来，只能说“重新”。她这次没抠住这一字之差，把写着“首次确立”的错误表述放了过去。抓手：凡涉文革后恢复原有正确路线、方针的，一律“重新”；只有全新创举才配“首次”。口诀：旧物复原叫重新，无中生有才首次。", "check_q": "“十一届三中全会首次确立了马克思主义的政治路线”——这句话错在哪里？", "check_a": "错在“首次”。政治路线（连同思想路线、组织路线）本来就存在、被“文革”破坏，十一届三中全会是“重新确立”了它们，不是首次确立。", "keys": ["政治|20|1"]}, {"subject": "政治", "a_name": "终极真理", "a_def": "把真理说成一成不变、到此为止的最终形态——这是对科学社会主义的错误表述，政治题中出现这类词基本判错。", "b_name": "发展的真理", "b_def": "科学社会主义是随着实践不断丰富、发展的科学真理，时代变了，它依然具有真理的光芒和改造现实的力量。", "diff": "差在真理“变不变”：“终极真理”把科学社会主义说成一成不变、到此为止的最终形态，这是错误表述；它实际是随着实践不断丰富、发展的真理，时代变了依然有真理光芒和改造现实的力量。她这次没识破选项①里的“终极”二字，把含错误项的组合选了进去。抓手：政治题里见“终极、永恒不变、彻底终结”这类把话说死的词，先划掉含它的组合，再看其余选项。口诀：真理在发展，没有终点站；凡说终极的，多半错误项。", "check_q": "判断正误：“科学社会主义是关于人类社会的终极真理，今后不会再发展了。”", "check_a": "错。科学社会主义是发展的、开放的真理，随实践不断丰富，不存在“终极真理”；“终极、不再发展”是绝对化表述，是政治选择题的典型错误项。", "keys": ["政治|17|1"]}, {"subject": "地理", "a_name": "大气反射", "a_def": "云层和较大尘埃颗粒把太阳短波辐射反射回宇宙空间，无选择性，属于削弱作用，发生在太阳辐射到达地面之前。", "b_name": "大气逆辐射", "b_def": "大气增温后射向地面的长波辐射，把热量返还给地面，属于保温作用（温室效应），发生在地面增温之后。", "diff": "差在时机和方向：反射发生在太阳辐射到达地面之前，是云层尘埃把短波辐射挡回宇宙，属于削弱作用；逆辐射发生在地面增温之后，是大气把长波热量射回地面，属于保温作用。她这次在大题里直接把“大气逆辐射”写成了“反射”，夜间保温整段丢分。抓手：问“白天为什么凉”找反射，问“夜里靠什么保温”只认逆辐射。口诀：反射在事前挡太阳，逆辐射在事后还热量。", "check_q": "多云的夜晚比晴朗的夜晚温暖，主要靠反射作用还是大气逆辐射？为什么？", "check_a": "大气逆辐射。云层厚使大气逆辐射强、保温作用好，地面降温慢；反射是白天把太阳辐射挡回去的削弱作用，发生在热量到达地面之前，与夜间保温无关。", "keys": ["地理|12|1", "地理|13|1"]}, {"subject": "地理", "a_name": "太阳辐射强", "a_def": "指到达地面的太阳辐射多，由削弱作用决定：空气越稀薄、晴天越多、被大气挡掉的越少，地面得到的辐射就越强。", "b_name": "气温高", "b_def": "指近地面空气温度高，由保温作用决定：大气吸收地面辐射多、逆辐射返还强，热量留得住，气温才高。", "diff": "差在决定机制不同：辐射强弱看削弱——空气越稀薄、晴天越多，被挡掉的越少，辐射越强；气温高低看保温——大气吸收地面辐射、逆辐射返还的能力越强，气温越高。青藏高原空气稀薄，削弱弱所以辐射最强，但保温也差，所以气温偏低。她这次写出“辐射与气温成反比”，就是把两套机制混成了一句。抓手：题问辐射查削弱，题问气温查保温。口诀：辐射看削弱，气温看保温，两套机制莫混谈。", "check_q": "青藏高原太阳辐射强、气温却偏低，这两个现象分别由哪种机制决定？", "check_a": "辐射强由削弱作用决定（海拔高、空气稀薄、晴天多，削弱少）；气温低由保温作用决定（空气稀薄，吸收地面辐射少、大气逆辐射弱，热量散失快）。两套机制不能混谈，更不是“成反比”。", "keys": ["地理|25|1", "地理|24|1"]}, {"subject": "地理", "a_name": "对流层", "a_def": "大气的最底层，直接热源是地面，气温随高度升高而降低，平均每升高100米下降约0.6℃，天气现象都发生在这一层。", "b_name": "平流层", "b_def": "对流层之上的大气层，含有臭氧层，能吸收紫外线而增温，气温随高度升高而升高，气流平稳，适合高空飞行。", "diff": "差在气温随高度的变化方向正好相反：对流层的直接热源是地面，离地越远得热越少，每升高100米降约0.6℃；平流层有臭氧吸收紫外线增温，越高越热。她这次把对流层的规律直接答成了“升高”，是把两层记反后原样复现。抓手：做题先问“题目说的是哪一层”，再套方向；看到山顶积雪、“高处不胜寒”，必是对流层递减。口诀：对流近地越上越冷，平流臭氧越上越热。", "check_q": "对流层和平流层中，气温随高度升高而升高的分别是哪一层？原因是什么？", "check_a": "平流层。对流层的热源是地面，越高离热源越远，气温越低（每100米约降0.6℃）；平流层靠臭氧吸收紫外线增温，高度越高吸收越多，气温越高。", "keys": ["地理|14|1"]}, {"subject": "地理", "a_name": "地壳", "a_def": "地球最外层的薄壳，上界是地表，下界是莫霍界面，平均厚度约17千米，只是地球内部圈层的第一层。", "b_name": "岩石圈", "b_def": "由地壳和上地幔顶部（软流层以上的部分）合起来的圈层，范围比地壳大，板块就漂浮在岩石圈之下的软流层上。", "diff": "差在范围：地壳只是地球最外层的薄壳，到莫霍界面为止，平均约17千米；岩石圈比地壳大，包括地壳再加上地幔顶部、软流层以上的部分。她这次的错题正栽在“岩石圈等于地壳”的对调坑上，软流层的位置也跟着答错。抓手：凡题里出现“软流层以上”拼成的圈层，答岩石圈；只问最外层薄壳，才答地壳。口诀：岩石圈是地壳加地幔顶，地壳只是其中一层皮。", "check_q": "岩石圈的范围到哪里为止？它和地壳是什么关系？", "check_a": "岩石圈从地表延伸到软流层上界，包括地壳和上地幔顶部；地壳只是岩石圈的一部分，岩石圈不等于地壳。", "keys": ["地理|10|1"]}, {"subject": "地理", "a_name": "海风", "a_def": "白天陆地增温快、海洋凉，陆地近地面形成低压，风从海洋（高压）吹向陆地（低压），以来源地海洋命名，叫海风。", "b_name": "陆风", "b_def": "夜晚陆地降温快、海洋相对较暖，陆地近地面形成高压，风从陆地（高压）吹向海洋（低压），以来源地陆地命名，叫陆风。", "diff": "差在昼夜与风向：白天陆地热、海洋凉，陆地近地面是低压，风从海洋吹向陆地，叫海风；夜晚正好反过来，陆地冷成高压，风从陆地吹向海洋，叫陆风。她这次在热力环流图里冷热源位置一换、箭头就全反，说明是凭图形眼熟下手。抓手：先定昼夜，再定陆地冷热和气压，最后顺“高压到低压”画箭头；风以来源地命名，从海上来就是海风。口诀：白天海风夜陆风，风名跟着来源走。", "check_q": "夜晚沿海地区吹什么风？近地面气流从哪里吹向哪里？", "check_a": "吹陆风。夜晚陆地降温快、近地面形成高压，海洋相对温暖、形成低压，风从陆地（高压）吹向海洋（低压），以来源地陆地命名。", "keys": ["地理|16|1"]}, {"subject": "化学", "a_name": "氯气（Cl2）", "a_def": "黄绿色、有毒的单质气体，密度比空气大，本身具有强氧化性。", "b_name": "氯水（Cl2的水溶液）", "b_def": "氯气溶于水形成的混合物，含Cl2、HCl、HClO等多种微粒，真正起漂白、杀菌作用的是次氯酸HClO。", "diff": "差在单质与混合物：氯气只有Cl2一种物质，氯水是Cl2溶于水后的一锅混合物。区分信号：问颜色、毒性、密度说的是氯气（黄绿色）；问漂白、杀菌、使布条褪色，功劳要记在氯水里的HClO头上。她第7题放过了铁与氯气生成FeCl3这个正确项，又在尾气吸收题里把Cl2与NaOH的产物写成HClO，把氯气与水、与碱两个反应混成一团。抓手：见氯水先默念成分名单；判断产物先看介质是水还是碱，碱环境里HClO必被中和成次氯酸盐。", "check_q": "新制氯水能使有色布条褪色，起漂白作用的物质是（ ）A.Cl2 B.HCl C.HClO D.O2", "check_a": "C。漂白靠HClO的强氧化性；久置氯水因HClO见光分解而失去漂白性。", "keys": ["化学|7|1", "化学|14-(3)|1"]}, {"subject": "化学", "a_name": "铁与氯气反应", "a_def": "Cl2氧化性强，把铁氧化到最高价+3，生成FeCl3，现象是剧烈燃烧、产生棕褐色烟：2Fe+3Cl2=点燃=2FeCl3。", "b_name": "铁与盐酸反应", "b_def": "盐酸是非氧化性酸，H+只能把铁氧化到+2价，生成FeCl2和H2：Fe+2HCl=FeCl2+H2↑。", "diff": "差在氧化剂的力气：Cl2是强氧化剂，专把变价金属推到最高价；盐酸里的H+是弱氧化剂，只能推到+2价。信号抓手：反应物是Cl2单质，氯化物取最高价；是HCl或稀硫酸，取低价。她默写方程式时直接把铁与氯气换成了铁与盐酸，还写出不存在的Fe3Cl2，反应物、价态、化学式三处全错。防混口诀：氯气高价，盐酸低价——动笔前先问一句：氧化剂是谁？", "check_q": "写出铁与盐酸反应的化学方程式，并指出铁的化合价。", "check_a": "Fe+2HCl=FeCl2+H2↑，铁为+2价（若与Cl2反应则生成+3价的FeCl3）。", "keys": ["化学|11-(3)|1"]}, {"subject": "化学", "a_name": "先水后盐（钠入盐溶液的实际路径）", "a_def": "钠投入盐溶液，先与水反应生成NaOH和H2，生成的碱再与盐发生复分解，可能产生沉淀。", "b_name": "直接置换（错误路径）", "b_def": "按金属活动性以为钠能把盐溶液中的金属置换出来——在水溶液中绝不会发生。", "diff": "差在第一步的反应对象：钠太活泼，在水溶液里第一反应永远是水，而不是盐。她两道题都栽在这：第4题按钠置换镁的思路选错，第13题又把析出红色的铜也圈了进去。信号：只要钠出现在溶液里，就先写钠与水的方程式；现象题按浮熔游响加碱与盐生成的沉淀两段拼，唯独没有金属单质析出。抓手一句话：钠入水溶液，置换靠边站，先跟水走，再看碱与盐。", "check_q": "一小块钠投入CuSO4溶液中，能观察到哪些现象？会不会有红色铜析出？", "check_a": "浮、熔、游、响，并产生蓝色Cu(OH)2沉淀；不会析出铜，因为钠先与水反应。", "keys": ["化学|4|1", "化学|13-(5)|1"]}, {"subject": "化学", "a_name": "漂白粉的成分", "a_def": "Cl2通入石灰乳制得的混合物，含CaCl2和Ca(ClO)2两种盐。", "b_name": "漂白粉的有效成分", "b_def": "只有Ca(ClO)2，它遇CO2和水生成HClO起漂白杀菌作用；CaCl2不起漂白作用。", "diff": "差在全部家当与干活的那一个：成分问的是混合物里有什么（两种盐），有效成分只锁定Ca(ClO)2。她在变质探究题里把成分、有效成分、变质产物CaCO3搅成一团，三个假设无从下手。区分信号：题干出现有效成分四字，答案永远是Ca(ClO)2；问主要成分或含有，才写两种盐。抓手把链条背熟：成分CaCl2+Ca(ClO)2，有效只认Ca(ClO)2，变质产物是CaCO3，三层各就各位。", "check_q": "漂白粉长期露置于空气中全部变质后，主要固体产物是什么？还有有效成分吗？", "check_a": "主要产物是CaCO3；有效成分Ca(ClO)2已转化失效，不再存在。", "keys": ["化学|14-(5)|1"]}, {"subject": "化学", "a_name": "分子的物质的量", "a_def": "题目直接给出、或由质量除以摩尔质量换算得到的分子数量计量，如0.5 mol NH3、4 g H2换算出的2 mol H2。", "b_name": "原子的物质的量", "b_def": "比较所含原子数时真正要比的量，等于分子的物质的量乘以每个分子的原子个数。", "diff": "差在数分子还是数原子：题目问原子数，必须多乘一步每个分子的原子个数。她第8题把分子的多少当成原子的多少，还漏了两步：4 g H2没先除以摩尔质量2 g/mol换成2 mol，H3PO4的原子数没数全（3+1+4=8）。信号：看到原子数、原子个数立刻启动两步——给质量的先算n=m/M统一成物质的量，再乘单分子原子总数。抓手：n(原子)=n(分子)×原子个数的总和，每个选项逐个算完写在旁边再排序。", "check_q": "0.4 mol H2SO4和8 g CH4，哪一个含的原子更多？", "check_a": "H2SO4更多：0.4×7=2.8 mol原子；CH4为0.5 mol，0.5×5=2.5 mol原子。", "keys": ["化学|8|1"]}, {"subject": "生物", "a_name": "氨基酸的个数", "a_def": "肽链中氨基酸残基的总数，决定肽的名称，并用于计算脱水数：脱水数=个数-肽链数。", "b_name": "氨基酸的种类", "b_def": "按R基不同划分的类别数，重复出现的氨基酸只算一种，人体蛋白质的氨基酸最多21种。", "diff": "差在数人头还是数姓氏：个数一个一个地数，种类要按R基去重。信号：题目问几种氨基酸，必须逐个看R基，相同的合并。她在脑啡肽题里把5个氨基酸直接等同于5种，没发现其中一种重复出现，白白掉进选项陷阱。连带提醒：算脱水数、肽键数用的是个数不是种类，别串台。抓手口诀：种类看R基，个数逐个点；同名只算一，脱水减链数。", "check_q": "某六肽由6个氨基酸组成，其中亮氨酸出现2次、其余各1次，该肽由几种氨基酸组成？脱去几个水分子？", "check_a": "5种氨基酸；脱去5个水分子（6-1=5）。", "keys": ["生物|20|1"]}, {"subject": "生物", "a_name": "自由水", "a_def": "以游离形式存在、能自由流动的水，是良好溶剂并参与代谢反应，相对比例高时代谢旺盛。", "b_name": "结合水", "b_def": "与蛋白质、多糖等物质结合、不能自由流动的水，是细胞结构的重要组成，比例高时抗逆性强。", "diff": "差在能不能流动、管什么事：自由水管代谢，结合水管结构和抗逆。判断代谢强弱的信号不是自由水的绝对含量，而是自由水与结合水的比值：比值大代谢旺，比值小如休眠种子则代谢弱而抗逆强。她第22题把决定因素答成自由水含量，丢了比值这个关键表述。还要连着记方向：种子萌发时比值上升，晒干储藏时比值下降。抓手：自由流动管代谢，结合固定管抗逆；强弱不看含量看比值。", "check_q": "休眠种子与萌发种子相比，哪一个自由水/结合水的比值更大？", "check_a": "萌发种子的比值更大（代谢旺盛）；休眠种子比值小、代谢弱但抗逆性强。", "keys": ["生物|22-(3)|1"]}, {"subject": "生物", "a_name": "鲜重（活细胞）", "a_def": "含水状态下的质量排序：含量最多的化合物是水（约85%），最多的元素是氧，最多的有机物是蛋白质。", "b_name": "干重", "b_def": "烘干除去全部水后的质量排序：含量最多的化合物是蛋白质，最多的元素是碳。", "diff": "差在算不算那约85%的水：同一个细胞，带水看（鲜重）冠军是水，去掉水（干重）冠军立刻换成蛋白质。她在青萝卜题里答淀粉，是把重要的储能物质错当成含量最多的化合物，连鲜重的基准线都没站对。信号抓手：先圈题干里的鲜还是干——问活细胞或鲜重的化合物答水、元素答氧；问干重的化合物答蛋白质、元素答碳，再落笔不迟。", "check_q": "晒干的种子（干重）中含量最多的化合物是什么？鲜活细胞中含量最多的元素是什么？", "check_a": "干重最多的是蛋白质；鲜活细胞中含量最多的元素是氧。", "keys": ["生物|22-(1)-①|1"]}, {"subject": "生物", "a_name": "蛋白质变性", "a_def": "高温、强酸、强碱、重金属盐等使蛋白质空间结构破坏、功能丧失，肽键不断裂，通常不可逆，如煮熟鸡蛋、高温灭菌。", "b_name": "蛋白质水解", "b_def": "在蛋白酶或酸碱作用下肽键断裂，蛋白质被拆成短肽直至氨基酸，破坏的是一级结构。", "diff": "差在动形状还是动链条：变性只拆空间结构，氨基酸的排列顺序和肽键都还在；水解专断肽键，链条本身被剪断。她以为变性就是肽链被打断，把两者混为一谈；脑啡肽题里高温不会丧失功能也是同一陷阱的变式。捎带分清盐析：只改变溶解度、结构不动、加水可复溶，是唯一可逆的。信号：见功能丧失、消毒、煮熟先想变性；见酶解、消化成氨基酸才是水解。", "check_q": "鸡蛋煮熟属于变性还是水解？煮熟过程中肽键断裂了吗？熟蛋加水能变回液态吗？", "check_a": "属于变性；肽键没有断裂，破坏的是空间结构；变性不可逆，不能变回液态。", "keys": ["生物|18|1", "生物|20|1"]}, {"subject": "生物", "a_name": "原核细胞", "a_def": "没有核膜包被的细胞核、只有拟核，唯一的细胞器是核糖体，如细菌、蓝藻（蓝细菌）、支原体。", "b_name": "真核细胞", "b_def": "有核膜包被的成形细胞核，具有多种细胞器，如动植物细胞、酵母菌、草履虫。", "diff": "差在分界线只有一条：有无以核膜为界限的细胞核。她混了三次：把无细胞结构的病毒塞进原核（病毒两者都不是，单独一类）；原核名单里多选了小肠上皮细胞（动物细胞，妥妥真核）；蓝藻光合作用填叶绿体——原核细胞没有叶绿体，靠藻蓝素和叶绿素。抓手：名单背死细菌、蓝藻、支衣放，再记两个反例，酵母菌、霉菌带菌字却是真核，衣藻带藻字也是真核，只有蓝藻是原核。", "check_q": "下列生物中属于原核生物的是（ ）A.酵母菌 B.颤藻 C.草履虫 D.衣藻", "check_a": "B。颤藻属于蓝藻；酵母菌、草履虫、衣藻均为真核生物。", "keys": ["生物|12|1", "生物|21-(1)|1", "生物|21-(2)-②|1", "生物|21-(3)-②|1"]}, {"subject": "生物", "a_name": "还原糖", "a_def": "能与斐林试剂在水浴加热下反应、生成砖红色Cu2O沉淀的糖，高中阶段只记三个：葡萄糖、果糖、麦芽糖。", "b_name": "非还原糖", "b_def": "不能被斐林试剂氧化的糖，如蔗糖、淀粉、纤维素，与斐林试剂共热不出现砖红色沉淀。", "diff": "差在能不能把斐林试剂还原出砖红色：名单内的葡、果、麦能，名单外的蔗糖、淀粉、纤维素不能。她没识破选项的坑——用蔗糖溶液作还原糖定量的颜色对照，蔗糖根本不显色，对照无从谈起。信号：凡涉及斐林试剂鉴定、颜色对照、定量的题目，先把材料对一遍还原糖名单；附带条件别忘水浴加热，她在海藻糖探究题里就漏了水浴二字丢分。抓手：葡果麦能还原，蔗淀纤不能，鉴定必水浴。", "check_q": "下列糖中属于还原糖的是（ ）A.蔗糖 B.淀粉 C.麦芽糖 D.纤维素", "check_a": "C。还原糖只记葡萄糖、果糖、麦芽糖；蔗糖、淀粉、纤维素均为非还原糖。", "keys": ["生物|17|1", "生物|24-(1)-③|1"]}, {"a_def": "从初位置指向末位置的有向线段，是矢量，只看起点和终点，带正负号：Δx=x末−x初。", "a_name": "位移", "b_def": "物体实际运动轨迹的长度，是标量，只有大小、永远不为负。", "b_name": "路程", "check_a": "路程=4+7=11m；位移=末位置−初位置=(5+4−7)−5=−3m（大小3m，方向沿x轴负方向）。把位移答成11m或正3m，都是把位移当成了路程。", "check_q": "小球从x=5m处出发，先向正方向走4m，再反向走7m停下。全程的路程和位移分别是多少？", "diff": "差在认不认方向：位移只认首末位置，路程认走过的全程。她第4s内坐标从3m降到0m，位移是0−3=−3m，她只写了大小3，等于把位移答成了路程。判断抓手：题目出现Δx、“变化量”“平均速度”，一律先定正方向、用“末减初”，符号自己会出来；问“路程”才去数轨迹长度。口诀：位移看两头，路程看全程；带Δ先定向。", "keys": ["物理|10空2|1", "物理|10空4|1"], "subject": "物理"}, {"a_def": "位移与所用时间的比值：v̄=Δx/Δt，是矢量，带方向符号。", "a_name": "平均速度", "b_def": "路程与所用时间的比值，是标量，只有大小。", "b_name": "平均速率", "check_a": "平均速度=0（位移为0）；平均速率=400÷50=8m/s。把平均速度答成8m/s，就是把速率当成了速度。", "check_q": "运动员绕400m跑道跑一圈回到起点，用时50s。这一圈的平均速度和平均速率各是多少？", "diff": "差在分子用谁：平均速度用位移，平均速率用路程。她第4s内位移−3m、路程3m，平均速度应是−3m/s，她却把路程和时间乱配、还丢了方向。有往返、掉头的运动里两者大小就不相等，只有单向直线运动才相等。抓手：先问题目要“速度”还是“速率”，要速度就先算带符号的Δx再除以时间，方向自动跟着符号走。口诀：速度认位移，速率认路程。", "keys": ["物理|10空4|1", "物理|14(2)|1"], "subject": "物理"}, {"a_def": "前后两段路程相等时，总平均速度=2v₁v₂/(v₁+v₂)，结果偏向慢的那一段。", "a_name": "等路程的平均速度（调和平均）", "b_def": "前后两段时间相等时，总平均速度=(v₁+v₂)/2，可以直接取两速度的中点。", "b_name": "等时间的平均速度（算术平均）", "check_a": "前者（等路程）=2×10×15÷(10+15)=12m/s；后者（等时间）=(10+15)/2=12.5m/s。两者答成一样，就是没分清路程等和时间等。", "check_q": "汽车前一半路程速度10m/s、后一半路程速度15m/s；另一辆车前一半时间速度10m/s、后一半时间速度15m/s。两车全程平均速度各是多少？", "diff": "平均速度永远只有一个定义：总位移÷总时间，两种算法只是这个定义在两种条件下的化简。等路程时慢段耗时更长、在总时间里权重更大，所以不能直接取中点。她把6m/s和9m/s的两段等路程算成(6+9)/2=7.5，正确是2×6×9÷(6+9)=7.2。抓手：先分清题眼是“一半路程”还是“一半时间”——路程等用调和，时间等才用算术。口诀：路程等，调和算；时间等，才对半。", "keys": ["物理|9空1|1"], "subject": "物理"}, {"a_def": "初速度为零的匀加速，按连续相等时间切分：各段位移比1:3:5:7…，各时刻速度比1:2:3:4。", "a_name": "等时间段比例规律", "b_def": "初速度为零的匀加速，按连续相等位移切分：各段末速度比1:√2:√3:2，各段用时越来越短，比为1:(√2−1):(√3−√2):(2−√3)。", "b_name": "等位移段比例规律", "check_a": "速度比1:√2:√3:2；时间比1:(√2−1)。若答速度增量相等或每段时间相等，就是又把等位移当成了等时间。", "check_q": "物体从静止做匀加速直线运动，通过连续四段相等位移，到达各段末端点的速度比是多少？通过第一段与第二段的时间比是多少？", "diff": "差在切分标准：一个按表（时间）切，一个按尺（位移）切，两套比例不能混用。她第8题把“相等位移”当成“相等时间”，以为每段速度增量相同，多选了A，双选含错项直接归零。等位移时车越走越快，每段Δt越来越小，Δv=aΔt自然越来越小、不可能相等。抓手：先看题眼是“每段位移相等”还是“每秒”，出现位移相等就调出v²=2ax。口诀：表切看奇数，尺切带根号。", "keys": ["物理|8|1"], "subject": "物理"}, {"a_def": "末速度减初速度，是矢量运算：必须先定正方向，把两个速度带符号再相减。", "a_name": "速度变化量Δv", "b_def": "末速度大小减初速度大小，只是两个数值的差，完全不看方向。", "b_name": "速度大小的变化", "check_a": "未掉头：Δv=3−12=−9，大小9m/s；掉头时取向东为正、末速为−3：Δv=−3−12=−15，大小15m/s。掉头时若答9，就是把Δv当成了速度大小之差。", "check_q": "汽车以12m/s向东行驶，刹车后仍以3m/s向东行驶，速度变化量大小是多少？若它掉头以3m/s向西开，速度变化量大小又是多少？", "diff": "差在减的是矢量还是数值。足球以10m/s迎面飞来、被8m/s反向踢回，取来球方向为正：v₀=+10、v=−8，Δv=−8−10=−18，大小18；她按数值算10−8=2，下一问加速度跟着错成20（正确180）。抓手：凡出现掉头、反弹、反向踢出，先给反方向的速度挂上负号再套Δv=v−v₀。口诀：反向相减变相加——方向相反时，Δv的大小等于两速度大小之和。", "keys": ["物理|13(1)|1", "物理|13(2)|1"], "subject": "物理"}, {"a_def": "描述位置变化快慢（运动快慢）的物理量，单位m/s，大小和加速度没有直接关系。", "a_name": "速度v", "b_def": "描述速度变化快慢的物理量，a=Δv/Δt；a大只说明速度变得快，不说明速度本身大。", "b_name": "加速度a", "check_a": "速度一直增大，只是增大得越来越慢，a减到0后保持匀速。答“速度减小”就是把a减小误当成了v减小。", "check_q": "物体做直线运动，加速度与速度同向，但加速度从5m/s²逐渐减小到0。这段时间内速度怎样变化？", "diff": "差在描述谁的变化：v管位置变得多快，a管速度变得多快。她第5题把a的大小和v的大小直接挂钩而选错。三句话钉死：刹车瞬间v很大而a可以很小；起步时v很小而a可以很大；高速匀速时v最大而a=0。判断v增减只看方向：a与v同向v增大、反向v减小；a变小只是变得慢了，不等于v变小。抓手：先比方向定增减，再看|a|定变快变慢。口诀：增减看方向，快慢看a值。", "keys": ["物理|5|1"], "subject": "物理"}, {"a_def": "p⇒q时，p是q的充分条件：站在箭头的尾巴，是能推出别人的那个（范围更小）。", "a_name": "充分条件", "b_def": "p⇒q时，q是p的必要条件：站在箭头的头部，是被别人推出的那个（范围更大，缺它不可）。", "b_name": "必要条件", "check_a": "q是p的必要不充分条件：p⇒q成立，但q⇒p不成立（如x=4.5满足q却不满足p）。答成充分条件就是方向又反了。", "check_q": "设p：1<x<4，q：0<x<5。q是p的什么条件？", "diff": "差在站在箭头的哪一头，名字正好反着。她第6题没先写推导链就套名称，方向答反。铁方法分两步：先判谁推出谁——p的范围(0,2)落在q的范围(−1,3)里面，所以p⇒q成立；再命名——箭尾p是充分、箭头q是必要，于是q是p的必要不充分条件。最后务必把答案代回题目问法再念一遍防反。口诀：小推大——小范围是充分条件，大范围是必要条件。", "keys": ["数学|6|1"], "subject": "数学"}, {"a_def": "两个集合元素完全相同，互相包含；是包含关系中最精确的一种结论。", "a_name": "集合相等（A=B）", "b_def": "A的元素都在B里面，但B可以多出元素，两集合可以并不相等。", "b_name": "子集包含（A⊆B）", "check_a": "A={−1,1}=B，两集合相等；A⊆C，C还多出别元素，只是包含。若对A、B答“包含”，就是没答到最精确。", "check_q": "A={x|x²=1}，B={−1,1}，C={x|x≥−1}。A与B、A与C分别是什么关系？", "diff": "差在B能不能多出元素。她第14题把A、B分别算成[−9,+∞)，两个−9明明已经对齐，最后却把“相等”写成了“包含”，关系答得不精确而判错。判断原则：先把两个集合都化到底、并排写成区间，端点和范围全同就是相等，必须答A=B——题目问关系时要答最精确的那个。抓手：证相等就是双向包含，A⊆B且B⊆A同时成立。口诀：全同选等号，单向才包含。", "keys": ["数学|14|1"], "subject": "数学"}, {"a_def": "A∩B=A ⟺ A⊆B：交集剩下的就是A，说明A的元素一个没少、全在B里面，A是子集。", "a_name": "A∩B=A 的转化", "b_def": "A∪B=A ⟺ B⊆A：并集合并后没有变大，说明B的元素A全都有，A是父集。", "b_name": "A∪B=A 的转化", "check_a": "A∩B=A ⟺ A⊆B，A是子集；A∪B=A ⟺ B⊆A，A是父集。结论都写“等于A”，包含方向却正好相反。", "check_q": "对非空集合A、B：若A∩B=A，A与B谁是谁的子集？若A∪B=A呢？", "diff": "同样是“等于A”，交和并推出来的包含方向正好相反，记反一次整题错。她第7题第一步就要把A∩B=A翻译成A⊆B，再分空集与非空讨论。想通法：交集是公共部分，能等于A说明A整个被B装住；并集是合并家当，合完还是A说明B没带来任何新东西。抓手：交集等于谁、谁就是子集；并集等于谁、谁就是父集。口诀：交等谁谁小，并等谁谁大。", "keys": ["数学|7|1"], "subject": "数学"}, {"a_def": "端点值可以取到：不等式写≤、≥，区间用方括号[ ]，数轴上画实心点，如分子零点、分类讨论中能成立的参数值。", "a_name": "可取的端点（闭端点）", "b_def": "端点值取不到：不等式写<、>，区间用圆括号( )，数轴上画空心点，如分母零点、使原式无意义或等号不成立的值。", "b_name": "不可取的端点（开端点）", "check_a": "−4取不到（开），0能取（闭）；∁_R A={x|x≤2或x≥3}，2、3两处都变闭——原集是开端点，补集就变闭端点，正好反过来。", "check_q": "解集{x|−4<m≤0}中，−4和0哪个能取？集合A={x|2<x<3}的补集∁_R A在2、3两处是开还是闭？", "diff": "差在这个数到底能不能代回去。她连栽三处：分式题旁边明明写了x≠2，最后还是选了包含x=2的选项；集合补集端点开闭写得含糊；恒成立结论漏并m=0，把≤写成了<。统一检查法：每个端点单独验一遍——代回原式，分母为零、无意义、等号不成立的就是开端点。补集再记一条：端点开闭与原集合正好反过来。口诀：能代回去用方括号，不能代用圆括号。", "keys": ["数学|4|1", "数学|15|1", "数学|17|1"], "subject": "数学"}, {"a_def": "对每一个x都成立，信号词是“恒成立、任意、一切”；必须保住最坏情况：恒≥某数就先求最小值。", "a_name": "恒成立问题（对任意x）", "b_def": "只要有一个x成立即可，信号词是“存在、有解、能”；只需够得着：如只需式子能取到负值，条件宽松得多。", "b_name": "存在性问题（存在x）", "check_a": "（1）需最小值大于0：x=1处最小值m−1>0，得m>1。（2）只需最小值小于0：m−1<0，得m<1。同一条抛物线，量词不同、答案方向正好相反，混用量词就会答反。", "check_q": "（1）x²−2x+m>0对一切实数x恒成立，求m的范围；（2）存在实数x使x²−2x+m<0，求m的范围。", "diff": "差在量词，转化路线完全不同，她这次两道都栽了：第8题是恒成立，要用最小值说话，她却通分硬算；第19题是存在性，只需“能取到负值”，应逐类验：m=0不成立、m<0开口向下自动成立、m>0再看Δ。抓手：动笔先圈量词——“恒/任意”走保底路线，求最值再比大小；“存在”走够得着路线，先验最省事的情形（参数为零、开口向下）。口诀：恒成立看底线，存在性看够不够得着。", "keys": ["数学|8|1", "数学|19|1"], "subject": "数学"}]};
